window.PA_SITUATIONS = [{"id": "ABH-01", "seq": 1, "module": "Foundations", "source": "Public post", "title": "Six PACS messages that run every flow", "explain": "The PACS family is the working vocabulary of ISO 20022 payments: pacs.008 carries the customer credit transfer, pacs.009 moves funds between financial institutions, pacs.002 reports status, pacs.004 returns a settled payment, pacs.028 requests status, and pacs.029 resolves an investigation. Master these six first, because every flow in this product is described in their terms.", "takeaway": "Master these six first, because every flow in this product is described in their terms.", "visual": {"type": "diagram", "diagram": {"centre": "Six PACS messages, one vocabulary", "parts": [{"label": "pacs.008", "note": "Customer credit transfer, the payment instruction itself"}, {"label": "pacs.009", "note": "Financial institution transfer between banks"}, {"label": "pacs.002", "note": "Status report for a payment"}, {"label": "pacs.004", "note": "Return of a payment already settled"}, {"label": "pacs.028", "note": "Status request for a payment"}, {"label": "pacs.029", "note": "Resolution of an investigation on a payment"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008", "pacs.009", "pacs.002", "pacs.004", "pacs.028", "pacs.029"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "ABH-02", "seq": 2, "module": "Foundations", "source": "Public post", "title": "ISO 20022: data, automation and control", "explain": "ISO 20022 is a data standard before it is a format change: structured data travels with the payment, so validation, screening and reconciliation can run straight through without manual rework. Richer data also gives every party visibility across the full lifecycle, from initiation to final status. Treat the message as the control point, not the envelope, and the automation follows.", "takeaway": "Treat the message as the control point, not the envelope, and the automation follows.", "visual": {"type": "diagram", "diagram": {"centre": "ISO 20022, more than a format", "parts": [{"label": "Richer data", "note": "Structured fields travel with the payment"}, {"label": "Better automation", "note": "Straight-through processing, no manual rework"}, {"label": "Smarter compliance", "note": "Screening and validation run in line"}, {"label": "Payment visibility", "note": "Status visible across the whole lifecycle"}, {"label": "Reconciliation", "note": "Structured data makes matching straightforward"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "ABH-04", "seq": 4, "module": "Foundations", "source": "Public post", "title": "Card payment: authorize, clear, settle", "explain": "A card payment runs in three distinct stages. At authorization the issuer verifies the card, the balance, fraud signals, and the PIN, CVV, or 3DS check; clearing is the network exchanging records between banks; and settlement is the point funds actually move to the merchant. Authorization is permission, clearing is the record, and settlement is the money, and only the last closes the payment.", "takeaway": "Authorization is permission, clearing is the record, and settlement is the money, and only the last closes the payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorization", "note": "Issuer verifies card, balance, fraud signals, PIN, CVV or 3DS"}, {"kind": "step", "title": "Clearing", "note": "Network exchanges the records between banks"}, {"kind": "step", "title": "Settlement", "note": "Funds actually move to the merchant"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "ABH-05", "seq": 5, "module": "Foundations", "source": "Public post", "title": "The payment map only works connected", "explain": "ISO 20022 and SWIFT knowledge alone does not make a payments expert. Real expertise connects the payment lifecycle, cards, rails, clearing and settlement, fraud and AML, APIs and the end-to-end journey, because each piece only makes sense through its joins to the others. Learn the connections, not the components in isolation, and the domain starts to behave as one system.", "takeaway": "Learn the connections, not the components in isolation, and the domain starts to behave as one system.", "visual": {"type": "diagram", "diagram": {"centre": "One connected payment lifecycle", "parts": [{"label": "Payment lifecycle", "note": "The journey every payment follows end to end"}, {"label": "Cards", "note": "Authorization, clearing and settlement"}, {"label": "Rails", "note": "The networks that carry the payment"}, {"label": "Clearing and settlement", "note": "Where records exchange and funds move"}, {"label": "Fraud and AML", "note": "Checks that keep payments safe and compliant"}, {"label": "APIs", "note": "How systems connect and exchange payment data"}, {"label": "End-to-end journey", "note": "Each piece only makes sense joined to the others"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "ABH-06", "seq": 6, "module": "Foundations", "source": "Public post", "title": "Payments is one system, not silos", "explain": "Payments is one connected system, not a set of separate topics. Rails, cards, ISO 8583 and ISO 20022, APIs, PCI and tokenization, the lifecycle, compliance and emerging payments each touch the rest, so study every piece by asking how it connects. A professional who maps the joins will always outperform one who memorises the parts.", "takeaway": "A professional who maps the joins will always outperform one who memorises the parts.", "visual": {"type": "diagram", "diagram": {"centre": "Payments, one connected system", "parts": [{"label": "Rails", "note": "The networks payments travel on"}, {"label": "Cards", "note": "Authorization, clearing and settlement"}, {"label": "ISO 8583", "note": "Card message standard in the mix"}, {"label": "ISO 20022", "note": "Rich data messaging for payments"}, {"label": "APIs", "note": "Connections between payment systems"}, {"label": "PCI and tokenization", "note": "Protecting card data in the flow"}, {"label": "Lifecycle", "note": "The stages a payment passes through"}, {"label": "Compliance", "note": "Rules the whole system must meet"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "ABH-07", "seq": 7, "module": "Foundations", "source": "Public post", "title": "Cross-border: speed, cost, control, clarity", "explain": "Cross-border payments join different countries and different systems into a single flow, and the test is the same everywhere: speed, cost, compliance and transparency. A payment that is fast but opaque, or cheap but non-compliant, fails that test whatever the corridor. Judge every cross-border design on all four together, never on one alone.", "takeaway": "Judge every cross-border design on all four together, never on one alone.", "visual": {"type": "diagram", "diagram": {"centre": "Cross-border payments", "parts": [{"label": "Speed", "note": "How fast the payment reaches the beneficiary"}, {"label": "Cost", "note": "What the payment costs to send"}, {"label": "Compliance", "note": "Rules every cross-border payment must meet"}, {"label": "Transparency", "note": "Visibility on status, fees and timing"}, {"label": "Countries", "note": "Different systems joined into one flow"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "ABH-08", "seq": 8, "module": "Foundations", "source": "Public post", "title": "Can a Letter of Credit go fully digital?", "explain": "A Letter of Credit is a trade finance instrument that has traditionally run on paper, yet a fully digital LC shows even the most document-heavy payment product can run end to end without it. For a BA, the real work is tracing what changes in process, data and controls when the paper goes away. Digitisation is a redesign of the control model, not a scan of the documents.", "takeaway": "Digitisation is a redesign of the control model, not a scan of the documents.", "visual": {"type": "diagram", "diagram": {"centre": "A fully digital Letter of Credit", "parts": [{"label": "Paper process", "note": "The traditional document-heavy LC"}, {"label": "Digital process", "note": "End to end without paper"}, {"label": "Process change", "note": "What changes when the paper goes away"}, {"label": "Data change", "note": "What data the digital LC carries"}, {"label": "Controls change", "note": "What controls replace paper checks"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D13 Payments product and business", "messages": []}, {"id": "ABH-09", "seq": 9, "module": "Foundations", "source": "Public post", "title": "Asia banking: real-time, API-first, cloud", "explain": "Banking in Asia is moving to real-time payments, API-first design, cloud and ISO 20022, and that shift opens a new engineering opportunity for people who understand both technology and the banking transaction lifecycle. The winners are the ones who can bridge the two.", "takeaway": "The winners are the ones who can bridge the two.", "visual": {"type": "diagram", "diagram": {"centre": "Asia's banking upgrade", "parts": [{"label": "Real-time payments", "note": "Banking moves to payments that settle instantly"}, {"label": "API-first design", "note": "Systems built around APIs from the start"}, {"label": "Cloud", "note": "Banking runs on cloud platforms"}, {"label": "ISO 20022", "note": "The common message standard for the shift"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": []}, {"id": "INS-121", "seq": 10, "module": "Foundations", "source": "Public post", "title": "Direct debit: the creditor pulls on the due date", "explain": "Direct debit is the collection method European businesses rely on for recurring payments such as subscriptions and utility bills, because the creditor initiates the pull on the due date instead of waiting for the debtor to pay. That creditor-driven timing is the whole point: it puts the collection schedule under the creditor's control and cuts late payment. It only works when the mandate, the Creditor Identifier and the scheme rules are all set up correctly, so a collection flow has to be designed around those three prerequisites from the start.", "takeaway": "It only works when the mandate, the Creditor Identifier and the scheme rules are all set up correctly, so a collection flow has to be designed around those three prerequisites from the start.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor-initiated recurring collections", "parts": [{"label": "Recurring collections", "note": "Subscriptions and utility bills are the classic recurring collections"}, {"label": "Creditor pulls funds", "note": "Creditor initiates the pull on the due date, the debtor does not pay"}, {"label": "Timing control", "note": "Creditor controls the collection schedule and cuts late payment"}, {"label": "Mandate", "note": "Mandate must be in place before any collection can run"}, {"label": "Creditor Identifier", "note": "Identifier must be correct for the collection to be recognised"}, {"label": "Scheme rules", "note": "Scheme rules govern how the collection is set up and run"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D13 Payments product and business", "messages": []}, {"id": "INS-122", "seq": 11, "module": "Foundations", "source": "Public post", "title": "Creditor and Creditor Identifier in SDD", "explain": "In SEPA Direct Debit the creditor is the business collecting the money, and the Creditor Identifier is the unique code that identifies that creditor across the scheme. The identifier travels with every collection, so the debtor bank and the debtor can both recognise who is pulling the funds. No correct identifier means no collection can be initiated or matched to the right creditor, so the identifier is a gating data item, not a label.", "takeaway": "No correct identifier means no collection can be initiated or matched to the right creditor, so the identifier is a gating data item, not a label.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor and Creditor Identifier", "parts": [{"label": "Creditor", "note": "Business collecting the money in SEPA Direct Debit"}, {"label": "Creditor Identifier", "note": "Unique code identifying that creditor across the scheme"}, {"label": "Travels with collection", "note": "Identifier travels with every collection in the scheme"}, {"label": "Debtor bank recognition", "note": "Debtor bank recognises who is pulling the funds"}, {"label": "Debtor recognition", "note": "Debtor recognises who is pulling the funds"}, {"label": "Correct identifier needed", "note": "Without it, no collection can be initiated or matched"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "INS-125", "seq": 12, "module": "Foundations", "source": "Public post", "title": "The four-corner model of a direct debit", "explain": "A SEPA Direct Debit moves through four corners: the creditor, the creditor PSP, the clearing and settlement mechanism, and the debtor PSP with the debtor. The creditor sends the collection file to its PSP, the PSP passes it to the clearing system, and the debtor PSP debits the debtor account on the due date. Each corner owns a distinct responsibility, so when a collection fails the model pinpoints exactly which party owns the failure.", "takeaway": "Each corner owns a distinct responsibility, so when a collection fails the model pinpoints exactly which party owns the failure.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Creditor sends collection file", "note": "Creditor sends the collection file to its PSP"}, {"kind": "step", "title": "Creditor PSP receives file", "note": "Creditor PSP receives the collection file from the creditor"}, {"kind": "step", "title": "Clearing system processes it", "note": "PSP passes the collection to the clearing system"}, {"kind": "step", "title": "Debtor PSP debits debtor", "note": "Debtor PSP debits the debtor account on the due date"}, {"kind": "decision", "title": "Which party owns a failure?", "note": "Model shows which corner owns the failure"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "INS-124", "seq": 13, "module": "Foundations", "source": "Public post", "title": "Due date, debit date and settlement date", "explain": "The due date is the date the creditor wants the money, the debit date is the date the debtor account is actually debited, and the settlement date is the date the funds move between the banks. The three dates often fall on the same day, but they can split apart when a PSP is closed or the clearing system is unavailable. Confusing them produces wrong value dating and reconciliation breaks, so each date must be tracked as a separate fact.", "takeaway": "Confusing them produces wrong value dating and reconciliation breaks, so each date must be tracked as a separate fact.", "visual": {"type": "diagram", "diagram": {"centre": "Due, debit and settlement dates", "parts": [{"label": "Due date", "note": "Date the creditor wants the money"}, {"label": "Debit date", "note": "Date the debtor account is actually debited"}, {"label": "Settlement date", "note": "Date the funds move between the banks"}, {"label": "Often the same day", "note": "Three dates often fall on the same day"}, {"label": "Dates can differ", "note": "Dates split when a PSP is closed or clearing is unavailable"}, {"label": "Wrong dating risk", "note": "Confusing them causes wrong value dating and reconciliation breaks"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "INS-126", "seq": 14, "module": "Foundations", "source": "Public post", "title": "Pre-notification is not collection submission", "explain": "Pre-notification is the notice the creditor sends the debtor before the collection, stating the amount and the date, while collection submission is the creditor PSP sending the collection file into the scheme for processing. The two steps run on different timelines, and generating the file is not the same as notifying the customer. If the amount changes and the pre-notification is not updated, the debtor can dispute the collection, so the notice and the file must stay in step.", "takeaway": "If the amount changes and the pre-notification is not updated, the debtor can dispute the collection, so the notice and the file must stay in step.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Pre-notification sent", "note": "Creditor notifies the debtor of the amount and the date"}, {"kind": "step", "title": "Collection file generated", "note": "Creditor generates the collection file for submission"}, {"kind": "step", "title": "Collection submitted", "note": "Creditor PSP sends the file into the scheme for processing"}, {"kind": "decision", "title": "Amount changed without update?", "note": "Unchanged notice after an amount change opens a dispute"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "INS-157", "seq": 15, "module": "Foundations", "source": "Public post", "title": "Pre-notification: 14 days unless agreed otherwise", "explain": "The scheme expects the creditor to notify the debtor before each collection, usually 14 calendar days in advance, unless creditor and debtor have agreed a different timeline. Any agreed alternative must be evidenced, so the creditor can prove the debtor accepted a shorter notice period. A shorter notice with no agreement behind it leaves the collection open to dispute, so the evidence is as much part of the collection as the notice itself.", "takeaway": "A shorter notice with no agreement behind it leaves the collection open to dispute, so the evidence is as much part of the collection as the notice itself.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor pre-notification agreement", "parts": [{"label": "Notify before collection", "note": "Creditor notifies the debtor before each collection"}, {"label": "14 calendar days", "note": "Notice is usually 14 calendar days in advance"}, {"label": "Agreed alternative", "note": "Creditor and debtor can agree a different timeline"}, {"label": "Evidence required", "note": "Agreed alternative must be evidenced by the creditor"}, {"label": "Shorter notice risk", "note": "Shorter notice without agreement leaves the collection open to dispute"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "INS-128", "seq": 16, "module": "Foundations", "source": "Public post", "title": "Calendar days are not banking business days", "explain": "Some scheme timelines run in calendar days and others in banking business days, and applying the wrong calendar produces the wrong date. Pre-notification, refund windows and scheme timelines each specify which calendar applies, so no two timelines can be assumed to work the same way. The discipline is simple: check the calendar for each timeline before computing any date.", "takeaway": "The discipline is simple: check the calendar for each timeline before computing any date.", "visual": {"type": "diagram", "diagram": {"centre": "Scheme timeline calendars", "parts": [{"label": "Calendar days", "note": "Some scheme timelines are counted in calendar days"}, {"label": "Banking business days", "note": "Other timelines are counted in banking business days"}, {"label": "Pre-notification", "note": "Pre-notification specifies which calendar applies"}, {"label": "Refund windows", "note": "Refund windows specify which calendar applies"}, {"label": "Scheme timelines", "note": "Each scheme timeline specifies which calendar applies"}, {"label": "Check each timeline", "note": "Analyst must check the calendar for each timeline"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-139", "seq": 19, "module": "Foundations", "source": "Public post", "title": "UETR: one reference across every hop", "explain": "The UETR is a unique end-to-end transaction reference that stays with a payment across every bank and system it passes through. It lets any party trace the payment and ask each hop for its status using the same reference. A UETR proves the payment exists and can be tracked, but it does not by itself prove where the money is or that it settled, so tracking and settlement evidence must never be confused.", "takeaway": "A UETR proves the payment exists and can be tracked, but it does not by itself prove where the money is or that it settled, so tracking and settlement evidence must never be confused.", "visual": {"type": "diagram", "diagram": {"centre": "UETR tracking reference", "parts": [{"label": "Unique reference", "note": "Unique end-to-end transaction reference for the payment"}, {"label": "Stays with the payment", "note": "Stays with the payment across every bank and system it passes through"}, {"label": "Trace the payment", "note": "Lets any party trace the payment end to end"}, {"label": "Status enquiry", "note": "Each hop can be asked for its status using the same reference"}, {"label": "Proves existence", "note": "Proves the payment exists and can be tracked"}, {"label": "Does not prove settlement", "note": "Does not by itself prove where the money is or that it settled"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": []}, {"id": "INS-152", "seq": 20, "module": "Foundations", "source": "Public post", "title": "Instant credit is not instant settlement", "explain": "When a customer sends an instant payment, the beneficiary may see the credit within seconds, but the banks behind the payment may still settle between themselves later. The customer experience, the scheme processing and the settlement finality are three different things that do not always happen at the same moment. A payment can look instant to the customer while the interbank settlement is still pending, so the screen is never proof of finality.", "takeaway": "A payment can look instant to the customer while the interbank settlement is still pending, so the screen is never proof of finality.", "visual": {"type": "diagram", "diagram": {"centre": "Instant payment versus settlement", "parts": [{"label": "Customer credit in seconds", "note": "Beneficiary may see the credit within seconds"}, {"label": "Banks settle later", "note": "Banks behind the payment may still settle between themselves later"}, {"label": "Customer experience", "note": "Customer experience is one of three different things"}, {"label": "Scheme processing", "note": "Scheme processing does not always happen at the same moment"}, {"label": "Settlement finality", "note": "Settlement finality does not always happen at the same moment"}, {"label": "Looks instant, still pending", "note": "Payment can look instant while interbank settlement is still pending"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-168", "seq": 21, "module": "Foundations", "source": "Public post", "title": "G20 targets for cross-border payments", "explain": "The G20 set targets for cross-border payments covering speed, cost, transparency and access, so that sending money across borders becomes cheaper, faster and easier to track. These are goals for the industry, not guarantees for a single payment, and each target needs concrete product and operational measures to be met. A business analyst uses the objectives to judge whether a corridor design is actually improving the customer outcome, which is the only test that matters.", "takeaway": "A business analyst uses the objectives to judge whether a corridor design is actually improving the customer outcome, which is the only test that matters.", "visual": {"type": "diagram", "diagram": {"centre": "G20 cross-border payment objectives", "parts": [{"label": "Speed", "note": "Sending money across borders faster"}, {"label": "Cost", "note": "Sending money across borders cheaper"}, {"label": "Transparency", "note": "Sending money easier to track"}, {"label": "Access", "note": "Cross-border payments easier to reach"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-A11", "seq": 23, "module": "Foundations", "source": "Public post", "title": "camt.052, camt.053, camt.054: three views, one account", "explain": "Liquidity management turns on when funds are available, not only how much, and camt.052, camt.053 and camt.054 each give a different view of the same account. The camt.052 account report shows the position accumulated so far today, the camt.053 statement shows the end-of-day position, and the camt.054 notification reports individual debits and credits as they occur. With a EUR 9 million opening balance, EUR 4 million coming in and a EUR 6 million payment to make, the intraday view shows EUR 7 million only if the incoming payment arrives in time, so relying on camt.053 alone misses the intraday picture entirely.", "takeaway": "With a EUR 9 million opening balance, EUR 4 million coming in and a EUR 6 million payment to make, the intraday view shows EUR 7 million only if the incoming payment arrives in time, so relying on camt.053 alone misses the intraday picture entirely.", "visual": {"type": "diagram", "diagram": {"centre": "Three views of one account", "parts": [{"label": "camt.052 intraday report", "note": "Shows the position accumulated so far today"}, {"label": "camt.053 end-of-day statement", "note": "Shows the end-of-day position after the close of business"}, {"label": "camt.054 notification", "note": "Reports individual debits and credits as they occur"}, {"label": "EUR 9 million opening balance", "note": "Opening balance with EUR 4 million coming in and EUR 6 million to pay"}, {"label": "EUR 7 million intraday", "note": "Intraday view shows EUR 7 million only if the incoming payment arrives in time"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["camt.052", "camt.053", "camt.054"]}, {"id": "JEB-A13", "seq": 24, "module": "Foundations", "source": "Public post", "title": "pain.001 for ten: three on-us payments need no pacs.008", "explain": "A pain.001 file promises a batch of payments, yet not every payment in the file becomes a pacs.008: when a corporate submits 10 payments and only 7 pacs.008 messages reach the next bank, the other 3 are on-us payments, where sender and beneficiary hold accounts with the same bank and the payment is handled internally. Counting only pacs.008 messages shows 7 payments and suggests 3 are missing, while comparing the file total with the message count reveals the 3 on-us payments and explains the gap. A pain.001 is therefore a promise that payments will be made, not a guarantee of a pacs.008 for each one.", "takeaway": "A pain.001 is therefore a promise that payments will be made, not a guarantee of a pacs.008 for each one.", "visual": {"type": "diagram", "diagram": {"centre": "pain.001 promises ten payments", "parts": [{"label": "10 payments submitted", "note": "Corporate submits 10 payments in the pain.001 file"}, {"label": "7 pacs.008 messages", "note": "Only 7 pacs.008 messages reach the next bank"}, {"label": "3 on-us payments", "note": "Sender and beneficiary hold accounts with the same bank, handled internally"}, {"label": "Comparing file and message counts", "note": "Comparing the file total with the message count explains the gap"}, {"label": "Promise, not guarantee", "note": "A pain.001 promises payments, not a pacs.008 for each one"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pain.001", "pacs.008"]}, {"id": "JEB-B01", "seq": 25, "module": "Foundations", "source": "Public post", "title": "Payment confirmation: trust the reply, not the debit", "explain": "Confirmation in payments comes from the receiving side, not from the debit: on PhonePe, Payment Successful appears only after the beneficiary bank confirms the credit and UPI passes that reply back. In UPI the reply is RespPay, carrying credited or failed, and ISO 20022 schemes carry the same step under a different name, pacs.002, the Payment Status Report. A payment therefore stands confirmed only when the receiving side returns a status, so trust the confirmation, not the debit.", "takeaway": "A payment therefore stands confirmed only when the receiving side returns a status, so trust the confirmation, not the debit.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The payer sends the payment and the debit is made", "title": "Payment sent, account debited"}, {"kind": "step", "note": "Success shows only after the beneficiary bank confirms the credit", "title": "Beneficiary bank confirms credit"}, {"kind": "step", "note": "In UPI the reply is RespPay and carries credited or failed", "title": "RespPay carries the result"}, {"kind": "step", "note": "ISO 20022 schemes carry the same step as pacs.002 status report", "title": "pacs.002 in ISO 20022"}, {"kind": "step", "note": "A payment is confirmed only when the receiving side sends back a status", "title": "Trust the confirmation"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": ["pacs.002", "RespPay"], "failure_category": "payment rejected or returned"}, {"id": "JEB-B11", "seq": 26, "module": "Foundations", "source": "Public post", "title": "Open Finance consent: know what you are agreeing to", "explain": "Consent to access financial information is not simply a yes to everything: when applying for a loan and seeing that request, check who is asking for the data, what data they want, why they need it, how often they will access it, and how long the consent is valid, because two services can need very different data for different purposes. Under India Account Aggregator ecosystem, consent can be revoked, and revoking it can stop further access to the data. Good consent states its purpose and duration plainly, with a clear way to withdraw, in plain language anyone can follow.", "takeaway": "Good consent states its purpose and duration plainly, with a clear way to withdraw, in plain language anyone can follow.", "visual": {"type": "diagram", "diagram": {"centre": "Know what you are agreeing to", "parts": [{"label": "Who is asking for your data?", "note": "Check who is asking for your data before clicking consent"}, {"label": "What data and why?", "note": "Check what data they want and why they need it"}, {"label": "How often and how long?", "note": "Check how often they will access it and how long the consent is valid"}, {"label": "Consent can be revoked", "note": "Under the Account Aggregator ecosystem, consent can be revoked"}, {"label": "Revoking stops further access", "note": "Revoking consent can stop further access to your data"}, {"label": "Clear purpose, duration, withdrawal", "note": "Good consent states a clear purpose, duration and way to withdraw"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "JEB-B14", "seq": 27, "module": "Foundations", "source": "Public post", "title": "Open Finance: the information moves, the account stays", "explain": "A salary account with one bank does not stop another bank from offering a competitive loan, because the financial relationship no longer has to sit with a single institution. One customer can hold an account with ICICI, a loan with SBI, insights with CRED and payments with Google Pay, while the salary account stays where it is. What moves between providers is the financial information, and it moves only with the customer consent. That reframes the competitive question: not how to become your bank, but how to become the provider chosen for the next financial need.", "takeaway": "That reframes the competitive question: not how to become your bank, but how to become the provider chosen for the next financial need.", "visual": {"type": "diagram", "diagram": {"centre": "The information moves, the account stays", "parts": [{"label": "Account with ICICI", "note": "One customer can hold an account with ICICI"}, {"label": "Loan with SBI", "note": "The same customer can hold a loan with SBI"}, {"label": "Insights with CRED", "note": "Insights can sit with CRED while payments sit with Google Pay"}, {"label": "Salary account stays put", "note": "The salary account stays where it is"}, {"label": "Information moves only with consent", "note": "Financial information moves between providers only with consent"}, {"label": "Become the chosen provider", "note": "The question becomes how to be the provider chosen for the next need"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "JEB-C11", "seq": 30, "module": "Foundations", "source": "Public post", "title": "Account aggregator: your money stays with your bank", "explain": "An account aggregator is not a bank and does not hold your money; it connects you to the financial institutions that do, giving you one dashboard across banks, mutual funds, insurers and NBFCs. Its three roles are pulling the data together, managing the customer consent before any access, and sharing the information with other financial institutions only with that consent. Apps like Paytm, PhonePe and Google Pay work the same way: they fetch and move money through your banks without holding it themselves. The single most important role of the aggregator is consent management, because it never holds the funds it connects you to.", "takeaway": "The single most important role of the aggregator is consent management, because it never holds the funds it connects you to.", "visual": {"type": "diagram", "diagram": {"centre": "Your money stays with your bank", "parts": [{"label": "Not a bank, holds no money", "note": "An account aggregator is not a bank and does not hold your money"}, {"label": "One dashboard across providers", "note": "One dashboard across banks, mutual funds, insurers and NBFCs"}, {"label": "Pulling the data together", "note": "One of its three roles is pulling the data together"}, {"label": "Managing customer consent", "note": "It manages the customer consent before any access"}, {"label": "Sharing only with consent", "note": "It shares information with other institutions only with that consent"}, {"label": "Consent is the most important role", "note": "Consent management matters most because it never holds the funds"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "JEB-C13", "seq": 31, "module": "Foundations", "source": "Public post", "title": "Three accounts, one place: what Open Banking allows", "explain": "Open Banking uses APIs and the Account Information Service to let one app show accounts held at several banks, so a customer can see three accounts in one place without switching apps. An account aggregator combines those accounts into a single dashboard, and the aggregated data can also support payments and loan eligibility decisions. The test is whether the app reaches the banking information through open APIs; if it locks the data in instead, that is monetisation of a latch-on mechanism, not Open Banking. A customer should not need a new bank account merely to view other accounts.", "takeaway": "A customer should not need a new bank account merely to view other accounts.", "visual": {"type": "diagram", "diagram": {"centre": "Three accounts, one place", "parts": [{"label": "APIs and Account Information Service", "note": "Open Banking uses APIs and the Account Information Service"}, {"label": "Three accounts in one place", "note": "A customer can see three accounts in one place without switching apps"}, {"label": "Aggregator combines the accounts", "note": "An account aggregator combines those accounts into a single dashboard"}, {"label": "Data supports payments and loans", "note": "Aggregated data can support payments and loan eligibility decisions"}, {"label": "Open APIs, not locked-in data", "note": "If the app locks the data in, that is monetisation, not Open Banking"}, {"label": "No new account needed to view", "note": "A customer should not need a new bank account merely to view accounts"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "JEB-C15", "seq": 32, "module": "Foundations", "source": "Public post", "title": "Open Banking is accounts; Open Finance is the whole life", "explain": "Open Banking lets one app show a customer bank accounts, track expenses, pay bills or apply for a loan, but it covers only bank accounts. Open Finance goes further, letting insurers, mutual fund companies and banks share information about investments, insurance, pensions and mortgages through APIs, always with the customer consent. Fintech apps like Paytm and PhonePe are not banks; they connect to banks to share account information, and Open Finance extends that same consented sharing beyond banking. The difference is scope: Open Banking is banking data, Open Finance is the customer whole financial life.", "takeaway": "The difference is scope: Open Banking is banking data, Open Finance is the customer whole financial life.", "visual": {"type": "diagram", "diagram": {"centre": "Open Finance is the whole financial life", "parts": [{"label": "Open Banking: bank accounts only", "note": "Open Banking covers only bank accounts"}, {"label": "Track expenses, pay bills, apply for loans", "note": "One app can show accounts, track expenses, pay bills or apply for a loan"}, {"label": "Open Finance goes further", "note": "Insurers, mutual funds and banks share information through APIs"}, {"label": "Investments, insurance, pensions, mortgages", "note": "Open Finance covers investments, insurance, pensions and mortgages"}, {"label": "Always with customer consent", "note": "Sharing always happens with the customer consent"}, {"label": "Fintech apps are not banks", "note": "Apps like Paytm and PhonePe connect to banks, they do not hold the money"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "INS-070", "seq": 42, "module": "Foundations", "source": "Public post", "title": "Payment gateway versus payment processor", "explain": "The gateway orchestrates the payment: it connects the merchant to the payment methods, routes the instruction and returns the outcome. The processor performs the transaction processing: it moves the instruction through authorisation, clearing and settlement with the scheme and the banks. Some providers do both, so check which role a provider actually performs before assuming what it is responsible for. Confusing the two roles means blaming the wrong party when a payment fails.", "takeaway": "Confusing the two roles means blaming the wrong party when a payment fails.", "visual": {"type": "diagram", "diagram": {"centre": "Gateway orchestrates, processor executes", "parts": [{"label": "Payment gateway", "note": "Connects the merchant, routes the instruction, returns the outcome."}, {"label": "Payment processor", "note": "Moves the instruction through authorisation, clearing and settlement."}, {"label": "Both roles", "note": "Some providers do both, so check which role is performed."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "system or connectivity failure", "resolution": "return"}, {"id": "PAI-C001", "seq": 49, "module": "Foundations", "source": "Article and reader comments", "title": "Serial versus cover: two ways funds move", "explain": "The serial method moves funds and payment information together down one chain, each bank passing the same instruction onward to the next. The cover method splits them: the instruction travels in an MT103 while the funds settle separately through an MT202 COV, so each leg is settled on its own. The method chosen governs tracking, charging and returns, so it must be identified before any of those are handled.", "takeaway": "The method chosen governs tracking, charging and returns, so it must be identified before any of those are handled.", "visual": {"type": "diagram", "diagram": {"centre": "Serial versus cover", "parts": [{"label": "Serial payment", "note": "Funds and instruction travel together in one chain"}, {"label": "Cover payment", "note": "Instruction in MT103, funds settle separately in MT202 COV"}, {"label": "Why the method matters", "note": "It governs tracking, charges and return handling"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103", "MT202"], "failure_category": "charge deduction", "resolution": "return"}, {"id": "PAI-C002", "seq": 50, "module": "Foundations", "source": "Article and reader comments", "title": "MT202 COV is not a plain MT202", "explain": "An MT202 COV exists to settle a specific MT103: it moves the funds for that customer payment and carries the reference that binds the two messages together. A plain MT202 is a bank's own transfer, moving proprietary funds between banks with no customer payment behind it. Both move money between banks, yet only the COV answers to a customer instruction, and that distinction is what trips people up.", "takeaway": "Both move money between banks, yet only the COV answers to a customer instruction, and that distinction is what trips people up.", "visual": {"type": "diagram", "diagram": {"centre": "MT202 COV versus plain MT202", "parts": [{"label": "MT202 COV", "note": "Settles a named MT103, carries the linking reference"}, {"label": "Plain MT202", "note": "Own funds between banks, no customer payment behind it"}, {"label": "Common error", "note": "Both move bank funds, only the COV answers to a customer instruction"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT202", "MT103"]}, {"id": "PAI-C004", "seq": 52, "module": "Foundations", "source": "Article and reader comments", "title": "MT103 pays customers, MT202 moves bank funds", "explain": "An MT103 is a customer payment instruction: it orders the receiving bank to pay a named beneficiary a named amount. An MT202 is a bank-to-bank instruction that moves funds between banks with no customer beneficiary attached. Every customer payment starts with an MT103, and an MT202 appears only when a separate funds leg is required.", "takeaway": "Every customer payment starts with an MT103, and an MT202 appears only when a separate funds leg is required.", "visual": {"type": "diagram", "diagram": {"centre": "MT103 and MT202: which does what", "parts": [{"label": "MT103", "note": "Customer instruction to pay a named beneficiary"}, {"label": "MT202", "note": "Bank-to-bank funds movement, no customer beneficiary"}, {"label": "When both appear", "note": "A customer payment gains an MT202 only for a separate funds leg"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"]}, {"id": "PAI-C005", "seq": 53, "module": "Foundations", "source": "Article and reader comments", "title": "Reading an MT103: fields 59 and 57", "explain": "Field 59 names the beneficiary customer and the account to be credited, so it is the first field to check when a payment must reach the right person. Field 57 names the beneficiary bank by BIC, telling the chain which bank must receive the instruction. In a serial payment each bank reads both fields from the MT103 it receives and forwards the message to the next bank in the chain.", "takeaway": "In a serial payment each bank reads both fields from the MT103 it receives and forwards the message to the next bank in the chain.", "visual": {"type": "diagram", "diagram": {"centre": "Reading an MT103", "parts": [{"label": "Field 59: beneficiary customer", "note": "Names the beneficiary and the account to credit"}, {"label": "Field 57: beneficiary bank", "note": "Names the receiving bank by BIC"}, {"label": "Each bank reads and forwards", "note": "Each bank reads both fields and passes the message onward"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "PAI-C006", "seq": 54, "module": "Foundations", "source": "Article and reader comments", "title": "MT103 fields 50 and 72: who pays, what else", "explain": "Field 50 identifies the ordering customer, the party who instructed the payment, and it is the first field screening and reconciliation check. Field 72 carries sender-to-receiver information, the extra instructions that fit no structured field. The two fields answer different questions: field 50 says who is paying, field 72 says what else the receiver needs to know.", "takeaway": "The two fields answer different questions: field 50 says who is paying, field 72 says what else the receiver needs to know.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 50 and 72 in an MT103", "parts": [{"label": "Field 50: ordering customer", "note": "Names the instructing party, first check for screening"}, {"label": "Field 72: sender-to-receiver information", "note": "Extra instructions with no structured field of their own"}, {"label": "Different purposes", "note": "Field 50 names the payer, field 72 carries the extra detail"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103"]}, {"id": "PAI-C007", "seq": 55, "module": "Foundations", "source": "Article and reader comments", "title": "SDD Core versus SDD B2B: the refund divide", "explain": "SDD Core covers collections from consumers and businesses, and it gives the debtor an eight-week refund right with no reason required. SDD B2B is restricted to business-to-business collections and grants no such refund right, which is why the debtor bank must verify the mandate before the first collection. The schemes differ on refunds and mandate checks, so using the wrong one is a real error, not a paperwork slip.", "takeaway": "The schemes differ on refunds and mandate checks, so using the wrong one is a real error, not a paperwork slip.", "visual": {"type": "diagram", "diagram": {"centre": "SDD Core versus SDD B2B", "parts": [{"label": "SDD Core", "note": "Consumers and businesses, eight-week refund without reason"}, {"label": "SDD B2B", "note": "Business to business only, no refund right"}, {"label": "Mandate check", "note": "Debtor bank verifies the mandate before the first collection"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "return"}, {"id": "PAI-C008", "seq": 56, "module": "Foundations", "source": "Article and reader comments", "title": "A SEPA payment is defined by its scheme", "explain": "A SEPA payment is defined by scheme rules on timing, reason codes and returns, not by the message format that happens to carry it. The format is only the envelope: the same payment can be initiated with an MT101 or an MT103 as well as with a pain.001. That is why an MT103 and a pacs.008 can carry one underlying SEPA payment, the pacs.008 being its ISO 20022 form.", "takeaway": "That is why an MT103 and a pacs.008 can carry one underlying SEPA payment, the pacs.008 being its ISO 20022 form.", "visual": {"type": "diagram", "diagram": {"centre": "A SEPA payment", "parts": [{"label": "Defined by scheme rules", "note": "Timing, reason codes and returns come from the scheme"}, {"label": "Format is the envelope", "note": "MT101, MT103 or pain.001 can all initiate it"}, {"label": "MT103 and pacs.008 carry the same payment", "note": "One payment, with pacs.008 as its ISO 20022 form"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pain.001", "pacs.008", "MT101", "MT103"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C059", "seq": 59, "module": "Foundations", "source": "Article and reader comments", "title": "MT to MX: the same legs, new names", "explain": "A pacs.008 is the ISO 20022 customer credit transfer, the equivalent of an MT103, and a pacs.009 is the financial institution credit transfer, the equivalent of an MT202. A pacs.004 is the payment return, used when a pacs.008 cannot be applied and the funds must go back. The two families describe the same payments, so a team moving from MT to MX only has to learn the new names for the same legs.", "takeaway": "The two families describe the same payments, so a team moving from MT to MX only has to learn the new names for the same legs.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.008, pacs.009 and pacs.004", "parts": [{"label": "pacs.008", "note": "Customer credit transfer, the MT103 equivalent"}, {"label": "pacs.009", "note": "Financial institution transfer, the MT202 equivalent"}, {"label": "pacs.004", "note": "Payment return when a pacs.008 cannot be applied"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008", "pacs.009", "pacs.004", "MT103", "MT202"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C068", "seq": 60, "module": "Foundations", "source": "Article and reader comments", "title": "Corporates instruct with MT101, banks pay", "explain": "A corporation connected to SWIFT instructs its bank with an MT101, and it is the bank that sends the MT103, or the MT103 plus an MT202 COV, into the interbank chain. Even a corporate with its own BIC and a direct relationship with a clearer does not send an MT103 itself. The rule is simple: corporates instruct, banks pay.", "takeaway": "The rule is simple: corporates instruct, banks pay.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate instructs its bank with MT101", "note": "A corporation connected to SWIFT instructs its bank with an MT101"}, {"kind": "step", "title": "Bank sends MT103 into the chain", "note": "The bank sends the MT103, or the MT103 plus an MT202 COV, into the chain"}, {"kind": "step", "title": "Corporate with own BIC still instructs", "note": "Even a corporate with its own BIC and a clearer relationship does not send an MT103"}, {"kind": "step", "title": "Corporates instruct, banks pay", "note": "The rule is simple: corporates instruct, banks pay"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT101", "MT103", "MT202"]}, {"id": "PAI-C077", "seq": 61, "module": "Foundations", "source": "Article and reader comments", "title": "Nostro and vostro: one account, two names", "explain": "When a bank holds an account with another bank in a foreign currency, it calls that account a nostro account, meaning our account with you. The bank that holds the account calls the very same account a vostro account, meaning your account with us. There is only one account, and the two words simply say which side of it each bank is standing on.", "takeaway": "There is only one account, and the two words simply say which side of it each bank is standing on.", "visual": {"type": "diagram", "diagram": {"centre": "Nostro and vostro: one account", "parts": [{"label": "Nostro: our account with you", "note": "A bank calls its foreign currency account with another bank a nostro account"}, {"label": "Vostro: your account with us", "note": "The bank holding the account calls the same account a vostro account"}, {"label": "Only one account exists", "note": "One account only; the two words say which side each bank stands on"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C080", "seq": 62, "module": "Foundations", "source": "Article and reader comments", "title": "Block 2: input or output depends on your side", "explain": "Block 2 of a SWIFT message, the application header, says whether the message is entering or leaving the SWIFT network. The same payment looks different from the two sides: from the sending bank it is an input message, and from the receiving bank it is an output message. An operator reading a stored message must therefore know which bank's copy it is looking at before deciding what block 2 means.", "takeaway": "An operator reading a stored message must therefore know which bank's copy it is looking at before deciding what block 2 means.", "visual": {"type": "diagram", "diagram": {"centre": "Block 2: input or output", "parts": [{"label": "Application header of a SWIFT message", "note": "Block 2 of a SWIFT message is the application header"}, {"label": "Says whether the message enters or leaves", "note": "Block 2 says whether the message enters or leaves the SWIFT network"}, {"label": "Sending bank sees an input message", "note": "From the sending bank the same payment is an input message"}, {"label": "Receiving bank sees an output message", "note": "From the receiving bank it is an output message"}, {"label": "Know whose copy you are reading", "note": "Know which bank's copy you hold before reading block 2"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C083", "seq": 63, "module": "Foundations", "source": "Article and reader comments", "title": "One MT103, one beneficiary", "explain": "An MT103 carries a single beneficiary in field 59, so one message pays one beneficiary at one bank. A payment that must reach a seller and a manufacturer at different banks needs two separate MT103 messages, one for each beneficiary. Trying to name two beneficiaries in a single MT103 is not possible, because the message has nowhere to put the second one.", "takeaway": "Trying to name two beneficiaries in a single MT103 is not possible, because the message has nowhere to put the second one.", "visual": {"type": "diagram", "diagram": {"centre": "One MT103, one beneficiary", "parts": [{"label": "Field 59 carries a single beneficiary", "note": "An MT103 carries a single beneficiary in field 59"}, {"label": "One message, one beneficiary, one bank", "note": "One message pays one beneficiary at one bank"}, {"label": "Seller and manufacturer need two MT103s", "note": "A seller and a manufacturer at different banks need two MT103 messages"}, {"label": "No place for a second beneficiary", "note": "Two beneficiaries cannot be named in one MT103; there is nowhere for the second"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT103"]}, {"id": "PAI-C085", "seq": 64, "module": "Foundations", "source": "Article and reader comments", "title": "Field 32A: value date, currency, settlement amount", "explain": "Field 32A carries three things: the value date in year-month-day order, the currency, and the interbank settlement amount. The value date is the date the funds are to be available to the receiver, not the date the message was sent. The currency in field 32A is the currency the receiver's bank actually receives, which is why it can differ from the currency the ordering customer instructed in field 33B.", "takeaway": "The currency in field 32A is the currency the receiver's bank actually receives, which is why it can differ from the currency the ordering customer instructed in field 33B.", "visual": {"type": "diagram", "diagram": {"centre": "Field 32A in an MT103", "parts": [{"label": "Value date in year-month-day order", "note": "Field 32A carries the value date in year-month-day order"}, {"label": "Value date is when funds are available", "note": "The value date is when funds are to be available to the receiver, not the date sent"}, {"label": "Currency the receiver actually gets", "note": "The currency in field 32A is the currency the receiver's bank actually receives"}, {"label": "Interbank settlement amount", "note": "Field 32A carries the interbank settlement amount"}, {"label": "Currency can differ from field 33B", "note": "The currency in 32A can differ from the currency instructed in field 33B"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C091", "seq": 65, "module": "Foundations", "source": "Article and reader comments", "title": "The restricted SWIFT character set", "explain": "SWIFT MT messages use a restricted character set, and characters outside it cannot be used in a message at all. That is why country-specific characters, such as Japanese or Thai script, cannot appear in an MT101 or an MT103, even when the underlying instruction is domestic. Names and addresses must be written with the characters the SWIFT set allows, or the message will not be accepted.", "takeaway": "Names and addresses must be written with the characters the SWIFT set allows, or the message will not be accepted.", "visual": {"type": "diagram", "diagram": {"centre": "The restricted SWIFT character set", "parts": [{"label": "Characters outside the set cannot be used", "note": "SWIFT MT messages use a restricted character set, and outside characters cannot be used"}, {"label": "Country-specific scripts excluded", "note": "Country-specific characters, like Japanese or Thai script, cannot appear in MT messages"}, {"label": "Applies even to domestic instructions", "note": "The restriction applies even when the underlying instruction is domestic"}, {"label": "Names must use the allowed characters", "note": "Names and addresses must use the allowed characters, or the message fails"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "MT103"]}, {"id": "PAI-C097", "seq": 66, "module": "Foundations", "source": "Article and reader comments", "title": "MT101: one message for three kinds of transfer", "explain": "An MT101 can move funds between an ordering customer's own accounts, in favour of a third party domestically, and in favour of a third party internationally. All three uses are valid, because the message is a general request for transfer, not a payment for one kind of beneficiary. The same message therefore serves a corporate moving money between its own accounts and a corporate paying a supplier abroad.", "takeaway": "The same message therefore serves a corporate moving money between its own accounts and a corporate paying a supplier abroad.", "visual": {"type": "diagram", "diagram": {"centre": "What an MT101 can move", "parts": [{"label": "Between the customer's own accounts", "note": "An MT101 can move funds between an ordering customer's own accounts"}, {"label": "In favour of a third party domestically", "note": "An MT101 can move funds in favour of a third party domestically"}, {"label": "In favour of a third party internationally", "note": "An MT101 can move funds in favour of a third party internationally"}, {"label": "A general request for transfer", "note": "The message is a general request for transfer, not for one kind of beneficiary"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "RUN3-009", "seq": 68, "module": "Foundations", "source": "Article and reader comments", "title": "MT900 and MT910 first, MT950 closes the day", "explain": "Through the day a bank sends MT900 and MT910 advices as each debit and credit lands on the account, so the owner hears about every movement as it happens. At day end the MT950 arrives and gathers all those movements into a single statement. The two must reconcile, since the advices and the statement describe the same day from different angles.", "takeaway": "The two must reconcile, since the advices and the statement describe the same day from different angles.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Advices go out through the day", "note": "MT900 and MT910 report each debit and credit as it lands."}, {"kind": "step", "title": "Owner sees each movement", "note": "Every advice tells the owner about one movement as it happens."}, {"kind": "step", "title": "MT950 arrives at day end", "note": "The statement gathers all the day movements into one document."}, {"kind": "step", "title": "Both must reconcile", "note": "Advices and statement describe the same day from two angles."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT900", "MT910", "MT950"]}, {"id": "RUN3-010", "seq": 69, "module": "Foundations", "source": "Article and reader comments", "title": "MT910: proof the credit has actually landed", "explain": "The MT910 goes from the account servicing bank to the account owner as confirmation that a credit has been posted. It is triggered by the credit entry itself, so it follows real posting rather than a mere instruction to pay. On receipt, the owner can treat the funds as received, with certainty that the account was credited.", "takeaway": "On receipt, the owner can treat the funds as received, with certainty that the account was credited.", "visual": {"type": "diagram", "diagram": {"centre": "MT910 confirmation of credit", "parts": [{"label": "Servicing bank to owner", "note": "The bank holding the account sends the MT910 to the account owner."}, {"label": "Triggered by the posting", "note": "It follows an actual credit entry, not a payment instruction."}, {"label": "Funds treated as received", "note": "Receipt confirms the credit has landed on the account."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D02 Accounts, ledger and accounting", "messages": ["MT910"]}, {"id": "RUN4-001", "seq": 70, "module": "Foundations", "source": "Article and reader comments", "title": "Nostro and mirror: only the real account holds funds", "explain": "When Bank A opens an account with Bank B, that account is Bank A's nostro, held in Bank B's books, and the real funds sit there. Bank A also keeps a mirror nostro in its own books, but the mirror holds no funds; it only reflects activity on the real account. The mirror is kept in the real account's currency, so a USD nostro carries a USD mirror, and the mirror lets a bank work out what the real account should show.", "takeaway": "The mirror is kept in the real account's currency, so a USD nostro carries a USD mirror, and the mirror lets a bank work out what the real account should show.", "visual": {"type": "diagram", "diagram": {"centre": "Nostro and its mirror", "parts": [{"label": "Real nostro at Bank B", "note": "Bank A's nostro sits in Bank B's books, where the funds are held."}, {"label": "Mirror nostro at Bank A", "note": "Bank A keeps a mirror in its own books; it holds no funds."}, {"label": "Same currency", "note": "The mirror is kept in the same currency as the real account."}, {"label": "Mirror reveals the real account", "note": "What the mirror shows lets a bank work out the real account position."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN4-004", "seq": 73, "module": "Foundations", "source": "Article and reader comments", "title": "Domestic payments never travel on SWIFT", "explain": "A payment inside one country runs through that country's own clearing and settlement systems, in local formats built on flat or XML files, and never touches the SWIFT network. SWIFT was created for cross-border payments, and the large majority of those still travel on it. Local networks carry local payments and SWIFT carries payments that cross a border; the two worlds stay separate.", "takeaway": "Local networks carry local payments and SWIFT carries payments that cross a border; the two worlds stay separate.", "visual": {"type": "diagram", "diagram": {"centre": "Domestic and cross-border rails", "parts": [{"label": "Local clearing for domestic", "note": "Payments inside one country run through that country's own systems."}, {"label": "Local formats", "note": "Domestic payments use flat or XML based local formats."}, {"label": "SWIFT untouched", "note": "A domestic payment never touches the SWIFT network."}, {"label": "SWIFT for cross-border", "note": "SWIFT was built for cross-border payments, and most still use it."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN4-005", "seq": 74, "module": "Foundations", "source": "Article and reader comments", "title": "Bid and ask: always read them from the bank's side", "explain": "Bid means buy and ask means sell, and the bank sets both prices, not the customer. The bank buys currency from the customer at the bid rate and sells it to the customer at the ask rate, so the customer buys at the higher ask and sells at the lower bid, and the bank keeps the difference. A base currency exporter therefore watches the ask price, while a base currency importer watches the bid price.", "takeaway": "A base currency exporter therefore watches the ask price, while a base currency importer watches the bid price.", "visual": {"type": "diagram", "diagram": {"centre": "Bid and ask, bank's side first", "parts": [{"label": "Bid is buy", "note": "Bid means buy; ask means sell, and the bank sets the prices."}, {"label": "Bank buys at bid", "note": "The bank buys currency from the customer at the bid rate."}, {"label": "Bank sells at ask", "note": "The bank sells currency to the customer at the ask rate."}, {"label": "Customer buys high, sells low", "note": "The customer buys at the ask and sells at the bid."}, {"label": "Exporter watches ask", "note": "A base currency exporter watches the ask price."}, {"label": "Importer watches bid", "note": "A base currency importer watches the bid price."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN4-006", "seq": 75, "module": "Foundations", "source": "Article and reader comments", "title": "Direct quote: domestic currency is the price currency", "explain": "In a direct quote, the quoted currency is the domestic one, and quoted and price currency mean the same thing. For a bank in the euro area quoting EUR/USD, the euro is therefore the domestic currency and the price is expressed in euros. Keeping this the right way round matters, because the direct and indirect quotes describe the same pair from opposite sides.", "takeaway": "Keeping this the right way round matters, because the direct and indirect quotes describe the same pair from opposite sides.", "visual": {"type": "diagram", "diagram": {"centre": "Direct quote, price in domestic currency", "parts": [{"label": "Domestic currency quoted", "note": "In a direct quote the quoted currency is the domestic one."}, {"label": "Quoted is price currency", "note": "Quoted currency and price currency mean the same thing."}, {"label": "EUR/USD example", "note": "A euro area bank quoting EUR/USD prices in euros."}, {"label": "Price expressed in euros", "note": "For that bank the price is expressed in euros."}, {"label": "Opposite of indirect", "note": "Direct and indirect quotes view the same pair from opposite sides."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN4-007", "seq": 76, "module": "Foundations", "source": "Article and reader comments", "title": "EUR/USD: buying and selling always mean the base", "explain": "In EUR/USD, EUR is the base currency and USD is the quoted currency, and every buy or sell refers to the base currency. Buying EUR/USD means receiving EUR and giving USD, while selling it means giving EUR and receiving USD. The quote number, such as 1.1635, states how much quoted currency one unit of the base is worth.", "takeaway": "The quote number, such as 1.1635, states how much quoted currency one unit of the base is worth.", "visual": {"type": "diagram", "diagram": {"centre": "EUR/USD: base first", "parts": [{"label": "EUR is base, USD quoted", "note": "In EUR/USD, EUR is the base currency and USD the quoted one."}, {"label": "Trade the base", "note": "Buying and selling always refer to the base currency."}, {"label": "Buy: receive EUR", "note": "Buying EUR/USD means receiving EUR and giving USD."}, {"label": "Sell: give EUR", "note": "Selling EUR/USD means giving EUR and receiving USD."}, {"label": "Quote number 1.1635", "note": "The number states the quoted currency one unit of base is worth."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN5-004", "seq": 77, "module": "Foundations", "source": "Article and reader comments", "title": "Card costs: merchant pays per deal, holder pays fees", "explain": "The costs of a card transaction split between the merchant and the cardholder, with each side paying for different things. The merchant is charged by the issuer and the processing chain for the transactions it accepts. The cardholder pays nothing per transaction, but pays the annual fee for the card and interest whenever a statement balance is not paid in full.", "takeaway": "The cardholder pays nothing per transaction, but pays the annual fee for the card and interest whenever a statement balance is not paid in full.", "visual": {"type": "diagram", "diagram": {"centre": "Who pays what on a card deal", "parts": [{"label": "Merchant pays issuer charges", "note": "The merchant is charged by the issuer and the processing chain."}, {"label": "No per-transaction fee for holder", "note": "The cardholder pays nothing per transaction."}, {"label": "Holder pays the annual fee", "note": "The cardholder pays the annual fee for the card."}, {"label": "Holder pays interest if unpaid", "note": "Interest applies whenever a statement balance is not paid in full."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "RUN5-006", "seq": 78, "module": "Foundations", "source": "Article and reader comments", "title": "Monthly fee versus processing fee: fixed versus volume", "explain": "A merchant pays two different fees to a payment processor, and the two are easy to confuse. The monthly fee is a fixed amount charged every month for using the payment processing service, with its level set by the processing firm. The payment processing fee is different: it is charged per transaction, so it rises and falls with the number of transactions the merchant processes.", "takeaway": "The payment processing fee is different: it is charged per transaction, so it rises and falls with the number of transactions the merchant processes.", "visual": {"type": "diagram", "diagram": {"centre": "Two merchant fees, easily confused", "parts": [{"label": "Monthly fee is fixed", "note": "A fixed amount charged every month for the processing service."}, {"label": "Processor sets the level", "note": "Its level is set by the processing firm."}, {"label": "Processing fee is per transaction", "note": "The payment processing fee is charged per transaction."}, {"label": "It rises with volume", "note": "It rises and falls with the number of transactions processed."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D13 Payments product and business", "messages": []}, {"id": "RUN5-008", "seq": 79, "module": "Foundations", "source": "Article and reader comments", "title": "Cheque clearing now runs on images, not paper", "explain": "A cheque no longer has to travel as paper to be collected. The beneficiary bank presents the cheque to the drawee bank, and in many countries it presents only an image of the cheque to collect the funds. Physical presentation is no longer required in those countries, which is why cheque clearing can run on images rather than on the movement of paper.", "takeaway": "Physical presentation is no longer required in those countries, which is why cheque clearing can run on images rather than on the movement of paper.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank presents the cheque", "note": "It presents the cheque to the drawee bank."}, {"kind": "step", "title": "Image presented, not paper", "note": "In many countries only an image is presented to collect funds."}, {"kind": "step", "title": "No physical presentation needed", "note": "Presenting the physical cheque is no longer required there."}, {"kind": "step", "title": "Clearing runs on images", "note": "Cheque clearing runs on images, not on moving paper."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-102", "seq": 80, "module": "Foundations", "source": "Public post", "title": "A payment is seven stages, not one action", "explain": "Treat a payment as a chain of seven stages, initiation, validation, processing, routing, clearing, settlement and confirmation, each with its own owner, status and failure mode. A file acknowledgement then means exactly what it says, receipt, and nothing about whether every supplier was paid. Diagnose by stage and evidence, because mistaking acceptance for settlement is how clearing rejections and returns stay hidden until a supplier complains.", "takeaway": "Diagnose by stage and evidence, because mistaking acceptance for settlement is how clearing rejections and returns stay hidden until a supplier complains.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Capture the instruction under a unique reference.", "title": "Capture the instruction"}, {"kind": "step", "note": "Check schema, fields, limits, account state and screening.", "title": "Validate the instruction"}, {"kind": "step", "note": "Enrich the instruction and reserve funds where required.", "title": "Process and enrich"}, {"kind": "step", "note": "Choose the clearing path and intermediary chain.", "title": "Select the route"}, {"kind": "step", "note": "Send the interbank message and await acceptance or rejection.", "title": "Clear the payment"}, {"kind": "step", "note": "Move funds between accounts, irrevocably.", "title": "Settle the funds"}, {"kind": "step", "note": "Update customer status and statements on authoritative evidence only.", "title": "Confirm to the customer"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": [], "resolution": "investigate"}, {"id": "INS-104", "seq": 81, "module": "Foundations", "source": "Public post", "title": "Network and standard are different things", "explain": "The confusion to kill first is between carrier and content: SWIFT is the network and service carrying messages between banks, ISO 20022 is the standard defining what those messages contain. The same payment can travel over SWIFT as older MT or newer MX messages, and changing the standard changes nothing about the network. Scope the migration accordingly, to message content, mapping and validation, not to a network change.", "takeaway": "Scope the migration accordingly, to message content, mapping and validation, not to a network change.", "visual": {"type": "diagram", "diagram": {"centre": "Carrier and content, kept apart", "parts": [{"label": "SWIFT: the network", "note": "The service carrying messages between banks."}, {"label": "ISO 20022: the standard", "note": "The standard defining message content."}, {"label": "MT family", "note": "Older message family, still in use."}, {"label": "MX family", "note": "ISO 20022 message family."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "INS-154", "seq": 82, "module": "Foundations", "source": "Public post", "title": "First collection starts with the mandate", "explain": "A collection cannot run before its mandate is set up and its authorisation evidence is in place. Creditor and debtor roles must be unambiguous, mandate data complete, and the same mandate reference carried through every downstream system the scheme will see. A first collection on an incomplete mandate is rejected, so put the setup check before the file is built, not after the rejection lands.", "takeaway": "A first collection on an incomplete mandate is rejected, so put the setup check before the file is built, not after the rejection lands.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Take the full mandate record.", "title": "Capture the mandate record"}, {"kind": "step", "note": "Evidence that the debtor agreed.", "title": "Confirm the authorisation evidence"}, {"kind": "step", "note": "One reference in every system.", "title": "Carry the reference downstream"}, {"kind": "step", "note": "Prove setup before building the file.", "title": "Validate ahead of the first collection"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "mandate issue"}, {"id": "INS-156", "seq": 83, "module": "Foundations", "source": "Public post", "title": "First or recurring: the mandate decides", "explain": "First and recurring collections are different instructions, even with the same amount and the same debtor. Sequence and mandate state decide which scheme data the collection carries and how the debtor bank treats it. Mark each collection first or recurring from the mandate state, never from a guess, because the wrong sequence processes the collection under the wrong rules.", "takeaway": "Mark each collection first or recurring from the mandate state, never from a guess, because the wrong sequence processes the collection under the wrong rules.", "visual": {"type": "diagram", "diagram": {"centre": "Sequence comes from the mandate", "parts": [{"label": "First debit", "note": "First debit under the mandate."}, {"label": "Later debits", "note": "Subsequent debits under the same mandate."}, {"label": "Mandate state decides", "note": "The state that fixes the sequence."}, {"label": "Data per sequence", "note": "Different data per sequence."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "SCN-15", "seq": 84, "module": "Foundations", "source": "Public post", "title": "Reject, return, cancel: settlement decides", "explain": "Reject, return and cancellation are three mechanisms separated by one boundary, settlement. A reject is a pre-settlement refusal reported by pacs.002 with an RJCT status, with no money moved. A return is a post-settlement reversal moving funds back through pacs.004, and a cancellation is a request to stop a queued or pending payment, sent by camt.055 or camt.056 and answered by camt.029.", "takeaway": "A return is a post-settlement reversal moving funds back through pacs.004, and a cancellation is a request to stop a queued or pending payment, sent by camt.055 or camt.056 and answered by camt.029.", "visual": {"type": "diagram", "diagram": {"centre": "One boundary, three paths", "parts": [{"label": "Rejection", "note": "Pre-settlement refusal on pacs.002 RJCT; no money moved."}, {"label": "Return of funds", "note": "Post-settlement reversal, pacs.004 returns funds."}, {"label": "Cancellation request", "note": "Stop a queued payment, camt.055 or camt.056."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": ["pacs.002", "pacs.004", "camt.055", "camt.056", "camt.029"], "failure_category": "payment rejected or returned"}, {"id": "SCN-17", "seq": 85, "module": "Foundations", "source": "Public post", "title": "pacs.002 reports; pacs.004 pays back", "explain": "The distinction is the money: a pacs.002 is a status report saying accepted, rejected or pending, and it moves nothing, while a pacs.004 is a payment return, an actual settlement instruction in reverse that can carry charges. Settlement is the boundary, before it pacs.002, after it pacs.004. Both draw on the same reference family, so systems can link the messages together.", "takeaway": "Both draw on the same reference family, so systems can link the messages together.", "visual": {"type": "diagram", "diagram": {"centre": "Report or money movement", "parts": [{"label": "pacs.002: status only", "note": "Accepted, rejected or pending; moves nothing."}, {"label": "pacs.004: money back", "note": "Settlement instruction in reverse."}, {"label": "The settlement boundary", "note": "Before settlement pacs.002, after it pacs.004."}, {"label": "References they share", "note": "UETR, MsgId and EndToEndId link them."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pacs.002", "pacs.004"], "failure_category": "payment rejected or returned"}, {"id": "SCN-20", "seq": 86, "module": "Foundations", "source": "Public post", "title": "The lifecycle in ISO 20022 messages", "explain": "Read a cross-border credit transfer as a chain of messages, not a single payment: pain.001 opens it from the customer, pain.002 answers acceptance or rejection, pacs.008 carries the interbank leg, pacs.002 reports status along the way, pacs.009 covers the funds where the cover method is used, and camt.052, camt.053 and camt.054 close the loop for reconciliation. Every step can branch into an exception with its own message, pacs.004 returns funds after settlement and camt.056 with camt.029 handles cancellation requests, so the message set is the lifecycle.", "takeaway": "Every step can branch into an exception with its own message, pacs.004 returns funds after settlement and camt.056 with camt.029 handles cancellation requests, so the message set is the lifecycle.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Customer initiation arrives.", "title": "pain.001: initiation"}, {"kind": "step", "note": "Bank answers acceptance or rejection per transaction.", "title": "pain.002: the bank answers"}, {"kind": "step", "note": "Interbank customer credit transfer between banks.", "title": "pacs.008: interbank transfer"}, {"kind": "step", "note": "ACTC, ACSP, ACSC and RJCT mark the journey.", "title": "pacs.002: status reports"}, {"kind": "step", "note": "Intraday, end-of-day and debit-credit notices close the loop.", "title": "camt: statements close the loop"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": ["pain.001", "pain.002", "pacs.008", "pacs.002", "pacs.009", "camt.052", "camt.053", "camt.054", "pacs.004", "camt.056", "camt.029"]}, {"id": "JEB-F12", "seq": 89, "module": "Foundations", "source": "Public post", "title": "SDD mandate lifecycle rests with the creditor", "explain": "Obtaining a mandate is only the beginning, because the creditor owns managing it throughout the customer relationship, and the lifecycle runs through creation, management, amendment, usage, cancellation and expiry, while a broken lifecycle can block future collections. Collections must be based on a valid mandate, and unlike a credit transfer, a direct debit is initiated by the creditor. Mandate management is therefore part of the payments journey, not only administration.", "takeaway": "Mandate management is therefore part of the payments journey, not only administration.", "visual": {"type": "diagram", "diagram": {"centre": "Mandate lifecycle", "parts": [{"label": "Creation", "note": "The debtor gives authorisation"}, {"label": "Management", "note": "Mandate information is properly maintained"}, {"label": "Amendment", "note": "Relevant changes are managed"}, {"label": "Usage", "note": "Collections are based on a valid mandate"}, {"label": "Cancellation and expiry", "note": "A mandate can be cancelled or become invalid"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "mandate issue"}, {"id": "JEB-F10", "seq": 90, "module": "Foundations", "source": "Public post", "title": "SEPA Direct Debit: why the mandate matters", "explain": "Every direct debit journey starts with a signature on a mandate, and from there the creditor can initiate recurring collections under the agreed arrangement. Direct debit runs to about 20 billion transactions a year within the EU, and the payoff is convenience for the customer, predictability for the business and lower collection cost for the merchant, while readers chose ISO 20022 payments as the next topic, ahead of US ACH. The journey runs from mandate through collection, rejection, return and refund, and its value lies in the business behind the payment method, not only in the mechanics.", "takeaway": "The journey runs from mandate through collection, rejection, return and refund, and its value lies in the business behind the payment method, not only in the mechanics.", "visual": {"type": "diagram", "diagram": {"centre": "Why SDD matters", "parts": [{"label": "Mandate first", "note": "Every journey starts with a signature"}, {"label": "20 billion transactions a year", "note": "Direct debit scale across the EU"}, {"label": "Customer convenience", "note": "Recurring payments without repeated action"}, {"label": "Business predictability", "note": "Collections follow the agreed arrangement"}, {"label": "Lower merchant cost", "note": "Cheaper collection than other payment methods"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-D03", "seq": 91, "module": "Foundations", "source": "Public post", "title": "One collection, three dates, three events", "explain": "Each date marks a different event: Due Date is when the collection falls due and the debtor PSP checks funds, Settlement Date is when interbank settlement moves funds to the creditor PSP through the CSM, and Debit Date is when the debtor account is actually debited. When both PSPs sit in the same SEPA country the three normally coincide, but across countries the debit can slip to the next Business Day, so the creditor PSP can be funded on the Due Date while the debtor account is debited a day later. The split is a calendar and processing-window effect, not an error, and each date must be read against its own event.", "takeaway": "The split is a calendar and processing-window effect, not an error, and each date must be read against its own event.", "visual": {"type": "diagram", "diagram": {"centre": "Three dates, three separate events", "parts": [{"label": "Due Date", "note": "Collection falls due, and debtor PSP checks the account for funds."}, {"label": "Settlement Date", "note": "Interbank settlement through the CSM, funding the creditor PSP."}, {"label": "Debit Date", "note": "Debtor account is actually debited, sometimes the next Business Day."}, {"label": "Same country", "note": "All three dates normally coincide when both PSPs share one country."}, {"label": "Different countries", "note": "Separate calendars and processing windows can push the debit a day later."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": []}, {"id": "JEB-D08", "seq": 93, "module": "Foundations", "source": "Public post", "title": "UPI and PayNow: instant systems working together", "explain": "India UPI moves money in real time, and its link with Singapore PayNow shows two such systems working together so an India to Singapore payment arrives instantly. UPI joins wallets, banks and small businesses in a point-to-point architecture, with banks verifying, reviewing and authorising its transactions. Linked systems give users faster and more transparent payments, and prove that instant systems can interoperate instead of operating in isolation.", "takeaway": "Linked systems give users faster and more transparent payments, and prove that instant systems can interoperate instead of operating in isolation.", "visual": {"type": "diagram", "diagram": {"centre": "Two instant systems, one payment", "parts": [{"label": "UPI, India real time", "note": "Real-time payment system for instant money transfer."}, {"label": "PayNow, Singapore", "note": "Singapore real-time payment system."}, {"label": "Integration", "note": "The two systems work together so payments arrive instantly."}, {"label": "Verified by banks", "note": "Transactions are verified, reviewed and authorised by banks."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D14", "seq": 95, "module": "Foundations", "source": "Public post", "title": "Fast Payment Systems: instant, any time, anywhere", "explain": "A Fast Payment System lets customers pay instantly, at any time and from anywhere, replacing 9 AM to 3 PM banking hours with round-the-clock processing, 24x7x365. In India, customers pay through IMPS, UPI, NEFT, mobile banking and wallets, while UPI launched in 2016 and is now accepted in seven countries, and SEPA Instant followed in 2017 and now reaches 33 European countries. Behind the mobile phone sits a payment ecosystem of many interacting parts, and Fast Payment Systems now run in over 70 countries, which is why the phone is only the front door.", "takeaway": "Behind the mobile phone sits a payment ecosystem of many interacting parts, and Fast Payment Systems now run in over 70 countries, which is why the phone is only the front door.", "visual": {"type": "diagram", "diagram": {"centre": "Fast Payment System", "parts": [{"label": "Anytime, anywhere", "note": "Instant payments at any time, not only during banking hours."}, {"label": "24x7x365", "note": "Customers expect payments completed around the clock."}, {"label": "UPI, 2016", "note": "Launched in India in 2016, now accepted in seven countries."}, {"label": "SEPA Instant, 2017", "note": "Launched in the EU in 2017, now in 33 European countries."}, {"label": "An ecosystem behind it", "note": "Many interacting parts run behind the mobile phone."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-E10", "seq": 99, "module": "Foundations", "source": "Public post", "title": "Y-Copy sends a copy, T2 V-Shape sends the full payment", "explain": "In the traditional Y-Copy model, Bank A sends the payment instruction and a copy goes to the settlement mechanism, which holds the payment until settlement and authorisation complete and only then releases it to Bank B. In the T2 V-Shape model, Bank A sends the full pacs.008 to T2, which validates and settles it and then forwards the settled payment to Bank B, so Bank B can treat the payment as settled because settlement already happened inside T2. The BA distinction is not the message format but the architecture: who receives the payment for settlement, whether a copy or the full payment is sent, when settlement happens, and when the payment is released to the receiving bank.", "takeaway": "The BA distinction is not the message format but the architecture: who receives the payment for settlement, whether a copy or the full payment is sent, when settlement happens, and when the payment is released to the receiving bank.", "visual": {"type": "diagram", "diagram": {"centre": "Copy or full payment to settlement?", "parts": [{"label": "Y-Copy: copy held", "note": "A copy goes to the settlement mechanism and the payment is held until authorised."}, {"label": "Y-Copy: released after", "note": "The payment is released to Bank B only after settlement completes."}, {"label": "V-Shape: full payment", "note": "The full pacs.008 goes to T2 RTGS for validation and settlement."}, {"label": "V-Shape: forwarded settled", "note": "T2 forwards the payment to Bank B after settlement is complete."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": ["pacs.008"]}, {"id": "JEB-E11", "seq": 100, "module": "Foundations", "source": "Public post", "title": "Instant for the customer is not instant between banks", "explain": "A UPI payment of 10,000 rupees from Customer A at Bank A reaches Customer B at Bank B instantly, yet the 10,000 rupees need not be settled between the two banks at that exact moment. Customer credit, payment processing and clearing, and interbank settlement are separate layers, and the banks' resulting positions can be settled later through the applicable mechanism, including Net Deferred Settlement arrangements. The BA must ask instant at which layer, and who pays for the infrastructure, remembering that the EU Instant Payments Regulation caps instant charges at the level of corresponding regular transfers while India's zero-MDR model for UPI is a different policy decision that must not be confused with net settlement.", "takeaway": "The BA must ask instant at which layer, and who pays for the infrastructure, remembering that the EU Instant Payments Regulation caps instant charges at the level of corresponding regular transfers while India's zero-MDR model for UPI is a different policy decision that must not be confused with net settlement.", "visual": {"type": "diagram", "diagram": {"centre": "Instant at which layer?", "parts": [{"label": "Customer credit", "note": "Money is available to the beneficiary immediately."}, {"label": "Processing and clearing", "note": "The system processes the transaction and sets obligations between banks."}, {"label": "Interbank settlement", "note": "Bank positions settle later, including through Net Deferred Settlement."}, {"label": "Who pays", "note": "Pricing and infrastructure funding are separate questions from speed."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-E12", "seq": 101, "module": "Foundations", "source": "Public post", "title": "ISO 20022, Swift, and CSM are three different roles", "explain": "ISO 20022 is the language and standard, a common data model with business concepts and message structures such as pacs.008, pacs.009, pacs.004, and camt.053, and it neither transports nor clears nor settles a payment on its own. Swift provides the messaging and network services that let institutions exchange messages and can carry ISO 20022, while a CSM is the clearing and settlement infrastructure that processes payments under scheme rules and can adopt ISO 20022 without being Swift. The payment therefore moves from initiation to an ISO 20022 message, through Swift or another network, into the CSM for clearing and settlement, and on to confirmation, so the BA must ask separately what the standard is, who transports the message, who clears it, who settles it, and which scheme rules apply.", "takeaway": "The payment therefore moves from initiation to an ISO 20022 message, through Swift or another network, into the CSM for clearing and settlement, and on to confirmation, so the BA must ask separately what the standard is, who transports the message, who clears it, who settles it, and which scheme rules apply.", "visual": {"type": "diagram", "diagram": {"centre": "Language, network, infrastructure", "parts": [{"label": "ISO 20022: the language", "note": "The standard, data model, and message structures."}, {"label": "Swift: the network", "note": "Messaging services that exchange the messages between institutions."}, {"label": "CSM: the infrastructure", "note": "Clearing and settlement under the rules of the scheme."}, {"label": "Same language, many rails", "note": "ISO 20022 can run across different networks and infrastructures."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pacs.008", "pacs.009", "pacs.004", "camt.053"]}, {"id": "JEB-E13", "seq": 102, "module": "Foundations", "source": "Public post", "title": "A payment BA must know the whole lifecycle", "explain": "A basic answer to the end-to-end payment question stops at instruction, processing, sending, crediting, and settlement, but that only describes one application and says nothing about what happens after settlement. The full lifecycle runs from initiation through a channel, through validation of format, mandatory fields, and limits and screening for sanctions, fraud, AML, and restricted parties, into clearing and settlement through central bank systems or correspondent banking, then into accounting where debit and credit entries, nostro movements, and reconciliation are recorded. Operations and investigations close the loop by tracking status and fixing downstream failures, and any engine change must be traced through every downstream consumer, because in payments a point left to clarify later can become an expensive production problem.", "takeaway": "Operations and investigations close the loop by tracking status and fixing downstream failures, and any engine change must be traced through every downstream consumer, because in payments a point left to clarify later can become an expensive production problem.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The customer instructs the payment through a channel into the payment engine.", "title": "Initiation"}, {"kind": "step", "note": "Format, limits, and mandatory fields checked; sanctions, fraud, and AML screened.", "title": "Validation and screening"}, {"kind": "step", "note": "The payment moves through central bank systems or correspondent banking.", "title": "Clearing and settlement"}, {"kind": "step", "note": "Debit and credit entries, nostro movement, ledger update, and reconciliation.", "title": "Accounting"}, {"kind": "step", "note": "Status tracked, failures investigated, reconciled, and fixed.", "title": "Operations and investigations"}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": []}, {"id": "JEB-E14", "seq": 103, "module": "Foundations", "source": "Public post", "title": "Message flow is not settlement responsibility", "explain": "Bank A asks Bank B to move funds onward to Bank C, which makes Bank A the Instructing Agent and Bank B the Instructed Agent: one issues the instruction for the next step, the other receives it and carries that step out. Knowing who instructs whom explains the message flow, but it does not say who settles the money, because the Settlement Agent is a separate party that settles on behalf of the Instructing or Instructed Agent and belongs to the settlement flow rather than the message flow. Naming the Settlement Agent makes the debit and credit entries and the nostro movements straightforward to work out, which is the point where a BA who grasps instructing, instructed, and settlement responsibility stops reading ISO 20022 fields and starts reading the payment business process.", "takeaway": "Naming the Settlement Agent makes the debit and credit entries and the nostro movements straightforward to work out, which is the point where a BA who grasps instructing, instructed, and settlement responsibility stops reading ISO 20022 fields and starts reading the payment business process.", "visual": {"type": "diagram", "diagram": {"centre": "Who instructs, who is instructed, who settles", "parts": [{"label": "Instructing Agent", "note": "The party that instructs the next party to carry out the payment."}, {"label": "Instructed Agent", "note": "The party that receives the instruction and executes the next step."}, {"label": "Settlement Agent", "note": "The party that actually settles the funds on behalf of another agent."}, {"label": "Two different flows", "note": "Message flow shows who instructs whom; settlement flow shows who pays."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN6-001", "seq": 104, "module": "Foundations", "source": "Article and reader comments", "title": "Acceptance turns paper into a bill of exchange", "explain": "Acceptance is the act that converts a drawn paper into a bill of exchange in the strict sense. Until the drawee signs, the instrument remains an unaccepted paper on a bill form, however loosely market usage labels it. Dishonour by non-acceptance therefore describes refusal at first presentment, and the instrument never returns for a second acceptance.", "takeaway": "Dishonour by non-acceptance therefore describes refusal at first presentment, and the instrument never returns for a second acceptance.", "visual": {"type": "diagram", "diagram": {"centre": "Acceptance creates the bill of exchange", "parts": [{"label": "Before acceptance", "note": "An unsigned paper on a bill form only."}, {"label": "Drawee signs", "note": "Signature converts the paper into a bill of exchange."}, {"label": "Refusal at first presentment", "note": "Non-acceptance means refusal when first presented."}, {"label": "One acceptance only", "note": "An accepted bill never goes back for acceptance again."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN6-002", "seq": 105, "module": "Foundations", "source": "Article and reader comments", "title": "Mandatory elements of a bill of exchange", "explain": "Validity turns on the parties and the acceptance, not on any bank name. Payor and payee must both be identified without ambiguity, and the drawee must have accepted the instrument. The remaining mandatory elements are those the article enumerates.", "takeaway": "The remaining mandatory elements are those the article enumerates.", "visual": {"type": "diagram", "diagram": {"centre": "What a valid bill must carry", "parts": [{"label": "Payor identified", "note": "The party who must pay is named without ambiguity."}, {"label": "Payee identified", "note": "The party to be paid is named without ambiguity."}, {"label": "Drawee acceptance", "note": "The drawee has signed to accept the bill."}, {"label": "No bank name required", "note": "Naming a bank is not a mandatory element."}, {"label": "Further elements listed", "note": "The article enumerates the remaining mandatory elements."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN6-004", "seq": 106, "module": "Foundations", "source": "Article and reader comments", "title": "Participants in a blockchain payment network", "explain": "Participation is confined to financial institutions: banks, clearing and settlement mechanisms and insurers among them. Each institution operates as a node and takes a direct part in processing transactions.", "takeaway": "Each institution operates as a node and takes a direct part in processing transactions.", "visual": {"type": "diagram", "diagram": {"centre": "Participants in a blockchain payment network", "parts": [{"label": "Banks", "note": "Banks act as nodes and process transactions."}, {"label": "Clearing and settlement mechanisms", "note": "A CSM can act as a node and handle settlement."}, {"label": "Insurance firms", "note": "Insurers and other financial institutions can be nodes."}, {"label": "Every participant is a node", "note": "All participants take part in transaction processing."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D15 Advanced and emerging payments", "messages": []}, {"id": "RUN6-006", "seq": 107, "module": "Foundations", "source": "Article and reader comments", "title": "SEPA fees: bank charge, not clearing charge", "explain": "The charge a customer sees is a bank charge, not a clearing charge. A bank may set its own price for sending a SEPA credit transfer, and likewise for a SEPA direct debit. The clearing system itself levies no interchange fee for processing the transaction.", "takeaway": "The clearing system itself levies no interchange fee for processing the transaction.", "visual": {"type": "diagram", "diagram": {"centre": "Charges on a SEPA payment", "parts": [{"label": "Bank may charge the customer", "note": "A bank may price a SEPA credit transfer or direct debit it sends."}, {"label": "Clearing system charges nothing", "note": "The clearing system levies no interchange fee for processing."}, {"label": "Fee comes from your bank", "note": "What the customer pays comes from their own bank, not the clearing layer."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "RUN6-008", "seq": 108, "module": "Foundations", "source": "Article and reader comments", "title": "CSM and ACH: what each term covers", "explain": "A clearing and settlement mechanism is the system through which banks exchange and clear payment transactions and then settle them. An automated clearing house concentrates on the clearing leg. The term CSM is preferred here because it makes the link between clearing and settlement explicit.", "takeaway": "The term CSM is preferred here because it makes the link between clearing and settlement explicit.", "visual": {"type": "diagram", "diagram": {"centre": "ACH or CSM", "parts": [{"label": "CSM", "note": "The clearing and settlement mechanism covers clearing and settlement together."}, {"label": "ACH", "note": "The automated clearing house concentrates on clearing."}, {"label": "Why CSM is used", "note": "It makes the link between clearing and settlement explicit."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-016", "seq": 109, "module": "Foundations", "source": "Article and reader comments", "title": "Indirect participants still hold central bank accounts", "explain": "Yes: every bank holds a central bank account in its own country, which the central bank needs to oversee the banking system. Direct participation only means a bank routes its real time gross settlement exchanges and settlement through another bank. A bank stays indirect because connecting directly demands setting up and running complex infrastructure, worthwhile only with enough volume.", "takeaway": "A bank stays indirect because connecting directly demands setting up and running complex infrastructure, worthwhile only with enough volume.", "visual": {"type": "diagram", "diagram": {"centre": "Indirect participants and central bank accounts", "parts": [{"label": "Every bank has one", "note": "All banks hold an account with their country's central bank."}, {"label": "The central bank oversees", "note": "The account lets the central bank oversee the banking system."}, {"label": "Direct means using another bank", "note": "A direct participant uses another bank to exchange RTGS transactions."}, {"label": "Why banks stay indirect", "note": "Connecting directly needs complex infrastructure, only worth it with volume."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-019", "seq": 110, "module": "Foundations", "source": "Article and reader comments", "title": "MT and MX: standards, formats and replacement", "explain": "MT rests on ISO 15022 and its flat files and tags, while MX rests on ISO 20022 and its XML files and message elements. ISO 20022 is far richer, so an MX message carries much more information, and almost every MT message has a corresponding MX message. MT is giving way to MX over time, yet both standards serve the same situations today.", "takeaway": "MT is giving way to MX over time, yet both standards serve the same situations today.", "visual": {"type": "diagram", "diagram": {"centre": "SWIFT MT versus SWIFT MX", "parts": [{"label": "MT: ISO 15022, flat files", "note": "MT messages use flat files and tags."}, {"label": "MX: ISO 20022, XML", "note": "MX messages use XML files and message elements."}, {"label": "MX carries more", "note": "ISO 20022 is richer and carries much more information."}, {"label": "One maps to the other", "note": "Almost every MT message has a corresponding MX message."}, {"label": "MT is being replaced", "note": "MX replaces MT over time, but both work in the same situations today."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "RUN6-023", "seq": 111, "module": "Foundations", "source": "Article and reader comments", "title": "MT101 or pain.001: what each carries", "explain": "Both messages carry credit transfer instructions to the bank. The MT101 leg rests on ISO 15022, a SWIFT MT message built on flat files and tags, while pain.001 is built on ISO 20022, with XML files and message elements. ISO 20022 is far richer, so pain.001 holds far more information than MT101 can.", "takeaway": "ISO 20022 is far richer, so pain.001 holds far more information than MT101 can.", "visual": {"type": "diagram", "diagram": {"centre": "MT101 versus pain.001", "parts": [{"label": "Both instruct the bank", "note": "Both send credit transfer instructions to the bank."}, {"label": "MT101: ISO 15022, flat files", "note": "MT101 uses flat files and tags."}, {"label": "pain.001: ISO 20022, XML", "note": "pain.001 uses XML files and message elements."}, {"label": "pain.001 carries more", "note": "ISO 20022 is richer, so pain.001 carries much more information."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "pain.001"]}, {"id": "RUN6-028", "seq": 112, "module": "Foundations", "source": "Article and reader comments", "title": "MT101 instructs, MT103 moves the money", "explain": "MT101 belongs to the customer-to-bank space and MT103 to the interbank space. An MT101 goes out before execution, carrying the payment instruction to the ordering bank. The MT103 follows as the next step, leaving the ordering bank for the beneficiary or correspondent banks after the ordering account has been debited.", "takeaway": "The MT103 follows as the next step, leaving the ordering bank for the beneficiary or correspondent banks after the ordering account has been debited.", "visual": {"type": "diagram", "diagram": {"centre": "MT101 versus MT103", "parts": [{"label": "MT101: customer to bank", "note": "MT101 carries the instruction from customer to bank."}, {"label": "MT103: bank to bank", "note": "MT103 moves funds between banks."}, {"label": "MT101 is before execution", "note": "MT101 sends the instruction to the ordering bank."}, {"label": "MT103 is after the debit", "note": "MT103 goes out once the ordering account has been debited."}, {"label": "One instructs, one moves", "note": "MT101 instructs the payment, MT103 moves the money."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "MT103"]}, {"id": "RUN6-029", "seq": 113, "module": "Foundations", "source": "Article and reader comments", "title": "SDD mandate expiry: silent after 36 months", "explain": "A SEPA mandate expires after 36 months with no orders related to it. Expiry triggers no SWIFT message to any party. The mandate simply lapses quietly after three years without use.", "takeaway": "The mandate simply lapses quietly after three years without use.", "visual": {"type": "diagram", "diagram": {"centre": "When an SDD mandate expires", "parts": [{"label": "36 months without orders", "note": "A mandate expires after 36 months with no related orders."}, {"label": "No message is sent", "note": "No SWIFT message tells any party the mandate expired."}, {"label": "It lapses quietly", "note": "The mandate simply ends after three years without use."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "mandate issue"}, {"id": "RUN6-032", "seq": 114, "module": "Foundations", "source": "Article and reader comments", "title": "On-us transfers use the same standard messages", "explain": "Intrabank book transfers run on the same standard messages as interbank ones. For a SEPA credit transfer that means the standard ISO 20022 set. Running different standards for interbank and intrabank traffic would create many problems over the long term, so an on-us transfer travels on the same message standards as any other payment.", "takeaway": "Running different standards for interbank and intrabank traffic would create many problems over the long term, so an on-us transfer travels on the same message standards as any other payment.", "visual": {"type": "diagram", "diagram": {"centre": "Messages for on-us intrabank transfers", "parts": [{"label": "Same standards as interbank", "note": "Intrabank transfers use the same standard messages."}, {"label": "SCT uses ISO 20022", "note": "For a SEPA credit transfer the ISO 20022 set applies."}, {"label": "Different standards cause problems", "note": "Separate standards for interbank and intrabank would create many problems."}, {"label": "On-us travels on the same rails", "note": "An on-us transfer uses the same message standards as any payment."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "RUN7-008", "seq": 115, "module": "Foundations", "source": "Article and reader comments", "title": "Foreign is an origin, not a cheque type", "explain": "Foreign on its own is not a complete cheque type. A cheque from another country still carries a type in that country, so it may be a foreign bank cheque, or equally a foreign order cheque. The word foreign only says where the cheque comes from, and the type must be named as well.", "takeaway": "The word foreign only says where the cheque comes from, and the type must be named as well.", "visual": {"type": "diagram", "diagram": {"centre": "What a foreign cheque really is", "parts": [{"label": "Foreign is not a complete type", "note": "A foreign cheque on its own is not a complete type of cheque."}, {"label": "Foreign bank cheque", "note": "You can have a foreign bank cheque."}, {"label": "Foreign order cheque", "note": "You can have a foreign order cheque."}, {"label": "Foreign describes where it comes from", "note": "The word foreign describes where the cheque comes from."}, {"label": "The type must be named as well", "note": "A cheque that comes from another country still has a type in that country, and the type must be named as well."}]}}, "level": "foundation", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "ABH-11", "seq": 118, "module": "Core", "source": "Public post", "title": "Corporate channel to core banking posting", "explain": "A corporate payment starts in a channel, passes an API gateway, validation and the payment hub, then compliance screening, routing and clearing, and finally the core banking debit and credit posting. Each hand-off is a place where the payment can be checked, enriched or stopped. That chain of hand-offs is what makes the flow controllable end to end.", "takeaway": "That chain of hand-offs is what makes the flow controllable end to end.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate channel", "note": "Where the payment starts"}, {"kind": "step", "title": "API gateway", "note": "Entry point into the bank systems"}, {"kind": "step", "title": "Validation", "note": "Payment checked before it moves on"}, {"kind": "step", "title": "Payment hub", "note": "Central processing for the payment"}, {"kind": "decision", "title": "Compliance screening clear?", "note": "A failed screen stops the payment here"}, {"kind": "step", "title": "Routing and clearing", "note": "Payment routed to the right rail and cleared"}, {"kind": "step", "title": "Core banking posting", "note": "Debit and credit posted to the ledger"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-13", "seq": 120, "module": "Core", "source": "Public post", "title": "Vietnam Send: channel to reconciliation", "explain": "A domestic payment in Vietnam moves from the channel to core banking, then the payment hub, validation and routing, NAPAS, the receiving bank and reconciliation. Each stage has a job, and reconciliation at the end proves the money arrived where it should.", "takeaway": "Each stage has a job, and reconciliation at the end proves the money arrived where it should.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Channel", "note": "Where the payment is sent from"}, {"kind": "step", "title": "Core banking", "note": "Payment enters the bank core"}, {"kind": "step", "title": "Payment hub", "note": "Central processing and control"}, {"kind": "step", "title": "Validation and routing", "note": "Checked, then routed to the right path"}, {"kind": "step", "title": "NAPAS", "note": "The domestic rail that carries it"}, {"kind": "step", "title": "Receiving bank", "note": "Bank that receives for the beneficiary"}, {"kind": "step", "title": "Reconciliation", "note": "Proves the money arrived where it should"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-19", "seq": 126, "module": "Core", "source": "Public post", "title": "Finastra GPP in corporate banking: 9 steps", "explain": "In corporate banking, GPP runs a nine-step journey from payment origination to settlement and reporting. The steps cover initiation, validation, compliance, routing, clearing, and the final posting and reporting. Knowing the nine steps lets a BA place any issue at the right stage.", "takeaway": "Knowing the nine steps lets a BA place any issue at the right stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Payment origination starts the journey"}, {"kind": "step", "title": "Validation", "note": "Payment checked before it moves on"}, {"kind": "decision", "title": "Compliance clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Routing", "note": "Payment routed to the right rail"}, {"kind": "step", "title": "Clearing", "note": "Payment cleared through the network"}, {"kind": "step", "title": "Settlement", "note": "Funds move to complete the payment"}, {"kind": "step", "title": "Posting and reporting", "note": "Final posting and reporting close the journey"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-20", "seq": 127, "module": "Core", "source": "Public post", "title": "GPP: one platform for many rails", "explain": "GPP orchestrates multiple payment types and rails from one platform: domestic, cross-border, real-time and high-value payments, with routing, compliance and reconciliation. One platform means one set of controls and one view of the payment, whatever the rail.", "takeaway": "One platform means one set of controls and one view of the payment, whatever the rail.", "visual": {"type": "diagram", "diagram": {"centre": "Finastra GPP, one platform", "parts": [{"label": "Domestic payments", "note": "Domestic payments on the one platform"}, {"label": "Cross-border payments", "note": "Cross-border payments on the one platform"}, {"label": "Real-time payments", "note": "Real-time payments on the one platform"}, {"label": "High-value payments", "note": "High-value payments on the one platform"}, {"label": "Routing", "note": "One set of controls, whatever the rail"}, {"label": "Compliance", "note": "One set of controls, whatever the rail"}, {"label": "Reconciliation", "note": "One view of the payment, whatever the rail"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-21", "seq": 128, "module": "Core", "source": "Public post", "title": "GPP integration in cross-border payments", "explain": "GPP integration in cross-border payments covers initiation, validation and enrichment, compliance, routing and orchestration, ISO 20022 and SWIFT, exceptions, and settlement with reconciliation. Each stage is a hand-off, and the integration is only as strong as the weakest hand-off.", "takeaway": "Each stage is a hand-off, and the integration is only as strong as the weakest hand-off.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Payment starts in the channel"}, {"kind": "step", "title": "Validation and enrichment", "note": "Checked and enriched before it moves on"}, {"kind": "decision", "title": "Compliance clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Routing and orchestration", "note": "Routed across rails from one platform"}, {"kind": "step", "title": "ISO 20022 and SWIFT", "note": "Mapped to the standard and sent on SWIFT"}, {"kind": "step", "title": "Exceptions", "note": "Handled when a stage fails"}, {"kind": "step", "title": "Settlement and reconciliation", "note": "Settled, then reconciled to close the flow"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-22", "seq": 129, "module": "Core", "source": "Public post", "title": "Finastra: wider than payments alone", "explain": "Finastra is a banking technology ecosystem, broader than a payment processor alone. Its products cover more of the bank than payments, so a BA working with Finastra must understand the wider platform, not only the payment flow.", "takeaway": "Its products cover more of the bank than payments, so a BA working with Finastra must understand the wider platform, not only the payment flow.", "visual": {"type": "diagram", "diagram": {"centre": "Finastra banking ecosystem", "parts": [{"label": "Payments", "note": "One part of the wider platform"}, {"label": "Wider banking products", "note": "Cover more of the bank than payments"}, {"label": "The BA view", "note": "Understand the wider platform, not only payments"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-23", "seq": 130, "module": "Core", "source": "Public post", "title": "GPP integration: the big picture", "explain": "GPP integration connects the bank's channels and systems to the payment hub so that a payment can flow end to end. The integration is the plumbing that makes the nine-step journey possible.", "takeaway": "The integration is the plumbing that makes the nine-step journey possible.", "visual": {"type": "diagram", "diagram": {"centre": "GPP integration", "parts": [{"label": "Channels and systems", "note": "Connected to the payment hub"}, {"label": "Payment hub", "note": "Where payments flow end to end"}, {"label": "Nine-step journey", "note": "Made possible by the integration"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "JEB-A08", "seq": 161, "module": "Core", "source": "Public post", "title": "pacs.009 ADV gives treasury sight, it is not the payment", "explain": "A pacs.009 ADV is an advice that funds are on the way, giving treasury visibility before arrival for liquidity planning and forecasting, and it is not a pacs.008 payment instruction. It may carry only part of the amount, so expecting EUR 20 million while seeing EUR 18 million means the missing EUR 2 million is still in transit, not lost. Confusing the advice with the payment itself is the error to avoid, because the two messages serve different purposes and treasury must read them apart.", "takeaway": "Confusing the advice with the payment itself is the error to avoid, because the two messages serve different purposes and treasury must read them apart.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.009 ADV: advice, not payment", "parts": [{"label": "Treasury visibility", "note": "Gives treasury visibility before the money arrives"}, {"label": "Liquidity planning", "note": "Supports liquidity planning and forecasting"}, {"label": "Part of the amount", "note": "May carry only part of the amount, so EUR 18 million of EUR 20 million is seen"}, {"label": "Missing EUR 2 million in transit", "note": "The missing EUR 2 million is in transit rather than lost"}, {"label": "pacs.008 is the payment", "note": "The payment itself is still the pacs.008, not the advice"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pacs.009", "pacs.008"]}, {"id": "JEB-B04", "seq": 165, "module": "Core", "source": "Public post", "title": "pacs.009 COV and ADV are use cases, not messages", "explain": "COV and ADV are not separate messages in the ISO 20022 catalogue: they share one underlying pacs.009 message, Financial Institution Credit Transfer, applied to a different business use case. Core is a bank-to-bank transfer of funds, COV is the cover or funding leg for an underlying customer payment, and ADV is advice of an expected funds movement. CBPR+ sets out Core, Cover and Advise for cross-border payments, while the EPC SEPA schemes do not use pacs.009 at all, so a requirement that says only that pacs.009 is needed stays incomplete until it also names the use case, the scheme, the usage guideline and the business context.", "takeaway": "CBPR+ sets out Core, Cover and Advise for cross-border payments, while the EPC SEPA schemes do not use pacs.009 at all, so a requirement that says only that pacs.009 is needed stays incomplete until it also names the use case, the scheme, the usage guideline and the business context.", "visual": {"type": "diagram", "diagram": {"centre": "One pacs.009, three use cases", "parts": [{"label": "Core: bank-to-bank transfer", "note": "A bank-to-bank transfer of funds"}, {"label": "COV: cover leg", "note": "The cover or funding leg for an underlying customer payment"}, {"label": "ADV: advice of funds movement", "note": "Advice of an expected funds movement"}, {"label": "CBPR+ defines all three", "note": "CBPR+ sets out Core, Cover and Advise for cross-border payments"}, {"label": "SEPA does not use pacs.009", "note": "The EPC SEPA schemes do not use pacs.009 at all"}, {"label": "Name the use case", "note": "A pacs.009 requirement must also name the use case, scheme and business context"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": ["pacs.009"]}, {"id": "JEB-C04", "seq": 173, "module": "Core", "source": "Public post", "title": "MT is retiring, not retired: know the November nuance", "explain": "The CBPR+ November 2026 deadline is often described as the end of MT for cross-border payments, but the picture is mixed: many MT messages migrate to MX by then, some were already retired, and others keep running after the deadline for specialised or domestic use. SWIFT is driving the migration because MT cannot carry the rich data, structured addresses and granularity that compliance and monitoring need. The right description is therefore that MT is retiring, not retired, and a BA should know the nuance rather than repeat the slogan, because the end date is not the same for every message and that nuance matters in migration planning.", "takeaway": "The right description is therefore that MT is retiring, not retired, and a BA should know the nuance rather than repeat the slogan, because the end date is not the same for every message and that nuance matters in migration planning.", "visual": {"type": "diagram", "diagram": {"centre": "MT is retiring, not retired", "parts": [{"label": "Many migrate by November 2026", "note": "Many MT messages migrate to MX by the deadline"}, {"label": "Some already retired", "note": "Some messages were already retired before the deadline"}, {"label": "Others keep running after the deadline", "note": "Others keep running for specialised or domestic use"}, {"label": "MT cannot carry rich data", "note": "MT cannot carry the rich data, structured addresses and granularity needed"}, {"label": "Compliance and monitoring need more", "note": "Compliance and monitoring need the richer data that MX carries"}, {"label": "End date differs per message", "note": "The end date is not the same for every message"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "JEB-C08", "seq": 176, "module": "Core", "source": "Public post", "title": "MT to MX: same SWIFT, different shape of data", "explain": "MT messages are FIN messages written as structured text with character limits, including free-text fields limited to 4 by 35 characters, while MX messages are ISO 20022 XML with properly structured data such as name, address, town and country. Converting a payment means translating it field by field and message by message, and the translator must also look at the MT structure, correspondent and account information and the business rules to derive the right MX settlement method. Banks must migrate certain payment types to MX under CBPR+, and getting the mapping right early is what keeps straight-through processing high, so the conversion is a business mapping exercise, not just a format change.", "takeaway": "Banks must migrate certain payment types to MX under CBPR+, and getting the mapping right early is what keeps straight-through processing high, so the conversion is a business mapping exercise, not just a format change.", "visual": {"type": "diagram", "diagram": {"centre": "MT to MX: same SWIFT, different data", "parts": [{"label": "MT: structured text, character limits", "note": "MT messages are FIN messages written as structured text with character limits"}, {"label": "MX: structured XML data", "note": "MX messages are ISO 20022 XML with properly structured data"}, {"label": "Translate field by field", "note": "Converting a payment means translating it field by field and message by message"}, {"label": "Derive the settlement method", "note": "Use MT structure, correspondent and account information and business rules"}, {"label": "Migrate payment types to MX", "note": "Banks must migrate certain payment types to MX under CBPR+"}, {"label": "Business mapping, not format change", "note": "Getting the mapping right early keeps straight-through processing high"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "INS-001", "seq": 179, "module": "Core", "source": "Public post", "title": "End-to-end card transaction flow", "explain": "A card transaction moves through four stages across four parties: authorisation is the issuer approving the payment at the point of sale, clearing is the network exchanging transaction records between acquirer and issuer, settlement is the movement of funds between the banks, and reconciliation matches clearing records, settlement positions and ledger postings so every amount agrees. The issuer, the acquirer, the network and the merchant each play a distinct role at each stage, and a failure at any stage has a different owner and a different fix. Know the stage, and you know who must act.", "takeaway": "Know the stage, and you know who must act.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorisation", "note": "The issuer approves the payment at the point of sale."}, {"kind": "step", "title": "Clearing", "note": "The network exchanges records between acquirer and issuer."}, {"kind": "step", "title": "Settlement", "note": "Funds move between the banks."}, {"kind": "step", "title": "Reconciliation", "note": "Clearing records, settlement positions and ledger postings agree."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "reconciliation break"}, {"id": "INS-002", "seq": 180, "module": "Core", "source": "Public post", "title": "Debit card versus credit card behaviour", "explain": "A debit card payment draws directly on the customer's account balance, so the funds leave the account at authorisation and settlement moves money the customer already holds. A credit card payment draws on a credit line, so the issuer funds the payment and the customer repays later, which changes settlement timing, interest treatment and the risk the issuer carries. The terminal experience looks identical, but the account and settlement implications are entirely different.", "takeaway": "The terminal experience looks identical, but the account and settlement implications are entirely different.", "visual": {"type": "diagram", "diagram": {"centre": "Same terminal, different money movement", "parts": [{"label": "Debit card", "note": "Draws on the customer balance; funds leave at authorisation."}, {"label": "Credit card", "note": "Draws on a credit line; the issuer funds it, the customer repays later."}, {"label": "Settlement and risk", "note": "Timing, interest treatment and issuer risk differ."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "INS-028", "seq": 184, "module": "Core", "source": "Public post", "title": "NEFT, RTGS and IMPS: three domestic rails", "explain": "NEFT, RTGS and IMPS are three domestic rails with different operating models: NEFT settles in batches and suits payments that can wait, RTGS settles each payment individually in central bank money and suits high value payments that must be final, and IMPS settles instantly around the clock and suits payments that must arrive immediately. Compare them on speed, availability, settlement model and customer use case, and use the current scheme rules rather than an old summary. The rail is chosen by the payment's need, not by habit.", "takeaway": "The rail is chosen by the payment's need, not by habit.", "visual": {"type": "diagram", "diagram": {"centre": "Three rails, three settlement models", "parts": [{"label": "NEFT", "note": "Settles in batches, for payments that can wait."}, {"label": "RTGS", "note": "Settles each payment individually in central bank money."}, {"label": "IMPS", "note": "Settles instantly around the clock."}, {"label": "How to compare", "note": "Speed, availability, settlement model and use case."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-027", "seq": 185, "module": "Core", "source": "Public post", "title": "The loan lifecycle, application to closure", "explain": "A loan moves from application through decision, agreement, disbursement, servicing, repayment and closure: application collects the request and supporting information, decision assesses credit and affordability, agreement records the terms, disbursement releases the funds, servicing collects repayments and manages changes, and closure confirms the balance is settled and the account is closed. Each stage has its own data, controls and hand-offs, so a failure at one stage does not always show up until a later stage. A loan is a chain, and a weak link anywhere shows up downstream.", "takeaway": "A loan is a chain, and a weak link anywhere shows up downstream.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Application", "note": "The bank collects the request and supporting information."}, {"kind": "step", "title": "Decision", "note": "Credit and affordability are assessed."}, {"kind": "step", "title": "Agreement", "note": "The terms are recorded."}, {"kind": "step", "title": "Disbursement", "note": "The funds are released."}, {"kind": "step", "title": "Servicing", "note": "Repayments are collected and changes managed."}, {"kind": "step", "title": "Repayment and closure", "note": "The balance is confirmed settled and the account closed."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": [], "failure_category": "payment rejected or returned"}, {"id": "INS-090", "seq": 187, "module": "Core", "source": "Public post", "title": "Settlement cycles and honest customer timing", "explain": "A settlement cycle is the period after which funds move between banks, and T+1 or T+2 are only examples of how long that can take. The actual timing depends on the scheme and the product, so always use the scheme and product specific rules rather than a generic T+1 or T+2. Customer communication must state the real timing for that product, because telling a customer the money will arrive tomorrow when the scheme settles in two days creates a complaint that was avoidable.", "takeaway": "Customer communication must state the real timing for that product, because telling a customer the money will arrive tomorrow when the scheme settles in two days creates a complaint that was avoidable.", "visual": {"type": "diagram", "diagram": {"centre": "Settlement timing: use the product rule", "parts": [{"label": "Settlement cycle", "note": "The period after which funds move between banks."}, {"label": "T+1 or T+2", "note": "Only examples of how long a cycle can take."}, {"label": "Scheme and product rules", "note": "Actual timing depends on these, not a generic label."}, {"label": "Customer communication", "note": "Must state the real timing for that product."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-069", "seq": 188, "module": "Core", "source": "Public post", "title": "Payment APIs across the product lifecycle", "explain": "A payment product exposes several APIs across the lifecycle, not just one for taking payment: the checkout API initiates the payment, the authentication API proves who is paying, the status API reports where a payment stands, the refund API returns money for a completed payment, and the reversal API cancels a payment that should not have completed. Map each touchpoint to the lifecycle stage it serves, so the product never ends up with a payment that can be taken but cannot be refunded or checked. Coverage of the whole lifecycle is what makes a payment product complete.", "takeaway": "Coverage of the whole lifecycle is what makes a payment product complete.", "visual": {"type": "diagram", "diagram": {"centre": "Payment product APIs across the lifecycle", "parts": [{"label": "Checkout API", "note": "Initiates the payment."}, {"label": "Authentication API", "note": "Proves who is paying."}, {"label": "Status API", "note": "Reports where a payment stands."}, {"label": "Refund API", "note": "Returns money for a completed payment."}, {"label": "Reversal API", "note": "Cancels a payment that should not have completed."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D10 APIs and integration", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-088", "seq": 189, "module": "Core", "source": "Public post", "title": "Refund API versus reversal API", "explain": "A refund and a reversal look similar but differ in trigger, timing and ledger effect: a refund returns money for a completed payment, is linked to the original transaction, and posts as a new credit to the customer, while a reversal cancels a payment that should not have completed, is also linked to the original transaction, but unwinds the original posting rather than creating a separate refund. Validate the rail and provider semantics before building either one, because the same word can mean different things on different rails. Build the ledger effect first, and the name will follow.", "takeaway": "Build the ledger effect first, and the name will follow.", "visual": {"type": "diagram", "diagram": {"centre": "Refund creates a credit, reversal unwinds the posting", "parts": [{"label": "Refund", "note": "Returns money for a completed payment, a new credit to the customer."}, {"label": "Reversal", "note": "Cancels a payment that should not have completed, unwinds the posting."}, {"label": "Shared link", "note": "Both are linked to the original transaction."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D10 APIs and integration", "messages": [], "failure_category": "reconciliation break", "resolution": "return"}, {"id": "INS-012", "seq": 190, "module": "Core", "source": "Public post", "title": "Gateway, bank and merchant: who owns what", "explain": "In a card payment the gateway, the bank and the merchant each own a distinct part: the gateway orchestrates the instruction and returns the outcome, the bank authorises and processes the payment and moves the funds, and the merchant is notified of the outcome and must act on it. When a payment fails, knowing which party owns which step decides who must fix it and who must tell the customer, so the boundary between gateway, bank and merchant must be explicit in the design. Unclear ownership turns every failure into a dispute between parties.", "takeaway": "Unclear ownership turns every failure into a dispute between parties.", "visual": {"type": "diagram", "diagram": {"centre": "Gateway, bank and merchant ownership", "parts": [{"label": "Gateway", "note": "Orchestrates the instruction and returns the outcome."}, {"label": "Bank", "note": "Authorises and processes the payment and moves the funds."}, {"label": "Merchant", "note": "Is notified of the outcome and must act on it."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "system or connectivity failure", "resolution": "return"}, {"id": "PAI-C022", "seq": 244, "module": "Core", "source": "Article and reader comments", "title": "Two ordering parties in one cover payment", "explain": "In a cover payment the ordering customer named in the MT103 and the ordering customer named in the MT202 COV can be different parties, because the MT103 names the customer who instructed the payment while the MT202 COV names the bank moving the funds. Readers ask which one counts as the ordering customer, and the answer is that each message has its own ordering party for its own leg. Treating them as one party is a common source of confusion in cover payments.", "takeaway": "Treating them as one party is a common source of confusion in cover payments.", "visual": {"type": "diagram", "diagram": {"centre": "The ordering customer in a cover payment", "parts": [{"label": "MT103 names the instructing customer", "note": "The MT103 names the customer who instructed the payment"}, {"label": "MT202 COV names the funding bank", "note": "The MT202 COV names the bank moving the funds"}, {"label": "Each message has its own ordering party", "note": "Each leg has its own ordering party"}, {"label": "Treating them as one party confuses", "note": "Merging the two parties is a common source of confusion"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"]}, {"id": "PAI-C023", "seq": 245, "module": "Core", "source": "Article and reader comments", "title": "Field 72: the instruction inside the cover", "explain": "Field 72 carries sender-to-receiver information, and in a cover payment it tells the next bank what the cover is for and what to do with it. Readers ask repeatedly what field 72 should contain in an MT202 COV, because the field is free text and a wrong instruction can send the funds to the wrong place or delay settlement. The discipline is to put only the instruction the next bank needs, in the form the next bank expects.", "takeaway": "The discipline is to put only the instruction the next bank needs, in the form the next bank expects.", "visual": {"type": "diagram", "diagram": {"centre": "Field 72 in the cover payment", "parts": [{"label": "Sender-to-receiver information", "note": "Field 72 carries sender-to-receiver information"}, {"label": "Tells the next bank what the cover is for", "note": "It tells the next bank what the cover is for and what to do"}, {"label": "Free text, so discipline matters", "note": "Free text means a wrong instruction can send funds astray"}, {"label": "Only the instruction the next bank needs", "note": "Put only what the next bank needs, in the form it expects"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT202"]}, {"id": "PAI-C024", "seq": 246, "module": "Core", "source": "Article and reader comments", "title": "Serial charges: deducted at every step", "explain": "In a serial payment the ordering customer bears the charges, and each intermediary bank deducts its own charge from the amount as the payment passes through. The beneficiary therefore receives the amount minus the charges deducted at each step, which is why the credit can be less than the amount sent. An analyst pricing a serial payment must account for every deduction in the chain, not just the first one.", "takeaway": "An analyst pricing a serial payment must account for every deduction in the chain, not just the first one.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Ordering customer bears the charges", "note": "The ordering customer is responsible for the charges"}, {"kind": "step", "title": "Each intermediary deducts its charge", "note": "Each intermediary takes its own charge as the payment passes"}, {"kind": "step", "title": "Beneficiary receives the reduced amount", "note": "The credit is the amount sent minus every deduction"}, {"kind": "step", "title": "Analyst accounts for every deduction", "note": "Pricing must cover every deduction in the chain"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C026", "seq": 248, "module": "Core", "source": "Article and reader comments", "title": "Charge arithmetic follows the payment method", "explain": "In a serial payment charges are deducted step by step as the payment passes through each intermediary, while in a cover payment the charges on the information leg and the funds leg are handled separately. The calculation therefore depends on the method, and a payment that mixes the two methods without care can double-charge or under-charge. The analyst must know which method applies before working out what the beneficiary will receive.", "takeaway": "The analyst must know which method applies before working out what the beneficiary will receive.", "visual": {"type": "diagram", "diagram": {"centre": "Charges in serial and cover payments", "parts": [{"label": "Serial payment", "note": "Charges deducted step by step at each intermediary"}, {"label": "Cover payment", "note": "Information leg and funds leg charges handled separately"}, {"label": "Mixed methods", "note": "Mixing the two can double-charge or under-charge"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C033", "seq": 255, "module": "Core", "source": "Article and reader comments", "title": "camt.026 reports, camt.056 recalls", "explain": "A camt.056 requests a recall of a payment, asking the beneficiary bank to return funds that have already been credited. A camt.026 reports that a payment cannot be applied, telling the sender that the instruction could not be processed. The two are often confused because both relate to a payment that did not complete, but they do different jobs: one asks for money back, the other reports that money could not be applied.", "takeaway": "The two are often confused because both relate to a payment that did not complete, but they do different jobs: one asks for money back, the other reports that money could not be applied.", "visual": {"type": "diagram", "diagram": {"centre": "camt.026 versus camt.056", "parts": [{"label": "camt.026", "note": "Reports a payment that cannot be applied"}, {"label": "camt.056", "note": "Requests recall of funds already credited"}, {"label": "Different jobs", "note": "One asks for money back, the other reports it could not be applied"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.026", "camt.056"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C039", "seq": 261, "module": "Core", "source": "Article and reader comments", "title": "An MT103 with field 57 left empty", "explain": "When an MT103 arrives with field 57 empty, the message names no beneficiary bank, so the receiving bank must work out where the payment should go from the other fields. The empty field is not necessarily an error: it can mean the payment is to be handled by the receiving bank itself, or that the beneficiary bank is identified elsewhere in the chain. The analyst must read the whole message before deciding whether the empty field is a gap or a deliberate omission.", "takeaway": "The analyst must read the whole message before deciding whether the empty field is a gap or a deliberate omission.", "visual": {"type": "diagram", "diagram": {"centre": "An MT103 with field 57 empty", "parts": [{"label": "No beneficiary bank named", "note": "The message names no beneficiary bank"}, {"label": "Receiving bank works out the route", "note": "The receiving bank must work out the route from the other fields"}, {"label": "Not necessarily an error", "note": "It can mean the receiving bank handles it, or the bank is named elsewhere"}, {"label": "Read the whole message first", "note": "Read the whole message before judging the empty field"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "PAI-C040", "seq": 262, "module": "Core", "source": "Article and reader comments", "title": "Parent pays for subsidiaries via MT101", "explain": "A parent company can pay on behalf of its subsidiaries using an MT101, and the question is how the instruction names the subsidiary as the ordering customer for each transaction. The MT101 carries a general instruction sequence and a per-transaction sequence, and the subsidiary appears as the ordering customer in the per-transaction sequence. The parent's bank must then report each transaction under the correct subsidiary, so the accounting and the screening both land on the right party.", "takeaway": "The parent's bank must then report each transaction under the correct subsidiary, so the accounting and the screening both land on the right party.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Parent instructs with an MT101", "note": "A parent company pays on behalf of its subsidiaries using an MT101"}, {"kind": "step", "title": "General instruction sequence carried", "note": "The MT101 carries a general instruction sequence"}, {"kind": "step", "title": "Subsidiary named per transaction", "note": "The subsidiary appears as ordering customer in the per-transaction sequence"}, {"kind": "step", "title": "Bank reports under the right subsidiary", "note": "Each transaction is reported under the correct subsidiary"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT101"]}, {"id": "PAI-C055", "seq": 264, "module": "Core", "source": "Article and reader comments", "title": "A credit notification is not an MT103", "explain": "An MT103 instructs the receiving bank to debit the sender's account and pay the beneficiary, so it is an instruction to move money. When a bank only wants to say that an account has already been credited, it uses an MT910 confirmation of credit or an MT950 or MT940 statement instead. Sending an MT103 for a credit that has already happened confuses an instruction with a notification, and the receiving bank may try to debit an account that should not be debited.", "takeaway": "Sending an MT103 for a credit that has already happened confuses an instruction with a notification, and the receiving bank may try to debit an account that should not be debited.", "visual": {"type": "diagram", "diagram": {"centre": "A credit notification is not an MT103", "parts": [{"label": "MT103 instructs a payment", "note": "An MT103 instructs the receiving bank to debit the sender and pay the beneficiary"}, {"label": "MT910 confirms a credit", "note": "A bank reporting a credit already made uses an MT910"}, {"label": "MT950 or MT940 statement instead", "note": "An MT950 or MT940 statement can also report a credit already made"}, {"label": "Instruction confused with notification", "note": "Sending an MT103 for a credit already made may debit the wrong account"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT910", "MT950", "MT940"]}, {"id": "PAI-C056", "seq": 265, "module": "Core", "source": "Article and reader comments", "title": "Fields 55 and 56: intermediary and reimbursement", "explain": "Field 56 names the intermediary institution, the bank that receives the payment from the sender and forwards it to the account with institution in field 57. Field 55 names a third reimbursement institution, used when the funds are reimbursed through a bank that is neither the sender nor the receiver. When a serial chain gains an intermediary, field 56A is simply added, and when the receiver is itself the receiver's correspondent there is no need to name it in field 56 at all.", "takeaway": "When a serial chain gains an intermediary, field 56A is simply added, and when the receiver is itself the receiver's correspondent there is no need to name it in field 56 at all.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 55 and 56 in an MT103", "parts": [{"label": "Field 56: intermediary institution", "note": "Field 56 names the intermediary that forwards the payment to field 57"}, {"label": "Field 55: third reimbursement institution", "note": "Field 55 names a third reimbursement institution for reimbursement elsewhere"}, {"label": "Field 56A added with an intermediary", "note": "When a serial chain gains an intermediary, field 56A is added"}, {"label": "No field 56 if receiver is own correspondent", "note": "When the receiver is its own correspondent, field 56 is not needed"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C057", "seq": 266, "module": "Core", "source": "Article and reader comments", "title": "MT900: confirmation of a debit", "explain": "When a bank debits an account on the instruction of an MT103, it can confirm the debit with an MT900, a confirmation of debit. The MT900 is a separate message, not part of the MT103 itself, and whether one is sent depends on the agreement between the two banks. A payment can therefore settle correctly without any MT900 being exchanged.", "takeaway": "A payment can therefore settle correctly without any MT900 being exchanged.", "visual": {"type": "diagram", "diagram": {"centre": "MT900: confirmation of debit", "parts": [{"label": "Confirms a debit from an MT103", "note": "A bank debiting on an MT103 instruction can confirm it with an MT900"}, {"label": "Separate message, not part of MT103", "note": "The MT900 is a separate message, not part of the MT103"}, {"label": "Sent only by agreement", "note": "Whether one is sent depends on the agreement between the banks"}, {"label": "Payment can settle without an MT900", "note": "A payment can settle correctly with no MT900 exchanged"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT900", "MT103"]}, {"id": "PAI-C063", "seq": 271, "module": "Core", "source": "Article and reader comments", "title": "SSI: the routing table banks share", "explain": "Banks tell each other how to send them funds in each currency through standing settlement instructions, exchanged as MT670 and MT671 messages and stored in payment engine databases. An SSI names the correspondent of the receiver and any intermediaries on the route, so the sending bank can build the MT103 and the cover from the database instead of asking every time. A sender who does not know the receiver's correspondent must find it out through SWIFT services or by asking the receiver directly.", "takeaway": "A sender who does not know the receiver's correspondent must find it out through SWIFT services or by asking the receiver directly.", "visual": {"type": "diagram", "diagram": {"centre": "Standing settlement instructions", "parts": [{"label": "Exchanged as MT670 and MT671", "note": "SSIs are exchanged as MT670 and MT671 and stored in payment engine databases"}, {"label": "Names the receiver's correspondent", "note": "An SSI names the correspondent and any intermediaries on the route"}, {"label": "Sending bank builds from the database", "note": "The sending bank builds the MT103 and the cover from the database"}, {"label": "Unknown correspondent must be found out", "note": "An unknown correspondent must be found via SWIFT services or by asking"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT670", "MT671", "MT103"]}, {"id": "PAI-C065", "seq": 273, "module": "Core", "source": "Article and reader comments", "title": "Field 57a points at a different bank in each leg", "explain": "In a serial MT103, field 57a names the bank that holds the beneficiary's account, and field 56 names the intermediary that forwards the payment to it. In an MT202 COV the roles shift: field 58a names the beneficiary bank, while field 57a names the correspondent bank of the beneficiary bank. Reading field 57a the same way in both messages is a common error, because the same field number points at a different bank in each leg.", "takeaway": "Reading field 57a the same way in both messages is a common error, because the same field number points at a different bank in each leg.", "visual": {"type": "diagram", "diagram": {"centre": "Field 57a in MT103 and MT202 COV", "parts": [{"label": "Serial MT103: bank holding the account", "note": "In a serial MT103, field 57a names the bank holding the beneficiary's account"}, {"label": "Serial MT103: field 56 is the intermediary", "note": "In a serial MT103, field 56 names the intermediary that forwards the payment"}, {"label": "MT202 COV: field 58a is the beneficiary bank", "note": "In an MT202 COV, field 58a names the beneficiary bank"}, {"label": "MT202 COV: field 57a is the correspondent", "note": "In an MT202 COV, field 57a names the correspondent of the beneficiary bank"}, {"label": "Reading 57a the same way is an error", "note": "The same field number points at a different bank in each leg"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"]}, {"id": "PAI-C066", "seq": 274, "module": "Core", "source": "Article and reader comments", "title": "The MT202 COV is itself a serial payment", "explain": "Looked at on its own, an MT202 COV is a serial payment: the sender instructs the receiver to debit the sender's account and credit the next bank in the chain. Each bank in the cover chain debits the previous bank's account and instructs the next bank, until the funds reach the beneficiary bank. The cover is therefore not a different kind of movement; it is the same serial mechanism carrying the funds leg of a customer payment.", "takeaway": "The cover is therefore not a different kind of movement; it is the same serial mechanism carrying the funds leg of a customer payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sender instructs receiver to debit its account", "note": "The sender instructs the receiver to debit the sender's account and credit the next bank"}, {"kind": "step", "title": "Each bank debits the previous bank", "note": "Each bank in the cover chain debits the previous bank's account"}, {"kind": "step", "title": "Each bank instructs the next bank", "note": "Each bank instructs the next bank in the chain"}, {"kind": "step", "title": "Funds reach the beneficiary bank", "note": "The funds reach the beneficiary bank through the same serial mechanism"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT202"]}, {"id": "PAI-C069", "seq": 275, "module": "Core", "source": "Article and reader comments", "title": "MT190 and MT191: the charges leg between banks", "explain": "When one bank owes another bank charges or interest on a payment, the claim travels in an MT191, a request for payment of charges, and the advice travels in an MT190. These messages exist because charges must not be deducted from a cover payment, so an intermediary that is owed money asks for it separately instead of taking it from the funds. A reader who sees an MT191 in a chain is therefore looking at the charges leg, not the payment itself.", "takeaway": "A reader who sees an MT191 in a chain is therefore looking at the charges leg, not the payment itself.", "visual": {"type": "diagram", "diagram": {"centre": "MT190 and MT191 move charges", "parts": [{"label": "MT191: request for payment of charges", "note": "When one bank owes another charges or interest, the claim travels in an MT191"}, {"label": "MT190: advice of charges", "note": "The advice of charges or interest travels in an MT190"}, {"label": "Charges must not come from the cover", "note": "Charges must not come from the cover, so an intermediary asks separately"}, {"label": "MT191 is the charges leg, not the payment", "note": "An MT191 in a chain is the charges leg, not the payment itself"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT190", "MT191"]}, {"id": "PAI-C070", "seq": 276, "module": "Core", "source": "Article and reader comments", "title": "No intermediary may change the currency", "explain": "The sender decides the currency of a transaction, and no intermediary may change it on the way. If the beneficiary's account is in a different currency, the conversion happens as a separate foreign exchange step, and the beneficiary is credited in the currency of the account. A payment sent in United States dollars to a United States dollar account that arrives short because an intermediary converted it twice has gone wrong, and the banks in the chain must be challenged on it.", "takeaway": "A payment sent in United States dollars to a United States dollar account that arrives short because an intermediary converted it twice has gone wrong, and the banks in the chain must be challenged on it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sender decides the currency", "note": "The sender decides the currency of a transaction"}, {"kind": "step", "title": "Intermediaries pass the currency unchanged", "note": "No intermediary may change the currency on the way"}, {"kind": "step", "title": "Conversion is a separate FX step", "note": "If the account is in another currency, conversion is a separate foreign exchange step"}, {"kind": "step", "title": "Beneficiary credited in account currency", "note": "The beneficiary is credited in the currency of the account"}, {"kind": "decision", "title": "Payment arriving short is wrong", "note": "A payment arriving short after a double conversion has gone wrong"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C074", "seq": 278, "module": "Core", "source": "Article and reader comments", "title": "71A BEN: the beneficiary bears every charge", "explain": "When field 71A carries BEN, every charge in the chain is borne by the beneficiary, and each bank deducts its charge from the amount as the payment passes through. The sender does not prepay the downstream charges, because the beneficiary is the one who pays them. A bank copy that shows SHA where the sender instructed BEN is therefore a discrepancy worth querying, since the two codes give the beneficiary a different amount.", "takeaway": "A bank copy that shows SHA where the sender instructed BEN is therefore a discrepancy worth querying, since the two codes give the beneficiary a different amount.", "visual": {"type": "diagram", "diagram": {"centre": "71A BEN: beneficiary pays all charges", "parts": [{"label": "Every charge borne by the beneficiary", "note": "When field 71A carries BEN, every charge is borne by the beneficiary"}, {"label": "Each bank deducts its charge", "note": "Each bank deducts its charge as the payment passes through"}, {"label": "Sender does not prepay downstream charges", "note": "The sender does not prepay downstream charges, the beneficiary pays them"}, {"label": "SHA shown where BEN was instructed", "note": "A bank copy showing SHA where BEN was instructed is a discrepancy worth querying"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C078", "seq": 280, "module": "Core", "source": "Article and reader comments", "title": "Field 57 options B, C and D: what each carries", "explain": "Field 57 offers four options, and option A, with a BIC, is the one that allows straight-through processing. Option B carries a party identifier, generally an account number, with the location of the account, and a BIC must never be passed in option B: if the BIC is to be used, option A is the right choice. Option D needs no routing code at all and can simply carry the bank's name and address, while the /C/ or /D/ code before an account number is part of the standard but almost never used in practice. Option A is therefore the default whenever a BIC is available, and the other options are for identifiers a BIC cannot express.", "takeaway": "Option A is therefore the default whenever a BIC is available, and the other options are for identifiers a BIC cannot express.", "visual": {"type": "diagram", "diagram": {"centre": "Options B, C and D of field 57", "parts": [{"label": "Option A allows straight-through processing", "note": "Option A, with a BIC, allows straight-through processing"}, {"label": "Option B: party identifier and location", "note": "Option B carries a party identifier, generally an account number, with the location"}, {"label": "No BIC in option B", "note": "A BIC must not be passed in option B; use option A instead"}, {"label": "Option D: name and address only", "note": "Option D needs no routing code and can carry the bank's name and address"}, {"label": "Codes /C/ and /D/ are rarely used", "note": "The /C/ or /D/ code before an account number is standard but almost never used"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C079", "seq": 281, "module": "Core", "source": "Article and reader comments", "title": "A CHIPS UID in field 57A", "explain": "In option A of field 57, the line before the BIC is the party identifier, and for a United States payment that identifier can be the beneficiary bank's CHIPS UID. The CHIPS UID identifies the bank in the United States clearing system, while the BIC identifies it on SWIFT, so the two sit together in the same field. Using the BIC alone is also valid, but the UID removes any doubt about which clearing account should be used.", "takeaway": "Using the BIC alone is also valid, but the UID removes any doubt about which clearing account should be used.", "visual": {"type": "diagram", "diagram": {"centre": "A CHIPS UID in field 57A", "parts": [{"label": "Party identifier line before the BIC", "note": "In option A of field 57, the line before the BIC is the party identifier"}, {"label": "CHIPS UID identifies the US clearing bank", "note": "For a United States payment the identifier can be the beneficiary bank's CHIPS UID"}, {"label": "BIC identifies the bank on SWIFT", "note": "The CHIPS UID identifies the bank in US clearing, the BIC on SWIFT"}, {"label": "BIC alone is also valid", "note": "The BIC alone is valid, but the UID removes doubt about the clearing account"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C081", "seq": 282, "module": "Core", "source": "Article and reader comments", "title": "Field 53B: pinning down the account to debit", "explain": "A bank can hold more than one account with the same correspondent in the same currency, and field 53B exists to say exactly which account must be debited. Using option B tells the receiver that the sender has many accounts with it and wants a specific one used to settle the transaction. Field 53 itself is optional in an MT103, and it does not always contain the sender's nostro account, because the field has three options that can carry different information.", "takeaway": "Field 53 itself is optional in an MT103, and it does not always contain the sender's nostro account, because the field has three options that can carry different information.", "visual": {"type": "diagram", "diagram": {"centre": "Field 53B: which account to debit", "parts": [{"label": "Bank can hold several accounts", "note": "A bank can hold more than one account with the same correspondent in the same currency"}, {"label": "Field 53B names the exact account", "note": "Field 53B says exactly which account must be debited"}, {"label": "Option B signals many accounts", "note": "Option B tells the receiver the sender has many accounts and wants one used"}, {"label": "Field 53 is optional in an MT103", "note": "Field 53 itself is optional in an MT103"}, {"label": "Not always the sender's nostro account", "note": "Field 53 does not always contain the sender's nostro account, as its options differ"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "PAI-C082", "seq": 283, "module": "Core", "source": "Article and reader comments", "title": "Field 70: codes, references and the 16-character limit", "explain": "Field 70 carries remittance information, and several references can be given if they are separated by a double slash, but one code such as /RFB/ or /INV/ cannot serve two references of the same kind. The reference that follows /RFB/ is limited to 16 characters, so a longer description must continue on the following lines of the field instead of stretching the reference. A field 70 that repeats a code or overruns the limit is not a valid instruction, even though no system may reject it automatically.", "takeaway": "A field 70 that repeats a code or overruns the limit is not a valid instruction, even though no system may reject it automatically.", "visual": {"type": "diagram", "diagram": {"centre": "Field 70: remittance information", "parts": [{"label": "Several references, separated by double slash", "note": "Several references can be given if separated by a double slash"}, {"label": "A code must not be repeated", "note": "A code such as /RFB/ or /INV/ cannot serve two references of the same kind"}, {"label": "/RFB/ reference limited to 16 characters", "note": "The reference following /RFB/ is limited to 16 characters"}, {"label": "Longer text continues on following lines", "note": "A longer description continues on the following lines, not in the reference"}, {"label": "Invalid field, even if not rejected", "note": "A field 70 repeating a code or overrunning the limit is not valid"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "system or connectivity failure", "resolution": "reject"}, {"id": "PAI-C084", "seq": 284, "module": "Core", "source": "Article and reader comments", "title": "FFC: routing funds past the named beneficiary", "explain": "When the funds must be credited to an account other than the beneficiary's own account, the instruction travels as /FFC/, for further credit, in field 72, sender to receiver information. The beneficiary bank reads the code and passes the funds on to the account named after it, instead of crediting the beneficiary directly. Without the code, the bank has no instruction to look beyond the beneficiary named in field 59.", "takeaway": "Without the code, the bank has no instruction to look beyond the beneficiary named in field 59.", "visual": {"type": "diagram", "diagram": {"centre": "FFC: credit a further account", "parts": [{"label": "Instruction travels as /FFC/ in field 72", "note": "The instruction travels as /FFC/, for further credit, in field 72"}, {"label": "Beneficiary bank passes funds onward", "note": "The beneficiary bank reads the code and passes the funds to the account named"}, {"label": "Without the code, no onward instruction", "note": "Without the code, the bank has no instruction beyond the beneficiary in field 59"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C087", "seq": 285, "module": "Core", "source": "Article and reader comments", "title": "UETR in field 121: the reference that traces a payment", "explain": "The unique end-to-end transaction reference, the UETR, is carried in field 121 of block 3 of the message header, not in the body of the MT103. When a payment is late or a bank cannot trace it, the UETR is the reference to give the bank, because every bank in the chain can use it to follow the payment across the network. A copy of an MT103 on its own proves nothing about whether the money moved; the UETR and the sending bank's records are what settle the question.", "takeaway": "A copy of an MT103 on its own proves nothing about whether the money moved; the UETR and the sending bank's records are what settle the question.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "UETR carried in field 121 of block 3", "note": "The UETR sits in field 121 of block 3 of the header, not in the body"}, {"kind": "step", "title": "Every bank in the chain can use it", "note": "Every bank in the chain can use it to follow the payment across the network"}, {"kind": "step", "title": "Payment late or untraceable", "note": "When a payment is late or untraceable, the UETR is the reference to give the bank"}, {"kind": "step", "title": "MT103 copy alone proves nothing", "note": "A copy of an MT103 alone proves nothing about whether the money moved"}, {"kind": "step", "title": "UETR and bank records settle the question", "note": "The UETR and the sending bank's records settle the question"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "PAI-C088", "seq": 286, "module": "Core", "source": "Article and reader comments", "title": "Field 50K: a name may span several lines", "explain": "Option K of field 50a allows the ordering customer's name and address in up to four lines of 35 characters each. The name does not have to fit on the first line: it can sit on one line with the address on the rest, or run over two or three lines with the address on what remains. The standard does not restrict the name to the first line, so a name split across lines is valid.", "takeaway": "The standard does not restrict the name to the first line, so a name split across lines is valid.", "visual": {"type": "diagram", "diagram": {"centre": "Field 50K: name over several lines", "parts": [{"label": "Up to four lines of 35 characters", "note": "Field 50K allows the name and address in up to four lines of 35 characters"}, {"label": "Name need not fit on the first line", "note": "The name does not have to fit on the first line"}, {"label": "Name on one line, address on the rest", "note": "The name can sit on one line with the address on the rest"}, {"label": "Name over two or three lines is valid", "note": "The name can run over two or three lines with the address on what remains"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C092", "seq": 289, "module": "Core", "source": "Article and reader comments", "title": "MT101 fields 20 and 21R: two references, two owners", "explain": "Field 20 is the sender's reference, assigned by the bank that sends the MT101 to identify the payment. Field 21R is the ordering customer's reference, assigned by the customer who ordered the payment, and it stays the same across every message sent for one order. The two references can coincide when the sender is also the ordering customer, but they belong to different parties, and field 21R is optional while field 20 is mandatory.", "takeaway": "The two references can coincide when the sender is also the ordering customer, but they belong to different parties, and field 21R is optional while field 20 is mandatory.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 20 and 21R in an MT101", "parts": [{"label": "Field 20: sender's reference", "note": "Field 20 is the sender's reference, assigned by the bank sending the MT101"}, {"label": "Field 21R: ordering customer's reference", "note": "Field 21R is the ordering customer's reference, assigned by the customer"}, {"label": "Field 21R stays the same across messages", "note": "Field 21R stays the same across every message sent for one order"}, {"label": "References can coincide", "note": "The two references can coincide when the sender is also the ordering customer"}, {"label": "Field 20 mandatory, field 21R optional", "note": "Field 21R is optional while field 20 is mandatory"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "PAI-C093", "seq": 290, "module": "Core", "source": "Article and reader comments", "title": "Parent pays, subsidiary is named to the beneficiary", "explain": "When a parent company sends an MT101 to pay on behalf of a subsidiary, the parent company stands as the sender, not the subsidiary. The beneficiary is told the payment is from the subsidiary through the Instructing Party field, which names the subsidiary even though the parent sent the instruction. The beneficiary therefore sees the parent as the sender and the subsidiary as the party the payment is really from.", "takeaway": "The beneficiary therefore sees the parent as the sender and the subsidiary as the party the payment is really from.", "visual": {"type": "diagram", "diagram": {"centre": "Who the beneficiary sees", "parts": [{"label": "Sender is the parent company", "note": "When a parent sends an MT101 for a subsidiary, the sender is the parent company"}, {"label": "Instructing Party names the subsidiary", "note": "The beneficiary is told the payment is from the subsidiary via the Instructing Party field"}, {"label": "Beneficiary sees parent as sender", "note": "The beneficiary sees the parent as sender and the subsidiary as the real source"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "PAI-C095", "seq": 292, "module": "Core", "source": "Article and reader comments", "title": "One MT101 to a concentrating bank", "explain": "A large corporate with accounts at many banks can send a single MT101 to one concentrating bank, and that bank forwards the instruction to each bank that holds an account to be debited. The alternative is for the corporate to prepare a separate MT101 for every bank, which is slower and harder to manage. The forwarding service is a genuine value-added service, and the concentrating bank charges for it.", "takeaway": "The forwarding service is a genuine value-added service, and the concentrating bank charges for it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate holds accounts at many banks", "note": "A large corporate has accounts at many banks"}, {"kind": "step", "title": "Alternative is one MT101 per bank", "note": "The alternative is a separate MT101 for every bank, which is slower and harder to manage"}, {"kind": "step", "title": "One MT101 to the concentrating bank", "note": "The corporate sends a single MT101 to one concentrating bank"}, {"kind": "step", "title": "Concentrating bank forwards to each bank", "note": "That bank forwards the instruction to each bank holding an account to be debited"}, {"kind": "step", "title": "Concentrating bank charges for the service", "note": "The forwarding service is a genuine value-added service, and the bank charges for it"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT101"]}, {"id": "PAI-C096", "seq": 293, "module": "Core", "source": "Article and reader comments", "title": "Field 28D: splitting one order across MT101s", "explain": "An MT101 message is limited to 10,000 characters, so an order with many transactions must be split across several MT101 messages, numbered in field 28D as 1 of 5, 2 of 5, and so on. Banks are configured to hold a chained message until every message in the chain has arrived, because processing one element alone could pay the wrong amounts. Banks also set their own limits on how many transactions they will accept in one order, so a very large order should be agreed with the bank before it is sent.", "takeaway": "Banks also set their own limits on how many transactions they will accept in one order, so a very large order should be agreed with the bank before it is sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Order exceeds the 10,000 character limit", "note": "An MT101 message is limited to 10,000 characters"}, {"kind": "step", "title": "Order split across several MT101s", "note": "An order with many transactions must be split across several MT101 messages"}, {"kind": "step", "title": "Messages numbered in field 28D", "note": "Messages are numbered in field 28D as 1 of 5, 2 of 5, and so on"}, {"kind": "step", "title": "Banks hold the chain until all arrive", "note": "Banks hold a chained message until every message in the chain has arrived"}, {"kind": "step", "title": "Very large order agreed with the bank", "note": "A very large order should be agreed with the bank first, as banks set their own limits"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT101"]}, {"id": "PAI-C098", "seq": 294, "module": "Core", "source": "Article and reader comments", "title": "Same bank, both accounts: one MT101 suffices", "explain": "If the same bank holds both the debtor's account and the beneficiary's account, the payment never leaves the bank, so no interbank message is needed. A single MT101 is enough: the bank debits the debtor's account and credits the beneficiary's account on its own books. An MT103 is only required when the beneficiary's bank is different from the debtor's bank.", "takeaway": "An MT103 is only required when the beneficiary's bank is different from the debtor's bank.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Same bank holds both accounts", "note": "The same bank holds both the debtor's and the beneficiary's account"}, {"kind": "step", "title": "Payment never leaves the bank", "note": "The payment never leaves the bank, so no interbank message is needed"}, {"kind": "step", "title": "Single MT101 is enough", "note": "A single MT101 is enough for the payment"}, {"kind": "step", "title": "Bank debits debtor and credits beneficiary", "note": "The bank debits the debtor and credits the beneficiary on its own books"}, {"kind": "step", "title": "MT103 only needed for different banks", "note": "An MT103 is only required when the beneficiary's bank differs from the debtor's bank"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "MT103"]}, {"id": "PAI-C100", "seq": 295, "module": "Core", "source": "Article and reader comments", "title": "MT940: one closing balance per statement", "explain": "A statement split across several MT940 messages must use the intermediate closing balance, tag 62M, in every message except the last. Only the final message carries the final closing balance, tag 62F, because there is only one closing balance for the whole statement. A client system that receives a 62F in an intermediate message may treat the statement as finished and fail to generate the messages that follow.", "takeaway": "A client system that receives a 62F in an intermediate message may treat the statement as finished and fail to generate the messages that follow.", "visual": {"type": "diagram", "diagram": {"centre": "One MT940, one closing balance", "parts": [{"label": "Intermediate messages use tag 62M", "note": "A statement split across several MT940s uses tag 62M in every message except the last"}, {"label": "Only the final message carries 62F", "note": "Only the final message carries the final closing balance, tag 62F"}, {"label": "Only one closing balance exists", "note": "There is only one closing balance for the whole statement"}, {"label": "Early 62F breaks the receiver's system", "note": "A client system receiving a 62F mid-statement may treat the statement as finished"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT940"], "failure_category": "system or connectivity failure"}, {"id": "PAI-C101", "seq": 296, "module": "Core", "source": "Article and reader comments", "title": "MT940 intermediate balance dates: match the last entry", "explain": "When a statement is split across several MT940 messages, the intermediate opening balance tag 60M and the intermediate closing balance tag 62M should ideally show the date of the last entry in that message. In practice receivers care most that the balances themselves are correct, and the dates that truly matter are those of the opening balance, the closing balance, the closing available balance and the forward available balance. If the intermediate dates can be fixed easily, they should be.", "takeaway": "If the intermediate dates can be fixed easily, they should be.", "visual": {"type": "diagram", "diagram": {"centre": "Dates on intermediate MT940 balances", "parts": [{"label": "Tags 60M and 62M should match the last entry", "note": "Tags 60M and 62M should ideally show the date of the last entry in that message"}, {"label": "Receivers care most that balances are correct", "note": "In practice receivers care most that the balances themselves are correct"}, {"label": "Dates that truly matter", "note": "The dates that matter are opening, closing, closing available and forward available balances"}, {"label": "Fix intermediate dates if easy", "note": "If the intermediate dates can be fixed easily, they should be"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT940"]}, {"id": "PAI-C102", "seq": 297, "module": "Core", "source": "Article and reader comments", "title": "A long statement arrives as several MT940s", "explain": "A single MT940 can carry only a limited number of entries, so a statement with many entries is split across several MT940 messages, one after another. Each message carries a statement number and a sequence number, and the sequence number rises with each new message, so the receiver can put the statement back together in order. The chain can run to a very large number of sequences, which is more than enough in practice.", "takeaway": "The chain can run to a very large number of sequences, which is more than enough in practice.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Statement has many entries", "note": "A single MT940 can carry only a limited number of entries"}, {"kind": "step", "title": "Statement split across several MT940s", "note": "The statement is split across several MT940 messages, one after another"}, {"kind": "step", "title": "Each message carries statement and sequence", "note": "Each message carries a statement number and a sequence number"}, {"kind": "step", "title": "Sequence number rises with each message", "note": "The sequence number rises with each message, so the receiver can rebuild the order"}, {"kind": "step", "title": "Chain can run to a very large number", "note": "The chain can run to a very large number of sequences, more than enough in practice"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D02 Accounts, ledger and accounting", "messages": ["MT940"]}, {"id": "RUN3-003", "seq": 299, "module": "Core", "source": "Article and reader comments", "title": "Credit notification: camt.054 or MT900, sender decides", "explain": "When a bank tells its customer that a credit has landed, it may use a camt.054 in ISO 20022 or an MT900 in MT format, and both do the same job. No rule compels one format over the other, so the sender picks the form it will use. The receiving side must therefore be ready to read either format when the advice arrives.", "takeaway": "The receiving side must therefore be ready to read either format when the advice arrives.", "visual": {"type": "diagram", "diagram": {"centre": "Credit advice: two formats, one job", "parts": [{"label": "camt.054", "note": "ISO 20022 advice telling the customer a credit has been applied."}, {"label": "MT900", "note": "MT format advice doing the same job of reporting a credit."}, {"label": "Sender picks the format", "note": "No governing rule forces one form; the sender chooses."}, {"label": "Receiver reads either", "note": "The receiving side must handle whichever format arrives."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D02 Accounts, ledger and accounting", "messages": ["camt.054", "MT900"]}, {"id": "RUN3-007", "seq": 303, "module": "Core", "source": "Article and reader comments", "title": "MT950 intraday runs only when both sides agree", "explain": "An MT950 is normally the end of day statement, yet it can also be produced intraday alongside the MT940. The single condition is agreement between the account servicing bank and the account owner. That agreement sets what the receiver should expect to see during the day.", "takeaway": "That agreement sets what the receiver should expect to see during the day.", "visual": {"type": "diagram", "diagram": {"centre": "MT950, end of day or intraday", "parts": [{"label": "Usually end of day", "note": "The MT950 normally closes the day as the account statement."}, {"label": "Intraday possible", "note": "It can also be generated during the day, alongside the MT940."}, {"label": "Agreement required", "note": "Both the servicing bank and the account owner must agree to it."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D02 Accounts, ledger and accounting", "messages": ["MT950", "MT940"]}, {"id": "RUN3-008", "seq": 304, "module": "Core", "source": "Article and reader comments", "title": "MT950: field 61 repeats, field 62F closes once", "explain": "Every transaction on an MT950 sits in its own repeating field 61, so twenty transactions mean twenty field 61 blocks. The closing balance in field 62F appears a single time, at the very end of the statement. That balance must agree with the opening balance plus all field 61 entries, and checking the arithmetic is the fastest completeness test.", "takeaway": "That balance must agree with the opening balance plus all field 61 entries, and checking the arithmetic is the fastest completeness test.", "visual": {"type": "diagram", "diagram": {"centre": "MT950 statement structure", "parts": [{"label": "Field 61 repeats", "note": "One field 61 block carries each transaction on the statement."}, {"label": "Twenty transactions, twenty blocks", "note": "The count of field 61 blocks matches the count of transactions."}, {"label": "Field 62F once", "note": "The closing balance appears a single time, at the end."}, {"label": "Arithmetic must agree", "note": "62F must equal the opening balance plus all field 61 entries."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT950"]}, {"id": "RUN3-011", "seq": 305, "module": "Core", "source": "Article and reader comments", "title": "MT940: field 61 moves the money, field 86 explains it", "explain": "In an MT940, field 61 is the statement line, carrying the date, the amount and the entry type for each transaction. Field 86 sits beside that line and carries the information to the account owner, the narrative behind the movement. Field 61 alone shows that money moved; field 86 shows why, and reconciliation needs both together.", "takeaway": "Field 61 alone shows that money moved; field 86 shows why, and reconciliation needs both together.", "visual": {"type": "diagram", "diagram": {"centre": "MT940: line and narrative", "parts": [{"label": "Field 61, the line", "note": "Each transaction line holds the date, amount and entry type."}, {"label": "Field 86, the narrative", "note": "It carries the information to the account owner about the movement."}, {"label": "61 shows movement", "note": "Field 61 alone shows that money moved."}, {"label": "86 shows the reason", "note": "Field 86 explains why the money moved, and both feed reconciliation."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT940"]}, {"id": "RUN3-012", "seq": 306, "module": "Core", "source": "Article and reader comments", "title": "MT940 balances: 62M, 64 and 65 answer different questions", "explain": "Field 62M is the interim closing balance, struck when the statement was cut during the day. Field 64 is the closing available balance, the funds actually available at day end, while field 65 is the forward available balance, the funds expected on a future date. Confusing them overstates or understates liquidity, so each balance must be read for the question it answers.", "takeaway": "Confusing them overstates or understates liquidity, so each balance must be read for the question it answers.", "visual": {"type": "diagram", "diagram": {"centre": "MT940: three balances, three questions", "parts": [{"label": "62M", "note": "Interim closing balance, struck when the statement was cut."}, {"label": "64", "note": "Closing available balance, funds available at day end."}, {"label": "65", "note": "Forward available balance, funds expected on a future date."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT940"]}, {"id": "RUN3-013", "seq": 307, "module": "Core", "source": "Article and reader comments", "title": "MT940: field 28C is the first completeness check", "explain": "Field 28C carries the statement number and the sequence number, pinning down exactly which statement this is and where it sits in the run. A missing statement, or one arriving out of order, shows as a gap in the 28C sequence before any transaction is examined. That makes 28C the first completeness check on every MT940 received.", "takeaway": "That makes 28C the first completeness check on every MT940 received.", "visual": {"type": "diagram", "diagram": {"centre": "MT940 completeness via 28C", "parts": [{"label": "28C names the statement", "note": "Statement number and sequence number identify this statement and its place."}, {"label": "Gaps show in the sequence", "note": "A missing or out of order statement leaves a gap in 28C."}, {"label": "Checked before transactions", "note": "The gap appears before any transaction is examined."}, {"label": "First completeness check", "note": "28C is the first completeness check on each MT940."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT940"]}, {"id": "RUN4-009", "seq": 309, "module": "Core", "source": "Article and reader comments", "title": "Settlement instructions: how banks publish correspondents", "explain": "Banks tell each other who their correspondents are through Standing Settlement Instructions, exchanged as SWIFT MT670 and MT671 messages, and receiving banks store them in their payment engines. The MT671 goes out to all SWIFT institutions, whether or not they hold a direct relationship with the sender. Where a bank has several correspondents in one currency it lists them all, leaving the sender to choose among them.", "takeaway": "Where a bank has several correspondents in one currency it lists them all, leaving the sender to choose among them.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Banks publish their correspondents", "note": "Each bank tells others who its correspondents are."}, {"kind": "step", "title": "MT670 and MT671 carry them", "note": "The instructions travel as SWIFT MT670 and MT671 messages."}, {"kind": "step", "title": "MT671 goes to everyone", "note": "MT671 is broadcast to all SWIFT institutions, related or not."}, {"kind": "step", "title": "Receiving banks store them", "note": "Banks store the instructions in their payment engines."}, {"kind": "step", "title": "Sender picks a correspondent", "note": "With several correspondents listed, the sender chooses one."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT670", "MT671"]}, {"id": "RUN4-018", "seq": 317, "module": "Core", "source": "Article and reader comments", "title": "Documentary collections: banks intermediate, never promise", "explain": "In a documentary collection the collecting bank and the remitting bank act only as intermediaries between the drawer and the drawee. Unlike a documentary credit, the collecting bank owes the drawer no payment even when the documents are in order. It releases the documents to the drawee when the drawee pays what is due, and the payment undertaking found under a letter of credit simply does not exist here.", "takeaway": "It releases the documents to the drawee when the drawee pays what is due, and the payment undertaking found under a letter of credit simply does not exist here.", "visual": {"type": "diagram", "diagram": {"centre": "Documentary collection, no payment promise", "parts": [{"label": "Collecting bank intermediates", "note": "It acts only as an intermediary between drawer and drawee."}, {"label": "Remitting bank intermediates", "note": "It too acts only as an intermediary in the collection."}, {"label": "No duty to pay", "note": "The collecting bank owes no payment even if documents are in order."}, {"label": "Documents released on payment", "note": "The drawee gets the documents when it pays what is due."}, {"label": "No payment undertaking", "note": "The undertaking behind a letter of credit does not exist here."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN5-001", "seq": 318, "module": "Core", "source": "Article and reader comments", "title": "Card payments: the order money actually moves", "explain": "Paying by card moves money in an order that surprises many people. First the card is used to pay, then the issuer sends the statement, then the merchant is paid by the acquirer at settlement, and finally the cardholder pays the issuer. The acquirer settles with the merchant every day across all transactions, while the cardholder's payment to the issuer comes only after the statement arrives.", "takeaway": "The acquirer settles with the merchant every day across all transactions, while the cardholder's payment to the issuer comes only after the statement arrives.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Card used to pay", "note": "First the cardholder pays with the card."}, {"kind": "step", "title": "Issuer sends the statement", "note": "Then the issuer sends the statement."}, {"kind": "step", "title": "Acquirer pays the merchant", "note": "The merchant is paid by the acquirer at settlement, every day."}, {"kind": "step", "title": "Cardholder pays the issuer", "note": "Finally the cardholder pays the issuer, after the statement arrives."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "RUN5-002", "seq": 319, "module": "Core", "source": "Article and reader comments", "title": "Card interest: timing decides the free credit window", "explain": "The interest-free credit period depends on where in the billing cycle the payment fell, and it can reach about 45 days for a payment made at the start of a cycle. When the cycle ends, the issuer sends the statement, and the cardholder then has a set period, usually about 21 days, to pay. Paying the full statement amount inside that window means no interest, while paying less leaves interest charged on the balance.", "takeaway": "Paying the full statement amount inside that window means no interest, while paying less leaves interest charged on the balance.", "visual": {"type": "diagram", "diagram": {"centre": "Card statement cycle and interest", "parts": [{"label": "Free credit up to 45 days", "note": "A payment at the start of a cycle can stretch to about 45 days."}, {"label": "Statement ends the cycle", "note": "The issuer sends the statement when the cycle ends."}, {"label": "About 21 days to pay", "note": "The cardholder then has usually about 21 days to pay."}, {"label": "Pay in full, no interest", "note": "Full payment inside the window means no interest is charged."}, {"label": "Pay less, interest charged", "note": "Paying less leaves interest charged on the balance."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "RUN5-003", "seq": 320, "module": "Core", "source": "Article and reader comments", "title": "Interchange: the acquirer's fee to the issuer", "explain": "Interchange is what the acquirer pays the issuer per card transaction, known too as the wholesale fee or interexchange fee. It is the issuer's transaction fee in clearing and settlement, typically running to 75 to 85 percent of the merchant service charges. The merchant bears this cost through the fees charged on the transaction, not the cardholder.", "takeaway": "The merchant bears this cost through the fees charged on the transaction, not the cardholder.", "visual": {"type": "diagram", "diagram": {"centre": "Interchange: acquirer pays issuer", "parts": [{"label": "What it is", "note": "Compensation the acquirer pays the issuer per transaction."}, {"label": "Also called", "note": "Wholesale fee or interexchange fee."}, {"label": "Size", "note": "Typically 75 to 85 percent of merchant service charges."}, {"label": "Who bears it", "note": "The merchant bears the cost, not the cardholder."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "RUN5-007", "seq": 321, "module": "Core", "source": "Article and reader comments", "title": "Scheme fees: Mastercard per deal, Visa by membership", "explain": "The card schemes collect fees from merchants alongside the processor, and each scheme charges in its own way. The processing firm usually takes what it is owed straight from the merchant's account. Mastercard charges per transaction, while Visa charges yearly or quarterly memberships, so a merchant's scheme cost depends on which cards its customers use and how much volume goes through each scheme.", "takeaway": "Mastercard charges per transaction, while Visa charges yearly or quarterly memberships, so a merchant's scheme cost depends on which cards its customers use and how much volume goes through each scheme.", "visual": {"type": "diagram", "diagram": {"centre": "How schemes collect their fees", "parts": [{"label": "Processor", "note": "Usually takes its fees straight from the merchant account."}, {"label": "Mastercard", "note": "Charges per transaction."}, {"label": "Visa", "note": "Charges yearly or quarterly memberships."}, {"label": "Merchant cost varies", "note": "Cost depends on card mix and volume through each scheme."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "INS-101", "seq": 322, "module": "Core", "source": "Public post", "title": "Settlement method: who moves the funds", "explain": "In an ISO 20022 credit transfer the settlement method is the field that assigns settlement to one bank in the chain. INDA puts settlement on the instructed agent, so the next bank moves the funds, while INGA puts it on the instructing agent, so the sending bank moves the funds itself. Read the field first in any funding dispute, because it fixes which bank must hold the liquidity, which account is debited, and how both sides reconcile.", "takeaway": "Read the field first in any funding dispute, because it fixes which bank must hold the liquidity, which account is debited, and how both sides reconcile.", "visual": {"type": "diagram", "diagram": {"centre": "Who settles the payment", "parts": [{"label": "INDA", "note": "Instructed agent settles; the next bank moves funds."}, {"label": "INGA", "note": "Instructing agent settles; the sending bank moves funds."}, {"label": "Liquidity burden", "note": "Liquidity must sit with the settling bank."}, {"label": "Settlement timing", "note": "Settlement timing follows the settling bank."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-105", "seq": 323, "module": "Core", "source": "Public post", "title": "UPI feels instant; settlement is not", "explain": "UPI compresses the customer experience into seconds, debit seen at once, merchant receipt confirmed almost immediately, while the banks still settle with each other later under the scheme settlement cycle. Customer leg and interbank settlement are two separate events, and the bank funds the liquidity and reconciliation exposure between them. In any failure, separate the two events first and ask which one broke: the customer leg or the settlement leg.", "takeaway": "In any failure, separate the two events first and ask which one broke: the customer leg or the settlement leg.", "visual": {"type": "diagram", "diagram": {"centre": "Two events behind one payment", "parts": [{"label": "Debit at once", "note": "Account debited at once."}, {"label": "Credit in seconds", "note": "Receipt confirmed within seconds."}, {"label": "Settlement later", "note": "Banks settle later, on the scheme cycle."}, {"label": "The gap the bank funds", "note": "The bank funds the gap in between."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "resolution": "investigate"}, {"id": "INS-123", "seq": 330, "module": "Core", "source": "Public post", "title": "A mandate is a lifecycle, not a record", "explain": "Think of a mandate as a lifecycle, created, amended when a customer changes bank accounts, and cancelled, with a reference and evidence at every step. Scatter that evidence, a paper scan in a shared drive, an online consent in another system, an amendment as a free-text note, and a collection rejected for a missing or invalid mandate becomes unexplainable. Give billing one view of each mandate, its current state and the evidence that proves it.", "takeaway": "Give billing one view of each mandate, its current state and the evidence that proves it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Record the mandate with its reference.", "title": "Create the mandate"}, {"kind": "step", "note": "Log changes such as a new bank account.", "title": "Amend the mandate"}, {"kind": "step", "note": "Close the mandate with its evidence.", "title": "Cancel the mandate"}, {"kind": "step", "note": "Hold one view of state and proof.", "title": "Hold the evidence together"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "mandate issue", "resolution": "investigate"}, {"id": "INS-155", "seq": 331, "module": "Core", "source": "Public post", "title": "The mandate reference never changes", "explain": "A mandate reference is generated once and stays with the mandate from creation through amendments to cancellation. Every amendment and cancellation is recorded against it with an audit history, so any collection traces back to the mandate that authorised it. Reuse it, change it or lose it and the mandate cannot be proven, and its collections cannot be defended.", "takeaway": "Reuse it, change it or lose it and the mandate cannot be proven, and its collections cannot be defended.", "visual": {"type": "diagram", "diagram": {"centre": "One reference, whole life", "parts": [{"label": "Generated once", "note": "Created once and unique to the mandate."}, {"label": "Amendments logged", "note": "Logged against the same reference."}, {"label": "Cancellation logged", "note": "Logged against the same reference."}, {"label": "Full audit history", "note": "Each change is traceable."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "mandate issue"}, {"id": "INS-163", "seq": 336, "module": "Core", "source": "Public post", "title": "Core and B2B: the risk points differ", "explain": "Core and B2B differ exactly where risk is decided: who may use them, what refund rights the debtor holds, and what the debtor bank must verify before the first collection. A business collected under Core holds a refund right the creditor may not expect, while under B2B there is no such right but the mandate must be verified first. Running one process for both hides those differences, so record the scheme on each mandate and follow that scheme's current rulebook.", "takeaway": "Running one process for both hides those differences, so record the scheme on each mandate and follow that scheme's current rulebook.", "visual": {"type": "diagram", "diagram": {"centre": "Two schemes, two risk profiles", "parts": [{"label": "Who may use it", "note": "Core: consumers and businesses. B2B: businesses only."}, {"label": "Debtor refund rights", "note": "Core debtors hold a refund right; B2B debtors do not."}, {"label": "Mandate verification", "note": "B2B mandates are verified before the first collection."}, {"label": "Rulebook per scheme", "note": "Each scheme runs on its own rulebook."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "INS-165", "seq": 337, "module": "Core", "source": "Public post", "title": "One transfer, three stacked charges", "explain": "Take the cited example, a 140 euro transfer carrying an 11.39 percent fee, and the corridor cost structure becomes visible: the fee is not one charge but transfer fee plus exchange margin plus intermediary charges along the route. Splitting the total into components is what lets a customer compare corridors and an analyst say which part is avoidable. These figures describe that cited example only, not every transfer on the corridor, so present them as one case, never as the corridor rate.", "takeaway": "These figures describe that cited example only, not every transfer on the corridor, so present them as one case, never as the corridor rate.", "visual": {"type": "diagram", "diagram": {"centre": "Stacked cost of one transfer", "parts": [{"label": "Sending fee", "note": "Charged for sending the payment."}, {"label": "FX margin", "note": "Cost hidden inside the FX rate."}, {"label": "Charges en route", "note": "Taken by banks along the route."}, {"label": "Total paid", "note": "What the customer actually pays."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D01", "seq": 365, "module": "Core", "source": "Public post", "title": "TARGET calendar governs the interbank SDD leg", "explain": "SDD counting runs on Inter-PSP Business Days, defined as TARGET Business Days, so a national holiday elsewhere leaves the TARGET schedule and the collection validity untouched. TARGET drives Due Date, D-1 and settlement for the interbank journey, while each PSP applies its own Business Day calendar only to customer-facing service. Treating a national holiday calendar as the SDD Business Day calendar is the classic error, and the TARGET calendar is the one that controls the interbank leg.", "takeaway": "Treating a national holiday calendar as the SDD Business Day calendar is the classic error, and the TARGET calendar is the one that controls the interbank leg.", "visual": {"type": "diagram", "diagram": {"centre": "Two calendars inside one SDD collection", "parts": [{"label": "TARGET calendar, interbank leg", "note": "Sets Due Date, D-1, D-14 and settlement, and ignores national holidays."}, {"label": "PSP calendar, customer service", "note": "Each bank applies its own calendar to decide when customer service is open."}, {"label": "National holiday abroad", "note": "A holiday in another country does not halt interbank processing on a TARGET Business Day."}, {"label": "Finding the calendar", "note": "The ECB publishes the TARGET Calendar, which covers all TARGET services."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-D10", "seq": 371, "module": "Core", "source": "Public post", "title": "UETR: one reference for the whole payment journey", "explain": "The UETR, the Unique End-to-End Transaction Reference, is a 36-character RFC 4122 identifier issued by the initiating bank and unchanged from originator to beneficiary. It lets a bank follow the journey from end to end, pinpoint where the payment sits at any moment, and carry the relevant details forward along the way, while also helping banks manage liquidity, exceptions and reconciliation. When the beneficiary thinks the money has not arrived, the UETR lets them claim, trace and prove the payment, which is why a payment lacking a UETR travels with no track at all.", "takeaway": "When the beneficiary thinks the money has not arrived, the UETR lets them claim, trace and prove the payment, which is why a payment lacking a UETR travels with no track at all.", "visual": {"type": "diagram", "diagram": {"centre": "UETR: one reference, end-to-end visibility", "parts": [{"label": "36 characters, RFC 4122", "note": "Assigned by the initiating bank, unchanged for the whole journey."}, {"label": "Trace the journey", "note": "Shows where the payment is at any moment."}, {"label": "Claim and prove", "note": "Beneficiary can use it to claim, trace and prove the payment."}, {"label": "Supports the bank", "note": "Helps manage liquidity, exceptions and reconciliation."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "JEB-D11", "seq": 372, "module": "Core", "source": "Public post", "title": "OCT Inst and the non-euro leg in 60 seconds", "explain": "OCT Inst is already live and processes cross-border payments in 60 seconds, handling both the payment and the settlement, with both legs settled through the Euro system. The non-euro leg runs wholly outside the Euro area, governed by non-euro rules, standards and bank policies, with conversion completed before the beneficiary is paid, so the beneficiary receives exactly the amount expected. Speed is not the test here, reliability and rule-following are.", "takeaway": "Speed is not the test here, reliability and rule-following are.", "visual": {"type": "diagram", "diagram": {"centre": "The non-euro leg", "parts": [{"label": "OCT Inst in 60 seconds", "note": "Cross-border payments processed in 60 seconds, payment and settlement together."}, {"label": "Both legs through the Euro system", "note": "Both legs are settled through the Euro system."}, {"label": "Non-euro leg outside the Euro area", "note": "Operates under non-euro rules, standards and bank policies."}, {"label": "Beneficiary gets the expected amount", "note": "Conversion is handled before the beneficiary is paid."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D12", "seq": 373, "module": "Core", "source": "Public post", "title": "One-Leg Out: OCT Inst clears in 10 seconds", "explain": "One-Leg Out means a payment starts in Europe and goes outside it, with a euro leg plus a leg outside the euro area, and the One-Leg Out Instant Credit Transfer, OCT Inst, clears such cross-border payments in 10 seconds. As part of SEPA, OCT Inst follows the SEPA rule set, and clears and settles through the Euro leg, while payments can be made around the clock, every day of the year. Speed is not the point, an efficient, consistent and compliant process is.", "takeaway": "Speed is not the point, an efficient, consistent and compliant process is.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "One-Leg Out: the payment starts in Europe and goes outside it.", "title": "Payment starts in Europe"}, {"kind": "step", "note": "Euro amount is paid by the Euro Leg Payer PSP and credited to the Euro Leg Payee PSP.", "title": "Euro leg"}, {"kind": "step", "note": "Leg outside the Euro area, under non-euro rules and bank policies.", "title": "Non-euro leg"}, {"kind": "step", "note": "OCT Inst clears and settles through the Euro leg in 10 seconds, 24/7/365.", "title": "Cleared and settled in 10 seconds"}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN6-003", "seq": 380, "module": "Core", "source": "Article and reader comments", "title": "Blockchain networks: keys, ledger and controls", "explain": "Every node in the network is a validated participant holding cryptographic keys, so encryption and mutual awareness work much as they do under bilateral key exchange. Settlement rests on a distributed ledger maintained by each participant and refreshed with every transaction, with accounting posted to participant accounts held inside that ledger, and a network under CSM control leaves settlement to the CSM. Compliance remains a live discussion, yet sanctions and similar controls are expected to operate alongside near real time processing without slowing it.", "takeaway": "Compliance remains a live discussion, yet sanctions and similar controls are expected to operate alongside near real time processing without slowing it.", "visual": {"type": "diagram", "diagram": {"centre": "How a blockchain payment network settles", "parts": [{"label": "Validated keyed nodes", "note": "Each participant holds cryptographic keys for encryption."}, {"label": "Mutual awareness", "note": "Every node learns of a new participant joining."}, {"label": "Ledger settlement", "note": "Each participant maintains a ledger updated per transaction."}, {"label": "Accounts inside the ledger", "note": "Accounting posts to participant accounts in the ledger."}, {"label": "Controls alongside speed", "note": "Sanctions checks run beside near real time processing."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D15 Advanced and emerging payments", "messages": []}, {"id": "RUN6-007", "seq": 381, "module": "Core", "source": "Article and reader comments", "title": "Multilateral clearing dominates, bilateral stays rare", "explain": "Multilateral clearing dominates because netting collapses many payments into a few positions and saves a huge number of transactions. Bilateral clearing stays rare, gaining appeal only where the banks involved are very large. Banks also favour a single connection to the clearing and settlement mechanism to reach every other bank, and the mechanism manages credit risk for all participants.", "takeaway": "Banks also favour a single connection to the clearing and settlement mechanism to reach every other bank, and the mechanism manages credit risk for all participants.", "visual": {"type": "diagram", "diagram": {"centre": "Bilateral versus multilateral clearing", "parts": [{"label": "Multilateral is most frequent", "note": "Netting many payments into a few positions saves a huge number of transactions."}, {"label": "Bilateral is seldom used", "note": "It gains appeal mainly where the banks involved are very large."}, {"label": "One connection to the CSM", "note": "Banks prefer one connection to reach all other banks."}, {"label": "CSM manages credit risk", "note": "The mechanism manages credit risk for all participating banks."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-009", "seq": 382, "module": "Core", "source": "Article and reader comments", "title": "Settlement flows through the CSM central bank account", "explain": "The mechanism is a company, not a bank, and it settles through an account it holds with the central bank. Banks ending in a net debit position transfer funds into that account. The mechanism then credits the accounts of banks in net credit positions, so settlement flows through central bank money with the CSM in the middle.", "takeaway": "The mechanism then credits the accounts of banks in net credit positions, so settlement flows through central bank money with the CSM in the middle.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Banks end in net debit or credit", "note": "After netting, each bank has a net debit or a net credit position."}, {"kind": "step", "title": "Net debit banks pay the CSM", "note": "Banks in net debit transfer funds to the CSM account at the central bank."}, {"kind": "step", "title": "CSM credits net credit banks", "note": "The CSM credits the accounts of the banks in net credit positions."}, {"kind": "step", "title": "Settlement completes", "note": "Funds move through central bank accounts, with the CSM in the middle."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-010", "seq": 383, "module": "Core", "source": "Article and reader comments", "title": "How the CSM tracks flows and computes positions", "explain": "The mechanism sees every flow in both directions, receiving transactions from all banks to each bank and from each bank to all the others, so it can track how many each bank sent and received. A cut-off fixes the time limit after which no further transactions enter that cycle, and netting then starts on what is available. Amounts carried in the messages let the mechanism compute each participant position.", "takeaway": "Amounts carried in the messages let the mechanism compute each participant position.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "CSM receives all transactions", "note": "It gets transactions from all banks to each bank and from each bank to all others."}, {"kind": "step", "title": "CSM tracks sent and received", "note": "It keeps count of how many transactions each bank sent and received."}, {"kind": "step", "title": "Cut-off stops new transactions", "note": "After the cut-off, no more transactions are accepted for that cycle."}, {"kind": "step", "title": "Netting starts", "note": "The CSM nets with what is available, using the amounts in the messages."}, {"kind": "step", "title": "Positions computed", "note": "Each participant net position is computed from the amounts."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-018", "seq": 386, "module": "Core", "source": "Article and reader comments", "title": "Validating a SWIFT MX message with the MDR", "explain": "Validation of a SWIFT MX message follows the ISO 20022 standard. The authoritative place to read how a given message is validated is its Message Definition Report, which sets out the message content and its validation rules. Those reports are free to download from the ISO 20022 website.", "takeaway": "Those reports are free to download from the ISO 20022 website.", "visual": {"type": "diagram", "diagram": {"centre": "Validating a SWIFT MX message", "parts": [{"label": "Based on ISO 20022", "note": "MX validation follows the ISO 20022 standard."}, {"label": "Read the MDR", "note": "The Message Definition Report holds content and validation details."}, {"label": "Free to download", "note": "MDRs can be downloaded free from the ISO 20022 website."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "RUN6-020", "seq": 387, "module": "Core", "source": "Article and reader comments", "title": "Beneficiary credit deadline after pacs.008", "explain": "Once pacs.008 arrives, the creditor agent must put the funds at the beneficiary disposal on the settlement day. The Payment Services Directive leaves the beneficiary bank no float, so the credit cannot slip past that day. The settlement day itself is therefore the maximum window.", "takeaway": "The settlement day itself is therefore the maximum window.", "visual": {"type": "diagram", "diagram": {"centre": "Crediting the beneficiary after pacs.008", "parts": [{"label": "Funds available on settlement day", "note": "The creditor agent must credit the beneficiary on the settlement day."}, {"label": "No float for the bank", "note": "The Payment Services Directive allows no float for the beneficiary bank."}, {"label": "Maximum window is the day", "note": "The beneficiary is credited on the settlement day, not later."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": ["pacs.008"]}, {"id": "RUN6-021", "seq": 388, "module": "Core", "source": "Article and reader comments", "title": "MT101 also starts domestic corporate payments", "explain": "Corporates initiate domestic payments with MT101 just as they initiate cross-border ones, covering real time gross settlement, electronic funds transfer, automated clearing house and cheque payments. The commercial logic is that the corporate enterprise resource planning system generates one standard format to initiate all payables. A single MT101 format therefore starts every kind of payment a corporate makes.", "takeaway": "A single MT101 format therefore starts every kind of payment a corporate makes.", "visual": {"type": "diagram", "diagram": {"centre": "MT101 for domestic and cross-border payments", "parts": [{"label": "Domestic payments too", "note": "MT101 starts RTGS, EFT, ACH and cheque payments in country."}, {"label": "Cross-border payments", "note": "MT101 also starts international payments."}, {"label": "One format for the ERP", "note": "The corporate ERP generates a single standard format for all payables."}, {"label": "Every payable, one message", "note": "One MT101 format can initiate every kind of corporate payment."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "RUN6-022", "seq": 389, "module": "Core", "source": "Article and reader comments", "title": "Concentrating bank forwards the same MT101", "explain": "In the concentration cases the bank forwards the MT101 it received instead of originating a new one. It pulls out the MT101 due to each destination bank and processes its own instruction, the one where it stands as debtor bank. The same instruction therefore travels onward, split per destination where needed.", "takeaway": "The same instruction therefore travels onward, split per destination where needed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Concentrating bank receives MT101", "note": "The corporate sends one MT101 to the concentrating bank."}, {"kind": "step", "title": "Same MT101 is forwarded", "note": "The bank forwards the same MT101, not a new one."}, {"kind": "step", "title": "Extract per destination", "note": "It extracts the MT101 to be forwarded to each destination bank."}, {"kind": "step", "title": "Process its own share", "note": "It processes the MT101 for which it is the debtor bank."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "RUN6-025", "seq": 390, "module": "Core", "source": "Article and reader comments", "title": "Can MT101 carry a SEPA payment?", "explain": "A SEPA payment can travel on an MT101, but the message cannot hold all the information a pain.001 can carry. Whether a bank processes MT101 as a SEPA payment turns entirely on that bank's own capabilities, so not every bank will do it. Where the information fits, MT101 works for SEPA; where it does not, pain.001 is the right message.", "takeaway": "Where the information fits, MT101 works for SEPA; where it does not, pain.001 is the right message.", "visual": {"type": "diagram", "diagram": {"centre": "MT101 as a SEPA payment", "parts": [{"label": "Yes, it can carry SEPA", "note": "A SEPA payment can be sent with an MT101."}, {"label": "But not all the information", "note": "MT101 cannot carry everything pain.001 can."}, {"label": "Depends on the bank", "note": "Whether a bank processes MT101 as SEPA depends on its capabilities."}, {"label": "pain.001 when it does not fit", "note": "Where the information does not fit, pain.001 is the right message."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "pain.001"]}, {"id": "RUN6-026", "seq": 391, "module": "Core", "source": "Article and reader comments", "title": "Account servicing institution: debit then MT103", "explain": "The account servicing institution is the bank holding the account to be debited. On receiving the MT101 it processes the instruction against that account. It then issues an MT103 to move the funds onward, so the MT101 instructs the debit and the MT103 carries the money.", "takeaway": "It then issues an MT103 to move the funds onward, so the MT101 instructs the debit and the MT103 carries the money.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT101 arrives", "note": "The ordering customer sends an MT101 to the bank."}, {"kind": "step", "title": "ASI holds the account", "note": "The account servicing institution holds the account to be debited."}, {"kind": "step", "title": "ASI processes the MT101", "note": "It processes the instruction against the account."}, {"kind": "step", "title": "ASI issues an MT103", "note": "It issues an MT103 to move the funds onward."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "MT103"]}, {"id": "RUN6-031", "seq": 392, "module": "Core", "source": "Article and reader comments", "title": "Creditor bank need not check the mandate", "explain": "SEPA applies the creditor driven mandate flow, so the creditor bank carries no obligation to check a pacs.003 against an active mandate. The creditor bank may still validate if it chooses, but the scheme does not require it. That contrasts with a debtor driven flow, where the debtor side holds the mandate.", "takeaway": "That contrasts with a debtor driven flow, where the debtor side holds the mandate.", "visual": {"type": "diagram", "diagram": {"centre": "Checking mandates for pacs.003", "parts": [{"label": "Creditor driven flow applies", "note": "In SEPA the creditor driven mandate flow is used."}, {"label": "No obligation to check", "note": "The creditor bank need not validate pacs.003 against mandates."}, {"label": "Validation is optional", "note": "The creditor bank may still choose to validate."}, {"label": "Debtor driven differs", "note": "In a debtor driven flow the debtor side holds the mandate."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": ["pacs.003"], "failure_category": "mandate issue"}, {"id": "RUN7-001", "seq": 393, "module": "Core", "source": "Article and reader comments", "title": "Open loop versus closed loop: who runs each", "explain": "Open loop systems are run by financial service providers regulated within the national payment system environment. Closed loop systems are usually run by non-financial service providers, and the payment is used for goods or services. A clothing store voucher for a pair of shoes worth R1000 shows the closed loop pattern.", "takeaway": "A clothing store voucher for a pair of shoes worth R1000 shows the closed loop pattern.", "visual": {"type": "diagram", "diagram": {"centre": "Open loop and closed loop payment systems", "parts": [{"label": "Open loop: run by financial service providers", "note": "Providers regulated in the national payment system environment."}, {"label": "Closed loop: run by non-financial service providers", "note": "The payment is used for goods or services."}, {"label": "Closed loop example: store voucher", "note": "A clothing store voucher for a pair of shoes worth R1000."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN7-002", "seq": 394, "module": "Core", "source": "Article and reader comments", "title": "Can a private individual pay by promissory note?", "explain": "In some countries, such as France, only businesses can issue promissory notes, so a private individual cannot use one to pay. Elsewhere the law may permit private individuals to issue them, yet banks stay silent about them and steer people toward bank loans, which are legally and financially more interesting for the banks. A bank or finance company may therefore refuse a personal promissory note even where the law allows it.", "takeaway": "A bank or finance company may therefore refuse a personal promissory note even where the law allows it.", "visual": {"type": "diagram", "diagram": {"centre": "Can a private individual pay with a promissory note?", "parts": [{"label": "France: only businesses can issue", "note": "In some countries, such as France, promissory notes can be issued only by businesses."}, {"label": "Other places: the law may allow it", "note": "The law may allow private individuals to issue them."}, {"label": "Banks do not communicate about them", "note": "Banks would rather people take bank loans, which are legally and financially more interesting for the banks."}, {"label": "Refusal is possible", "note": "A bank or finance company may refuse a personal promissory note even where the law allows it."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "RUN7-003", "seq": 395, "module": "Core", "source": "Article and reader comments", "title": "Push or pull: follow the money, not the device", "explain": "Push and pull describe the movement of the instruction and the funds, never the technology behind the payment. A PayPal reserve debit sent straight to the beneficiary counts as push. Paying by card through PayPal counts as pull: the beneficiary is credited right away after a balance check, while the bank account behind the card is debited one or two days later. A credit transfer started directly from a bank account counts as push, with the account debited right away.", "takeaway": "A credit transfer started directly from a bank account counts as push, with the account debited right away.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Push or pull describes the movement", "note": "It describes how the instruction and the funds move, not the technology used."}, {"kind": "step", "title": "PayPal reserve debit is push", "note": "Money debited from a PayPal reserve and sent to the beneficiary is a push transaction."}, {"kind": "step", "title": "Card through PayPal is pull", "note": "PayPal checks the balance, credits the beneficiary at once, but the bank account is debited one or two days later."}, {"kind": "step", "title": "Bank account credit transfer is push", "note": "A credit transfer initiated directly from a bank account is a push transaction, with the account debited right away."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D03 Payment lifecycle", "messages": []}, {"id": "RUN7-004", "seq": 396, "module": "Core", "source": "Article and reader comments", "title": "Wallet and bank account: moving your own money", "explain": "Moving funds between a mobile wallet and a bank account means moving money between two accounts belonging to the same customer. Push transactions should be enough for these moves. A wallet to bank transfer should start only when the wallet holds sufficient funds, and a bank to wallet transfer only when the bank account holds sufficient funds.", "takeaway": "A wallet to bank transfer should start only when the wallet holds sufficient funds, and a bank to wallet transfer only when the bank account holds sufficient funds.", "visual": {"type": "diagram", "diagram": {"centre": "Moving money between a mobile wallet and a bank account", "parts": [{"label": "Two of your own accounts", "note": "The customer is moving money between two of their own accounts."}, {"label": "Push transactions should be enough", "note": "Push transactions should be enough for these moves."}, {"label": "Wallet to bank: needs wallet funds", "note": "A transfer from the wallet to the bank should be initiated only when there are sufficient funds on the wallet."}, {"label": "Bank to wallet: needs bank funds", "note": "A transfer from the bank to the wallet should be initiated only when there are sufficient funds on the bank account."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D02 Accounts, ledger and accounting", "messages": []}, {"id": "RUN7-005", "seq": 397, "module": "Core", "source": "Article and reader comments", "title": "SEPA Cards done, SEPA Cash still ongoing", "explain": "The SEPA Cards Framework stands complete across the SEPA area, with Visa and Mastercard as the two main card networks and interoperability that was already working accelerated by SEPA. Major projects that began in 2007 to 2010 are complete, so people in Europe can now use their bank cards in any SEPA country regardless of the country that issued the card. The SEPA Cash initiative remains a work in progress, because cash is a sensitive area and standardising practices everywhere in SEPA is a real challenge.", "takeaway": "The SEPA Cash initiative remains a work in progress, because cash is a sensitive area and standardising practices everywhere in SEPA is a real challenge.", "visual": {"type": "diagram", "diagram": {"centre": "SEPA Cards Framework and SEPA Cash: where each stands", "parts": [{"label": "SEPA Cards Framework is complete", "note": "It is complete in the SEPA area, with Visa and Mastercard as the two main card networks."}, {"label": "Interoperability accelerated", "note": "Interoperability that was already working was accelerated by SEPA."}, {"label": "Major projects 2007 to 2010 complete", "note": "Major projects began in 2007 to 2010 and are complete."}, {"label": "Cards work across SEPA today", "note": "Today people in Europe can use their bank cards in any SEPA country no matter where the card was issued."}, {"label": "SEPA Cash is still ongoing", "note": "Cash is a sensitive area and standardizing practices everywhere in SEPA is a real challenge."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "RUN7-007", "seq": 398, "module": "Core", "source": "Article and reader comments", "title": "GPA versus FIN: system messages or user traffic", "explain": "The General Purpose Application carries system messages only: a user writing to SWIFT, or SWIFT writing to a user, never one user writing to another. The FIN Application carries messages from one user to another, and alongside that it covers the user-to-user range MT1xx through MT9xx, the system messages MT0xx, plus other service messages such as acknowledgements. The distinction is therefore about who a message can travel between, not the network itself.", "takeaway": "The distinction is therefore about who a message can travel between, not the network itself.", "visual": {"type": "diagram", "diagram": {"centre": "SWIFT General Purpose Application versus FIN Application", "parts": [{"label": "General Purpose Application: system messages only", "note": "It allows only system messages, from a user to SWIFT or from SWIFT to a user, but not from one user to another."}, {"label": "FIN Application: user to user messages", "note": "It allows messages from one user to another."}, {"label": "FIN includes MT0xx system messages", "note": "The FIN Application includes the system messages MT0xx."}, {"label": "FIN includes MT1xx to MT9xx", "note": "It includes the user-to-user messages MT1xx through MT9xx."}, {"label": "FIN includes other service messages", "note": "It includes other service messages such as acknowledgements."}, {"label": "The difference is who messages travel between", "note": "The difference is who the message can travel between, not the network itself."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT0xx", "MT1xx", "MT9xx"]}, {"id": "RUN7-009", "seq": 399, "module": "Core", "source": "Article and reader comments", "title": "Interchange pays for the issuer guarantee", "explain": "Card networks do not charge interchange. The fee compensates the issuer, who takes on all the risk, authorises the transaction and guarantees payment to the merchant. That guarantee is what interchange pays for.", "takeaway": "That guarantee is what interchange pays for.", "visual": {"type": "diagram", "diagram": {"centre": "Why interchange exists: the issuer takes the risk", "parts": [{"label": "Not a network charge", "note": "Card networks do not charge interchange."}, {"label": "It compensates the issuer", "note": "Interchange compensates the issuer."}, {"label": "The issuer authorises after accepting all risk", "note": "The issuer authorises the transaction after accepting all risk."}, {"label": "The issuer guarantees payment to the merchant", "note": "The issuer guarantees the payment to the merchant."}, {"label": "The guarantee is what interchange pays for", "note": "The issuer's guarantee is what the interchange pays for."}]}}, "level": "core", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "ABH-27", "seq": 400, "module": "Advanced", "source": "Public post", "title": "When AI agents pay for customers", "explain": "An AI agent that pays on behalf of a customer follows six steps: understand, verify, evaluate, authorize, execute and confirm. The use cases range from paying bills to paying vendor invoices, and the authorisation step is the control that makes the whole flow safe.", "takeaway": "The use cases range from paying bills to paying vendor invoices, and the authorisation step is the control that makes the whole flow safe.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Understand", "note": "Agent understands the payment request"}, {"kind": "step", "title": "Verify", "note": "Agent verifies the payment details"}, {"kind": "step", "title": "Evaluate", "note": "Agent evaluates the payment"}, {"kind": "decision", "title": "Authorize", "note": "The control that makes the flow safe"}, {"kind": "step", "title": "Execute", "note": "Pays bills and vendor invoices"}, {"kind": "step", "title": "Confirm", "note": "Payment confirmed to the customer"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "ABH-28", "seq": 401, "module": "Advanced", "source": "Public post", "title": "Coinbase x402: internet-native payments", "explain": "Coinbase x402 is a standard for internet-native payments that lets AI agents pay for APIs and digital services with stablecoins. It enables pay-per-use, micropayments and programmable payments, so a machine can pay a machine for exactly what it used.", "takeaway": "It enables pay-per-use, micropayments and programmable payments, so a machine can pay a machine for exactly what it used.", "visual": {"type": "diagram", "diagram": {"centre": "Coinbase x402", "parts": [{"label": "Stablecoins", "note": "The payment currency for agents"}, {"label": "Pay-per-use", "note": "Pay for exactly what was used"}, {"label": "Micropayments", "note": "Small payments machines can make"}, {"label": "Programmable payments", "note": "Payments a machine can trigger"}, {"label": "APIs and digital services", "note": "What agents pay for"}, {"label": "Internet-native payments", "note": "Built for the internet, not cards"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D15 Advanced and emerging payments", "messages": []}, {"id": "ABH-29", "seq": 402, "module": "Advanced", "source": "Public post", "title": "An AI assistant built for BFSI", "explain": "Anomic AI is an AI assistant built for banking, financial services and insurance, for banking knowledge, BRD creation and customer conversations. It is an example of AI aimed at the daily work of a banking professional rather than at the customer.", "takeaway": "It is an example of AI aimed at the daily work of a banking professional rather than at the customer.", "visual": {"type": "diagram", "diagram": {"centre": "An AI assistant for BFSI", "parts": [{"label": "Banking knowledge", "note": "Answers grounded in banking"}, {"label": "BRD creation", "note": "Drafts business requirements"}, {"label": "Customer conversations", "note": "Handles customer-facing chat"}, {"label": "Banking professionals", "note": "Built for daily banking work"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "ABH-30", "seq": 403, "module": "Advanced", "source": "Public post", "title": "BFSI chatbots and BRDs in minutes", "explain": "The Anomic AI brand partnership promises smarter BFSI chatbots and BRDs in ten minutes instead of three days. The claim is about speed: the same banking document, produced far faster.", "takeaway": "The claim is about speed: the same banking document, produced far faster.", "visual": {"type": "diagram", "diagram": {"centre": "Smarter BFSI chatbots and BRDs", "parts": [{"label": "BRDs in ten minutes", "note": "Same document, produced far faster"}, {"label": "BRDs in three days", "note": "Old time to produce the document"}, {"label": "Smarter chatbots", "note": "Chatbots that serve banking better"}, {"label": "Speed", "note": "Claim is about speed, not new content"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-029", "seq": 448, "module": "Advanced", "source": "Public post", "title": "End-to-end payment transaction lifecycle", "explain": "A payment moves through a chain of states from initiation to confirmation, and each state needs a named owner and a named piece of evidence. Initiation creates the instruction with an instruction ID and an end-to-end ID, validation checks the instruction, routing chooses the rail, clearing moves it through the scheme, settlement moves the funds between banks, posting records it in the ledger, and confirmation tells the customer it is done. When a payment goes missing, the investigation follows this chain state by state, because the state where the evidence stops is the state where the payment is stuck.", "takeaway": "When a payment goes missing, the investigation follows this chain state by state, because the state where the evidence stops is the state where the payment is stuck.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Creates the instruction with instruction and end-to-end IDs."}, {"kind": "step", "title": "Validation", "note": "Checks the instruction."}, {"kind": "step", "title": "Routing", "note": "Chooses the rail."}, {"kind": "step", "title": "Clearing", "note": "Moves the payment through the scheme."}, {"kind": "step", "title": "Settlement", "note": "Moves the funds between banks."}, {"kind": "step", "title": "Posting", "note": "Records the payment in the ledger."}, {"kind": "step", "title": "Confirmation", "note": "Tells the customer the payment is done."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "INS-031", "seq": 449, "module": "Advanced", "source": "Public post", "title": "End-to-end credit card transaction flow", "explain": "A credit card transaction has four distinct stages with different owners and different evidence. Authorisation happens in seconds: the terminal sends the card and transaction details to the acquirer, the scheme routes them to the issuer, and the issuer checks the card status, the available credit and the fraud rules, then approves or declines and places a hold on the funds. Clearing exchanges the transaction records, settlement moves the funds between the banks, and billing and dispute touchpoints handle the customer statement and any later dispute. Each stage must be understood separately, because a problem at authorisation looks nothing like a problem at settlement.", "takeaway": "Each stage must be understood separately, because a problem at authorisation looks nothing like a problem at settlement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorisation", "note": "Issuer checks card, credit and fraud rules, then holds funds."}, {"kind": "step", "title": "Clearing", "note": "Exchanges the transaction records."}, {"kind": "step", "title": "Settlement", "note": "Moves the funds between the banks."}, {"kind": "step", "title": "Billing and disputes", "note": "Handles the statement and any later dispute."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "sanctions or fraud block"}, {"id": "PAI-C041", "seq": 478, "module": "Advanced", "source": "Article and reader comments", "title": "Message flow after the clearing system", "explain": "After the clearing system, the message flow continues with the pacs.008 reaching the beneficiary bank and the pacs.002 reporting the status back, and the question is how those messages fit together once the clearing system is in the middle. The clearing system sits between the originator bank and the beneficiary bank, so the pacs.008 passes through it and the pacs.002 returns through it. An analyst drawing the flow must include the clearing system as a party, not as a pipe, because it sends and receives messages of its own.", "takeaway": "An analyst drawing the flow must include the clearing system as a party, not as a pipe, because it sends and receives messages of its own.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 passes through clearing system", "note": "The pacs.008 reaches the beneficiary bank through the clearing system"}, {"kind": "step", "title": "Clearing system sends and receives", "note": "The clearing system is a party with messages of its own"}, {"kind": "step", "title": "pacs.002 reports status back", "note": "The pacs.002 reports the status back through the clearing system"}, {"kind": "step", "title": "Draw clearing system as a party", "note": "Draw it as a party, not as a pipe"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": ["pacs.008", "pacs.002"], "failure_category": "system or connectivity failure", "resolution": "return"}, {"id": "PAI-C043", "seq": 480, "module": "Advanced", "source": "Article and reader comments", "title": "Language never blocks an MT103", "explain": "When the beneficiary bank is in a country whose language is not English, the MT103 is still processed from its structured fields, which are coded and do not depend on the language of the country. The names and addresses in the message may be in the local language, but the fields that drive processing, such as the account number, the currency, and the amount, are numeric or coded. Processing therefore does not stop at a language barrier; it follows the fields.", "takeaway": "Processing therefore does not stop at a language barrier; it follows the fields.", "visual": {"type": "diagram", "diagram": {"centre": "A payment to a non-English-speaking country", "parts": [{"label": "Structured fields are coded", "note": "The MT103 is processed from coded structured fields"}, {"label": "Names may be in the local language", "note": "Names and addresses may be in the local language"}, {"label": "Account, currency and amount drive processing", "note": "Account number, currency and amount are numeric or coded"}, {"label": "Processing follows the fields", "note": "Processing follows the fields, not the language"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT103"]}, {"id": "PAI-C048", "seq": 485, "module": "Advanced", "source": "Article and reader comments", "title": "Faster Payments and BACS: not SEPA messages", "explain": "The messages exchanged between banks in UK Faster Payments and in BACS are different from the messages used in SEPA, and readers ask for the flow in each system. The SEPA message set is a good starting point, because the concepts of initiation, clearing, and status reporting are the same, but the actual messages and the clearing systems differ. An analyst who understands the SEPA flow can learn the UK flows by mapping each SEPA message to its UK equivalent, rather than starting from nothing.", "takeaway": "An analyst who understands the SEPA flow can learn the UK flows by mapping each SEPA message to its UK equivalent, rather than starting from nothing.", "visual": {"type": "diagram", "diagram": {"centre": "UK Faster Payments and BACS flows", "parts": [{"label": "Different messages from SEPA", "note": "Faster Payments and BACS messages differ from SEPA messages"}, {"label": "Same concepts: initiation, clearing, status", "note": "Initiation, clearing and status reporting work the same way"}, {"label": "Actual messages and clearing differ", "note": "The actual messages and clearing systems differ from SEPA"}, {"label": "Map each SEPA message to its UK equivalent", "note": "Learn UK flows by mapping each SEPA message to its UK equivalent"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": []}, {"id": "PAI-C050", "seq": 487, "module": "Advanced", "source": "Article and reader comments", "title": "Why BACS outlasts Faster Payments for bulk pay", "explain": "Faster Payments settles in seconds, yet BACS remains the preferred way to pay for many UK businesses, and the reason is that BACS is built for bulk, scheduled, low-cost payments such as salaries and supplier runs. Faster Payments is built for single, urgent payments, and it costs more per payment and carries limits that bulk runs do not want. The two systems therefore serve different needs, and the older one survives because it fits the bulk use case better.", "takeaway": "The two systems therefore serve different needs, and the older one survives because it fits the bulk use case better.", "visual": {"type": "diagram", "diagram": {"centre": "Why BACS is still preferred after Faster Payments", "parts": [{"label": "BACS", "note": "Bulk, scheduled, low-cost payments such as salaries and supplier runs"}, {"label": "Faster Payments", "note": "Single, urgent payments, more costly per payment"}, {"label": "Different needs", "note": "The older system survives because it fits the bulk use case"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "PAI-C052", "seq": 489, "module": "Advanced", "source": "Article and reader comments", "title": "Cover currency and fields 52, 53 and 54", "explain": "In a cover payment the MT103 and the MT202 can carry different currencies, and the question is how the currency of each leg is decided and what fields 52, 53 and 54 carry. Field 52 identifies the ordering institution, field 53 identifies the sender's correspondent, and field 54 identifies the receiver's correspondent, so together they describe the chain of banks that will fund the payment. The currency of the cover leg follows the correspondent account it settles in, which is why the two legs can differ.", "takeaway": "The currency of the cover leg follows the correspondent account it settles in, which is why the two legs can differ.", "visual": {"type": "diagram", "diagram": {"centre": "Currency and fields 52, 53 and 54", "parts": [{"label": "Legs can carry different currencies", "note": "The MT103 and the MT202 can carry different currencies"}, {"label": "Field 52: ordering institution", "note": "Field 52 identifies the ordering institution"}, {"label": "Field 53: sender's correspondent", "note": "Field 53 identifies the sender's correspondent"}, {"label": "Field 54: receiver's correspondent", "note": "Field 54 identifies the receiver's correspondent"}, {"label": "Cover currency follows its account", "note": "The cover currency follows the correspondent account it settles in"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"]}, {"id": "PAI-C086", "seq": 495, "module": "Advanced", "source": "Article and reader comments", "title": "A future-dated MT103 cannot be discounted", "explain": "An MT103 can be value-dated far in the future, but that does not turn it into an instrument a bank will discount. An MT103 is an instruction to pay, not a proof of financial commitment: when the due date arrives, execution depends on the payer account holding sufficient funds. If the payer does not pay, the beneficiary has no recourse, and neither does a bank that discounted it, unless it signed a separate contract with the payer.", "takeaway": "If the payer does not pay, the beneficiary has no recourse, and neither does a bank that discounted it, unless it signed a separate contract with the payer.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 value-dated far in the future", "note": "An MT103 can be value-dated far in the future"}, {"kind": "step", "title": "MT103 is an instruction to pay", "note": "An MT103 is an instruction to pay, not proof of financial commitment"}, {"kind": "decision", "title": "Payer account holds sufficient funds", "note": "At the due date the payment executes only if the payer's account holds sufficient funds"}, {"kind": "step", "title": "Beneficiary has no recourse if unpaid", "note": "If the payer does not pay, the beneficiary has no recourse"}, {"kind": "step", "title": "Discounting bank needs a separate contract", "note": "A bank that discounted it has no recourse without a separate contract with the payer"}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "RUN4-020", "seq": 499, "module": "Advanced", "source": "Article and reader comments", "title": "France before SEPA: PNS and TBF, then CORE for retail", "explain": "Before SEPA, France already ran EBA systems for interbank payments alongside high value systems called PNS and TBF. CORE, the retail clearing system, arrived after SEPA to process XML format files and improve retail payment services. The market infrastructures changed greatly with the SEPA project, with old and new systems sitting side by side for a time.", "takeaway": "The market infrastructures changed greatly with the SEPA project, with old and new systems sitting side by side for a time.", "visual": {"type": "diagram", "diagram": {"centre": "France: systems before and after SEPA", "parts": [{"label": "PNS and TBF, high value", "note": "France ran high value systems called PNS and TBF before SEPA."}, {"label": "EBA systems for interbank", "note": "EBA systems already handled interbank payments before SEPA."}, {"label": "CORE for retail", "note": "CORE, the retail clearing system, arrived after SEPA."}, {"label": "Better retail services", "note": "CORE improved services for retail payments."}, {"label": "Old and new side by side", "note": "The infrastructures changed greatly, with old and new side by side."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN5-005", "seq": 500, "module": "Advanced", "source": "Article and reader comments", "title": "RuPay: scheme and clearing house in one", "explain": "On RuPay, clearing and settlement run between domestic and other network partners, with RuPay acting as both the card scheme and the clearing house. In India the clearing house role sits with NPCI, which operates RuPay. When issuer and acquirer are both RuPay members, they clear their transactions through RuPay itself rather than through a separate clearing house.", "takeaway": "When issuer and acquirer are both RuPay members, they clear their transactions through RuPay itself rather than through a separate clearing house.", "visual": {"type": "diagram", "diagram": {"centre": "RuPay clearing and settlement", "parts": [{"label": "Scheme and clearing house", "note": "RuPay acts as both the card scheme and the clearing house."}, {"label": "NPCI operates RuPay", "note": "In India the clearing house role sits with NPCI."}, {"label": "Clearing between partners", "note": "Clearing and settlement run between domestic and other network partners."}, {"label": "Members clear through RuPay", "note": "Two RuPay members clear through RuPay itself, not a separate house."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D08 Cards and alternative payments", "messages": []}, {"id": "RUN6-011", "seq": 522, "module": "Advanced", "source": "Article and reader comments", "title": "Status responses: CSM on RTGS, beneficiary bank abroad", "explain": "The sender of a status response depends on the rail the payment travelled. On a real time gross settlement system the clearing and settlement mechanism sends pacs.002, pacs.004 and camt.029 to the originator. On a cross-border payment the beneficiary bank, or instructed bank, sends them.", "takeaway": "On a cross-border payment the beneficiary bank, or instructed bank, sends them.", "visual": {"type": "diagram", "diagram": {"centre": "Who sends the status responses", "parts": [{"label": "RTGS: the CSM", "note": "In real time gross settlement, the CSM sends pacs.002, pacs.004 and camt.029."}, {"label": "Cross-border: the beneficiary bank", "note": "In cross-border payments, the beneficiary or instructed bank sends them."}, {"label": "It depends on the rail", "note": "The sender depends on which rail the payment travelled on."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pacs.002", "pacs.004", "camt.029"]}, {"id": "RUN6-015", "seq": 524, "module": "Advanced", "source": "Article and reader comments", "title": "Scheme cycles for direct and indirect participants", "explain": "Cycle sign-up belongs to the direct participant alone, so a direct participant enrolled for cycle 00 receives those transactions yet sends nothing to an indirect participant that did not enrol. Forwarding runs on a timetable the two agree separately, for instance once at the end of the day, and stays independent of the cycles. In classic SEPA only the direct participant exchanges files with the clearing and settlement mechanism. In SCT Inst some indirect participants connect directly to the mechanism and files move immediately, so no cycles exist there.", "takeaway": "In SCT Inst some indirect participants connect directly to the mechanism and files move immediately, so no cycles exist there.", "visual": {"type": "diagram", "diagram": {"centre": "Scheme cycles for direct and indirect participants", "parts": [{"label": "Only the DP signs up", "note": "Only the direct participant can sign up for scheme cycles."}, {"label": "DP receives, IP may not", "note": "The DP gets cycle 00 transactions but sends nothing to an IP that did not sign up."}, {"label": "Forwarding is separately agreed", "note": "The IP receives files when the DP forwards them, on an agreed schedule."}, {"label": "Classic SEPA: DP only", "note": "Only the DP exchanges files with the CSM in classic SEPA."}, {"label": "SCT Inst: direct IP links", "note": "In SCT Inst some IPs connect directly and files move immediately, with no cycles."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-017", "seq": 525, "module": "Advanced", "source": "Article and reader comments", "title": "Reading pacs.008 for direct or indirect payment", "explain": "Two agents in pacs.008 reveal the participation model behind a payment. Where the payer is a direct participant, both instructing agent and debtor agent name that direct participant. Where the payer is indirect, the instructing agent still names the direct participant while the debtor agent names the indirect participant.", "takeaway": "Where the payer is indirect, the instructing agent still names the direct participant while the debtor agent names the indirect participant.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.008 for direct and indirect payments", "parts": [{"label": "Direct: instructing agent is the DP", "note": "The direct participant instructs the payment."}, {"label": "Direct: debtor agent is the DP", "note": "The direct participant is also the debtor."}, {"label": "Indirect: instructing agent is the DP", "note": "The direct participant still instructs the payment."}, {"label": "Indirect: debtor agent is the IP", "note": "The indirect participant is the debtor."}, {"label": "Two fields tell the story", "note": "Reading both fields shows which kind of participant paid."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["pacs.008"]}, {"id": "RUN6-024", "seq": 526, "module": "Advanced", "source": "Article and reader comments", "title": "TAG 21 of MT101 stays out of the MT103", "explain": "TAG 21 of an MT101 never maps into the MT103 that follows. It serves reporting to the ordering customer about the MT101, letting that customer reconcile the reporting automatically with the original transaction. TAG 21 stops there and never travels to the next party in the chain.", "takeaway": "TAG 21 stops there and never travels to the next party in the chain.", "visual": {"type": "diagram", "diagram": {"centre": "TAG 21 of MT101", "parts": [{"label": "Not mapped to MT103", "note": "TAG 21 does not appear in the MT103 that follows."}, {"label": "Used in customer reporting", "note": "It appears in reporting sent to the ordering customer."}, {"label": "Enables reconciliation", "note": "The customer reconciles the reporting with the original transaction."}, {"label": "Not forwarded onward", "note": "TAG 21 is not passed to the next party in the chain."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D04 Messaging and standards", "messages": ["MT101", "MT103"]}, {"id": "RUN6-030", "seq": 528, "module": "Advanced", "source": "Article and reader comments", "title": "Routing e-mandates without a CSM in the middle", "explain": "A creditor bank needs a player in between to route e-mandate messages to debtor banks, but that player does not have to be a clearing and settlement mechanism. The operating model defines two services for this: routing and validation, each delivered by a service provider, and either service can come from a debtor bank, a creditor bank or a CSM. Market players such as GoCardless and EquensWorldline provide this kind of routing service, and a search for SEPA e-mandate providers finds more names.", "takeaway": "Market players such as GoCardless and EquensWorldline provide this kind of routing service, and a search for SEPA e-mandate providers finds more names.", "visual": {"type": "diagram", "diagram": {"centre": "Routing e-mandate messages without a CSM", "parts": [{"label": "A player in between is needed", "note": "The creditor bank needs someone to route the message to debtor banks."}, {"label": "Routing service provider", "note": "Routes the messages between the parties."}, {"label": "Validation service provider", "note": "Validates the messages in the flow."}, {"label": "Any party can provide them", "note": "A debtor bank, creditor bank or CSM can provide either service."}, {"label": "Market players exist", "note": "GoCardless and EquensWorldline are examples of routing providers."}]}}, "level": "advanced", "stage": 1, "stage_name": "Payment mechanics", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-C01", "seq": 28, "module": "Foundations", "source": "Public post", "title": "VoP No Match: the payment does not always stop", "explain": "Verification of Payee tests whether the name the payer gave matches the name the payee bank holds for the account, cutting authorised push payment fraud and misdirected payments. A No Match result does not stop the payment automatically: depending on the bank process, the payer can review and correct the details, or continue knowing the payment may reach the wrong payee. A No Match says only that the name does not match, not whether it is fraud or a simple error, so it needs attention but not automatic rejection, and a BA documenting VoP requirements must capture these rules rather than assume No Match means stop.", "takeaway": "A No Match says only that the name does not match, not whether it is fraud or a simple error, so it needs attention but not automatic rejection, and a BA documenting VoP requirements must capture these rules rather than assume No Match means stop.", "visual": {"type": "diagram", "diagram": {"centre": "No Match does not always stop payment", "parts": [{"label": "Name match check", "note": "VoP checks whether the payer name matches the name the payee bank holds"}, {"label": "Cuts fraud and misdirection", "note": "The check cuts authorised push payment fraud and misdirected payments"}, {"label": "Review and correct, or continue", "note": "The payer can review and correct the details or continue with the payment"}, {"label": "No Match is not proof of fraud", "note": "No Match says only the name does not match, not whether it is fraud or an error"}, {"label": "Attention, not automatic rejection", "note": "A No Match needs attention but not automatic rejection"}, {"label": "Capture the rules", "note": "Document the rules rather than assuming a No Match means stop"}]}}, "level": "foundation", "stage": 2, "stage_name": "Processing decisions", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "message mismatch", "resolution": "reject"}, {"id": "PAI-C003", "seq": 51, "module": "Foundations", "source": "Article and reader comments", "title": "Why banks split information from funds", "explain": "The cover method separates the payment instruction from the funds so the MT103 can reach the beneficiary bank fast while settlement works through correspondent accounts at its own pace. Keeping customer details out of the funds leg also protects privacy and keeps the correspondent chain clean. The price is reconciliation: the two legs must match on amount and reference, and any mismatch becomes an exception.", "takeaway": "The price is reconciliation: the two legs must match on amount and reference, and any mismatch becomes an exception.", "visual": {"type": "diagram", "diagram": {"centre": "Why split the two legs", "parts": [{"label": "Separate paths for information and funds", "note": "Instruction arrives fast, funds settle through correspondents"}, {"label": "Customer details kept out of funds leg", "note": "Privacy holds and the correspondent chain stays clean"}, {"label": "Two legs must be matched", "note": "An amount or reference mismatch becomes an exception"}]}}, "level": "foundation", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "message mismatch"}, {"id": "JEB-E08", "seq": 97, "module": "Foundations", "source": "Public post", "title": "When routing is unknown, the business must choose", "explain": "When the system cannot determine payment routing automatically, rejecting the payment is the easiest answer but not necessarily the best one, since a competitor may find an alternative route, repair and enrich the payment, and send it through. The real choice sits between rejection, repair with alternative routing, and manual intervention, and each option carries different consequences for customer experience, revenue, operational effort, SLA, risk, and payment success rate. The BA should identify the decision point, frame the options with their impact, and take the decision to the Payment Product Manager or Business Owner, because the most valuable question is what the business wants the system to do when this situation occurs.", "takeaway": "The BA should identify the decision point, frame the options with their impact, and take the decision to the Payment Product Manager or Business Owner, because the most valuable question is what the business wants the system to do when this situation occurs.", "visual": {"type": "diagram", "diagram": {"centre": "Routing unknown: reject or repair?", "parts": [{"label": "Reject", "note": "The easiest answer, but the weakest customer experience."}, {"label": "Repair and reroute", "note": "Find an alternative route, enrich the payment, and send it through."}, {"label": "Manual intervention", "note": "A person decides when automation cannot determine the route."}, {"label": "Impact of each option", "note": "Customer experience, revenue, effort, SLA, risk, and success rate."}]}}, "level": "foundation", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "JEB-E09", "seq": 98, "module": "Foundations", "source": "Public post", "title": "A missing field can fail the payment, not just the data", "explain": "A BA fails not by missing every answer but by simplifying too quickly, as when a Eurozone customer payment arrives with the reference, account number, and customer name filled but the debtor postal address missing its street name. Checking only mandatory fields misses the point, because the debit instruction and the screening of the payment can depend on data that is not mandatory but is relevant in cross-border payments, and a missing street name can look harmless while the payment itself is not meaningful. The BA must ask what happens if the data is missing, whether it causes a rejection downstream, blocks processing, or violates a regulatory or scheme requirement, because some missing fields are business rules that will fail the payment in processing.", "takeaway": "The BA must ask what happens if the data is missing, whether it causes a rejection downstream, blocks processing, or violates a regulatory or scheme requirement, because some missing fields are business rules that will fail the payment in processing.", "visual": {"type": "diagram", "diagram": {"centre": "Mandatory is not the same as meaningful", "parts": [{"label": "Only mandatory checked", "note": "A BA who checks mandatory fields only assumes the rest is irrelevant."}, {"label": "Screening needs more", "note": "Debit instruction and screening can depend on non-mandatory data."}, {"label": "Business impact missed", "note": "Some missing data is business-critical, not a data quality issue."}, {"label": "Ask what happens", "note": "Does the gap reject, block, or breach a rule downstream."}]}}, "level": "foundation", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "ABH-10", "seq": 117, "module": "Core", "source": "Public post", "title": "One click to Pay: 15 steps, 9 decisions", "explain": "A corporate payment passes fifteen steps and nine decisions from maker to ledger. The preprocessor checks entitlement, account, limits, fees and payee, then workflow approves it, the bank screens and debits it, the network clears it and the ledger closes it. Every Yes moves the payment forward, and every No stops or re-routes it.", "takeaway": "Every Yes moves the payment forward, and every No stops or re-routes it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Maker initiates the payment", "note": "Fifteen steps and nine decisions to the ledger"}, {"kind": "decision", "title": "Preprocessor checks clear?", "note": "Entitlement, account, limits, fees and payee"}, {"kind": "step", "title": "Workflow approves the payment", "note": "Approval moves it to the bank"}, {"kind": "decision", "title": "Bank screening clear?", "note": "A No stops or re-routes the payment"}, {"kind": "step", "title": "Bank debits the account", "note": "Funds leave the payer account"}, {"kind": "step", "title": "Network clears the payment", "note": "Clearing moves it to the beneficiary bank"}, {"kind": "step", "title": "Ledger closes the payment", "note": "Posting completes the journey"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-12", "seq": 119, "module": "Core", "source": "Public post", "title": "Vietnam: the preprocessor is the control point", "explain": "In a domestic payment in Vietnam, the payment preprocessor is the central control point. The flow runs from the corporate, through the preprocessor, to the payment hub, then NAPAS, then the beneficiary bank. Nothing reaches the rail until the preprocessor has cleared it.", "takeaway": "Nothing reaches the rail until the preprocessor has cleared it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate initiates payment", "note": "The payment starts with the corporate"}, {"kind": "step", "title": "Preprocessor control point", "note": "Nothing reaches the rail until it clears here"}, {"kind": "step", "title": "Payment hub", "note": "Central processing after the preprocessor"}, {"kind": "step", "title": "NAPAS", "note": "The domestic rail in Vietnam"}, {"kind": "step", "title": "Beneficiary bank", "note": "Final bank that credits the beneficiary"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-14", "seq": 121, "module": "Core", "source": "Public post", "title": "Vietnam preprocessor: seven checks first", "explain": "Before a domestic payment moves on, the preprocessor runs the full gate: account, format, authorisation, limits, AML and sanctions, duplicates, routing and enrichment. Those checks are the reason a payment can be trusted to reach the right account.", "takeaway": "Those checks are the reason a payment can be trusted to reach the right account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Account validation", "note": "Account exists and is valid"}, {"kind": "step", "title": "Format check", "note": "Message format is correct"}, {"kind": "step", "title": "Authorisation check", "note": "Payment is properly authorised"}, {"kind": "decision", "title": "Limits, AML and sanctions clear?", "note": "Limits, AML and sanctions all checked"}, {"kind": "step", "title": "Duplicate check", "note": "Payment is not a repeat"}, {"kind": "step", "title": "Routing", "note": "Payment routed to the right path"}, {"kind": "step", "title": "Enrichment", "note": "Payment enriched before it moves on"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "ABH-15", "seq": 122, "module": "Core", "source": "Public post", "title": "Preprocessor: control tower, cross-border", "explain": "In cross-border payments the preprocessor is the control tower: it validates, enriches, checks compliance, routes and processes the payment, so fewer payments are rejected and more go straight through. A strong preprocessor is what makes straight-through processing possible.", "takeaway": "A strong preprocessor is what makes straight-through processing possible.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Validate the payment", "note": "Checks before the payment moves on"}, {"kind": "step", "title": "Enrich the payment", "note": "Data added for straight-through processing"}, {"kind": "decision", "title": "Compliance checks clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Route the payment", "note": "Sent down the right rail"}, {"kind": "step", "title": "Process the payment", "note": "Fewer rejections, more straight-through"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "payment rejected or returned", "resolution": "reject"}, {"id": "ABH-16", "seq": 123, "module": "Core", "source": "Public post", "title": "Preprocessor validation, layer by layer", "explain": "Preprocessor validation works in layers: technical, payment data, business, compliance and routing. Each layer catches a different kind of error, and the full lifecycle runs from initiation through to settlement and reconciliation.", "takeaway": "Each layer catches a different kind of error, and the full lifecycle runs from initiation through to settlement and reconciliation.", "visual": {"type": "diagram", "diagram": {"centre": "Preprocessor validation, layer by layer", "parts": [{"label": "Technical", "note": "Catches technical errors"}, {"label": "Payment data", "note": "Catches payment data errors"}, {"label": "Business", "note": "Catches business errors"}, {"label": "Compliance", "note": "Catches compliance errors"}, {"label": "Routing", "note": "Catches routing errors"}, {"label": "Full lifecycle", "note": "Initiation through settlement and reconciliation"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "ABH-17", "seq": 124, "module": "Core", "source": "Public post", "title": "Finastra GPP: the technical payment flow", "explain": "From a Tech BA view, a payment flows from the channel through the API gateway and message queue into GPP, where it is parsed, validated, checked for duplicates, mapped to ISO 20022, screened for compliance, routed to a SWIFT or domestic rail, acknowledged, and finally posted to core banking with reconciliation. Exceptions are handled at each stage.", "takeaway": "Exceptions are handled at each stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Channel", "note": "Where the payment starts"}, {"kind": "step", "title": "API gateway and message queue", "note": "Entry and queuing into the bank"}, {"kind": "step", "title": "GPP parse and validate", "note": "Parsed, validated and duplicate-checked"}, {"kind": "step", "title": "Map to ISO 20022", "note": "Payment mapped to the rich data standard"}, {"kind": "decision", "title": "Compliance screening clear?", "note": "Screened before routing"}, {"kind": "step", "title": "Route to SWIFT or domestic rail", "note": "Routed to the right rail"}, {"kind": "step", "title": "Acknowledge, post and reconcile", "note": "Acknowledged, posted to core banking, reconciled"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "ABH-24", "seq": 131, "module": "Core", "source": "Public post", "title": "What makes a reliable payment API", "explain": "A reliable payment API rests on stateless validation, synchronous fraud and risk checks, idempotency, metadata-driven configuration, orchestration, compliance and reconciliation. Idempotency matters because a retried call must never create a duplicate payment.", "takeaway": "Idempotency matters because a retried call must never create a duplicate payment.", "visual": {"type": "diagram", "diagram": {"centre": "A reliable payment API", "parts": [{"label": "Stateless validation", "note": "Validation without stored session state"}, {"label": "Synchronous fraud and risk checks", "note": "Fraud and risk checked in line"}, {"label": "Idempotency", "note": "A retried call never creates a duplicate payment"}, {"label": "Metadata-driven configuration", "note": "Behaviour driven by metadata"}, {"label": "Orchestration", "note": "Steps coordinated across the flow"}, {"label": "Compliance", "note": "Rules enforced in the API flow"}, {"label": "Reconciliation", "note": "Proves payments completed correctly"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D10 APIs and integration", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "INS-138", "seq": 144, "module": "Core", "source": "Public post", "title": "FX transparency: show the full deal upfront", "explain": "When a customer pays in a different currency, they need to see the exchange rate, the fees, how long the rate is valid, and the exact amount the beneficiary will receive. If the rate changes or the fees are not shown clearly, the beneficiary is credited a different amount and the customer cannot reconcile the payment. Transparency means showing the total cost and the applied rate before the customer confirms, because a price agreed after the fact is no agreement at all.", "takeaway": "Transparency means showing the total cost and the applied rate before the customer confirms, because a price agreed after the fact is no agreement at all.", "visual": {"type": "diagram", "diagram": {"centre": "FX transparency for customer", "parts": [{"label": "Exchange rate", "note": "Customer needs to see the exchange rate"}, {"label": "Fees", "note": "Customer needs to see the fees"}, {"label": "Rate validity", "note": "Customer needs to see how long the rate is valid"}, {"label": "Beneficiary amount", "note": "Customer needs the exact amount the beneficiary will receive"}, {"label": "Rate change risk", "note": "If the rate changes, the beneficiary is credited a different amount"}, {"label": "Unclear fees risk", "note": "If fees are not shown clearly, the beneficiary is credited a different amount"}, {"label": "Show before confirming", "note": "Show the total cost and the applied rate before the customer confirms"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "INS-140", "seq": 145, "module": "Core", "source": "Public post", "title": "Structured data makes a payment reconcilable", "explain": "Every cross-border payment carries payer, beneficiary, purpose and remittance data that the supplier needs to allocate the cash and that compliance screening depends on. If the data is unstructured or incomplete, the supplier cannot match the payment to the invoice and the screening cannot run properly. Structured data is what makes a payment reconcilable and compliant at the same time, so data quality is a payment control, not a formatting preference.", "takeaway": "Structured data is what makes a payment reconcilable and compliant at the same time, so data quality is a payment control, not a formatting preference.", "visual": {"type": "diagram", "diagram": {"centre": "Structured payment data", "parts": [{"label": "Payer data", "note": "Payment carries payer data the supplier needs"}, {"label": "Beneficiary data", "note": "Payment carries beneficiary data"}, {"label": "Purpose data", "note": "Payment carries purpose data"}, {"label": "Remittance data", "note": "Payment carries remittance data the supplier needs to allocate cash"}, {"label": "Compliance screening", "note": "Structured data lets screening run properly"}, {"label": "Unstructured data risk", "note": "Unstructured or incomplete data means supplier cannot match payment to invoice"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "INS-113", "seq": 152, "module": "Core", "source": "Public post", "title": "Reject reasons: precise inside, careful outside", "explain": "When a payment is rejected, the internal diagnostic reason can be precise and sensitive, such as the account being closed or the name not matching. That reason cannot always be shared with the customer, because privacy rules differ by country. The bank must configure what reason is shown, at what scope and through which channel, so the customer gets a useful explanation without exposing sensitive information.", "takeaway": "The bank must configure what reason is shown, at what scope and through which channel, so the customer gets a useful explanation without exposing sensitive information.", "visual": {"type": "diagram", "diagram": {"centre": "Reject reason privacy by country", "parts": [{"label": "Internal diagnostic reason", "note": "Internal reason can be precise and sensitive"}, {"label": "Account closed example", "note": "Example reason is the account being closed"}, {"label": "Name mismatch example", "note": "Example reason is the name not matching"}, {"label": "Privacy rules differ", "note": "Privacy rules differ by country"}, {"label": "Configure what is shown", "note": "Bank must configure what reason is shown"}, {"label": "Configure scope and channel", "note": "Bank must configure scope and channel for the reason"}, {"label": "Useful but safe explanation", "note": "Customer gets a useful explanation without exposing sensitive information"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-117", "seq": 153, "module": "Core", "source": "Public post", "title": "Scheme maximum versus your customer limit", "explain": "The scheme maximum for instant euro payments and the limits a bank sets for its own customers are two different numbers. An older internal guide may still say the scheme maximum is 100,000 euro when the regulation has changed it, so the product configuration and the routing rules must be updated together. A payment above the scheme maximum cannot go as an instant payment at all, whatever the customer limit says, so the scheme figure is the hard gate.", "takeaway": "A payment above the scheme maximum cannot go as an instant payment at all, whatever the customer limit says, so the scheme figure is the hard gate.", "visual": {"type": "diagram", "diagram": {"centre": "Instant payment maximum amount", "parts": [{"label": "Scheme maximum", "note": "Scheme maximum for instant euro payments"}, {"label": "Bank customer limit", "note": "Limits a bank sets for its own customers are a different number"}, {"label": "Older guide says 100,000 euro", "note": "Older internal guide may still say the scheme maximum is 100,000 euro"}, {"label": "Regulation changed it", "note": "Regulation has changed the scheme maximum"}, {"label": "Update configuration", "note": "Product configuration must be updated"}, {"label": "Update routing rules", "note": "Routing rules must be updated together with configuration"}, {"label": "Above maximum cannot go instant", "note": "Payment above the scheme maximum cannot go as an instant payment"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "resolution": "escalate"}, {"id": "JEB-A06", "seq": 160, "module": "Core", "source": "Public post", "title": "SSI overrides the customer instruction on routing", "explain": "Routing precedence puts the Standing Settlement Instruction ahead of a conflicting customer instruction, because an SSI is a settlement instruction agreed in advance between banks, naming the preferred correspondent for a currency and counterparty. Here the customer named Citi New York as intermediary, yet the engine applied the SSI and routed through Chase New York, and a SwiftRef update did not displace that rule. A different intermediary therefore requires the SSI to be updated first or an explicit override in the payment message, since routing follows the governing rules as much as the message itself.", "takeaway": "A different intermediary therefore requires the SSI to be updated first or an explicit override in the payment message, since routing follows the governing rules as much as the message itself.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The instruction names Citi New York as intermediary", "title": "Customer names Citi New York"}, {"kind": "step", "note": "An SSI names the preferred correspondent in advance", "title": "Engine applies the SSI"}, {"kind": "step", "note": "The engine chose Chase New York, and SwiftRef did not change that", "title": "Chase New York is routed"}, {"kind": "decision", "note": "Change requires an SSI update first or an explicit override", "title": "Different intermediary wanted?"}, {"kind": "step", "note": "Routing follows the governing rules, not only the message", "title": "Update SSI or override in message"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": [], "resolution": "repair"}, {"id": "JEB-A09", "seq": 162, "module": "Core", "source": "Public post", "title": "Warehoused payments need revalidation at execution", "explain": "Warehousing turns a future-dated payment into a commitment to execute, not merely a stored instruction: a EUR 5 million payment accepted on Monday for Friday execution, against a EUR 6 million balance, may still fail by Friday. Balance, account details, sanctions status and cut-off times can all move between submission and execution, so validity on Monday proves nothing about Friday. The payment must therefore be re-validated on balance, account status, sanctions and cut-offs at execution, then executed or rejected, because warehousing is risk management across the interval, not a guarantee.", "takeaway": "The payment must therefore be re-validated on balance, account status, sanctions and cut-offs at execution, then executed or rejected, because warehousing is risk management across the interval, not a guarantee.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Future-dated payment accepted and stored for Friday execution", "title": "EUR 5 million accepted Monday"}, {"kind": "step", "note": "Warehousing commits to execute, it is not just storage", "title": "Warehousing is a commitment"}, {"kind": "step", "note": "Balance, account details, sanctions status and cut-off times can all change", "title": "Conditions move before Friday"}, {"kind": "step", "note": "Check balance, account status, sanctions and cut-offs again at execution", "title": "Re-validate at execution"}, {"kind": "decision", "note": "A payment valid on Monday is not necessarily valid on Friday", "title": "Still valid on Friday?"}, {"kind": "step", "note": "Execute the payment, or reject it if re-validation fails", "title": "Execute or reject"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "reject"}, {"id": "JEB-B02", "seq": 164, "module": "Core", "source": "Public post", "title": "Payment controls: sequential, parallel, or mixed", "explain": "Control design is a business decision about ordering, not a technical default: when thousands of payments arrive together, running every control in sequence is not always the smartest design. If the account is closed and rejection is the defined outcome, the payment can go to rejection once the account check is done, unless the business requires flagging for other checks too, while compliance and fraud can run in parallel, so checks of 3 and 4 seconds finish in 4 seconds together instead of 7 in sequence, which can decide whether the SLA is met. The BA must also spell out the intended outcome for a control that fails, times out, or comes back inconclusive, because otherwise the decision is left to technical defaults.", "takeaway": "The BA must also spell out the intended outcome for a control that fails, times out, or comes back inconclusive, because otherwise the decision is left to technical defaults.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Running every control one after another is not always the smartest design", "title": "Thousands of payments arrive"}, {"kind": "decision", "note": "If the account is closed and the outcome is rejection, reject after the account check", "title": "Account closed, outcome clear?"}, {"kind": "step", "note": "Checks of 3 and 4 seconds finish in 4 seconds together instead of 7", "title": "Run compliance and fraud in parallel"}, {"kind": "step", "note": "Parallel checks can decide whether the SLA is met", "title": "Protect the SLA"}, {"kind": "step", "note": "Define what happens when a control fails, times out or returns inconclusive", "title": "Define failure outcomes"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "return"}, {"id": "JEB-B08", "seq": 168, "module": "Core", "source": "Public post", "title": "Treasury waits on Nostro credit: choose by the decision", "explain": "A Treasury desk awaiting a Nostro credit ahead of releasing an outgoing payment needs one answer before the cut-off: has the expected credit arrived. The camt.053 statement holds the account movements and the balance at close of business, so it cannot answer a question that must be decided during the day. The camt.052 intraday report and the camt.054 debit or credit notification are the candidates for an intraday answer, and the poll split evenly between them. The real lesson is to choose the message by the business decision it must support, not by its definition alone.", "takeaway": "The real lesson is to choose the message by the business decision it must support, not by its definition alone.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Treasury needs the credit before releasing an outgoing payment", "title": "Treasury waits for Nostro credit"}, {"kind": "decision", "note": "The question must be answered before the cut-off", "title": "Has the expected credit arrived?"}, {"kind": "step", "note": "The statement shows the balance at close of business, too late for the day", "title": "camt.053 cannot answer it"}, {"kind": "step", "note": "The intraday report and the debit or credit notification can answer during the day", "title": "camt.052 and camt.054 are candidates"}, {"kind": "step", "note": "Choose the message by the business decision it must support, not by its definition alone", "title": "Choose by the decision"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D04 Messaging and standards", "messages": ["camt.053", "camt.052", "camt.054"]}, {"id": "JEB-B09", "seq": 169, "module": "Core", "source": "Public post", "title": "Routing rules decide the engine, not the message", "explain": "Even a flawless pain.001 can turn into a production incident when routing rules send it to the wrong payment engine. Routing rules are set by the payment business and applied by the acquisition layer; the pain.001 provides the clues, such as instrument, currency and amount, but the engine never invents or overrides the route. If the rules are incomplete or incorrectly applied, a valid USD payment can land in an instant payment engine handling EUR only, and the payment can be held, delayed or rejected despite a correct customer instruction. The message provides the clues, and the business rules determine the route.", "takeaway": "The message provides the clues, and the business rules determine the route.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Even a flawless pain.001 can turn into a production incident", "title": "Valid pain.001 arrives"}, {"kind": "step", "note": "The payment business defines the routing rules and the acquisition layer applies them", "title": "Routing rules are defined"}, {"kind": "step", "note": "Instrument, currency and amount are the clues, but the engine does not invent the route", "title": "pain.001 provides the clues"}, {"kind": "decision", "note": "If the rules are incomplete or incorrectly applied, the route can be wrong", "title": "Rules complete and correct?"}, {"kind": "step", "note": "A valid USD payment can land in an instant payment engine handling EUR only", "title": "USD payment reaches EUR engine"}, {"kind": "step", "note": "The payment can be held, delayed or rejected despite a correct instruction", "title": "Payment held, delayed or rejected"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pain.001"], "failure_category": "wrong routing", "resolution": "reject"}, {"id": "JEB-B12", "seq": 170, "module": "Core", "source": "Public post", "title": "API success is not a business decision", "explain": "Technical success and business outcome are different things: an API can answer HTTP 200 because the call succeeded technically, while the payment engine still rejects the payment based on the response and the business rules. Checking whether an account is open or closed is not enough if the engine also needs the account currency and the product does not support FX, so the BA must ask what information the engine needs to make its decision. A fraud score works the same way: the fraud system controls its scoring model, while the engine must convert the score into an action, above 90 reject, 50 to 90 process with a customer alert, and below 50 process normally. An API can be technically sound yet yield the wrong business outcome when the business rules are undefined, so start with the business decision the process needs to make, not the API to build.", "takeaway": "An API can be technically sound yet yield the wrong business outcome when the business rules are undefined, so start with the business decision the process needs to make, not the API to build.", "visual": {"type": "diagram", "diagram": {"centre": "API success is not a business decision", "parts": [{"label": "HTTP 200 is only technical", "note": "An API can return HTTP 200 while the engine still rejects the payment"}, {"label": "Account currency matters", "note": "Checking open or closed is not enough if the engine also needs the currency"}, {"label": "Fraud score above 90: reject", "note": "Above 90 reject, the engine translates the score into an action"}, {"label": "Score 50 to 90: alert", "note": "From 50 to 90 process with a customer alert"}, {"label": "Score below 50: process normally", "note": "Below 50 process the payment normally"}, {"label": "Start with the business decision", "note": "Start with the business decision the process needs to make, not the API"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D10 APIs and integration", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "return"}, {"id": "JEB-C03", "seq": 172, "module": "Core", "source": "Public post", "title": "Serial or cover: decide by accounts and currency", "explain": "Serial and cover are infrastructure choices, not customer choices: in the serial method the remitting bank sends one pacs.008 with settlement to the beneficiary bank, which suits cases where correspondent or nostro accounts exist and the settlement currency matches the payer account currency. In the cover method the pacs.008 goes without settlement and a separate pacs.009 cover moves the funds through an intermediary, which suits cases with no direct relationship or a different settlement currency, as in a USD 10,000 payment from a US bank to HDFC Bank in India for an INR account. The bank decides by checking whether nostro accounts exist in the beneficiary bank country and which settlement systems the currency needs, such as Fedwire, TARGET2 or CHAPS, so the extra leg in the cover method is a settlement decision, not a matter of instruction wording.", "takeaway": "The bank decides by checking whether nostro accounts exist in the beneficiary bank country and which settlement systems the currency needs, such as Fedwire, TARGET2 or CHAPS, so the extra leg in the cover method is a settlement decision, not a matter of instruction wording.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "decision", "note": "Check whether nostro accounts exist in the beneficiary bank country", "title": "Do nostro accounts exist?"}, {"kind": "decision", "note": "Check whether the settlement currency matches the payer account currency", "title": "Does the currency match?"}, {"kind": "step", "note": "Suits cases where correspondent accounts exist and the currency matches", "title": "Serial: one pacs.008 with settlement"}, {"kind": "step", "note": "Suits cases with no direct relationship or a different settlement currency", "title": "Cover: pacs.008 plus pacs.009"}, {"kind": "step", "note": "Check which systems the currency needs, such as Fedwire, TARGET2 or CHAPS", "title": "Check the settlement systems"}, {"kind": "step", "note": "The cover method adds an extra leg, so the choice is about settlement", "title": "Choice is about infrastructure"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": ["pacs.008", "pacs.009"]}, {"id": "JEB-C05", "seq": 174, "module": "Core", "source": "Public post", "title": "An optional field can still be mandatory for processing", "explain": "In pain.001, a field marked optional may still be needed by the sender bank, for example the sending business agent address and postcode, to process the payment correctly. If the field is left out, the beneficiary or intermediary bank may fall back to default values, which can cause compliance issues, errors or deductions even when the payment goes through. A field M, O or C status describes the message, while whether the information must be captured is decided by the business rules of the process, so the BA should always ask whether the field is needed for the process, rather than trusting the message status alone.", "takeaway": "A field M, O or C status describes the message, while whether the information must be captured is decided by the business rules of the process, so the BA should always ask whether the field is needed for the process, rather than trusting the message status alone.", "visual": {"type": "diagram", "diagram": {"centre": "Optional can still be mandatory", "parts": [{"label": "Optional field, needed by the bank", "note": "A field marked optional may still be needed by the sender bank"}, {"label": "Agent address and postcode", "note": "For example the sending business agent address and postcode"}, {"label": "Default values cause problems", "note": "Falling back to defaults can cause compliance issues, errors or deductions"}, {"label": "M, O or C describes the message", "note": "A field status describes the message, not the process"}, {"label": "Business rules decide capture", "note": "Whether the information must be captured is decided by business rules"}, {"label": "Ask whether the field is needed", "note": "Always ask whether the field is needed for the process"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": ["pain.001"], "resolution": "repair"}, {"id": "JEB-C06", "seq": 175, "module": "Core", "source": "Public post", "title": "Sequential for validation, parallel for screening", "explain": "Control ordering follows dependency: some payment controls depend on the result of the previous one, so they run one after another and stop the payment as soon as one fails, while others have no dependency and can run at the same time. Validation checks such as account number and currency, name matching, account status and closure belong in the sequential group, while sanction screening, fraud screening, limit checks, risk assessment and regulatory checks can run in parallel. The design question is therefore which controls depend on each other and which do not, because that decides both speed and the stopping point, and for a finance BA the rule of thumb is sequential for validation and parallel for screening.", "takeaway": "The design question is therefore which controls depend on each other and which do not, because that decides both speed and the stopping point, and for a finance BA the rule of thumb is sequential for validation and parallel for screening.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "They run one after another and stop the payment as soon as one fails", "title": "Controls with dependencies run in sequence"}, {"kind": "step", "note": "Account number and currency, name matching, account status and closure", "title": "Validation checks are sequential"}, {"kind": "step", "note": "They can run at the same time because they have no dependency", "title": "Controls without dependencies run in parallel"}, {"kind": "step", "note": "Sanction, fraud, limit, risk and regulatory checks", "title": "Screening checks are parallel"}, {"kind": "step", "note": "Which controls depend on each other decides both speed and the stopping point", "title": "Decide by dependency"}, {"kind": "step", "note": "The rule of thumb is sequential for validation and parallel for screening", "title": "Sequential validation, parallel screening"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "escalate"}, {"id": "INS-003", "seq": 181, "module": "Core", "source": "Public post", "title": "How the issuer decides to approve or decline", "explain": "When a card is presented, the issuer decides whether to approve or decline: it checks card status, available funds or credit, transaction limits and fraud rules, then returns an approval or a decline with a response code. The outcome depends on all these checks together, so a payment can be declined even when the balance is sufficient, if a fraud rule or a limit is breached. Sufficient funds alone never guarantee approval.", "takeaway": "Sufficient funds alone never guarantee approval.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Card presented", "note": "The issuer must decide whether to approve or decline."}, {"kind": "decision", "title": "Check card status", "note": "The issuer checks the card status."}, {"kind": "decision", "title": "Check funds or credit", "note": "The issuer checks available funds or credit."}, {"kind": "decision", "title": "Check limits and fraud rules", "note": "Limits and fraud rules are checked."}, {"kind": "step", "title": "Return approval or decline", "note": "An approval or decline is returned with a response code."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "return"}, {"id": "INS-024", "seq": 192, "module": "Core", "source": "Public post", "title": "AML and CFT controls: what a BA must know", "explain": "Anti-money laundering and counter-terrorist financing controls cover both the customer and the transaction, so map the customer risk controls and the transaction risk controls, the screening outcomes, the case escalation path and the audit trail. An analyst must understand these controls well enough to write requirements that keep the audit trail complete, because a control that cannot be evidenced is treated as if it did not happen. Evidence is the control.", "takeaway": "Evidence is the control.", "visual": {"type": "diagram", "diagram": {"centre": "AML and CFT controls for a BA", "parts": [{"label": "Customer risk controls", "note": "Cover the customer side of the controls."}, {"label": "Transaction risk controls", "note": "Cover the transaction side of the controls."}, {"label": "Screening outcomes", "note": "Recorded as part of the control set."}, {"label": "Case escalation path", "note": "Shows how a case moves when it is raised."}, {"label": "Audit trail", "note": "A control that cannot be evidenced is treated as absent."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "escalate"}, {"id": "PAI-C020", "seq": 242, "module": "Core", "source": "Article and reader comments", "title": "Addressing the MT202 COV to the funding bank", "explain": "In a chain, the MT202 COV is addressed to the bank that holds the account from which the funds will settle, and each bank in the chain addresses its own cover leg to the next bank that will fund it. Addressing the cover to the wrong bank breaks settlement, because the funds land in an account that was not expecting them. The address is therefore part of the settlement design, not an administrative detail.", "takeaway": "The address is therefore part of the settlement design, not an administrative detail.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover addressed to the funding bank", "note": "The MT202 COV goes to the bank holding the settlement account"}, {"kind": "step", "title": "Each bank addresses its own leg onward", "note": "Each bank aims its cover leg at the next funding bank"}, {"kind": "decision", "title": "Wrong address breaks settlement", "note": "Funds landing in an unexpecting account break settlement"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": ["MT202"]}, {"id": "PAI-C035", "seq": 257, "module": "Core", "source": "Article and reader comments", "title": "Screen both legs of a cover payment", "explain": "An MT103 and its MT202 COV are both subject to sanction screening, and the screening must happen before the payment is credited to the beneficiary. Readers ask what the screening process looks like for a cover payment, because the information leg and the funds leg are screened separately and a hit on either leg stops the payment. A bank that screens only the MT103 and not the cover, or the reverse, leaves a gap that a regulator will find.", "takeaway": "A bank that screens only the MT103 and not the cover, or the reverse, leaves a gap that a regulator will find.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 screened before credit", "note": "The information leg is screened before the payment is credited"}, {"kind": "step", "title": "MT202 COV screened separately", "note": "The funds leg is screened separately from the information leg"}, {"kind": "decision", "title": "Hit on either leg stops payment", "note": "A hit on either leg stops the payment"}, {"kind": "step", "title": "Screening gap risks a regulator finding", "note": "Screening one leg only leaves a gap a regulator will find"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": ["MT103", "MT202"], "resolution": "reject"}, {"id": "PAI-C054", "seq": 263, "module": "Core", "source": "Article and reader comments", "title": "MT103 STP: option A only", "explain": "An MT103 STP is a straight-through-processing version of the MT103, and it only allows option A for fields such as 52, 54 and 57. Option A carries the party identifier and the BIC, so the receiving system can identify the bank without human help. Any other option leaves the bank to work out who the party is by hand, which is why those options are not allowed in an STP message.", "takeaway": "Any other option leaves the bank to work out who the party is by hand, which is why those options are not allowed in an STP message.", "visual": {"type": "diagram", "diagram": {"centre": "MT103 STP", "parts": [{"label": "Straight-through-processing version", "note": "An MT103 STP is the straight-through-processing version of the MT103"}, {"label": "Only option A allowed", "note": "Only option A is allowed for fields such as 52, 54 and 57"}, {"label": "Option A carries party identifier and BIC", "note": "Option A carries the party identifier and the BIC"}, {"label": "Receiving system identifies the bank", "note": "The receiving system identifies the bank without human help"}, {"label": "Other options need manual work", "note": "Other options leave the bank to identify the party by hand"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D04 Messaging and standards", "messages": ["MT103"]}, {"id": "PAI-C058", "seq": 267, "module": "Core", "source": "Article and reader comments", "title": "Account relationships decide serial or cover", "explain": "A Canadian bank paying a United States beneficiary held its United States dollars with Wells Fargo, while the beneficiary held its account with Citibank New York. Because the sending bank had no account relationship with Citibank, the correct route was a cover payment: an MT103 sent directly to Citibank and an MT202 COV sent to Wells Fargo. If the sending bank had held an account with the beneficiary's bank, a single serial MT103 would have been enough.", "takeaway": "If the sending bank had held an account with the beneficiary's bank, a single serial MT103 would have been enough.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Canadian bank holds USD with Wells Fargo", "note": "The sending bank held its United States dollars with Wells Fargo"}, {"kind": "step", "title": "Beneficiary holds account with Citibank", "note": "The beneficiary held its account with Citibank New York"}, {"kind": "decision", "title": "Direct account relationship or not", "note": "The sending bank had no account relationship with Citibank"}, {"kind": "step", "title": "Cover payment used: MT103 plus MT202 COV", "note": "An MT103 went directly to Citibank and an MT202 COV went to Wells Fargo"}, {"kind": "step", "title": "Serial MT103 would have sufficed", "note": "With a direct account relationship, a single serial MT103 would have sufficed"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"], "resolution": "repair"}, {"id": "PAI-C061", "seq": 269, "module": "Core", "source": "Article and reader comments", "title": "RMA: authorisation before the MT103 arrives", "explain": "Before one bank can send an MT103 to another over SWIFT, the receiving bank must set up an RMA, a relationship management authorisation, for that sender. Without an RMA the receiving bank's system will not accept the message, which is why a beneficiary bank is asked to establish one before a payment is sent. The RMA is therefore a precondition for the payment, not a formality that can be sorted out afterwards.", "takeaway": "The RMA is therefore a precondition for the payment, not a formality that can be sorted out afterwards.", "visual": {"type": "diagram", "diagram": {"centre": "RMA before an MT103 can arrive", "parts": [{"label": "Receiving bank sets up the RMA", "note": "The receiving bank sets up a relationship management authorisation for the sender"}, {"label": "Without an RMA, the message is refused", "note": "Without an RMA the receiving bank's system will not accept the message"}, {"label": "Beneficiary bank asked to establish it first", "note": "A beneficiary bank is asked to establish one before a payment is sent"}, {"label": "Precondition, not a formality", "note": "The RMA is a precondition, not a formality for afterwards"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D04 Messaging and standards", "messages": ["MT103"]}, {"id": "PAI-C064", "seq": 272, "module": "Core", "source": "Article and reader comments", "title": "Several SSIs: the sender picks the shortest route", "explain": "A bank can publish several standing settlement instructions for one currency, marking one as preferred, but the preferred route is an option, not an order. The sender may use a shorter route, even one that passes through a bank named in a non-preferred instruction, because the aim is for the funds to reach the beneficiary. If the beneficiary is paid faster on the shorter route, no one in the chain will complain.", "takeaway": "If the beneficiary is paid faster on the shorter route, no one in the chain will complain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank publishes several SSIs", "note": "A bank can publish several standing settlement instructions for one currency"}, {"kind": "step", "title": "One route marked as preferred", "note": "One instruction is marked preferred, but it is an option, not an order"}, {"kind": "step", "title": "Sender may use a shorter route", "note": "The sender may use a shorter route through a bank in a non-preferred instruction"}, {"kind": "step", "title": "Beneficiary paid faster", "note": "If the beneficiary is paid faster on the shorter route, no one will complain"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "PAI-C094", "seq": 291, "module": "Core", "source": "Article and reader comments", "title": "Drawing on the parent's account needs authority", "explain": "A subsidiary cannot simply use its parent company's account to pay: an authorisation is required before the subsidiary may draw on the parent's account. In the MT101 the subsidiary appears as the Instructing Party in field 50L, while the parent company appears as the ordering customer in field 50H, because the parent owns the account that will be debited. The same need for authorisation applies whenever the sender of an instruction is not the owner of the account being debited.", "takeaway": "The same need for authorisation applies whenever the sender of an instruction is not the owner of the account being debited.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Subsidiary wants to use parent's account", "note": "A subsidiary cannot simply use its parent company's account to pay"}, {"kind": "step", "title": "Authorisation required first", "note": "Authorisation is required before the subsidiary may draw on the parent's account"}, {"kind": "step", "title": "Subsidiary appears as Instructing Party", "note": "In the MT101 the subsidiary appears as the Instructing Party in field 50L"}, {"kind": "step", "title": "Parent appears as ordering customer", "note": "The parent company appears as the ordering customer in field 50H, as it owns the account"}, {"kind": "step", "title": "Rule applies whenever sender is not owner", "note": "The same need applies whenever the sender is not the owner of the account debited"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D04 Messaging and standards", "messages": ["MT101"]}, {"id": "RUN4-012", "seq": 312, "module": "Core", "source": "Article and reader comments", "title": "FX tenor counts from the trade, if before cut-off", "explain": "An FX tenor such as Today, Tomorrow or Spot counts from the day the deal is traded, provided the trade happens before the FX cut-off time. Traded today before the cut-off, a Today tenor settles today, a Tomorrow tenor settles tomorrow, and Spot settles in two days or more. A trade after the cut-off settles a day later, because once the cut-off passes the bank is already working on the next day.", "takeaway": "A trade after the cut-off settles a day later, because once the cut-off passes the bank is already working on the next day.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Trade placed before cut-off", "note": "Tenors count from the trade day when traded before the cut-off."}, {"kind": "decision", "title": "Traded before the cut-off?", "note": "A trade after the cut-off settles a day later."}, {"kind": "step", "title": "Today tenor settles today", "note": "Traded today before cut-off, a Today tenor settles the same day."}, {"kind": "step", "title": "Tomorrow tenor settles tomorrow", "note": "A Tomorrow tenor settles the next day on a pre cut-off trade."}, {"kind": "step", "title": "Spot settles in two days or more", "note": "A Spot tenor settles in two days or more on a pre cut-off trade."}, {"kind": "step", "title": "After cut-off, a day later", "note": "Past the cut-off the bank works on the next day, so settlement slips."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-106", "seq": 324, "module": "Core", "source": "Public post", "title": "D-1 submission: four readiness checks", "explain": "Bringing direct debit submission forward to D-1 is an operational commitment, not a diary change. Four things must support the earlier date, the scheme calendar, the file cut-off, the bank processing window and operational capacity, or collections fail at the first step. Verify all four before moving the date, because a date the infrastructure cannot meet turns into rejects, complaints and refunds.", "takeaway": "Verify all four before moving the date, because a date the infrastructure cannot meet turns into rejects, complaints and refunds.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Prove the earlier date is a valid scheme day.", "title": "Validate the scheme calendar"}, {"kind": "step", "note": "Prove the file can be built in time.", "title": "Validate the file cut-off"}, {"kind": "step", "note": "Prove the processing window fits.", "title": "Validate the bank processing window"}, {"kind": "step", "note": "Prove staffing and systems can run the earlier date.", "title": "Validate operational capacity"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "cut-off missed"}, {"id": "INS-110", "seq": 326, "module": "Core", "source": "Public post", "title": "Request to Pay: the date cannot be vague", "explain": "Without a requested execution date a SEPA Request to Pay has no payment date, so one must be derived, chosen by the customer, or validated against a rule. Unless derivation, choice and validation are all defined, the same request settles on different dates in different systems. Execution then follows the agreed date, and a date that fails validation is rejected before it ever reaches the scheme.", "takeaway": "Execution then follows the agreed date, and a date that fails validation is rejected before it ever reaches the scheme.", "visual": {"type": "diagram", "diagram": {"centre": "The missing execution date", "parts": [{"label": "Deriving the date", "note": "A defined rule fixes the date."}, {"label": "Customer picks the date", "note": "The customer may select the date."}, {"label": "Checking the date", "note": "The date is tested before use."}, {"label": "Executing downstream", "note": "Execution runs on the agreed date."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": [], "resolution": "reject"}, {"id": "INS-111", "seq": 327, "module": "Core", "source": "Public post", "title": "Control order is a risk decision", "explain": "Running payment controls sequentially or in parallel is a risk decision, not a performance tweak: it changes latency, risk coverage and behaviour under load. Sequential controls are slower but easy to reason about, since each waits for its predecessor, while parallel controls are faster but demand explicit rules for one control failing while another passes. Map control dependencies first, because a control that assumes a predecessor has run will pass bad payments the moment the order changes.", "takeaway": "Map control dependencies first, because a control that assumes a predecessor has run will pass bad payments the moment the order changes.", "visual": {"type": "diagram", "diagram": {"centre": "How controls are orchestrated", "parts": [{"label": "Controls in sequence", "note": "In turn: slower, but easy to reason about."}, {"label": "Controls in parallel", "note": "Together: faster, but failure rules are essential."}, {"label": "Time taken", "note": "Order sets how long the flow takes."}, {"label": "Coverage and order", "note": "No control may run ahead of its dependency."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "SCN-09", "seq": 341, "module": "Core", "source": "Public post", "title": "Uncertain party details: ask, do not kill", "explain": "Ultimate debtor or creditor details that look wrong but are not proven wrong call for a question, not a rejection, because rejecting outright can kill a legitimate payment. Park the payment under a clear status, request the additional information back up the chain, and give the sender a bounded window to answer. Clean facts release it, confirmed problems mean rejection or return depending on settlement state, and a missed deadline falls back to the policy default.", "takeaway": "Clean facts release it, confirmed problems mean rejection or return depending on settlement state, and a missed deadline falls back to the policy default.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Held in a visible queue, never lost.", "title": "Park it with a clear status"}, {"kind": "step", "note": "Ask the sender bank what is missing.", "title": "Ask for the missing information"}, {"kind": "decision", "note": "Clean facts release; confirmed problems reject or return.", "title": "Decide on the facts"}, {"kind": "step", "note": "Pre-settlement rejects, post-settlement returns.", "title": "Fall back to the default on timeout"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "SCN-12", "seq": 343, "module": "Core", "source": "Public post", "title": "Cover: instruction one way, money another", "explain": "The cover method splits the payment in two: the pacs.008 carries customer details to the beneficiary bank, while the pacs.009 with settlement method COVE moves the funds through correspondents, the pair linked by one UETR. A sanctions hold on either leg stops the whole payment, because the beneficiary bank may credit the customer only when both legs reconcile. A cover that arrives alone parks as an unmatched item until its instruction completes the pair.", "takeaway": "A cover that arrives alone parks as an unmatched item until its instruction completes the pair.", "visual": {"type": "diagram", "diagram": {"centre": "Instruction and money travel apart", "parts": [{"label": "pacs.008: the instruction", "note": "Customer and remittance details."}, {"label": "pacs.009 COVE: the funds", "note": "Funds through correspondents."}, {"label": "Chain of correspondents", "note": "Funding moves through Nostro accounts."}, {"label": "Hold on either leg", "note": "A hold on either leg stops the payment."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": ["pacs.008", "pacs.009"], "failure_category": "sanctions or fraud block", "resolution": "investigate"}, {"id": "SCN-18", "seq": 347, "module": "Core", "source": "Public post", "title": "Spot the at-risk payment before the call", "explain": "At-risk has a precise meaning: no status update within the expected window for that corridor and amount, drawn from the tracker, pacs.002 statuses and internal hop timestamps. Every flagged payment needs a named owner, operations, the relationship manager, or investigations, and action before the deadline, reroute, chase the intermediary, or warn the customer early. A dashboard of unowned flags is decoration; a flag works only with an owner and a next action.", "takeaway": "A dashboard of unowned flags is decoration; a flag works only with an owner and a next action.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "No update inside the corridor expected window.", "title": "Define at-risk precisely"}, {"kind": "step", "note": "Tracker, pacs.002 statuses, hop timestamps.", "title": "Pull the signals"}, {"kind": "step", "note": "Operations, the relationship manager, or investigations.", "title": "Route it to an owner"}, {"kind": "step", "note": "Reroute, chase, or warn the customer early.", "title": "Act ahead of the deadline"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002"], "resolution": "investigate"}, {"id": "SCN-23", "seq": 350, "module": "Core", "source": "Public post", "title": "A surname parked a 28M dirham LC", "explain": "Sanctions screening is a false-positive business: about 95 percent of alerts are false positives, yet each one delays real business, and a fuzzy match on a common surname parked a legitimate 28 million dirham letter of credit for 8 working days. The answer is risk triage, exact matches and high-risk corridors first, with matching thresholds tuned per corridor and name frequency instead of one global setting. Judge the screening flow on its KPIs, the false-positive rate and the average hold time, and measure and report both.", "takeaway": "Judge the screening flow on its KPIs, the false-positive rate and the average hold time, and measure and report both.", "visual": {"type": "diagram", "diagram": {"centre": "False positives that delay business", "parts": [{"label": "Fuzzy name match", "note": "Common surname parked a real letter of credit."}, {"label": "Triage by risk", "note": "Exact matches and high-risk corridors go first."}, {"label": "Thresholds per corridor", "note": "Set per corridor and name frequency."}, {"label": "Hold time as KPI", "note": "False-positive rate and hold time, measured."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "investigate"}, {"id": "SCN-24", "seq": 351, "module": "Core", "source": "Public post", "title": "SDN block holds $500K; SAR filed", "explain": "A sanctions list match stops the payment at once: it is held immediately and no funds move while the review is open. The analyst escalates to the compliance officer with the match evidence attached, and true-match verification decides the path, release if false, block if true. Where the activity meets the threshold a Suspicious Activity Report is filed, and every step is documented, because the decision trail is what regulators will ask for.", "takeaway": "Where the activity meets the threshold a Suspicious Activity Report is filed, and every step is documented, because the decision trail is what regulators will ask for.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Beneficiary name fuzzy-matches the SDN list.", "title": "Screening flags a match"}, {"kind": "step", "note": "Funds frozen while the review is open.", "title": "Hold the payment"}, {"kind": "step", "note": "Send the match evidence up.", "title": "Send it to compliance"}, {"kind": "step", "note": "False releases, true blocks.", "title": "Verify the true match"}, {"kind": "step", "note": "File where the activity meets the threshold.", "title": "File the SAR if needed"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "escalate"}, {"id": "SCN-25", "seq": 352, "module": "Core", "source": "Public post", "title": "APP fraud: $85K lost, ruled authorised", "explain": "Authorised push payment fraud exploits the gap between a valid payment and a deceived customer. A scammer posing as a bank representative won remote access to the victim computer, and the wire left from the victim's own login and device, so the bank classified it as authorised and refused reimbursement. The defences are confirmation of payee, friction on first-time payees, warnings at the point of payment, and behavioural detection, and the regulatory trend is shifting liability back toward banks.", "takeaway": "The defences are confirmation of payee, friction on first-time payees, warnings at the point of payment, and behavioural detection, and the regulatory trend is shifting liability back toward banks.", "visual": {"type": "diagram", "diagram": {"centre": "Valid payment, deceived customer", "parts": [{"label": "The deception", "note": "Fake bank representative wins remote access."}, {"label": "Technically valid", "note": "Sent from the victim's own login and device."}, {"label": "The reimbursement gap", "note": "Deceived customer, rule-following payment."}, {"label": "Controls that prevent it", "note": "Confirmation of payee, friction, warnings and detection."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "sanctions or fraud block"}, {"id": "SCN-31", "seq": 355, "module": "Core", "source": "Public post", "title": "Mule accounts: read the network, not the case", "explain": "A mule network is a pattern, not an account: small inward transfers from unrelated sources, funds moved out within minutes of credit, minimal balance retention, and common device or IP linkage. One account is a case, linked accounts are a network, so freeze suspect accounts on debit first, then run EDD and KYC reviews and escalate to investigations. Recalibrate detection rules so the pattern is caught earlier next time, without punishing genuine customers.", "takeaway": "Recalibrate detection rules so the pattern is caught earlier next time, without punishing genuine customers.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Small credits in, out in minutes, tiny balances, shared devices.", "title": "Spot the red flags"}, {"kind": "step", "note": "Linked accounts make a network, not a case.", "title": "Confirm the network linkage"}, {"kind": "step", "note": "Stop the flow at once.", "title": "Freeze the suspect accounts"}, {"kind": "step", "note": "Review every flagged account.", "title": "Run EDD and KYC checks"}, {"kind": "step", "note": "Catch the pattern sooner next time.", "title": "Recalibrate the rules"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "escalate"}, {"id": "JEB-F11", "seq": 358, "module": "Core", "source": "Public post", "title": "Five ways the SDD timeline can break", "explain": "On a normal due date the due date, settlement date and debit date are the same, but the timeline breaks when calendars do not align. Five scenarios test it for a single due date: the creditor PSP closed, TARGET or the CSM closed, the debtor PSP closed, both PSPs closed, and a new national holiday declared after planning. In each case the BA must ask which parties are open, what activity needs to happen and which calendar applies, rather than assuming which date moves, because a good SDD timeline is designed for the broken assumptions, not only for the happy flow.", "takeaway": "In each case the BA must ask which parties are open, what activity needs to happen and which calendar applies, rather than assuming which date moves, because a good SDD timeline is designed for the broken assumptions, not only for the happy flow.", "visual": {"type": "diagram", "diagram": {"centre": "Due Date 15 October", "parts": [{"label": "Creditor PSP closed", "note": "Creditor closed, debtor and TARGET open"}, {"label": "TARGET or CSM closed", "note": "Both PSPs open, no inter-PSP settlement"}, {"label": "Debtor PSP closed", "note": "Can the debtor account be debited that day"}, {"label": "Both PSPs closed", "note": "Infrastructure open, neither PSP working"}, {"label": "New national holiday", "note": "A holiday declared after the timeline was planned"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-F07", "seq": 360, "module": "Core", "source": "Public post", "title": "SDD retry: D+5 is a window, not a penalty", "explain": "When a direct debit fails for insufficient funds, retries are confined to the D+5 window of inter-PSP business days, and D+5 is a window, not a penalty or a fine. A scheduler that retries in first-in-first-out order can keep failing, because retry logic is also seasonal: salary credits land on specific dates, and salary accounts hold a balance on those dates. The better requirement checks the balance daily and collects when the account can fund the debit, rather than assuming the scheduler is the optimum solution. Who owns a retry failure, the BA, the developer or the product owner, is a stakeholder agreement, not a technical fact.", "takeaway": "Who owns a retry failure, the BA, the developer or the product owner, is a stakeholder agreement, not a technical fact.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The account cannot fund the collection on the due date", "title": "Debit fails for insufficient funds"}, {"kind": "decision", "note": "Retries are allowed only inside D+5 inter-PSP business days", "title": "Within the D+5 retry window?"}, {"kind": "step", "note": "Salary crediting dates change when an account can pay", "title": "Check the balance daily"}, {"kind": "decision", "note": "Collect when the balance funds the debit, not by FIFO order", "title": "Balance sufficient now?"}, {"kind": "step", "note": "A failed collection after D+5 stays failed", "title": "Collect or let the window close"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "insufficient funds"}, {"id": "JEB-D02", "seq": 366, "module": "Core", "source": "Public post", "title": "SDD presentation window runs D-14 to D-1", "explain": "D-14 marks the earliest Inter-PSP Business Day for presenting a collection to the Inter-PSP Space, and it doubles as the pre-notification date, by which the debtor must be told about the collection at least 14 calendar days ahead of the Due Date. Receipt by the debtor PSP through the CSM must fall inside that span, with D-1 as the latest permitted day, and for a 15 October Due Date the window is 1 October to 14 October, while the debtor pre-notification in the example went out on 15 September. Confusing D-14 with a submission deadline misreads the rule, since D-14 opens the window and D-1 closes it.", "takeaway": "Confusing D-14 with a submission deadline misreads the rule, since D-14 opens the window and D-1 closes it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Earliest Inter-PSP Business Day to present the collection to the Inter-PSP Space.", "title": "D-14 opens the window"}, {"kind": "step", "note": "Debtor must be told at least 14 calendar days before the Due Date.", "title": "Notify the debtor first"}, {"kind": "step", "note": "Debtor PSP must receive the collection via the CSM inside the window.", "title": "Present through the CSM"}, {"kind": "decision", "note": "Receipt earlier than D-14 or later than D-1 breaks the rule.", "title": "Inside D-14 to D-1?"}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-D06", "seq": 369, "module": "Core", "source": "Public post", "title": "Compliance must run at instant payment speed", "explain": "A payment reaching the beneficiary in 10 seconds still needs AML, sanctions and fraud controls, because instant means compliance must work at payment speed, not that controls disappear. The difficulty is that screening for AML, sanctions and fraud often runs longer than the instant window allows, yet newer technology is making screens smarter and automated, with same-day handling and, in some cases, real-time checks. Once the check sits inside the journey instead of blocking it, instant payments become instant, intelligent and compliant.", "takeaway": "Once the check sits inside the journey instead of blocking it, instant payments become instant, intelligent and compliant.", "visual": {"type": "diagram", "diagram": {"centre": "Instant, yet fully controlled", "parts": [{"label": "Instant is not uncontrolled", "note": "AML, sanctions and fraud controls still apply to a 10-second payment."}, {"label": "Timing gap", "note": "Compliance checks often run longer than the instant payment window allows."}, {"label": "Smarter checks", "note": "Screens are now intelligent, automated, same-day, and sometimes real-time."}, {"label": "Check inside the journey", "note": "Compliance becomes part of the payment journey, not a roadblock."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "JEB-E15", "seq": 379, "module": "Core", "source": "Public post", "title": "Intermediary Agent 2: optional, until it is not", "explain": "In a pacs.008 cover payment, Intermediary Agent 2 is optional in the message definition, shown as 0..1, so a reader can conclude it can always be left out. But the beneficiary bank may need the intermediary chain to understand the expected cover path, and without it the payment can be held for cover information, sent to investigation, or rejected. Message cardinality answers a design question, so the working test is not whether the field is mandatory but whether the business scenario needs it, who consumes it, and what happens if it is missing.", "takeaway": "Message cardinality answers a design question, so the working test is not whether the field is mandatory but whether the business scenario needs it, who consumes it, and what happens if it is missing.", "visual": {"type": "diagram", "diagram": {"centre": "Optional at message level, necessary in the flow", "parts": [{"label": "pacs.008 cover path", "note": "Bank A to Bank B through two correspondents; Intermediary Agent 2 carries the chain."}, {"label": "Intermediary Agent 2, 0..1", "note": "Optional in the message definition, so it reads as safe to omit."}, {"label": "Bank B without it", "note": "May wait for cover information, investigate, hold or reject the payment."}, {"label": "The working test", "note": "Ask who consumes the field, in which scenario, and what breaks without it."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": ["pacs.008"]}, {"id": "RUN6-012", "seq": 384, "module": "Core", "source": "Article and reader comments", "title": "How short positions are checked before settlement", "explain": "Risk control rests on procedures that keep participants funded on the account used for settlement. The mechanism also reviews short participants at intervals to confirm they can meet their obligations. The final check still falls immediately before settlement, so a bank unable to cover its short position is caught before settlement completes.", "takeaway": "The final check still falls immediately before settlement, so a bank unable to cover its short position is caught before settlement completes.", "visual": {"type": "diagram", "diagram": {"centre": "How the CSM checks short positions", "parts": [{"label": "Procedures for enough funds", "note": "Participants must hold enough money on the settlement account."}, {"label": "Checks from time to time", "note": "The CSM reviews short participants positions at intervals."}, {"label": "Final check before settlement", "note": "The last check happens just before settlement."}, {"label": "Shortfalls caught early", "note": "A bank that cannot cover its position is caught before settlement completes."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "liquidity shortfall"}, {"id": "RUN6-013", "seq": 385, "module": "Core", "source": "Article and reader comments", "title": "Direct participants carry indirect participant risk", "explain": "Accountability for risk arising from indirect participants sits with the direct participant. In practice the indirect participant funds an account held with the direct participant, and before the direct participant sends a debit on its behalf it draws the money from that account, rejecting the transaction when funds are insufficient. For a credit the direct participant credits the indirect participant account and forwards the transaction.", "takeaway": "For a credit the direct participant credits the indirect participant account and forwards the transaction.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "IP opens an account with the DP", "note": "The indirect participant puts money on an account with the direct participant."}, {"kind": "step", "title": "DP checks funds before debit", "note": "Before sending a debit, the DP takes the money from that account."}, {"kind": "step", "title": "Insufficient funds means rejection", "note": "If the account is short, the direct participant rejects the transaction."}, {"kind": "step", "title": "Credits are forwarded", "note": "For credit transactions, the DP credits the IP account and forwards the transaction."}]}}, "level": "core", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "insufficient funds", "resolution": "reject"}, {"id": "INS-169", "seq": 428, "module": "Advanced", "source": "Public post", "title": "Proxy resolution decides who gets the money", "explain": "In a linked payment ecosystem, the beneficiary can be identified by a mobile number, a UPI ID or virtual payment address, or a traditional account number. The system must resolve that identifier to the correct account before the payment is sent, and the resolution rules differ by scheme. Getting the proxy resolution wrong sends the money to the wrong person, so resolution is a payment control, not a lookup convenience.", "takeaway": "Getting the proxy resolution wrong sends the money to the wrong person, so resolution is a payment control, not a lookup convenience.", "visual": {"type": "diagram", "diagram": {"centre": "Beneficiary identifier resolution", "parts": [{"label": "Mobile number", "note": "Beneficiary can be identified by a mobile number"}, {"label": "UPI ID or virtual address", "note": "Beneficiary can be identified by a UPI ID or virtual payment address"}, {"label": "Traditional account number", "note": "Beneficiary can be identified by a traditional account number"}, {"label": "Resolve before sending", "note": "System must resolve the identifier to the correct account before sending"}, {"label": "Resolution rules differ", "note": "Resolution rules differ by scheme"}, {"label": "Wrong resolution risk", "note": "Getting the proxy resolution wrong sends the money to the wrong person"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D05 Domestic payment systems", "messages": [], "resolution": "repair"}, {"id": "INS-149", "seq": 431, "module": "Advanced", "source": "Public post", "title": "Show total cost and rate before confirmation", "explain": "A customer sending money across borders needs to see the total cost, the applied exchange rate, the fee breakdown, and the expected delivery status before confirming. If any of those are hidden or unclear, the customer cannot judge whether the payment is good value or when it will arrive. Transparency is a product requirement, not a nice-to-have, and it has to be designed into the journey, not added as a footnote.", "takeaway": "Transparency is a product requirement, not a nice-to-have, and it has to be designed into the journey, not added as a footnote.", "visual": {"type": "diagram", "diagram": {"centre": "Customer transparency on fees and FX", "parts": [{"label": "Total cost", "note": "Customer needs to see the total cost"}, {"label": "Applied exchange rate", "note": "Customer needs to see the applied exchange rate"}, {"label": "Fee breakdown", "note": "Customer needs to see the fee breakdown"}, {"label": "Expected delivery status", "note": "Customer needs to see the expected delivery status"}, {"label": "Hidden cost risk", "note": "If any of those are hidden or unclear, the customer cannot judge value"}, {"label": "Cannot judge arrival", "note": "If any are hidden, the customer cannot judge when it will arrive"}, {"label": "Product requirement", "note": "Transparency is a product requirement, not a nice-to-have"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D13 Payments product and business", "messages": []}, {"id": "INS-145", "seq": 433, "module": "Advanced", "source": "Public post", "title": "Controls must keep up with a 10-second payment", "explain": "An instant payment that completes in 10 seconds still needs sanctions, anti-money laundering and fraud checks, but those checks can take longer than the rail allows. The controls must be fast and automated, with a clear escalation path and a full audit trail when a payment is held. The design must never imply that controls are bypassed to meet the speed promise, because the speed target and the control standard have to hold at the same time.", "takeaway": "The design must never imply that controls are bypassed to meet the speed promise, because the speed target and the control standard have to hold at the same time.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment completes in 10 seconds", "note": "Instant payment completes in 10 seconds"}, {"kind": "step", "title": "Sanctions, AML and fraud checks", "note": "Sanctions, anti-money laundering, and fraud checks are still needed"}, {"kind": "step", "title": "Checks slower than the rail", "note": "Checks can take longer than the rail allows"}, {"kind": "step", "title": "Fast automated controls", "note": "Controls must be fast and automated"}, {"kind": "step", "title": "Escalation and audit trail", "note": "Clear escalation path and a full audit trail when a payment is held"}, {"kind": "step", "title": "Never bypass controls", "note": "Design must never imply controls are bypassed to meet the speed promise"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": [], "resolution": "escalate"}, {"id": "INS-146", "seq": 434, "module": "Advanced", "source": "Public post", "title": "Fraud controls for payments that settle in seconds", "explain": "Instant payments settle in seconds, which is what customers want and what fraudsters want too. A fraudster who gains access to an account can move money out before the customer notices, and an authorised push payment scam can persuade the customer to send the money themselves. The controls must use risk signals, velocity checks, confirmation of payee, intervention points, and post-transaction monitoring together, because no single control can cover a journey that completes in seconds.", "takeaway": "The controls must use risk signals, velocity checks, confirmation of payee, intervention points, and post-transaction monitoring together, because no single control can cover a journey that completes in seconds.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Instant payments settle in seconds", "note": "Instant payments settle in seconds"}, {"kind": "step", "title": "Fraudster gains access", "note": "Fraudster who gains access can move money out before customer notices"}, {"kind": "step", "title": "Authorised push payment scam", "note": "Scam can persuade the customer to send the money themselves"}, {"kind": "step", "title": "Risk signals", "note": "Controls must use risk signals"}, {"kind": "step", "title": "Velocity checks, payee check", "note": "Controls must use velocity checks and confirmation of payee"}, {"kind": "step", "title": "Intervention and monitoring", "note": "Controls must use intervention points and post-transaction monitoring"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "JEB-A07", "seq": 438, "module": "Advanced", "source": "Public post", "title": "T2 or CBPR+: BAH BizSvc sets the route, not pacs.008", "explain": "The same pacs.008 for EUR 5 million resolves to a different route according to its destination, and the BAH BizSvc code, not the message, declares that route. A T2 payment travels through ESMIG to the ECB for central bank money settlement, identified by a BizSvc such as trgt.002.001.01, while a CBPR+ payment travels cross-border through SWIFT FINplus, identified by a BizSvc such as swift.cbprplus.02. Because the route sets settlement, timing, cost and risk, a payment routed wrongly can face delay, rejection or incorrect settlement, so the pacs.008 is the instruction and the BAH plus BizSvc is the route.", "takeaway": "Because the route sets settlement, timing, cost and risk, a payment routed wrongly can face delay, rejection or incorrect settlement, so the pacs.008 is the instruction and the BAH plus BizSvc is the route.", "visual": {"type": "diagram", "diagram": {"centre": "BAH BizSvc declares the route", "parts": [{"label": "pacs.008 EUR 5 million", "note": "One message, different route according to destination"}, {"label": "T2 via ESMIG to ECB", "note": "Central bank money settlement, BizSvc trgt.002.001.01"}, {"label": "CBPR+ via SWIFT FINplus", "note": "Cross-border route, BizSvc swift.cbprplus.02"}, {"label": "Settlement, timing, cost, risk", "note": "The route sets settlement, timing, cost and risk"}, {"label": "Wrong route consequences", "note": "Wrong routing can delay, reject or mis-settle a payment"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008"], "failure_category": "wrong routing", "resolution": "reject"}, {"id": "PAI-C045", "seq": 482, "module": "Advanced", "source": "Article and reader comments", "title": "Direct relationship: is an intermediary needed?", "explain": "When the ordering bank and the beneficiary bank already hold accounts with each other, the question is whether an intermediary bank should still be used for an international payment. A direct relationship can carry the payment without an intermediary, which is faster and cheaper, but an intermediary may still be used for a currency, a corridor, or a compliance reason. The choice is a design decision, not a rule, and it depends on the corridor and the banks involved.", "takeaway": "The choice is a design decision, not a rule, and it depends on the corridor and the banks involved.", "visual": {"type": "diagram", "diagram": {"centre": "Direct account relationship", "parts": [{"label": "Direct route is faster and cheaper", "note": "A direct relationship carries the payment without an intermediary"}, {"label": "Intermediary may still be used", "note": "An intermediary may still serve a currency, corridor or compliance need"}, {"label": "Choice is a design decision", "note": "The choice depends on the corridor and the banks involved"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "INS-107", "seq": 502, "module": "Advanced", "source": "Public post", "title": "Routing must survive a limit cut", "explain": "Good routing rules are written for the bad day, not the quiet one: a correspondent can cut an intraday credit limit without warning, and an engine that keeps feeding the same corridor will queue payments and generate rejects it cannot explain. Build the rules with eligibility checks, fallback routes, a defined decision order, and an audit trail naming the affected payments and the reason. A routing decision nobody can reconstruct is a control failure, not a routing outcome.", "takeaway": "A routing decision nobody can reconstruct is a control failure, not a routing outcome.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Test whether the corridor can take the payment.", "title": "Test corridor eligibility"}, {"kind": "decision", "note": "Re-route or queue, and record the reason.", "title": "Has the limit or capacity changed?"}, {"kind": "step", "note": "Follow the defined decision order.", "title": "Apply the routing rules"}, {"kind": "step", "note": "Take the next eligible corridor when the first is blocked.", "title": "Take the fallback route"}, {"kind": "step", "note": "Show which payments were affected and why.", "title": "Record the decision and audit trail"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "wrong routing", "resolution": "repair"}, {"id": "JEB-F02", "seq": 516, "module": "Advanced", "source": "Public post", "title": "Cut-offs are set backwards from the deadline", "explain": "A cut-off time is a calculated risk decision, not a time on the clock, and it starts from the downstream deadline, subtracting screening time, buffer, processing capacity, file size, treasury funding and expected rejections. In the worked example a 4:00 PM downstream deadline minus a 15-minute buffer minus 20 minutes of screening gives a 3:25 PM customer cut-off, with guaranteed service until 3:00 PM, best effort until 3:25 PM and next-day service after that. A payment BA should ask what time the payment must be out of the file, whether the deadline is hard, and whether tiers are needed in the requirements.", "takeaway": "A payment BA should ask what time the payment must be out of the file, whether the deadline is hard, and whether tiers are needed in the requirements.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "A 4:00 PM correspondent or scheme deadline is the anchor", "title": "Start from the downstream deadline"}, {"kind": "step", "note": "20 minutes screening and a 15-minute buffer give 3:25 PM", "title": "Subtract screening, buffer and processing time"}, {"kind": "decision", "note": "Funding and format variation decide the service tiers", "title": "Is funding available for the full volume?"}, {"kind": "step", "note": "Guaranteed until 3:00 PM, best effort until 3:25 PM, next day after", "title": "Publish tiered service levels"}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "RUN6-027", "seq": 527, "module": "Advanced", "source": "Article and reader comments", "title": "How the debtor bank picks the cheapest rail", "explain": "A debtor bank looks for the cheapest way to reach the beneficiary on time. When the receiver sits in the same country the payment goes through the local clearing and settlement mechanism or the local real time gross settlement system, and when the receiver sits abroad it goes through SWIFT. Routing rules set up in the payment engine apply that choice automatically, including for bulk MT101 and pain.001 files.", "takeaway": "Routing rules set up in the payment engine apply that choice automatically, including for bulk MT101 and pain.001 files.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Find the cheapest way on time", "note": "The debtor bank looks for the cheapest route that still arrives on time."}, {"kind": "step", "title": "Same country: local rail", "note": "The payment goes through the local CSM or the local RTGS."}, {"kind": "step", "title": "Another country: SWIFT", "note": "The payment goes through SWIFT."}, {"kind": "step", "title": "Routing rules decide", "note": "Rules in the payment engine apply the choice automatically, even for bulk files."}]}}, "level": "advanced", "stage": 2, "stage_name": "Processing decisions", "domain": "D07 Clearing, settlement and liquidity", "messages": ["MT101", "pain.001"]}, {"id": "ABH-03", "seq": 3, "module": "Foundations", "source": "Public post", "title": "SEPA reject vs return: the stage decides", "explain": "In SEPA, timing is the whole distinction: a reject happens before settlement and is reported with pacs.002, while a return happens after settlement and uses pacs.004. The first diagnostic question on any failed SEPA payment is therefore the stage at which it failed. Pin the stage first, and the handling path follows.", "takeaway": "Pin the stage first, and the handling path follows.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment fails before settlement", "note": "Reject, reported with pacs.002"}, {"kind": "decision", "title": "At which stage did it fail?", "note": "The stage decides the handling path"}, {"kind": "step", "title": "Reject before settlement", "note": "Reported with pacs.002"}, {"kind": "step", "title": "Return after settlement", "note": "Reported with pacs.004"}]}}, "level": "foundation", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-086", "seq": 43, "module": "Foundations", "source": "Public post", "title": "Seven causes behind payment failures", "explain": "Payment failures classify into a small set of causes: issuer declines, validation failures, limit failures, timeout failures, connectivity failures, risk failures and downstream processing failures. An issuer decline refuses authorisation, a validation failure means the instruction is incomplete or wrong, a limit failure means an amount or frequency limit is exceeded, a timeout means no response arrived in time, a connectivity failure means a link dropped, a risk failure means a fraud or sanctions screen blocked the payment, and a downstream failure happens after acceptance. Classifying correctly decides who must act and what the customer should be told.", "takeaway": "Classifying correctly decides who must act and what the customer should be told.", "visual": {"type": "diagram", "diagram": {"centre": "Classifying payment failures by cause", "parts": [{"label": "Issuer declines", "note": "The issuer refuses authorisation."}, {"label": "Validation failures", "note": "The instruction is incomplete or wrong."}, {"label": "Limit failures", "note": "An amount or frequency limit is exceeded."}, {"label": "Timeout failures", "note": "No response arrives in time."}, {"label": "Connectivity failures", "note": "A link drops during the payment."}, {"label": "Risk failures", "note": "A fraud or sanctions screen blocks the payment."}, {"label": "Downstream processing failures", "note": "The failure happens after the payment was accepted."}]}}, "level": "foundation", "stage": 3, "stage_name": "Operational exceptions", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "timeout", "resolution": "reject"}, {"id": "PAI-C009", "seq": 57, "module": "Foundations", "source": "Article and reader comments", "title": "pacs.004 returns, camt.056 recalls", "explain": "A pacs.004 returns a payment that has already settled, sending the funds back along the chain to the originator. A camt.056 requests a recall, asking the beneficiary bank to return a payment already credited. The two are often confused, yet they do opposite jobs: the pacs.004 moves the money back, while the camt.056 asks for the money back.", "takeaway": "The two are often confused, yet they do opposite jobs: the pacs.004 moves the money back, while the camt.056 asks for the money back.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.004 returns, camt.056 recalls", "parts": [{"label": "pacs.004", "note": "Returns a settled payment, funds travel back along the chain"}, {"label": "camt.056", "note": "Requests a recall of funds already credited"}, {"label": "Opposite jobs", "note": "pacs.004 moves money back, camt.056 asks for it back"}]}}, "level": "foundation", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004", "camt.056"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C010", "seq": 58, "module": "Foundations", "source": "Article and reader comments", "title": "Catching a duplicate pacs.008", "explain": "Every payment inside a pacs.008 file carries its own unique identification, and that identifier is the control that catches a file containing the same transaction twice before it is processed. The check matters because a bulk file such as a pain.001 can carry one instruction more than once, and paying it twice is a real loss. Duplicate detection is therefore a pre-processing discipline, not a post-payment investigation.", "takeaway": "Duplicate detection is therefore a pre-processing discipline, not a post-payment investigation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 carries unique identification", "note": "Each payment in the file carries its own unique identifier"}, {"kind": "decision", "title": "Check the file for a repeated identification", "note": "A file holding the same transaction twice is caught before processing"}, {"kind": "step", "title": "Duplicate blocked before it is processed", "note": "The identifier stops a duplicate becoming a second payment"}]}}, "level": "foundation", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008", "pain.001"], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "RUN3-001", "seq": 67, "module": "Foundations", "source": "Article and reader comments", "title": "SCT: a pacs.002 rejection stops at the CSM", "explain": "In a SEPA credit transfer, the pacs.008 passes through the clearing and settlement mechanism on its way to the beneficiary bank, and the mechanism validates it against its own rules. A failure at that stage comes back as a pacs.002, so the payment never reaches the beneficiary bank and that bank stays unaware of it. A fault spotted later, at the beneficiary bank itself, travels back as a pacs.004 return instead, because receipt has already happened by then.", "takeaway": "A fault spotted later, at the beneficiary bank itself, travels back as a pacs.004 return instead, because receipt has already happened by then.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends pacs.008", "note": "The instruction enters the clearing and settlement mechanism for validation."}, {"kind": "decision", "title": "Mechanism validation passed?", "note": "A failed validation is rejected here by the mechanism itself."}, {"kind": "step", "title": "pacs.002 sent back to the originator", "note": "Rejection at this stage means the beneficiary bank never sees the payment."}, {"kind": "step", "title": "Beneficiary bank receives and checks it", "note": "A fault found here sits with the beneficiary bank, not the mechanism."}, {"kind": "step", "title": "pacs.004 return travels back", "note": "The return follows because the beneficiary bank had already received the payment."}]}}, "level": "foundation", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.008", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-129", "seq": 134, "module": "Core", "source": "Public post", "title": "Creditor PSP closed on the due date", "explain": "If the creditor PSP is closed on the due date, the collection cannot be submitted into the scheme on that date, even if the debtor PSP is open. The creditor-side processing constraint moves the collection to the next business day. The creditor must plan for its own closure days, not just the debtor's, because its own calendar is a hard gate on submission.", "takeaway": "The creditor must plan for its own closure days, not just the debtor's, because its own calendar is a hard gate on submission.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor PSP closed on due date", "parts": [{"label": "Creditor PSP closed", "note": "Creditor PSP is closed on the due date"}, {"label": "Cannot submit", "note": "Collection cannot be submitted into the scheme on that date"}, {"label": "Debtor PSP open", "note": "Debtor PSP may be open, but that does not help"}, {"label": "Moves to next business day", "note": "Collection moves to the next business day"}, {"label": "Plan for own closure", "note": "Creditor must plan for its own closure days, not just the debtor's"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D13 Payments product and business", "messages": [], "failure_category": "cut-off missed"}, {"id": "INS-130", "seq": 135, "module": "Core", "source": "Public post", "title": "Debtor PSP closed on the due date", "explain": "If the debtor PSP is closed on the due date, the debtor account cannot be debited on that date, so the debit moves to the next business day the debtor PSP is open. The collection is not lost, but the timing shifts, and the creditor must know which date the debit will actually happen. This is why the debtor PSP calendar matters as much as the creditor's: it fixes the real debit date.", "takeaway": "This is why the debtor PSP calendar matters as much as the creditor's: it fixes the real debit date.", "visual": {"type": "diagram", "diagram": {"centre": "Debtor PSP closed on due date", "parts": [{"label": "Debtor PSP closed", "note": "Debtor PSP is closed on the due date"}, {"label": "Cannot debit", "note": "Debtor account cannot be debited on that date"}, {"label": "Moves to next business day", "note": "Debit moves to the next business day the debtor PSP is open"}, {"label": "Collection is not lost", "note": "Collection is not lost, but the timing shifts"}, {"label": "Creditor must know actual date", "note": "Creditor must know which date the debit will actually happen"}, {"label": "Debtor calendar matters", "note": "Debtor PSP calendar matters as much as the creditor's"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D13 Payments product and business", "messages": [], "failure_category": "cut-off missed"}, {"id": "INS-131", "seq": 136, "module": "Core", "source": "Public post", "title": "Clearing mechanism closed on the due date", "explain": "The clearing and settlement mechanism is the infrastructure that moves collections between the creditor PSP and the debtor PSP. If it is closed on the due date, the collections cannot be submitted and settled that day, even when both banks are open and working. Both banks being open is not enough: the infrastructure between them must also be open, so the mechanism's calendar belongs in every collection plan.", "takeaway": "Both banks being open is not enough: the infrastructure between them must also be open, so the mechanism's calendar belongs in every collection plan.", "visual": {"type": "diagram", "diagram": {"centre": "Clearing mechanism closed", "parts": [{"label": "Clearing mechanism", "note": "Infrastructure that moves collections between creditor PSP and debtor PSP"}, {"label": "Closed on due date", "note": "Clearing and settlement mechanism is closed on the due date"}, {"label": "Cannot submit and settle", "note": "Collections cannot be submitted and settled that day"}, {"label": "Both banks open", "note": "Both banks can be open and working"}, {"label": "Infrastructure must be open", "note": "Infrastructure between them must also be open"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "cut-off missed"}, {"id": "INS-132", "seq": 137, "module": "Core", "source": "Public post", "title": "Authorised SDD Core refund: eight weeks", "explain": "When a debtor authorised a SEPA Direct Debit collection, they can ask for a refund within eight weeks of the debit date. The eight-week rule is the stated scheme position, but the exact application can vary by jurisdiction, so it must be checked against the current EPC rulebook. A refund inside this window is a normal scheme right, not an exception.", "takeaway": "A refund inside this window is a normal scheme right, not an exception.", "visual": {"type": "diagram", "diagram": {"centre": "Authorised SDD refund window", "parts": [{"label": "Authorised collection", "note": "Debtor authorised the SEPA Direct Debit collection"}, {"label": "Eight weeks", "note": "Refund can be asked within eight weeks of the debit date"}, {"label": "Scheme position", "note": "Eight-week rule is the stated scheme position"}, {"label": "Varies by jurisdiction", "note": "Exact application can vary by jurisdiction"}, {"label": "Check the rulebook", "note": "Must be checked against the current EPC rulebook"}, {"label": "Normal scheme right", "note": "Refund inside this window is a normal scheme right, not an exception"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-133", "seq": 138, "module": "Core", "source": "Public post", "title": "Unauthorised SDD claim: 13 months", "explain": "When a debtor says a direct debit was never authorised, they can claim a refund for up to 13 months after the debit. The 13-month period is the stated scheme position, and the precise legal and scheme conditions must be checked against the current rulebook. An unauthorised claim is a different process from an authorised refund, with a longer window and different evidence, so the two must never be handled as one case type.", "takeaway": "An unauthorised claim is a different process from an authorised refund, with a longer window and different evidence, so the two must never be handled as one case type.", "visual": {"type": "diagram", "diagram": {"centre": "Unauthorised SDD claim window", "parts": [{"label": "Never authorised", "note": "Debtor says a direct debit was never authorised"}, {"label": "13 months", "note": "Refund can be claimed for up to 13 months after the debit"}, {"label": "Scheme position", "note": "13-month period is the stated scheme position"}, {"label": "Check the rulebook", "note": "Precise legal and scheme conditions must be checked against the rulebook"}, {"label": "Different process", "note": "Unauthorised claim is a different process from an authorised refund"}, {"label": "Longer window, more evidence", "note": "Longer window and different evidence apply"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-134", "seq": 139, "module": "Core", "source": "Public post", "title": "Return, refund and reversal are not the same", "explain": "A return, a refund and a reversal are three different money-back events with different initiators, reasons, messages and accounting treatment: a return is started by the debtor PSP, usually because the account cannot be debited; a refund is started by the debtor asking for money back; and a reversal is started by the creditor PSP to undo a collection. Treating them as the same thing causes wrong messages, wrong timelines and wrong ledger entries, so the three must be modelled as separate events.", "takeaway": "Treating them as the same thing causes wrong messages, wrong timelines and wrong ledger entries, so the three must be modelled as separate events.", "visual": {"type": "diagram", "diagram": {"centre": "Return, refund and reversal", "parts": [{"label": "Return", "note": "Started by the debtor PSP, usually because the account cannot be debited"}, {"label": "Refund", "note": "Started by the debtor asking for money back"}, {"label": "Reversal", "note": "Started by the creditor PSP to undo a collection"}, {"label": "Different initiators", "note": "Three events have different initiators"}, {"label": "Different reasons", "note": "Three events have different reasons"}, {"label": "Different messages and accounting", "note": "Different messages and accounting treatment apply"}, {"label": "Confusing them", "note": "Treating them the same causes wrong messages, timelines, ledger entries"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "return"}, {"id": "INS-109", "seq": 140, "module": "Core", "source": "Public post", "title": "SDD return versus refund on the same day", "explain": "A SEPA Direct Debit return and a refund can arrive on the same day and look similar, but they are different business events. A return happens when the debtor bank sends the collection back, for example because the account has insufficient funds, and it travels as a pacs.004, while a refund happens when the debtor asks for an authorised collection to be repaid. Each has its own trigger, timeline and accounting treatment, so the system must handle them as separate events even when they land together.", "takeaway": "Each has its own trigger, timeline and accounting treatment, so the system must handle them as separate events even when they land together.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collection presented", "note": "Collection is presented for debit"}, {"kind": "decision", "title": "Return or refund?", "note": "Return and refund can arrive the same day and look similar but differ"}, {"kind": "step", "title": "Return travels as pacs.004", "note": "Debtor bank sends the collection back, for example insufficient funds"}, {"kind": "step", "title": "Refund on debtor request", "note": "Debtor asks for an authorised collection to be repaid"}, {"kind": "step", "title": "Handle them separately", "note": "Each has its own trigger, timeline, and accounting treatment"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "insufficient funds", "resolution": "return"}, {"id": "INS-162", "seq": 141, "module": "Core", "source": "Public post", "title": "Reading a pacs.004 return: reason and timing", "explain": "When a direct debit collection is returned, the pacs.004 carries a reason code that explains why, and the scheme sets a timeline for when the return must happen. The creditor needs to learn about the return quickly and understand whether the collection can be presented again. If the returns team cannot interpret the reason codes consistently, creditors find out days late with no clear explanation, so code interpretation is an operational capability, not a back-office nicety.", "takeaway": "If the returns team cannot interpret the reason codes consistently, creditors find out days late with no clear explanation, so code interpretation is an operational capability, not a back-office nicety.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collection is returned", "note": "Direct debit collection is returned"}, {"kind": "step", "title": "Reason code in pacs.004", "note": "pacs.004 carries a reason code that explains why"}, {"kind": "step", "title": "Scheme timeline applies", "note": "Scheme sets a timeline for when the return must happen"}, {"kind": "step", "title": "Creditor learns quickly", "note": "Creditor needs to learn about the return quickly"}, {"kind": "decision", "title": "Can it be presented again?", "note": "Creditor must understand whether the collection can be presented again"}, {"kind": "step", "title": "Interpret codes consistently", "note": "Without consistent interpretation, creditors find out days late"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-112", "seq": 151, "module": "Core", "source": "Public post", "title": "Ninety percent of a remittance file needs repair", "explain": "A large corporate customer sends a daily remittance file with thousands of supplier payments, and around 90 percent of the transactions enter the manual repair queue because key data is missing or inconsistent, such as account numbers that fail the modulus check or incomplete remittance information. The repair queue becomes the bottleneck, and the business must balance transaction-level repair flexibility against operational capacity, customer experience and reconciliation. Fixing the data at the source matters more than adding repair staff, because the queue is a symptom of bad input, not of slow repair.", "takeaway": "Fixing the data at the source matters more than adding repair staff, because the queue is a symptom of bad input, not of slow repair.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Enters manual repair", "note": "Around 90 percent enter the repair queue, key data missing or inconsistent", "value": 90}, {"label": "Passes without repair", "note": "Remaining share passes without entering the manual repair queue", "value": 10}], "unit": "%"}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "repair"}, {"id": "JEB-A03", "seq": 158, "module": "Core", "source": "Public post", "title": "camt.055 only before settlement: check lifecycle first", "explain": "Cancellation and return are governed by lifecycle position, not by urgency: camt.055 can stop a payment only while it remains before settlement, through initiation, validation and processing. Once settlement and credit to the beneficiary have completed, camt.055 is rejected and the bank receives camt.029 carrying RJCR. Recovery then switches to the return route, a camt.056 requesting the funds back or a pacs.004 carrying them back, so the disciplined move is to establish the lifecycle stage before choosing the message.", "takeaway": "Recovery then switches to the return route, a camt.056 requesting the funds back or a pacs.004 carrying them back, so the disciplined move is to establish the lifecycle stage before choosing the message.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Locate the payment before choosing any cancellation or return message", "title": "Establish the lifecycle stage"}, {"kind": "step", "note": "camt.055 can act from initiation through validation, processing and settlement", "title": "Initiation through settlement"}, {"kind": "decision", "note": "After settlement and credit, camt.055 is rejected", "title": "Settled and credited already?"}, {"kind": "step", "note": "The rejection is reported in camt.029 with RJCR status", "title": "camt.029 arrives with RJCR"}, {"kind": "step", "note": "Request return with camt.056, or receive the funds back in pacs.004", "title": "Recover by return route"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.055", "camt.029", "camt.056", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "JEB-A05", "seq": 159, "module": "Core", "source": "Public post", "title": "pacs.009 COV rejected FF01: read the code before recredit", "explain": "A pacs.009 COV rejected with FF01, invalid account number, does not by itself prove the underlying payment failed: the credit advice may simply carry a wrong account mapping while the funds remain held by the bank. The reason code therefore governs the next move, and the bank must investigate it before re-crediting the customer. Crediting too quickly risks paying the customer twice or directing the funds to the wrong account, so the rejection alone must never trigger the refund.", "takeaway": "Crediting too quickly risks paying the customer twice or directing the funds to the wrong account, so the rejection alone must never trigger the refund.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Cover rejected for invalid account number, yet funds do not return", "title": "pacs.009 COV rejected, FF01"}, {"kind": "decision", "note": "A rejected cover does not necessarily mean the payment failed", "title": "Did the payment fail itself?"}, {"kind": "step", "note": "Test whether it is an account mapping issue with funds still held", "title": "Investigate the reason code"}, {"kind": "step", "note": "Fast re-crediting can pay twice or send funds to the wrong account", "title": "Hold the re-credit"}, {"kind": "step", "note": "The reason code, not the rejection alone, decides the next step", "title": "Let the code decide"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.009"], "failure_category": "invalid beneficiary data", "resolution": "investigate"}, {"id": "JEB-A12", "seq": 163, "module": "Core", "source": "Public post", "title": "camt.056 unanswered: design every waiting state an exit", "explain": "An unanswered camt.056 leaves the payment in a waiting state, neither completed nor rejected, simply stuck while the return of funds hangs. The exit is a camt.029 status check, followed by waiting for a response or escalating when the beneficiary does not reply within the agreed time. Each waiting state should therefore be planned in advance with an entry, an exit, a time limit, a status check and an escalation route, and the open design questions are how long to wait before the camt.029 check, how long before escalation, and what follows if no response ever arrives.", "takeaway": "Each waiting state should therefore be planned in advance with an entry, an exit, a time limit, a status check and an escalation route, and the open design questions are how long to wait before the camt.029 check, how long before escalation, and what follows if no response ever arrives.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Bank asks for a return of funds and receives no answer at all", "title": "camt.056 sent, no answer"}, {"kind": "step", "note": "Not completed and not rejected, just stuck in a waiting state", "title": "Payment sits waiting"}, {"kind": "step", "note": "Check the status and wait for a response", "title": "Send camt.029 status check"}, {"kind": "decision", "note": "Escalate if the beneficiary does not reply within the agreed time", "title": "Reply within agreed time?"}, {"kind": "step", "note": "Each waiting state needs an entry, an exit, a time limit and an escalation route", "title": "Agree the way out in advance"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "camt.029"], "failure_category": "timeout", "resolution": "escalate"}, {"id": "INS-005", "seq": 183, "module": "Core", "source": "Public post", "title": "Chargeback lifecycle and reason codes", "explain": "A chargeback starts when a cardholder disputes a transaction and the issuer raises it with the scheme, and the acquirer and merchant respond with representment evidence while the scheme applies its timelines and reason codes. The financial impact moves between issuer, acquirer and merchant as the case progresses, so knowing the reason code matters: it decides what evidence is needed and who bears the loss at each stage. The reason code is the case, not a label on it.", "takeaway": "The reason code is the case, not a label on it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cardholder disputes", "note": "The cardholder disputes a transaction; the issuer raises it."}, {"kind": "step", "title": "Acquirer and merchant respond", "note": "Representment evidence is provided."}, {"kind": "step", "title": "Scheme applies rules", "note": "The scheme applies its timelines and reason codes."}, {"kind": "step", "title": "Financial impact moves", "note": "Impact moves between issuer, acquirer and merchant."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "charge deduction", "resolution": "return"}, {"id": "PAI-C011", "seq": 233, "module": "Core", "source": "Article and reader comments", "title": "A pacs.004 return travels the chain in reverse", "explain": "When a beneficiary bank returns a payment with a pacs.004, the intermediary that received it sends a new pacs.004 back to the originator bank, so the return travels the chain in reverse. The intermediary never keeps the return: it forwards it with the reference to the original payment so the originator bank can match it. In a three-bank chain the rule is uniform: every bank that handled the payment forwards the return to the bank that sent it the payment.", "takeaway": "In a three-bank chain the rule is uniform: every bank that handled the payment forwards the return to the bank that sent it the payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank returns with pacs.004", "note": "The beneficiary bank sends the return as a pacs.004"}, {"kind": "step", "title": "Intermediary receives the pacs.004", "note": "The intermediary takes the return from the beneficiary bank"}, {"kind": "step", "title": "Intermediary sends a new pacs.004 onward", "note": "It forwards the return to the originator bank with the original reference"}, {"kind": "step", "title": "Originator bank matches the return", "note": "The originator bank matches the return to the payment it sent"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C012", "seq": 234, "module": "Core", "source": "Article and reader comments", "title": "How a pacs.004 points back to its payment", "explain": "A pacs.004 carries the original instruction identification and the original end-to-end identification, and those two references tie it to the payment it returns. The originator bank reads them and matches the return to the payment it sent, even after the return has passed through an intermediary. Without those references a return is only a credit with no story, and reconciliation cannot prove which payment it belongs to.", "takeaway": "Without those references a return is only a credit with no story, and reconciliation cannot prove which payment it belongs to.", "visual": {"type": "diagram", "diagram": {"centre": "How a pacs.004 links back", "parts": [{"label": "Original instruction identification", "note": "The pacs.004 carries the original instruction identifier"}, {"label": "Original end-to-end identification", "note": "The pacs.004 carries the original end-to-end identifier"}, {"label": "Originator bank matches the return", "note": "The originator bank reads both references and matches the return"}, {"label": "Without references, no story", "note": "Without them a return is a credit reconciliation cannot place"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "reconciliation break", "resolution": "return"}, {"id": "PAI-C013", "seq": 235, "module": "Core", "source": "Article and reader comments", "title": "A recall must travel the whole chain", "explain": "When an originator recalls a payment that went through an intermediary, the originator bank sends a camt.056 to the intermediary, which forwards it to the beneficiary bank. The beneficiary bank checks whether the recall is feasible, and if it is, it returns the funds with a pacs.004 to the intermediary, which sends a pacs.004 back to the originator bank. A recall is therefore a chain of messages rather than a single message, and the funds come back only when every bank in the chain acts.", "takeaway": "A recall is therefore a chain of messages rather than a single message, and the funds come back only when every bank in the chain acts.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends camt.056", "note": "The recall goes first to the intermediary"}, {"kind": "step", "title": "Intermediary forwards camt.056", "note": "The intermediary passes the recall to the beneficiary bank"}, {"kind": "decision", "title": "Beneficiary bank checks feasibility", "note": "The beneficiary bank checks whether the recall can be done"}, {"kind": "step", "title": "Beneficiary bank returns funds by pacs.004", "note": "If feasible, funds return by pacs.004 to the intermediary"}, {"kind": "step", "title": "Intermediary sends pacs.004 to originator", "note": "The intermediary sends a pacs.004 back to the originator bank"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C014", "seq": 236, "module": "Core", "source": "Article and reader comments", "title": "A pacs.004 can start from either end", "explain": "Both the originator payment service provider and the beneficiary payment service provider can initiate a pacs.004, because a return can be started from either end of the payment. The originator side starts one when it recalls or reverses a payment, and the beneficiary side starts one when it rejects or returns a payment it cannot apply. The message is identical in both cases; only the initiating bank and the reason differ.", "takeaway": "The message is identical in both cases; only the initiating bank and the reason differ.", "visual": {"type": "diagram", "diagram": {"centre": "Who can initiate a pacs.004", "parts": [{"label": "Originator payment service provider", "note": "Starts a return when recalling or reversing a payment"}, {"label": "Beneficiary payment service provider", "note": "Starts a return when rejecting a payment it cannot apply"}, {"label": "Same message, different starter", "note": "One message; only the initiating bank and reason differ"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C015", "seq": 237, "module": "Core", "source": "Article and reader comments", "title": "camt.029 closes the recall question", "explain": "A camt.029 answers a camt.056 recall request by stating whether the recall has been accepted or refused. Readers raise the open question of who sends it, the beneficiary bank or the clearing system, and what it must contain in each case. The answer matters because the originator bank cannot close the recall until that response arrives and confirms whether the funds are coming back.", "takeaway": "The answer matters because the originator bank cannot close the recall until that response arrives and confirms whether the funds are coming back.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Recall request sent as camt.056", "note": "The recall starts with a camt.056 request"}, {"kind": "step", "title": "camt.029 states accepted or refused", "note": "The response states whether the recall was accepted or refused"}, {"kind": "step", "title": "Originator bank closes the recall", "note": "No closure until that response arrives"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.029", "camt.056"], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "PAI-C016", "seq": 238, "module": "Core", "source": "Article and reader comments", "title": "Return reason codes are a closed list", "explain": "When a payment is returned or rejected, the reason code comes from the bank that refused it, and the scheme rulebook lists the codes that bank may use. The open question is whether a payment service provider may add its own codes beyond the rulebook, and a bank that invents one risks the return being rejected by the next bank in the chain. A reason code is therefore a controlled vocabulary, not a free-text field.", "takeaway": "A reason code is therefore a controlled vocabulary, not a free-text field.", "visual": {"type": "diagram", "diagram": {"centre": "The reason for a return or reject", "parts": [{"label": "Reason code comes from the refusing bank", "note": "The bank that refused the payment supplies the code"}, {"label": "Rulebook lists the permitted codes", "note": "Only the codes in the scheme rulebook may be used"}, {"label": "Invented codes risk rejection", "note": "An invented code risks rejection by the next bank"}, {"label": "Controlled vocabulary, not free text", "note": "Reason codes are a closed list, not free text"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C017", "seq": 239, "module": "Core", "source": "Article and reader comments", "title": "What a pacs.002 must carry on a rejection", "explain": "When a pacs.008 is rejected, the pacs.002 reports that rejection, and the open question is which fields it must carry to explain what went wrong. It must identify the original payment and carry the status and the reason code, so the originator bank knows the payment did not settle and why. A pacs.002 without that information leaves the originator guessing, which is why the exact fields required are the question readers ask.", "takeaway": "A pacs.002 without that information leaves the originator guessing, which is why the exact fields required are the question readers ask.", "visual": {"type": "diagram", "diagram": {"centre": "A pacs.002 reporting a rejection", "parts": [{"label": "Identifies the original payment", "note": "The pacs.002 must name the rejected payment"}, {"label": "Carries the status", "note": "It must state the payment did not settle"}, {"label": "Carries the reason code", "note": "It must state why the payment was rejected"}, {"label": "Without it, the originator guesses", "note": "Without these fields the originator cannot tell what failed"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.008"], "failure_category": "payment rejected or returned", "resolution": "reject"}, {"id": "PAI-C021", "seq": 243, "module": "Core", "source": "Article and reader comments", "title": "Returning the funds of a rejected cover payment", "explain": "When a cover payment is rejected, the funds leg and the information leg have different senders, so the question is who returns the funds and by which message. The bank holding the rejected cover must return the funds to the bank that sent them, so the money travels back along the same correspondent path it came on. A return sent to the wrong bank creates a second exception on top of the first.", "takeaway": "A return sent to the wrong bank creates a second exception on top of the first.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover payment is rejected", "note": "The funds leg and the information leg have different senders"}, {"kind": "step", "title": "Bank holding the cover returns the funds", "note": "The bank holding the rejected cover must return the funds"}, {"kind": "step", "title": "Funds travel back along the same path", "note": "The money returns along the correspondent path it came on"}, {"kind": "step", "title": "Return reaches the bank that sent it", "note": "The funds go back to the bank that sent them"}, {"kind": "decision", "title": "Return to the wrong bank is a second error", "note": "A wrong-bank return creates a second exception"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "wrong routing", "resolution": "return"}, {"id": "PAI-C027", "seq": 249, "module": "Core", "source": "Article and reader comments", "title": "An MT103 return travels the chain backwards", "explain": "When an MT103 is returned, the funds come back through the same chain of banks that carried the payment forward, each bank sending the return to the bank that sent it the payment. The charges on the return follow fields 71A and 71F, so the amount that comes back is the amount sent minus the charges already deducted. A return is therefore not a new payment; it is the original payment travelling backwards, and the chain must be able to trace it.", "takeaway": "A return is therefore not a new payment; it is the original payment travelling backwards, and the chain must be able to trace it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 is returned", "note": "The return starts when the MT103 is returned"}, {"kind": "step", "title": "Each bank sends the return backwards", "note": "Each bank sends the return to the bank that sent it the payment"}, {"kind": "step", "title": "Charges follow fields 71A and 71F", "note": "The amount returned is the amount sent minus charges deducted"}, {"kind": "step", "title": "Return is the payment travelling backwards", "note": "A return is the original payment in reverse, and the chain must trace it"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103"], "failure_category": "charge deduction", "resolution": "investigate"}, {"id": "PAI-C028", "seq": 250, "module": "Core", "source": "Article and reader comments", "title": "Invalid beneficiary account: the return route", "explain": "When the beneficiary bank finds the customer account invalid, it returns the payment, and the return must travel back through the intermediary to the originator bank. The beneficiary bank cannot simply keep the funds, and it cannot return them directly to the originator while an intermediary sits in between. An invalid account is one of the most common reasons for a return, and the handling is the same whether the fault is a wrong number, a closed account, or a name that does not match.", "takeaway": "An invalid account is one of the most common reasons for a return, and the handling is the same whether the fault is a wrong number, a closed account, or a name that does not match.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank finds account invalid", "note": "The fault may be a wrong number, a closed account, or a mismatched name"}, {"kind": "step", "title": "Beneficiary bank returns the payment", "note": "The beneficiary bank cannot keep the funds"}, {"kind": "step", "title": "Return travels back through intermediary", "note": "The return must pass back through the intermediary to the originator"}, {"kind": "step", "title": "Originator bank receives the return", "note": "The return reaches the originator bank through the chain"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "message mismatch", "resolution": "return"}, {"id": "PAI-C029", "seq": 251, "module": "Core", "source": "Article and reader comments", "title": "When a clearing house cannot carry a recall", "explain": "Some clearing houses do not support the camt.056 recall message, so the originator bank and the clearing system cannot send a recall to the beneficiary bank for a payment that has already settled. The Estonian clearing house is a real example: it does not support the recall message, so a settled SCT payment cannot be recalled through that route. An analyst must know which clearing systems support a recall before promising a customer that a payment can be taken back.", "takeaway": "An analyst must know which clearing systems support a recall before promising a customer that a payment can be taken back.", "visual": {"type": "diagram", "diagram": {"centre": "A clearing house without camt.056", "parts": [{"label": "Recall cannot be sent through it", "note": "Originator bank and clearing system cannot recall a settled payment"}, {"label": "Estonian clearing house example", "note": "The Estonian clearing house does not support the recall message"}, {"label": "Analyst must check support first", "note": "Check recall support before promising a customer a take-back"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056"], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "PAI-C030", "seq": 252, "module": "Core", "source": "Article and reader comments", "title": "A recall after the beneficiary has spent the funds", "explain": "When a payment has been executed and the beneficiary has already spent the funds, a camt.056 can still be sent to ask the beneficiary bank to return the money, but the beneficiary bank must ask its customer whether it agrees. If the funds are no longer there, the recall cannot be completed by message alone, and the customer must take action against the beneficiary. Once the money has been spent, a recall is a request, not a reversal.", "takeaway": "Once the money has been spent, a recall is a request, not a reversal.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment executed and funds spent", "note": "The beneficiary has already spent the funds"}, {"kind": "step", "title": "camt.056 still sent to ask for return", "note": "A camt.056 can still ask the beneficiary bank to return the money"}, {"kind": "step", "title": "Beneficiary bank asks its customer", "note": "The beneficiary bank must ask its customer whether it agrees"}, {"kind": "decision", "title": "Funds still there or not", "note": "If the funds are gone, the recall cannot complete by message alone"}, {"kind": "step", "title": "Customer must act against beneficiary", "note": "The customer must take action against the beneficiary to recover the money"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C031", "seq": 253, "module": "Core", "source": "Article and reader comments", "title": "Recall in favour of a third-party beneficiary", "explain": "When a recall is made in favour of a third-party beneficiary, for example a bank acting as debtor agent, the question is who receives the recall and who must act on it. The recall is sent to the first agent in the chain, the bank that must return the credit, and that bank then passes the recall onward. The third party never receives the recall directly; it receives the result through the bank that acts for it.", "takeaway": "The third party never receives the recall directly; it receives the result through the bank that acts for it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Recall made for a third-party beneficiary", "note": "For example, a bank acting as debtor agent"}, {"kind": "step", "title": "Recall sent to the first agent", "note": "The recall goes to the first agent, the bank that must return the credit"}, {"kind": "step", "title": "First agent passes the recall onward", "note": "That bank then passes the recall onward"}, {"kind": "step", "title": "Third party receives the result", "note": "The third party receives the result through the bank acting for it"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C032", "seq": 254, "module": "Core", "source": "Article and reader comments", "title": "A rejected recall and a misused GVC code", "explain": "A camt.056 recall request can itself be rejected, and readers ask what that rejection looks like and what the reason code means. One real case is a recall returned with a pacs.004 carrying the reason code GVC, which is not a code that should be used for a return, so the handling was wrong. A reason code must match the message and the situation, and a code used in the wrong place creates a second exception.", "takeaway": "A reason code must match the message and the situation, and a code used in the wrong place creates a second exception.", "visual": {"type": "diagram", "diagram": {"centre": "A rejected camt.056 recall request", "parts": [{"label": "Recall request can itself be rejected", "note": "A camt.056 recall request can itself be rejected"}, {"label": "GVC code on a pacs.004 return", "note": "One real case: a recall returned with a pacs.004 carrying GVC"}, {"label": "GVC should not be used for a return", "note": "GVC is not a code for a return, so the handling was wrong"}, {"label": "Code must match message and situation", "note": "A code in the wrong place creates a second exception"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D14 Business analysis and professional practice", "messages": ["camt.056", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C034", "seq": 256, "module": "Core", "source": "Article and reader comments", "title": "Is pacs.004 mandatory for a return?", "explain": "When a payment must be returned, the question is whether a pacs.004 is mandatory or the return can be made another way. The pacs.004 is the ISO 20022 message designed for returns in the SEPA interbank space, and it carries the link to the original payment that lets every bank in the chain match it. Using another route breaks that link, which is why the pacs.004 is the expected message for a return.", "takeaway": "Using another route breaks that link, which is why the pacs.004 is the expected message for a return.", "visual": {"type": "diagram", "diagram": {"centre": "Is a pacs.004 mandatory for a return", "parts": [{"label": "Designed for returns in SEPA", "note": "The ISO 20022 message designed for returns in the SEPA interbank space"}, {"label": "Carries the link to the original payment", "note": "Its link lets every bank in the chain match the return"}, {"label": "Another route breaks the link", "note": "Another route breaks the link to the original payment"}, {"label": "Expected message for a return", "note": "The pacs.004 is the expected message for a return"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C037", "seq": 259, "module": "Core", "source": "Article and reader comments", "title": "Recalling a serial MT103 follows the chain", "explain": "A serial MT103 can be recalled, but the recall must travel the same chain of banks that carried the payment forward, because each bank in the chain holds part of the payment. The originator bank sends the recall to the next bank in the chain, and each bank passes it on until it reaches the beneficiary bank, which decides whether the funds can be returned. A recall that skips a bank cannot work, because the bank that was skipped still holds the funds.", "takeaway": "A recall that skips a bank cannot work, because the bank that was skipped still holds the funds.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends the recall", "note": "The recall goes to the next bank in the chain"}, {"kind": "step", "title": "Each bank passes the recall onward", "note": "Each bank passes it on until it reaches the beneficiary bank"}, {"kind": "decision", "title": "Beneficiary bank decides on the funds", "note": "The beneficiary bank decides whether the funds can be returned"}, {"kind": "step", "title": "Recall cannot skip a bank", "note": "A skipped bank still holds the funds, so the recall fails"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "PAI-C060", "seq": 268, "module": "Core", "source": "Article and reader comments", "title": "The cover amount must never fall short", "explain": "It is forbidden to take charges from an MT202 COV, so the cover amount must never be lower than the amount announced in the MT103. If an intermediary needs to be paid for its part in the chain, it asks the sending bank to pay through an MT191 or debits the account directly under the agreement between the banks. A cover that arrives short of the announced amount is therefore an exception, not a normal deduction.", "takeaway": "A cover that arrives short of the announced amount is therefore an exception, not a normal deduction.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Charges must not be taken from MT202 COV", "note": "It is forbidden to take charges from an MT202 COV"}, {"kind": "step", "title": "Cover amount must match the MT103 amount", "note": "The cover amount must never be lower than the amount in the MT103"}, {"kind": "step", "title": "Intermediary claims charges separately", "note": "An intermediary asks the sending bank through an MT191 or debits the account directly"}, {"kind": "decision", "title": "Cover arriving short is an exception", "note": "A cover arriving short of the announced amount is an exception"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103", "MT202", "MT191"], "failure_category": "charge deduction"}, {"id": "PAI-C072", "seq": 277, "module": "Core", "source": "Article and reader comments", "title": "Cross-border timing: when a delay is a problem", "explain": "A transfer in a major currency such as the United States dollar or the euro usually arrives in 48 to 72 hours, while a transfer in a less common local currency takes longer because the currency is harder to buy. A large amount can also slow a payment down, because it may need extra checks before it is released. If the money has not arrived after two weeks, there is definitely a problem, and the sending bank should be asked to trace it, since it knows every party in the chain.", "takeaway": "If the money has not arrived after two weeks, there is definitely a problem, and the sending bank should be asked to trace it, since it knows every party in the chain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Major currency transfer takes 48 to 72 hours", "note": "A transfer in United States dollars or euros usually arrives in 48 to 72 hours"}, {"kind": "step", "title": "Less common currency takes longer", "note": "A less common local currency takes longer because it is harder to buy"}, {"kind": "step", "title": "Large amount may need extra checks", "note": "A large amount can slow a payment down because it may need extra checks"}, {"kind": "decision", "title": "Money not arrived after two weeks", "note": "If the money has not arrived after two weeks, there is definitely a problem"}, {"kind": "step", "title": "Sending bank asked to trace it", "note": "The sending bank should be asked to trace it, since it knows every party"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "PAI-C090", "seq": 288, "module": "Core", "source": "Article and reader comments", "title": "An MT103 with no beneficiary name", "explain": "An MT103 can arrive showing only the beneficiary's IBAN and address in field 59, with no name at all. Field 59 is meant to identify the beneficiary, so a missing name leaves the beneficiary bank unable to confirm that the account belongs to the person the payment was meant for. The bank may hold the payment and ask for confirmation instead of crediting it, and the sender's bank is the one that must supply the missing name.", "takeaway": "The bank may hold the payment and ask for confirmation instead of crediting it, and the sender's bank is the one that must supply the missing name.", "visual": {"type": "diagram", "diagram": {"centre": "An MT103 with no beneficiary name", "parts": [{"label": "Only IBAN and address in field 59", "note": "An MT103 can arrive showing only the beneficiary's IBAN and address in field 59"}, {"label": "Field 59 must identify the beneficiary", "note": "Field 59 is meant to identify the beneficiary"}, {"label": "Bank cannot confirm the account owner", "note": "A missing name leaves the bank unable to confirm the account belongs to the right person"}, {"label": "Bank may hold and ask for confirmation", "note": "The bank may hold the payment and ask for confirmation instead of crediting it"}, {"label": "Sender's bank must supply the name", "note": "The sender's bank must supply the missing name"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D04 Messaging and standards", "messages": ["MT103"], "failure_category": "invalid beneficiary data"}, {"id": "RUN3-004", "seq": 300, "module": "Core", "source": "Article and reader comments", "title": "SDD: silence after pacs.007 is normal, not failure", "explain": "Under the SDD scheme the debtor bank sends no scheme response once it has the pacs.007 collection instruction, so silence after that point says nothing about the outcome. When the collection comes back, it arrives as a pacs.004 return or refund, and the creditor bank must process it without any option to refuse. The creditor therefore builds its processing around handling returns, rather than waiting for the debtor bank to seek agreement.", "takeaway": "The creditor therefore builds its processing around handling returns, rather than waiting for the debtor bank to seek agreement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Creditor bank sends pacs.007", "note": "The collection instruction goes to the debtor bank under SDD."}, {"kind": "step", "title": "No scheme response follows", "note": "Silence after this point does not signal a failed collection."}, {"kind": "step", "title": "pacs.004 comes back", "note": "A return or refund arrives in a pacs.004."}, {"kind": "step", "title": "Creditor bank must process it", "note": "The creditor bank has no option to refuse the pacs.004."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.007", "pacs.004"], "failure_category": "timeout", "resolution": "return"}, {"id": "RUN3-005", "seq": 301, "module": "Core", "source": "Article and reader comments", "title": "pacs.004: the initiator decides return or refund", "explain": "A pacs.004 can carry either a return or a refund, and the two are distinct business events sharing one message type. The debtor bank starts a return, while the debtor starts a refund, so reading the initiator identifies which event the message carries. That identification matters because the two events run under different rules and different time limits.", "takeaway": "That identification matters because the two events run under different rules and different time limits.", "visual": {"type": "diagram", "diagram": {"centre": "One message, two events", "parts": [{"label": "Return", "note": "Started by the debtor bank, using a pacs.004."}, {"label": "Refund", "note": "Started by the debtor, using the same pacs.004."}, {"label": "Read the initiator", "note": "The initiator identifies which of the two events the message carries."}, {"label": "Different rules, different limits", "note": "Each event runs under its own rules and time limits."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D08 Cards and alternative payments", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "RUN3-006", "seq": 302, "module": "Core", "source": "Article and reader comments", "title": "SDD Core refunds: 8 weeks, or 13 months if no mandate", "explain": "In SDD Core a debtor may claim a refund within 8 weeks where a valid mandate stands behind the collection. The 13 month window opens only where no valid mandate exists at all, so the two periods must never be confused. The creditor holds the mandate, which is why the creditor must produce it when a refund claim is disputed.", "takeaway": "The creditor holds the mandate, which is why the creditor must produce it when a refund claim is disputed.", "visual": {"type": "diagram", "diagram": {"centre": "SDD Core refund windows", "parts": [{"label": "8 weeks, valid mandate", "note": "Refund claim window where a valid mandate backs the collection."}, {"label": "13 months, no valid mandate", "note": "The longer window applies only where no valid mandate exists."}, {"label": "Creditor holds the mandate", "note": "The creditor must produce the mandate when a claim is disputed."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "mandate issue", "resolution": "return"}, {"id": "INS-108", "seq": 325, "module": "Core", "source": "Public post", "title": "Bad intermediary data, rejected downstream", "explain": "An instruction can name an intermediary that cannot serve the destination currency and holds no settlement relationship for that corridor, and the payment dies downstream. The failure is then unreadable: message mapping, routing reference data and routing logic all look equally guilty. Start from the agent chain data, validate every intermediary against the corridor, repair the reference data, and track repair rates so the bad intermediary is caught before its next payment.", "takeaway": "Start from the agent chain data, validate every intermediary against the corridor, repair the reference data, and track repair rates so the bad intermediary is caught before its next payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Test currency and corridor coverage.", "title": "Test the intermediary"}, {"kind": "step", "note": "Confirm the chain is complete at every agent.", "title": "Test the agent chain data"}, {"kind": "step", "note": "Fix mapping or routing data at its source.", "title": "Repair the reference data"}, {"kind": "step", "note": "Spot a bad intermediary before the next payment uses it.", "title": "Track the repair rate"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "wrong routing", "resolution": "repair"}, {"id": "INS-116", "seq": 328, "module": "Core", "source": "Public post", "title": "The purpose code gap that breaks payments", "explain": "A purpose code that is optional at the customer and mandatory downstream is a defect waiting for a payment. Name the downstream system that needs it, give enrichment a named owning source, and validate early enough to catch a missing code before the payment reaches that system. And define the repair behaviour up front, who fixes it, how fast, and what happens to the payment while it waits.", "takeaway": "And define the repair behaviour up front, who fixes it, how fast, and what happens to the payment while it waits.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Name the system that needs the code.", "title": "Name the downstream requirement"}, {"kind": "step", "note": "Give a named source the job of supplying it.", "title": "Assign the enrichment owner"}, {"kind": "step", "note": "Catch the missing code early.", "title": "Validate before the payment is sent"}, {"kind": "step", "note": "Settle who fixes it, how fast, and what waits.", "title": "Define the repair behaviour"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "INS-118", "seq": 329, "module": "Core", "source": "Public post", "title": "When Intermediary Agent 2 data goes stale", "explain": "Reference data without an owner decays, and Intermediary Agent 2 is the proof: nobody maintains it, so it quietly points payments at a bank that no longer serves the corridor. The control set is fourfold, a named owner, a validation rule, an update process, and a routing control that stops a payment whose intermediary data is out of date. Leave any of the four out and the same bad intermediary keeps reappearing until a rejection or a repair exposes it.", "takeaway": "Leave any of the four out and the same bad intermediary keeps reappearing until a rejection or a repair exposes it.", "visual": {"type": "diagram", "diagram": {"centre": "Intermediary Agent 2, unmaintained", "parts": [{"label": "One named owner", "note": "One person accountable for the data."}, {"label": "Currency check", "note": "A rule testing whether the data is current."}, {"label": "Timely updates", "note": "Changes land in the data on time."}, {"label": "Routing block on stale data", "note": "Stale data blocks the payment at routing."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "wrong routing", "resolution": "repair"}, {"id": "INS-158", "seq": 332, "module": "Core", "source": "Public post", "title": "A collection file is a scheme submission", "explain": "Treat a collection file as a regulated scheme submission, not a spreadsheet job: the same errors return every month, a cancelled customer still collected, an amount changed after the file was built, a file submitted after the scheme deadline. The discipline is the sequence, build from current mandate and billing data, validate, win creditor PSP acceptance, submit inside the scheme window. Skip a step and the cost arrives as refunds, complaints and rework.", "takeaway": "Skip a step and the cost arrives as refunds, complaints and rework.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Build on live mandate and billing data.", "title": "Build on current data"}, {"kind": "step", "note": "Test amounts, mandates and dates.", "title": "Validate the file"}, {"kind": "step", "note": "Win the PSP acceptance for submission.", "title": "Win creditor PSP acceptance"}, {"kind": "step", "note": "Submit before the scheme deadline.", "title": "Submit inside the scheme window"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "INS-159", "seq": 333, "module": "Core", "source": "Public post", "title": "After submission, deletion stops working", "explain": "Once a file is with the creditor PSP, cancelling a collection is a scheme process, not a delete key. Cancellation follows the process for the collection state at that moment, and a collection already in processing can only be stopped on the defined cancellation path. Billing must know the exact lifecycle point where deletion stops working and cancellation takes over, because that point decides whether the customer is debited.", "takeaway": "Billing must know the exact lifecycle point where deletion stops working and cancellation takes over, because that point decides whether the customer is debited.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Locate the collection in its lifecycle.", "title": "Locate the collection state"}, {"kind": "step", "note": "Delete it while the file is still yours.", "title": "Cancel ahead of submission"}, {"kind": "step", "note": "Follow the scheme cancellation path.", "title": "Cancel once submitted"}, {"kind": "step", "note": "Evidence the customer will not be debited.", "title": "Prove the cancellation held"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "INS-160", "seq": 334, "module": "Core", "source": "Public post", "title": "Same word, different mechanism", "explain": "Cancellation and revocation are different mechanisms that happen to sound alike: different parties start them, at different times, for collections in different states. A member cancelling a membership expects no further collection, a billing clerk revoking a collection expects it never to leave the building, and a creditor PSP receiving a cancellation request expects a scheme message with a response. Choose by collection state, because the wrong mechanism debits the member anyway or gets the request rejected by the bank.", "takeaway": "Choose by collection state, because the wrong mechanism debits the member anyway or gets the request rejected by the bank.", "visual": {"type": "diagram", "diagram": {"centre": "State picks the mechanism", "parts": [{"label": "Cancelling", "note": "Ends future collections for the membership."}, {"label": "Revoking", "note": "Stops a collection before it leaves."}, {"label": "Who starts it", "note": "Member, clerk or PSP, each on its own path."}, {"label": "State decides", "note": "State, not wording, decides the mechanism."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "INS-161", "seq": 335, "module": "Core", "source": "Public post", "title": "Settled money is reversed, never erased", "explain": "A reversal is its own transaction, not a deletion and not a debtor refund claim: a separate, linked entry returning money already settled, used when a duplicate collection can no longer be cancelled or revoked because the money has moved. It carries the original references, is initiated by the creditor, and posts as its own accounting entry so reconciliation pairs it with the original instead of finding a hole. Deleting settled entries breaks reconciliation, so the duplicate is reversed, never erased.", "takeaway": "Deleting settled entries breaks reconciliation, so the duplicate is reversed, never erased.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Cancellation and revocation are past their point.", "title": "Confirm the money has settled"}, {"kind": "step", "note": "Creditor opens a linked return.", "title": "Open the reversal"}, {"kind": "step", "note": "Attach the duplicate references.", "title": "Attach the original references"}, {"kind": "step", "note": "Book the reversal as a separate entry.", "title": "Book the accounting entries"}, {"kind": "step", "note": "Match the reversal to the original collection.", "title": "Reconcile the pair"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "duplicate payment", "resolution": "return"}, {"id": "SCN-04", "seq": 338, "module": "Core", "source": "Public post", "title": "RJCT before settlement: repair, do not return", "explain": "An RJCT on a pacs.002 is a pre-settlement verdict: the status report says the instruction failed, and no money has moved. The reason code names the failure precisely, technical, such as a schema or format error, or business, such as a sanctions flag, and each kind has its own owner. The remedy is repair at source and resubmission as a new instruction, new message ID, same UETR, so tracking stays continuous.", "takeaway": "The remedy is repair at source and resubmission as a new instruction, new message ID, same UETR, so tracking stays continuous.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Status RJCT plus reason code names the failure.", "title": "Read the pacs.002 report"}, {"kind": "step", "note": "Schema or format is technical; sanctions or rules is business.", "title": "Classify the failure"}, {"kind": "step", "note": "Nothing settled, so repair applies, not return.", "title": "Confirm nothing settled"}, {"kind": "step", "note": "Correct the instruction data or the originating system.", "title": "Repair at the source"}, {"kind": "step", "note": "New message ID, same UETR, unbroken tracking.", "title": "Resubmit on the same UETR"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002"], "failure_category": "payment rejected or returned", "resolution": "repair"}, {"id": "SCN-05", "seq": 339, "module": "Core", "source": "Public post", "title": "After settlement, only a return moves money", "explain": "Settlement closes the pacs.002 path for good: a status report never moves money, so a settled payment cannot be fixed by reporting. The funds must come back through a pacs.004, a real settlement instruction in reverse, travelling the return chain through every bank the original passed. Return charges may come off along the way, so the amount returning can differ from the amount sent, and the UETR ties both legs together for reconciliation.", "takeaway": "Return charges may come off along the way, so the amount returning can differ from the amount sent, and the UETR ties both legs together for reconciliation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "ACSC means funds moved; the pacs.002 path is closed.", "title": "Confirm the settlement"}, {"kind": "step", "note": "Open a genuine settlement instruction in reverse.", "title": "Open the pacs.004"}, {"kind": "step", "note": "Outbound A to B to C to D, return D to C to B to A.", "title": "Trace the return chain"}, {"kind": "step", "note": "Charges on the way back may shrink the amount.", "title": "Reconcile the variance"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "SCN-08", "seq": 340, "module": "Core", "source": "Public post", "title": "Beneficiary bank sends the money back itself", "explain": "A beneficiary bank that credits an account and then finds it closed or frozen does not wait to be asked. It becomes the return originator and sends the pacs.004 back along the chain in reverse. Charges may be deducted at hops, so the sender recovers the original minus charges, and the return is matched to the original payment by UETR.", "takeaway": "Charges may be deducted at hops, so the sender recovers the original minus charges, and the return is matched to the original payment by UETR.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Account closed or frozen, found after the funds landed.", "title": "Find the problem after credit"}, {"kind": "step", "note": "Beneficiary bank originates the return.", "title": "Open the pacs.004 return"}, {"kind": "step", "note": "Each intermediary validates and passes the return on.", "title": "Send it back along the chain"}, {"kind": "step", "note": "Pair the return with the original by UETR.", "title": "Match the return to the original"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "SCN-11", "seq": 342, "module": "Core", "source": "Public post", "title": "A timeout is an unknown, not a failure", "explain": "A timeout reports nothing about the outcome, and a blind retry on an unknown can double-pay. Freeze the payment, then work the evidence, UETR, EndToEndId and TxId across the tracker and hop logs, late responses, and statements against camt.054 notifications. Act only on the true state found: resubmit if it truly failed, recall or claim if it settled incorrectly.", "takeaway": "Act only on the true state found: resubmit if it truly failed, recall or claim if it settled incorrectly.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Stop automatic retry until the state is known.", "title": "Freeze the payment"}, {"kind": "step", "note": "Work the tracker and hop logs.", "title": "Investigate by UETR"}, {"kind": "step", "note": "A pacs.002, pacs.004 or pacs.009 may arrive late.", "title": "Check for late responses"}, {"kind": "step", "note": "Test whether funds actually moved.", "title": "Reconcile the statements"}, {"kind": "step", "note": "Resubmit only on a proven failure.", "title": "Act on the true state"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.054"], "failure_category": "timeout", "resolution": "investigate"}, {"id": "SCN-13", "seq": 344, "module": "Core", "source": "Public post", "title": "India to USA: trace the failed payment", "explain": "Cross-border tracing works leg by leg, never as one rail: a SWIFT pacs.008 moves across correspondents, then Fedwire completes final US dollar settlement. Start from the UETR in the tracker, locate the last successful hop, and read the status message there, because its reason code names the failure. Then test the corridor suspects, a missing purpose code, a sanctions hold, an invalid routing number, or an FX or cut-off gap, and close the case with the right message, a pacs.004 return or a camt.056 recall.", "takeaway": "Then test the corridor suspects, a missing purpose code, a sanctions hold, an invalid routing number, or an FX or cut-off gap, and close the case with the right message, a pacs.004 return or a camt.056 recall.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Use the tracker to see every hop.", "title": "Take the UETR"}, {"kind": "step", "note": "Failure sits at or just after that point.", "title": "Find the last good hop"}, {"kind": "step", "note": "AC04 account closed, BE01 details mismatch, RC01 bad routing, AM05 duplicate.", "title": "Read the status and reason code"}, {"kind": "step", "note": "Purpose code, sanctions, routing, FX or cut-off gap.", "title": "Test the corridor suspects"}, {"kind": "step", "note": "Return or recall, closed with a camt.029.", "title": "Resolve with the right message"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": ["pacs.008", "pacs.004", "camt.056"], "resolution": "investigate"}, {"id": "SCN-14", "seq": 345, "module": "Core", "source": "Public post", "title": "Timeout: pull the recall brake", "explain": "A payment timed out mid-chain with its true state unknown is exactly when a recall earns its name as an emergency brake: send the request down the chain and stop it before it completes. The brake has one limit, it cannot undo a completed credit. Where the credit already completed, switch to the return flow via pacs.004, and update the customer at each step, because silence turns incidents into escalations.", "takeaway": "Where the credit already completed, switch to the return flow via pacs.004, and update the customer at each step, because silence turns incidents into escalations.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "pacs.008 left core banking; the delay is downstream.", "title": "Pin down the timeout point"}, {"kind": "step", "note": "Test whether funds actually moved.", "title": "Track by UETR"}, {"kind": "step", "note": "Brake the payment, do not reverse it.", "title": "Send the recall request"}, {"kind": "step", "note": "Completed credit means return the funds.", "title": "Switch to pacs.004 once completed"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "timeout"}, {"id": "SCN-16", "seq": 346, "module": "Core", "source": "Public post", "title": "A return is a payment in reverse", "explain": "Treat a pacs.004 as what it is, a real payment in reverse: settled funds moving backward through the same chain, carrying its own charges and its own references. It applies when the beneficiary bank finds a closed or frozen account, a duplicate payment, or a wrong beneficiary after settlement. Its return chain element preserves the original chain so every intermediary knows its place, and returns deserve the same operational controls as outward payments.", "takeaway": "Its return chain element preserves the original chain so every intermediary knows its place, and returns deserve the same operational controls as outward payments.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Closed account, duplicate, or wrong beneficiary, after settlement.", "title": "Trigger only after settlement"}, {"kind": "step", "note": "Settled funds move backward.", "title": "Send the pacs.004 in reverse"}, {"kind": "step", "note": "Returned amount can differ from the amount sent.", "title": "Deduct the return charges"}, {"kind": "step", "note": "Tie it by UETR and message references.", "title": "Link the return to the original"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "SCN-19", "seq": 348, "module": "Core", "source": "Public post", "title": "Investigations run on rails, not instinct", "explain": "A payment investigation is a fixed sequence: intake and triage, identify the payment, verify the true status, check compliance, contact the correspondent, and resolve. Give every case type an SLA and an escalation matrix, because investigations without deadlines become backlogs. And contact the correspondent with structured queries and full references, never free-text emails that go nowhere.", "takeaway": "And contact the correspondent with structured queries and full references, never free-text emails that go nowhere.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Sort the trigger: beneficiary error, delay, hold, Nostro break, duplicate.", "title": "Take in and triage"}, {"kind": "step", "note": "Fix it with UETR and references.", "title": "Identify the payment"}, {"kind": "step", "note": "Find the hop reached, settled or not.", "title": "Verify the true status"}, {"kind": "step", "note": "Screening and regulatory constraints come first.", "title": "Run the compliance check"}, {"kind": "step", "note": "Structured queries, full references.", "title": "Contact the correspondent"}, {"kind": "step", "note": "Return, recall, repair or re-release, closed with evidence.", "title": "Resolve and close the case"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "SCN-32", "seq": 356, "module": "Core", "source": "Public post", "title": "250,000 euros held on a name mismatch", "explain": "A 250,000 euro payment sat uncredited for three days because the beneficiary bank flagged a name mismatch. A pacs.002 showing Pending means the beneficiary bank is holding the payment, not rejecting it, so open with an investigation query for the exact mismatch detail. Correct and verify the name and the bank applies the funds; if it cannot be resolved the payment returns via pacs.004, so validate beneficiary details at initiation, including confirmation of payee where the corridor supports it.", "takeaway": "Correct and verify the name and the bank applies the funds; if it cannot be resolved the payment returns via pacs.004, so validate beneficiary details at initiation, including confirmation of payee where the corridor supports it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Pending is a hold, not a rejection.", "title": "Read the pacs.002 Pending"}, {"kind": "step", "note": "Ask for the exact mismatch detail.", "title": "Raise the investigation query"}, {"kind": "step", "note": "Verify the correction, or return the funds.", "title": "Correct the name or return the funds"}, {"kind": "step", "note": "Confirmation of payee where the corridor supports it.", "title": "Validate at the start"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.004"], "failure_category": "name mismatch", "resolution": "investigate"}, {"id": "JEB-F14", "seq": 359, "module": "Core", "source": "Public post", "title": "Stop a mistaken collection by its lifecycle stage", "explain": "When a creditor realises a collection was made by mistake, the right mechanism depends on where the collection sits in its lifecycle. While it is warehoused with the creditor PSP and has not entered the inter-PSP flow, the creditor revokes it, and once it is in the clearing flow but before settlement, the creditor requests cancellation through the PSP or CSM process. After clearing and settlement, only a reversal can reimburse the debtor for the erroneous collection, and one generic cancel requirement cannot cover all three because the stage, initiator, mechanism and responsibilities differ, with refund the remaining step after settlement.", "takeaway": "After clearing and settlement, only a reversal can reimburse the debtor for the erroneous collection, and one generic cancel requirement cannot cover all three because the stage, initiator, mechanism and responsibilities differ, with refund the remaining step after settlement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The collection must be stopped, but the mechanism depends on its stage", "title": "Creditor spots a mistake in a collection"}, {"kind": "decision", "note": "Warehoused, in the clearing flow, or already settled", "title": "Where is the collection?"}, {"kind": "step", "note": "Revocation goes from creditor to creditor PSP", "title": "Warehoused: revoke it"}, {"kind": "step", "note": "Cancellation before settlement through the PSP or CSM process", "title": "In clearing: request cancellation"}, {"kind": "step", "note": "Reversal reimburses the debtor after clearing and settlement", "title": "Settled: reverse it"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-D04", "seq": 367, "module": "Core", "source": "Public post", "title": "Untraced payments turn queries into investigations", "explain": "A processed cross-border payment can still show no credit by mid-morning because it may have failed silently, queued, stalled on missing details, or stopped for compliance checks, and without a live trace one customer query becomes hours of back-and-forth, reconciliation and investigation. Visibility comes from three elements working together: the UETR, ISO 20022 structured data, and connected systems and processes. A payment without a trace leaves a customer question unanswered, while a tracked payment reconciles faster, clears exceptions sooner, and avoids duplication, failed credits and manual rework.", "takeaway": "A payment without a trace leaves a customer question unanswered, while a tracked payment reconciles faster, clears exceptions sooner, and avoids duplication, failed credits and manual rework.", "visual": {"type": "diagram", "diagram": {"centre": "Making the payment journey visible", "parts": [{"label": "UETR", "note": "Unique End-to-End Transaction Reference, tracking the payment through its journey."}, {"label": "ISO 20022 structured data", "note": "Rich structured data travelling with the payment."}, {"label": "Connected systems", "note": "Systems and processes sharing status end to end."}, {"label": "No real-time trace", "note": "One customer query becomes hours of reconciliation and investigation."}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "JEB-D05", "seq": 368, "module": "Core", "source": "Public post", "title": "Failed instant payments: find the outcome first", "explain": "When an instant payment fails, the debit can land immediately while the beneficiary receives nothing, so the first task is to establish the cause: a timeout, an account issue, a technical problem, a compliance issue, or insufficient funds. Failed payments split into two kinds: genuinely rejected ones, where the money returns to the payer, and stuck ones, which need investigation, sometimes with the receiving bank helping to return the money. The same payment can even end differently in different countries, so the operative question is not only whether money left, but what the outcome is and where the money now sits.", "takeaway": "The same payment can even end differently in different countries, so the operative question is not only whether money left, but what the outcome is and where the money now sits.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Money is debited at once, yet the beneficiary receives nothing.", "title": "Instant payment sent"}, {"kind": "decision", "note": "Insufficient funds, compliance, technical fault, account issue, or timeout.", "title": "What caused the failure?"}, {"kind": "step", "note": "Money returns to the payer.", "title": "Genuinely rejected"}, {"kind": "step", "note": "Payment needs investigation, and the receiving bank can sometimes help return it.", "title": "Stuck, investigate"}, {"kind": "step", "note": "The same payment can end differently in different countries.", "title": "Outcome varies by country"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "JEB-E04", "seq": 376, "module": "Core", "source": "Public post", "title": "Repair at scale needs a threshold, not a habit", "explain": "Sending failed transactions to a repair queue works when only a few fail, but when 90 percent of a remittance file needs repair, Operations cannot manage the volume and the customer cannot reconcile what was processed, what was not, and what must be corrected. The working rule is size-based: files with fewer than 20 transactions carry no threshold and send problem items to repair while valid items continue, while files with 20 or more apply a 5 percent threshold, so up to 5 percent repair goes to repair and anything above it rejects the whole file for correction and resubmission. No transaction is released before the threshold is checked, because releasing some items first and then discovering the whole file should have been rejected leaves a partially processed file that cannot be undone cleanly.", "takeaway": "No transaction is released before the threshold is checked, because releasing some items first and then discovering the whole file should have been rejected leaves a partially processed file that cannot be undone cleanly.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Some transactions in a remittance file fail a control.", "title": "File fails a banking control"}, {"kind": "decision", "note": "Small files carry no threshold; larger files apply the 5 percent rule.", "title": "File has 20 or more transactions?"}, {"kind": "step", "note": "Valid transactions continue and exceptions go to repair.", "title": "At or below 5 percent"}, {"kind": "step", "note": "The whole file is rejected and the client corrects and resubmits it.", "title": "Above 5 percent"}, {"kind": "step", "note": "No transaction is released before the threshold is checked.", "title": "Check before releasing"}]}}, "level": "core", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "reject"}, {"id": "JEB-A02", "seq": 436, "module": "Advanced", "source": "Public post", "title": "Missing pacs.002 on SCT Inst: request status, never resend", "explain": "In SCT Inst, absence of a pacs.002 after the 20 second timeout leaves a EUR 5,000 payment in limbo: the customer account stands debited, the funds have left, and credit to the beneficiary stays unconfirmed. Resending would risk a duplicate, so the sender bank must instead issue a pacs.028 status request and let the recipient bank investigate. That investigation either confirms the credit, closing the case, or confirms rejection, triggering an automatic refund and restoration of the account, since leaving the customer unrestored can breach Article 5 of the SEPA Instant Regulation.", "takeaway": "That investigation either confirms the credit, closing the case, or confirms rejection, triggering an automatic refund and restoration of the account, since leaving the customer unrestored can breach Article 5 of the SEPA Instant Regulation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "An SCT Inst payment should complete within seconds", "title": "EUR 5,000 instant payment sent"}, {"kind": "step", "note": "No final confirmation arrives within the scheme timeout", "title": "20 second timeout, no pacs.002"}, {"kind": "decision", "note": "Debit is posted and funds have left, but credit stays unconfirmed", "title": "Beneficiary credited or not?"}, {"kind": "step", "note": "A second debit and payment would create a duplicate", "title": "Never send it a second time"}, {"kind": "step", "note": "Ask the recipient bank to investigate the original payment", "title": "Issue pacs.028 status request"}, {"kind": "step", "note": "Confirmed credit closes the case; rejection triggers automatic refund", "title": "Close the case or refund"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.028"], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "JEB-A14", "seq": 440, "module": "Advanced", "source": "Public post", "title": "gpi tracking cannot stop a credited payment: recall it", "explain": "Tracking a SWIFT gpi payment only shows where it is, while stopping it prevents credit to the beneficiary, and the two must never be confused: a EUR 100,000 payment sent to the wrong beneficiary was already credited as ACSC within 30 minutes, so the stop message had no effect. Once credited, the bank needs a Stop and Recall request, routed by urgency: FAST, acknowledged within 2 hours when the payment is settled and credited; MEDIUM, answered within 12 hours when the beneficiary bank needs time to reach the beneficiary; and SLOW, answered within 72 hours when more time is needed. Delay steadily shrinks the chance of recovery, so speed decides whether a recall remains possible.", "takeaway": "Delay steadily shrinks the chance of recovery, so speed decides whether a recall remains possible.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Tracking only shows where the payment is", "title": "Tracking shows the location"}, {"kind": "decision", "note": "Once credited to the beneficiary, a stop message has no effect", "title": "Already credited as ACSC?"}, {"kind": "step", "note": "Stopping needs a Stop and Recall request instead of tracking", "title": "Send Stop and Recall request"}, {"kind": "step", "note": "Acknowledged within 2 hours when the payment is settled and credited", "title": "FAST queue: within 2 hours"}, {"kind": "step", "note": "Answered within 12 hours when the bank needs time to contact the beneficiary", "title": "MEDIUM queue: within 12 hours"}, {"kind": "step", "note": "Answered within 72 hours when more time is needed", "title": "SLOW queue: within 72 hours"}, {"kind": "step", "note": "Each minute lost lowers the odds of stopping the payment", "title": "Act fast"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "JEB-B13", "seq": 445, "module": "Advanced", "source": "Public post", "title": "camt.055: cancellation depends on where payment sits", "explain": "When a camt.055 cancellation request arrives, do not assume a camt.056 should be sent straight away; the first question is where the original payment sits in its lifecycle. A future-dated or warehoused payment that has not been released may be cancelled before execution, a payment pending a compliance decision must be considered alongside that process, and a payment already processed by the debtor bank is no longer an internal decision. In a direct and cover model, each leg is controlled by a different party, so the pacs.008 leg and the pacs.009 COV leg may each need their own follow-up. A cancellation request only asks for the cancellation, it does not guarantee it, and if it fails, the next step is to determine the appropriate return or investigation path.", "takeaway": "A cancellation request only asks for the cancellation, it does not guarantee it, and if it fails, the next step is to determine the appropriate return or investigation path.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Do not assume a camt.056 should be sent straight away", "title": "camt.055 cancellation arrives"}, {"kind": "decision", "note": "First ask where the original payment sits in its lifecycle", "title": "Where does the payment sit?"}, {"kind": "step", "note": "A future-dated payment not yet released may be cancelled before execution", "title": "Warehoused: cancel before execution"}, {"kind": "step", "note": "A payment pending a compliance decision must be considered alongside that process", "title": "Pending compliance: consider together"}, {"kind": "step", "note": "A payment already processed by the debtor bank is no longer an internal decision", "title": "Already processed: not internal"}, {"kind": "step", "note": "In a direct and cover model, the pacs.008 and pacs.009 COV legs may each need follow-up", "title": "Each leg needs its own follow-up"}, {"kind": "step", "note": "A cancellation is a request, not a guarantee; determine the return or investigation path", "title": "If it fails, find the return path"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.055", "camt.056", "pacs.008", "pacs.009"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "JEB-C12", "seq": 447, "module": "Advanced", "source": "Public post", "title": "The recall journey in four messages, one open question", "explain": "The end-to-end recall journey runs through camt.055, the customer cancellation request, camt.056, the interbank cancellation request, pacs.004, the payment return, and camt.029, the resolution of the investigation. The post asks which of these four messages is not used in the flow and puts it to a poll, promising the author perspective later in the week. The post itself does not give the answer, so this item states the journey as the post presents it and leaves the poll question open rather than guessing the answer. Connecting the four messages into one journey is the point of the exercise, not naming each message on its own.", "takeaway": "Connecting the four messages into one journey is the point of the exercise, not naming each message on its own.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The journey starts with the customer cancellation request", "title": "camt.055: customer cancellation request"}, {"kind": "step", "note": "The bank sends the interbank cancellation request", "title": "camt.056: interbank cancellation request"}, {"kind": "step", "note": "The return of the payment follows", "title": "pacs.004: the payment return"}, {"kind": "step", "note": "The investigation is resolved with a camt.029", "title": "camt.029: resolution of investigation"}, {"kind": "step", "note": "The post asks which message is not used and leaves the poll question open", "title": "One message is not used: poll open"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.055", "camt.056", "pacs.004", "camt.029"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-087", "seq": 453, "module": "Advanced", "source": "Public post", "title": "Duplicate transaction investigation", "explain": "A supplier payment appears twice on the account statement for the same amount, to the same supplier, on the same day, and the supplier confirms receiving two credits. Reconstruct both payments end to end from the same evidence set: for each submission collect the channel timestamp, the idempotency key and payload hash, the gateway reference, the payment engine reference, the ledger posting reference and the clearing acknowledgement. Comparing the two sets of evidence shows whether the duplicate came from a client retry, a gateway redelivery or a missing idempotency check, and each cause has a different fix.", "takeaway": "Comparing the two sets of evidence shows whether the duplicate came from a client retry, a gateway redelivery or a missing idempotency check, and each cause has a different fix.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collect evidence, first payment", "note": "Timestamps, idempotency key, hashes and references."}, {"kind": "step", "title": "Collect evidence, second payment", "note": "The same evidence set for the second payment."}, {"kind": "step", "title": "Compare the two sets", "note": "Comparing shows where the duplicate came from."}, {"kind": "step", "title": "Identify the cause", "note": "Client retry, gateway redelivery or missing check."}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "INS-050", "seq": 454, "module": "Advanced", "source": "Public post", "title": "Duplicate transactions appear after release", "explain": "After a new corporate payment channel is released, the operations team notices duplicate debits: several corporate customers have been charged twice for the same instruction, and a few suppliers have been paid twice. Contain the failure first by confirming whether duplicates are still being created and, if so, stopping the affected path or routing it through a manual check. Then establish the affected population using stable identifiers rather than guesswork, matching on idempotency key, instruction reference, end-to-end identification, debtor, creditor, amount, currency and value date, and separate confirmed duplicates from suspected ones before remediating.", "takeaway": "Then establish the affected population using stable identifiers rather than guesswork, matching on idempotency key, instruction reference, end-to-end identification, debtor, creditor, amount, currency and value date, and separate confirmed duplicates from suspected ones before remediating.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Contain the failure", "note": "Confirm duplicates are still being created; stop the path."}, {"kind": "step", "title": "Establish the population", "note": "Match on stable identifiers, not guesswork."}, {"kind": "step", "title": "Separate confirmed and suspected", "note": "Separate confirmed duplicates from suspected ones."}, {"kind": "step", "title": "Remediate", "note": "Fix the cause and put right the affected payments."}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "PAI-C042", "seq": 479, "module": "Advanced", "source": "Article and reader comments", "title": "Deducted, rejected, and the funds must return", "explain": "When the originator bank deducts the amount from the customer but the payment never reaches the beneficiary because the clearing system rejected it, the funds must be returned, and the question is which messages carry that return inside the clearing system. The clearing system holds the funds it rejected, so the return starts there and travels back to the originator bank, which credits the customer. The customer sees a deduction with no payment, and the return is what makes the customer whole.", "takeaway": "The customer sees a deduction with no payment, and the return is what makes the customer whole.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank deducts from customer", "note": "The originator bank deducts the amount from the customer"}, {"kind": "step", "title": "Clearing system rejects the payment", "note": "The clearing system rejects it, so it never reaches the beneficiary"}, {"kind": "step", "title": "Clearing system holds the rejected funds", "note": "The clearing system holds the funds it rejected"}, {"kind": "step", "title": "Return travels back to originator bank", "note": "The return starts at the clearing system and travels back"}, {"kind": "step", "title": "Originator bank credits the customer", "note": "The originator bank credits the customer, making the customer whole"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "charge deduction", "resolution": "return"}, {"id": "PAI-C046", "seq": 483, "module": "Advanced", "source": "Article and reader comments", "title": "A misspelt name in field 50 can return a payment", "explain": "When the ordering customer name in field 50 is misspelt, the MT103 can be returned to the originator bank, and the question is which message carries that return. The misspelling matters because screening and reconciliation match on the name, and a name that does not match the account can look like a different party. The return is therefore a data-quality failure, not a funds failure, and it is fixed by correcting the name and resending.", "takeaway": "The return is therefore a data-quality failure, not a funds failure, and it is fixed by correcting the name and resending.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Name in field 50 is misspelt", "note": "The ordering customer name in field 50 does not match the account"}, {"kind": "step", "title": "Screening and reconciliation flag the name", "note": "A mismatched name looks like a different party to screening"}, {"kind": "step", "title": "MT103 returned to originator bank", "note": "The MT103 can be returned to the originator bank"}, {"kind": "step", "title": "Name corrected and payment resent", "note": "The fix is to correct the name and resend"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103"], "failure_category": "message mismatch", "resolution": "return"}, {"id": "PAI-C053", "seq": 490, "module": "Advanced", "source": "Article and reader comments", "title": "SEPA dispute, cancellation and recall: three acts", "explain": "In SEPA, a dispute, a cancellation, and a recall are three different actions, and the question is how each one works and which message carries it. A recall is requested with a camt.056 and answered with a camt.029, a return is made with a pacs.004, and a cancellation stops a payment before it settles. The three are often confused because they all undo a payment, but they apply at different stages and they use different messages.", "takeaway": "The three are often confused because they all undo a payment, but they apply at different stages and they use different messages.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "decision", "title": "Payment already settled or not", "note": "The three actions apply at different stages of the payment"}, {"kind": "step", "title": "Cancellation stops a payment before settlement", "note": "A cancellation stops a payment before it settles"}, {"kind": "step", "title": "Recall requested with camt.056", "note": "A recall is requested with a camt.056 and answered with a camt.029"}, {"kind": "step", "title": "Return made with pacs.004", "note": "A return is made with a pacs.004"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "camt.029", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "PAI-C073", "seq": 493, "module": "Advanced", "source": "Article and reader comments", "title": "Five returns over a wrong field 57A", "explain": "A payment sent to Australia was returned five times over six weeks, each time with the note that the beneficiary bank's SWIFT code had to appear in field 57A. The code had been placed in field 72 and in field 52A, where the receiving bank could see it, but that did not satisfy the validation: field 57A is the field the receiving bank reads to find the account with institution. The beneficiary bank had also been taken over and its SWIFT code had changed, so the sender had to use the new code in field 57A before the payment could be applied.", "takeaway": "The beneficiary bank had also been taken over and its SWIFT code had changed, so the sender had to use the new code in field 57A before the payment could be applied.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment sent to Australia", "note": "A payment sent to Australia was returned five times over six weeks"}, {"kind": "step", "title": "SWIFT code placed in field 72 and 52A", "note": "The beneficiary bank's SWIFT code was placed in field 72 and in field 52A"}, {"kind": "step", "title": "Receiving bank requires code in 57A", "note": "Field 57A is the field the receiving bank reads to find the account with institution"}, {"kind": "step", "title": "Beneficiary bank taken over, code changed", "note": "The beneficiary bank had been taken over and its SWIFT code had changed"}, {"kind": "step", "title": "New code used in field 57A", "note": "The sender had to use the new code in field 57A before the payment could be applied"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "invalid beneficiary data", "resolution": "return"}, {"id": "SCN-06", "seq": 506, "module": "Advanced", "source": "Public post", "title": "Credited already? The recall is only a request", "explain": "Once the beneficiary bank has credited the customer, the sender bank has no power to command the money back; it can only request it. The sender sends a camt.056 cancellation request, the beneficiary bank tests whether the funds are still available and answers with a camt.029, and a pacs.004 moves the money only on acceptance. A rejection leaves the sender with a commercial claim outside the payment rails, so the camt.056 must go out fast, while the funds are still there.", "takeaway": "A rejection leaves the sender with a commercial claim outside the payment rails, so the camt.056 must go out fast, while the funds are still there.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Sender bank requests the money back.", "title": "Issue the camt.056"}, {"kind": "step", "note": "Tests availability and any fraud concern.", "title": "Beneficiary bank tests the funds"}, {"kind": "decision", "note": "Acceptance moves the money; rejection leaves a commercial claim.", "title": "The camt.029 answer"}, {"kind": "step", "note": "Money moves back only on acceptance.", "title": "pacs.004 follows acceptance"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "camt.029", "pacs.004"], "resolution": "return"}, {"id": "SCN-22", "seq": 509, "module": "Advanced", "source": "Public post", "title": "Duplicate payouts: 90 percent recovered", "explain": "Duplicates demand containment before diagnosis: freeze the retry and payout batch so no more duplicates are created while the team investigates. Then identify the full population by reference or idempotency key, reverse the duplicates systematically, and track recovery until every case is closed. The cause here was a retry firing twice after a timeout through an idempotency gap, and the permanent fix is idempotency keys on every payout plus real-time reconciliation flagging double credits.", "takeaway": "The cause here was a retry firing twice after a timeout through an idempotency gap, and the permanent fix is idempotency keys on every payout plus real-time reconciliation flagging double credits.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Contain the incident before investigating.", "title": "Freeze the retry and payout batch"}, {"kind": "step", "note": "Match on reference or idempotency key.", "title": "Identify the full population"}, {"kind": "step", "note": "Reverse systematically; track recovery to closure.", "title": "Reverse the duplicates"}, {"kind": "step", "note": "Retry fired twice after a timeout, through an idempotency gap.", "title": "Fix the idempotency gap"}, {"kind": "step", "note": "Failure-injection test every retry-logic change first.", "title": "Gate the release"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "duplicate payment", "resolution": "return"}, {"id": "SCN-30", "seq": 511, "module": "Advanced", "source": "Public post", "title": "125,000 pounds, no trace: prove first", "explain": "A 125,000 pound international payment left the sender and never arrived, with no rejection, no return and no confirmation. Before acting, prove what happened: pull the UETR, check the tracker for the last confirmed hop, and ask whether the money sits with an intermediary, in a compliance review, or stuck in a queue. Never re-send until the original is accounted for, because a duplicate is worse than a delay, and keep both sender and expectant beneficiary updated.", "takeaway": "Never re-send until the original is accounted for, because a duplicate is worse than a delay, and keep both sender and expectant beneficiary updated.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Failed outright, or not yet proven.", "title": "Prove what happened first"}, {"kind": "step", "note": "Tracker shows the last confirmed hop.", "title": "Pull the UETR and last hop"}, {"kind": "step", "note": "Intermediary, compliance review or queue.", "title": "Ask the three questions"}, {"kind": "step", "note": "Structured references, never a vague question.", "title": "Contact the intermediary"}, {"kind": "step", "note": "Uncertainty is when communication matters most.", "title": "Update both sides"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D06 Cross-border payments", "messages": [], "resolution": "investigate"}, {"id": "JEB-E02", "seq": 519, "module": "Advanced", "source": "Public post", "title": "A pacs.004 does not decide the debtor credit by itself", "explain": "A pacs.004 only says a payment was returned, so crediting the debtor on receipt is an event-to-action shortcut that skips the questions that matter: what the return is for, who initiated it, whether the original was a pacs.008 or a pacs.009, why it was returned, and what happened to the original payment. When the pacs.004 relates to a rejected pacs.009 cover payment, the related pacs.008 cannot be assumed rejected, since the cover may have failed for lack of correspondent funds, wrong beneficiary correspondent or bank details, or a cover rejection for incorrect bank information. The correct procedure investigates the reason, establishes the status of the pacs.008 and any open exception, and only then chooses between re-initiating the pacs.009, returning funds to the debtor, re-initiating the pacs.008, or another defined action.", "takeaway": "The correct procedure investigates the reason, establishes the status of the pacs.008 and any open exception, and only then chooses between re-initiating the pacs.009, returning funds to the debtor, re-initiating the pacs.008, or another defined action.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "A return is received; the reason and the original transaction are not yet known.", "title": "pacs.004 arrives"}, {"kind": "decision", "note": "Identify which transaction the return relates to and who initiated it.", "title": "Original pacs.008 or pacs.009?"}, {"kind": "step", "note": "Establish why the cover was rejected and the current status of the pacs.008.", "title": "Investigate the rejection"}, {"kind": "step", "note": "Re-initiate the cover, return funds, re-initiate the instruction, or take another defined action.", "title": "Choose the business outcome"}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.004", "pacs.008", "pacs.009"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "RUN7-006", "seq": 529, "module": "Advanced", "source": "Article and reader comments", "title": "Cancelling SEPA payments: the right message each time", "explain": "In the SEPA Credit Transfer scheme camt.056 is the message used to request cancellation of an SCT transaction. For SDD Core reversals the creditor bank sends pacs.007 against funds mistakenly debited. Corporations may also send camt.055 through their bank to cancel a pain.008: an unexecuted transaction is cancelled, while an executed one is reversed by the bank with pacs.007 instead.", "takeaway": "Corporations may also send camt.055 through their bank to cancel a pain.008: an unexecuted transaction is cancelled, while an executed one is reversed by the bank with pacs.007 instead.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "camt.056 cancels an SCT transaction", "note": "In SEPA, the camt.056 is supported in the SEPA Credit Transfer scheme as a request to cancel an SCT transaction."}, {"kind": "step", "title": "pacs.007 reverses a mistaken SDD debit", "note": "In SDD Core, the creditor bank sends a pacs.007 to reverse funds that were mistakenly debited."}, {"kind": "decision", "title": "Has the pain.008 transaction been executed?", "note": "Corporations send a camt.055 to cancel a pain.008; the outcome depends on whether it has been executed yet."}, {"kind": "step", "title": "Not executed: it is cancelled", "note": "If the transaction has not been executed yet it is cancelled."}, {"kind": "step", "title": "Executed: pacs.007 reverses the funds", "note": "If it has been executed, the bank sends a pacs.007 to reverse the funds instead."}]}}, "level": "advanced", "stage": 3, "stage_name": "Operational exceptions", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "camt.055", "pacs.007", "pain.008"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "INS-136", "seq": 142, "module": "Core", "source": "Public post", "title": "Euro leg fast, non-euro leg on its own clock", "explain": "In an instant cross-border payment from Europe, the euro leg inside SEPA can complete in seconds, but the non-euro leg outside SEPA follows different rules and a different timeline. The customer sees the euro leg finish and expects the whole payment to be done, then nothing happens for hours while the other leg is processed. The two legs must be explained separately, with their own coverage and responsibilities, because a single status cannot describe two different journeys.", "takeaway": "The two legs must be explained separately, with their own coverage and responsibilities, because a single status cannot describe two different journeys.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Euro leg inside SEPA", "note": "Euro leg inside SEPA can complete in seconds"}, {"kind": "step", "title": "Non-euro leg outside SEPA", "note": "Non-euro leg outside SEPA follows different rules and timeline"}, {"kind": "step", "title": "Customer sees euro leg finish", "note": "Customer sees the euro leg finish and expects the whole payment done"}, {"kind": "step", "title": "Hours pass, nothing happens", "note": "Nothing happens for hours while the other leg is processed"}, {"kind": "step", "title": "Explain legs separately", "note": "Two legs must be explained separately, with own coverage and duties"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": []}, {"id": "INS-147", "seq": 148, "module": "Core", "source": "Public post", "title": "One payment, three different statuses", "explain": "When a cross-border payment passes through several payment service providers, each one can show a different status: the app says pending, the engine says processed, and the ledger has no posting. The customer and the contact centre cannot tell whether the money has left, arrived, or is lost. The fix is consistent status meanings, a status enquiry path and clear customer communication at every step, because a payment whose state cannot be stated cannot be managed.", "takeaway": "The fix is consistent status meanings, a status enquiry path and clear customer communication at every step, because a payment whose state cannot be stated cannot be managed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment passes several PSPs", "note": "Cross-border payment passes through several payment service providers"}, {"kind": "step", "title": "App says pending", "note": "App says pending"}, {"kind": "step", "title": "Engine says processed", "note": "Engine says processed"}, {"kind": "step", "title": "Ledger has no posting", "note": "Ledger has no posting"}, {"kind": "step", "title": "Customer cannot tell", "note": "Customer and contact centre cannot tell whether money left, arrived, or is lost"}, {"kind": "step", "title": "Fix with consistent statuses", "note": "Fix is consistent status meanings, a status enquiry path, clear communication"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "INS-170", "seq": 150, "module": "Core", "source": "Public post", "title": "Pending on screen, unpaid at the supplier", "explain": "A payment that travels through a bank, a correspondent and the supplier bank shows only one status on the customer screen, usually Pending, while the supplier says it has not been paid. The clerk cannot say where the money is because the status does not reflect the intermediary steps. Customer-facing statuses must stay accurate while the underlying processing is still pending, so the customer is not left guessing.", "takeaway": "Customer-facing statuses must stay accurate while the underlying processing is still pending, so the customer is not left guessing.", "visual": {"type": "diagram", "diagram": {"centre": "Customer visibility across systems", "parts": [{"label": "Bank, correspondent, supplier", "note": "Payment travels through a bank, a correspondent, and the supplier bank"}, {"label": "One status on screen", "note": "Customer screen shows only one status, usually Pending"}, {"label": "Supplier says not paid", "note": "Supplier says it has not been paid"}, {"label": "Clerk cannot say where it is", "note": "Clerk cannot say where the money is"}, {"label": "Status hides middle steps", "note": "Status does not reflect the intermediary steps"}, {"label": "Accurate statuses needed", "note": "Customer-facing statuses must stay accurate while processing is pending"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "SCN-01", "seq": 155, "module": "Core", "source": "Public post", "title": "One payment, two amounts", "explain": "The same cross-border payment can show a different amount at different stages, because the payment engine and the clearing layer apply different rules. The engine validates the instruction and converts it to ISO 20022, while the clearing layer settles a different amount after fees, charges, or an FX conversion at a shifted value date. The investigation starts by comparing the instructed amount in the pacs.008 against what clearing actually settled, then finding which rule changed it, because the amount gap always has a rule behind it.", "takeaway": "The investigation starts by comparing the instructed amount in the pacs.008 against what clearing actually settled, then finding which rule changed it, because the amount gap always has a rule behind it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Engine validates instruction", "note": "Engine validates the instruction and converts it to ISO 20022"}, {"kind": "step", "title": "Clearing settles a different amount", "note": "Clearing layer settles a different amount after fees, charges, or FX conversion"}, {"kind": "step", "title": "Value date shifts", "note": "FX conversion can apply at a shifted value date"}, {"kind": "step", "title": "Compare instructed amount", "note": "Compare the instructed amount in pacs.008 against what clearing settled"}, {"kind": "decision", "title": "Which rule changed it?", "note": "Find which rule changed the amount"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008"], "failure_category": "message mismatch", "resolution": "investigate"}, {"id": "SCN-02", "seq": 156, "module": "Core", "source": "Public post", "title": "Nostro feed failure, stale Treasury funding view", "explain": "A payment can settle correctly while the Nostro ledger feed fails, leaving Treasury to fund from a stale screen. In this case the real funding requirement moved from 2 million to 5 million dollars before cut-off, and nothing alerted Treasury. The payment settled, but the bank was making funding decisions from outdated data, which is a critical operational risk even though no payment failed.", "takeaway": "The payment settled, but the bank was making funding decisions from outdated data, which is a critical operational risk even though no payment failed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment settles correctly", "note": "Payment settles correctly"}, {"kind": "step", "title": "Nostro ledger feed fails", "note": "Nostro ledger feed fails"}, {"kind": "step", "title": "Treasury funds from stale screen", "note": "Treasury funds from a stale screen"}, {"kind": "step", "title": "Funding need moves to 5 million", "note": "Real funding requirement moved from 2 million to 5 million dollars before cut-off"}, {"kind": "step", "title": "Nothing alerts Treasury", "note": "Nothing alerted Treasury"}, {"kind": "step", "title": "Decisions from outdated data", "note": "Bank makes funding decisions from outdated data, a critical operational risk"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "liquidity shortfall", "resolution": "repair"}, {"id": "JEB-B07", "seq": 167, "module": "Core", "source": "Public post", "title": "One statement line, many entries: reconcile the batch", "explain": "Settlement happens in batches, so a single statement line can stand for many ledger entries sharing one batch reference. Reconciliation must collect the entries by batch reference and reconcile that group as one against the statement line, rather than matching a single entry. If one entry is missing, the whole group fails and a temporary GL entry may be raised while investigating, so the engine must preserve the batch reference linkage across the items, and the point is to grasp the reason the batch exists, not merely how it matches.", "takeaway": "If one entry is missing, the whole group fails and a temporary GL entry may be raised while investigating, so the engine must preserve the batch reference linkage across the items, and the point is to grasp the reason the batch exists, not merely how it matches.", "visual": {"type": "diagram", "diagram": {"centre": "Reconcile the batch, not one entry", "parts": [{"label": "One statement line, many entries", "note": "One statement line can represent many ledger entries"}, {"label": "Common batch reference", "note": "The entries share a common batch reference"}, {"label": "Group and reconcile together", "note": "Collect the entries by batch reference and reconcile the group as one"}, {"label": "One missing entry breaks the group", "note": "If one entry is missing, the whole group fails"}, {"label": "Temporary GL entry", "note": "A temporary GL entry may be raised while investigating"}, {"label": "Keep the reference linked", "note": "The engine must preserve the batch reference linkage across the items"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "JEB-C02", "seq": 171, "module": "Core", "source": "Public post", "title": "Optional in the message, mandatory for the flow", "explain": "In a four-bank cover payment, Bank A sends pacs.008 to Bank B and a pacs.009 cover to intermediary Bank C, which must link the cover to the customer payment using the same UETR and related remittance reference. The pacs.009 RltdRmtInf field carries that link, and although it is optional in the message, the intermediary cannot reconcile the cover without it. Optional or mandatory is a property of the message, not of the process, so a field marked optional can still be required to make the payment work, and the message flow and the field status must be handled as two separate things.", "takeaway": "Optional or mandatory is a property of the message, not of the process, so a field marked optional can still be required to make the payment work, and the message flow and the field status must be handled as two separate things.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The customer payment goes directly to the beneficiary bank", "title": "Bank A sends pacs.008 to Bank B"}, {"kind": "step", "note": "The cover goes to the intermediary bank", "title": "Bank A sends pacs.009 cover to Bank C"}, {"kind": "step", "note": "Bank C must link the cover using the same UETR and remittance reference", "title": "Link cover with UETR and reference"}, {"kind": "step", "note": "The pacs.009 RltdRmtInf field carries that link", "title": "RltdRmtInf carries the link"}, {"kind": "decision", "note": "The field is optional in the message, yet the intermediary cannot reconcile without it", "title": "Optional in the message?"}, {"kind": "step", "note": "Optional or mandatory is a property of the message, not of the process", "title": "Treat flow and field status separately"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008", "pacs.009"]}, {"id": "INS-004", "seq": 182, "module": "Core", "source": "Public post", "title": "Card settlement and reconciliation control", "explain": "After clearing, the settlement position is the net amount each bank owes or is owed, and the ledger postings must match that position exactly. Reconciliation compares clearing records, settlement positions and ledger postings, and any break between them is investigated rather than written off. A settlement that does not reconcile means money is unaccounted for, which is a control failure even if the customer-facing payment appeared to succeed.", "takeaway": "A settlement that does not reconcile means money is unaccounted for, which is a control failure even if the customer-facing payment appeared to succeed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Clearing completes", "note": "The settlement position is the net amount each bank owes."}, {"kind": "step", "title": "Compare the records", "note": "Clearing records, settlement positions and ledger postings."}, {"kind": "decision", "title": "Do the records agree", "note": "Any break between them is investigated."}, {"kind": "step", "title": "Investigate the break", "note": "A break is investigated rather than written off."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "INS-034", "seq": 186, "module": "Core", "source": "Public post", "title": "Approved loan, failed disbursement: tracing the break", "explain": "A loan can be approved and still fail to disburse, so trace the path from approval through account validation, the disbursement instruction, the ledger posting and the customer communication, because the break can sit at any of these points. A valid approval with a wrong account, a failed instruction or a missing ledger posting all look the same to the customer, who simply sees that the money has not arrived. Check each stage in order rather than assuming the approval was the problem.", "takeaway": "Check each stage in order rather than assuming the approval was the problem.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Approval", "note": "The loan is approved."}, {"kind": "step", "title": "Account validation", "note": "The account details are validated."}, {"kind": "step", "title": "Disbursement instruction", "note": "The instruction to release funds is sent."}, {"kind": "step", "title": "Ledger posting", "note": "The posting is recorded in the ledger."}, {"kind": "step", "title": "Customer communication", "note": "The customer is told whether the money arrived."}, {"kind": "step", "title": "Check each stage in order", "note": "The break can sit at any stage, so check them all."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "PAI-C018", "seq": 240, "module": "Core", "source": "Article and reader comments", "title": "Cover timing: MT103 first, funds later", "explain": "In a cover payment the MT103 and the MT202 COV travel separately, so the MT103 can reach the beneficiary bank before the funds leg arrives. The beneficiary bank must then hold the instruction and wait for the cover, because it cannot credit the beneficiary until the funds have settled. This timing gap is a normal feature of the cover method, not an error, though it is also the moment when an amount or reference mismatch is most likely to surface.", "takeaway": "This timing gap is a normal feature of the cover method, not an error, though it is also the moment when an amount or reference mismatch is most likely to surface.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 reaches beneficiary bank first", "note": "The information leg can arrive ahead of the funds leg"}, {"kind": "step", "title": "Beneficiary bank holds the instruction", "note": "It holds the instruction and waits for the cover"}, {"kind": "step", "title": "Cover arrives and funds settle", "note": "No credit to the beneficiary until the funds have settled"}, {"kind": "decision", "title": "Check amount and reference match", "note": "A mismatch is most likely to surface at this moment"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202"], "failure_category": "message mismatch"}, {"id": "PAI-C019", "seq": 241, "module": "Core", "source": "Article and reader comments", "title": "Spotting the MT202 COV at the beneficiary bank", "explain": "When an MT202 COV reaches the beneficiary bank, the bank must recognise that its purpose is to cover a specific MT103, and the link is the reference and the fields that tie the two messages together. Without that link the cover looks like an ordinary bank-to-bank transfer, and the beneficiary bank cannot match it to the customer payment it is meant to settle. The reference is therefore the bridge between the information leg and the funds leg.", "takeaway": "The reference is therefore the bridge between the information leg and the funds leg.", "visual": {"type": "diagram", "diagram": {"centre": "Recognising an MT202 COV", "parts": [{"label": "Purpose is to cover a specific MT103", "note": "The cover must be recognised as settling a named MT103"}, {"label": "Reference links the two messages", "note": "Reference and fields tie the two messages together"}, {"label": "Without the link, just a transfer", "note": "Without the link the cover looks like an ordinary transfer"}, {"label": "Reference is the bridge", "note": "The reference bridges the information leg and the funds leg"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D04 Messaging and standards", "messages": ["MT202", "MT103"]}, {"id": "PAI-C025", "seq": 247, "module": "Core", "source": "Article and reader comments", "title": "Two deductions, one final credit: fields 71A, 71F", "explain": "When two intermediary banks each deduct a charge, the beneficiary bank works out the final credit from fields 71A and 71F of the MT103. Field 71A states who bears the charges, and field 71F states the amount of each charge deducted, so the credit can be reconciled against the amount the ordering customer sent. Without those fields the beneficiary cannot reconcile the credit against the amount sent.", "takeaway": "Without those fields the beneficiary cannot reconcile the credit against the amount sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Two intermediaries each deduct a charge", "note": "Two intermediary banks each take a charge"}, {"kind": "step", "title": "Field 71A states who bears charges", "note": "Field 71A states who bears the charges"}, {"kind": "step", "title": "Field 71F states each charge deducted", "note": "Field 71F states the amount of each charge deducted"}, {"kind": "step", "title": "Beneficiary bank works out final credit", "note": "The beneficiary bank derives the final credit from those fields"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103"], "failure_category": "charge deduction"}, {"id": "PAI-C036", "seq": 258, "module": "Core", "source": "Article and reader comments", "title": "When the MT103 and the MT202 COV disagree", "explain": "In a cover payment the MT103 and the MT202 COV must agree on amount and on the references that link them, and a mismatch between the two creates an exception that stops settlement. The discrepancy can be a different amount, a missing reference, or details that do not line up, and the bank must investigate before it credits the beneficiary. A mismatch is therefore not a minor data error; it is a break in the link between the information leg and the funds leg.", "takeaway": "A mismatch is therefore not a minor data error; it is a break in the link between the information leg and the funds leg.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 and MT202 COV must agree", "note": "They must agree on amount and on the linking references"}, {"kind": "decision", "title": "Check amount and references match", "note": "A different amount, a missing reference or misaligned details stop settlement"}, {"kind": "step", "title": "Bank investigates before crediting", "note": "The bank must investigate before crediting the beneficiary"}, {"kind": "step", "title": "Mismatch is a break in the link", "note": "The mismatch breaks the link between the two legs"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT103", "MT202"], "failure_category": "message mismatch", "resolution": "investigate"}, {"id": "PAI-C062", "seq": 270, "module": "Core", "source": "Article and reader comments", "title": "Sequence B of the MT202 COV must mirror the MT103", "explain": "In sequence B of an MT202 COV, only the ordering and beneficiary customer information in fields 50a and 59a is mandatory, and the other fields are optional. When the bank does provide a field such as field 72 or field 59, it must match the same field in the MT103 exactly, or the field must be left empty. Some banks reject a cover whose sequence B does not match the announcement, so a mismatch stops the funds even when the amounts agree.", "takeaway": "Some banks reject a cover whose sequence B does not match the announcement, so a mismatch stops the funds even when the amounts agree.", "visual": {"type": "diagram", "diagram": {"centre": "Sequence B of the MT202 COV", "parts": [{"label": "Only fields 50a and 59a are mandatory", "note": "Only the ordering and beneficiary customer information in fields 50a and 59a is mandatory"}, {"label": "Other fields are optional", "note": "The other fields in sequence B are optional"}, {"label": "Provided fields must match the MT103", "note": "A field such as 72 or 59, if given, must match the MT103 exactly"}, {"label": "Or the field must be left empty", "note": "If it cannot match, the field must be left empty"}, {"label": "Some banks reject a mismatched cover", "note": "Some banks reject a cover whose sequence B does not match the announcement"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["MT202", "MT103"], "failure_category": "message mismatch", "resolution": "reject"}, {"id": "PAI-C075", "seq": 279, "module": "Core", "source": "Article and reader comments", "title": "The charges equation: 32A, 33B, 71G, 71F", "explain": "Field 32A is the amount that settles between banks, field 33B is the amount the ordering customer instructed, field 71G is the receiver's charges prepaid by the sender, and field 71F is each sender's charge deducted along the way. The relationship always holds: 32A equals 33B plus 71G minus all the 71F charges. Field 71A itself is set by the bank that generates the MT103 and cannot be changed by later banks, which can only add a 71F when they take a charge.", "takeaway": "Field 71A itself is set by the bank that generates the MT103 and cannot be changed by later banks, which can only add a 71F when they take a charge.", "visual": {"type": "diagram", "diagram": {"centre": "32A equals 33B plus 71G minus 71F", "parts": [{"label": "32A", "note": "Amount that settles between banks"}, {"label": "33B", "note": "Amount the ordering customer instructed"}, {"label": "71G", "note": "Receiver charges prepaid by the sender"}, {"label": "71F", "note": "Each sender charge deducted along the way"}, {"label": "71A", "note": "Set by the MT103 bank, later banks can only add a 71F"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D14 Business analysis and professional practice", "messages": ["MT103"], "failure_category": "charge deduction"}, {"id": "PAI-C089", "seq": 287, "module": "Core", "source": "Article and reader comments", "title": "The announcement must name the cover's source", "explain": "In a cover payment the MT103 announcement should state in field 53 which correspondent will send the cover, so the beneficiary bank knows where the funds will come from. When the cover arrives from a bank the announcement never mentioned, the beneficiary bank cannot match the two legs and will not credit the beneficiary. The fix sits with the sender, whose bank must correct the announcement so the two legs agree.", "takeaway": "The fix sits with the sender, whose bank must correct the announcement so the two legs agree.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 announcement states field 53", "note": "The announcement should state in field 53 which correspondent will send the cover"}, {"kind": "step", "title": "Beneficiary bank knows where funds come from", "note": "The beneficiary bank knows where the funds will come from"}, {"kind": "step", "title": "Cover arrives from an unmentioned bank", "note": "When the cover comes from an unmentioned bank, the legs cannot be matched"}, {"kind": "step", "title": "Beneficiary bank will not credit", "note": "The beneficiary bank cannot match the two legs and will not credit the beneficiary"}, {"kind": "step", "title": "Sender corrects the announcement", "note": "The sender's bank must correct the announcement so the two legs agree"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": ["MT103"], "resolution": "repair"}, {"id": "RUN3-002", "seq": 298, "module": "Core", "source": "Article and reader comments", "title": "pacs.002: a status report with no entry of its own", "explain": "A pacs.002 reports the outcome of a pacs.008; it moves no money, so it normally needs no accounting entry of its own. When it carries a negative acknowledgement, the postings made for the original payment are undone exactly, debit and credit reversed, restoring the books to their pre-payment position. Booking the status report itself as a debit or credit would count the same payment twice.", "takeaway": "Booking the status report itself as a debit or credit would count the same payment twice.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.002, a status report only", "parts": [{"label": "No entry of its own", "note": "It reports an outcome; it moves no money, so no posting arises from it."}, {"label": "Negative acknowledgement", "note": "A negative outcome triggers an exact reversal of the earlier postings."}, {"label": "Books restored", "note": "Reversal returns the books to their position before the payment was attempted."}, {"label": "No double count", "note": "Posting the report itself would count the same payment twice."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002"], "failure_category": "reconciliation break", "resolution": "return"}, {"id": "RUN4-010", "seq": 310, "module": "Core", "source": "Article and reader comments", "title": "Mirror nostro moves transaction by transaction", "explain": "Every movement on the real nostro is mirrored one transaction at a time, never in a daily batch. When the nostro is credited, the correspondent advises the holder, for example with an MT910 or MT950, and the mirror is updated from that advice. When the bank instructs its correspondent to debit the nostro, the mirror is updated at once, and the two entries always carry the same amount with opposite signs.", "takeaway": "When the bank instructs its correspondent to debit the nostro, the mirror is updated at once, and the two entries always carry the same amount with opposite signs.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Movement hits the real nostro", "note": "Each movement is reflected on the mirror one transaction at a time."}, {"kind": "step", "title": "Correspondent advises the holder", "note": "A credit triggers advice, for example an MT910 or MT950."}, {"kind": "step", "title": "Mirror updated from the advice", "note": "The holder updates the mirror from the advice received."}, {"kind": "step", "title": "Debit instructed, mirror updated at once", "note": "Ordering a debit updates the mirror immediately."}, {"kind": "step", "title": "Same amount, opposite signs", "note": "Both entries carry the same amount with opposite signs."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": ["MT910", "MT950"], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "RUN4-011", "seq": 311, "module": "Core", "source": "Article and reader comments", "title": "Why the mirror nostro always shows the opposite sign", "explain": "A debit on the real nostro appears as a credit on the mirror, and a credit on the real account appears as a debit on the mirror, always for the same amount. The mirror reflects the real account, so the two sides sit opposite by design rather than by coincidence. Reading the mirror balance and its movements therefore tells a bank exactly what the real account should show.", "takeaway": "Reading the mirror balance and its movements therefore tells a bank exactly what the real account should show.", "visual": {"type": "diagram", "diagram": {"centre": "Mirror nostro: opposite by design", "parts": [{"label": "Real debit, mirror credit", "note": "A debit on the real nostro appears as a credit on the mirror."}, {"label": "Real credit, mirror debit", "note": "A credit on the real account appears as a debit on the mirror."}, {"label": "Same amount", "note": "Both sides always carry the same amount."}, {"label": "Opposite by design", "note": "The mirror reflects the real account, so the signs sit opposite."}, {"label": "Mirror reveals the real account", "note": "The mirror balance shows what the real account should hold."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "message mismatch"}, {"id": "SCN-21", "seq": 349, "module": "Core", "source": "Public post", "title": "Small breaks, one $2M surprise", "explain": "Small uncleared items accumulated for months, looking harmless, until rising volumes exposed a 2 million dollar discrepancy just before an audit. The cause was timing: two systems derived the transaction value date with different logic. Aligning that logic cleared 80 percent of breaks automatically, which is the lesson to keep: fix the process that creates the break, never optimise the manual workaround, and run reconciliation as an early-warning system.", "takeaway": "Aligning that logic cleared 80 percent of breaks automatically, which is the lesson to keep: fix the process that creates the break, never optimise the manual workaround, and run reconciliation as an early-warning system.", "visual": {"type": "diagram", "diagram": {"centre": "Breaks that compounded unnoticed", "parts": [{"label": "Mismatched value dates", "note": "Each system derived the date its own way."}, {"label": "Small breaks, compounding", "note": "Small daily differences compounded for months."}, {"label": "Align the logic", "note": "Aligned derivation cleared 80 percent of breaks."}, {"label": "Watch break aging", "note": "Spot drift early, not at the audit."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "repair"}, {"id": "SCN-29", "seq": 354, "module": "Core", "source": "Public post", "title": "The parameter everyone assumed was filled", "explain": "One unchecked assumption can survive QA, staging and a small rollout, then fail at full volume: a parameter assumed to always return a value sometimes came back empty. Partner API calls failed, reconciliation mismatched, and rebuilding partner trust took longer than the three-hour fix. Validate every input, above all the ones assumed always present, and add contract tests with the partner covering empty and null variants of every field.", "takeaway": "Validate every input, above all the ones assumed always present, and add contract tests with the partner covering empty and null variants of every field.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Edge case hid until full volume.", "title": "Small rollout goes clean"}, {"kind": "step", "note": "Assumed-populated parameter came back empty.", "title": "Full volume exposes the gap"}, {"kind": "step", "note": "Partner API failures, reconciliation mismatches.", "title": "Find the empty parameter"}, {"kind": "step", "note": "Repair the code, then the assumption.", "title": "Fix the code and the assumption"}, {"kind": "step", "note": "Empty and null variants of every field.", "title": "Add the contract tests"}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D10 APIs and integration", "messages": [], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "SCN-35", "seq": 357, "module": "Core", "source": "Public post", "title": "The cut-off moved; nobody told the fintech", "explain": "Code can be perfect and dashboards green while transactions fail, because the bank moved its transaction cut-off time and the fintech kept sending on the old settlement window. Requests were accepted, then processed in a later cycle, breaking user expectations without a single error. Most production incidents in finance are coordination failures of this kind, cut-off changes, holiday calendars, or report timings that moved without notice, so keep cut-off and calendar configuration synced with every bank partner.", "takeaway": "Most production incidents in finance are coordination failures of this kind, cut-off changes, holiday calendars, or report timings that moved without notice, so keep cut-off and calendar configuration synced with every bank partner.", "visual": {"type": "diagram", "diagram": {"centre": "Coordination failure, not a bug", "parts": [{"label": "Cut-off moved", "note": "Transaction cut-off moved without notice."}, {"label": "Old window kept", "note": "Fintech kept sending on the old time."}, {"label": "Silent late settlement", "note": "Accepted, settled in a later cycle."}, {"label": "Partner change process", "note": "Sync cut-offs and calendars across every partner."}]}}, "level": "core", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "cut-off missed", "resolution": "repair"}, {"id": "INS-151", "seq": 432, "module": "Advanced", "source": "Public post", "title": "Richer data only works if it survives the chain", "explain": "Structured purpose and remittance data helps compliance screening and lets the beneficiary reconcile the payment against the right invoice. But the data is only useful if it is captured correctly, mapped consistently, and consumed by the downstream systems that need it. Poor data quality in one system becomes a compliance and reconciliation problem in the next, so data quality has to be owned end to end.", "takeaway": "Poor data quality in one system becomes a compliance and reconciliation problem in the next, so data quality has to be owned end to end.", "visual": {"type": "diagram", "diagram": {"centre": "Richer data for AML and reconciliation", "parts": [{"label": "Purpose data", "note": "Structured purpose data helps compliance screening"}, {"label": "Remittance data", "note": "Structured remittance data lets beneficiary reconcile against the right invoice"}, {"label": "Captured correctly", "note": "Data is only useful if it is captured correctly"}, {"label": "Mapped consistently", "note": "Data is only useful if it is mapped consistently"}, {"label": "Consumed downstream", "note": "Data is only useful if consumed by the downstream systems that need it"}, {"label": "Poor quality spreads", "note": "Poor data quality in one system becomes a compliance and reconciliation problem"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "sanctions or fraud block", "resolution": "repair"}, {"id": "JEB-A04", "seq": 437, "module": "Advanced", "source": "Public post", "title": "PMNE: prove the payment state before acting on Nostro", "explain": "A Payment Missing a Nostro Entry arises when a SAR 250,000 payment leaves the customer account and is sent onward, yet the corresponding Nostro debit never posts, so the statement shows no debit even though the beneficiary may already stand credited. The governing discipline is evidence before action: the bank proves the payment state with pacs.002, camt.052 or camt.053, or pacs.028 where no notification arrived. Once proved, the correspondent bank posts the Nostro debit, and the payment must never be re-effected, because a second execution would duplicate the payment and break the Nostro at reconciliation.", "takeaway": "Once proved, the correspondent bank posts the Nostro debit, and the payment must never be re-effected, because a second execution would duplicate the payment and break the Nostro at reconciliation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Customer debited and confirmation sent, yet the statement shows no debit", "title": "SAR 250,000 sent, no Nostro debit"}, {"kind": "step", "note": "Confirm with pacs.002, camt.052 or camt.053, or pacs.028 if nothing arrived", "title": "Prove the payment state first"}, {"kind": "decision", "note": "Evidence must precede any action on the missing Nostro debit", "title": "State proved with evidence?"}, {"kind": "step", "note": "Once proved, the correspondent bank posts the missing Nostro debit", "title": "Correspondent posts the debit"}, {"kind": "step", "note": "Re-effecting duplicates the payment and breaks the Nostro at reconciliation", "title": "Never re-effect the payment"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "camt.052", "camt.053", "pacs.028"], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "JEB-A10", "seq": 439, "module": "Advanced", "source": "Public post", "title": "Back valuation: value date drives interest, not booking", "explain": "Back valuation is a mismatch between value date and booking date, and it matters because interest runs from the value date, not the booking date, as a USD 10 million payment delayed by two days shows. In a single-sided case the mismatch sits on one side, for example the customer leg is credited on Monday at a Monday value date, while the Nostro leg is booked later at that same value date, while in a double-sided case it sits on both sides. The working sequence is to confirm the value date first, establish whether the mismatch is single or double-sided, then assess the impact on interest, liquidity and reconciliation.", "takeaway": "The working sequence is to confirm the value date first, establish whether the mismatch is single or double-sided, then assess the impact on interest, liquidity and reconciliation.", "visual": {"type": "diagram", "diagram": {"centre": "Value date drives interest", "parts": [{"label": "Value date vs booking date", "note": "Payment processed with a value date that differs from its booking date"}, {"label": "Single-sided mismatch", "note": "Mismatch sits on one side, for example customer credited Monday, Nostro debited later"}, {"label": "Double-sided mismatch", "note": "Mismatch sits on both sides of the transaction"}, {"label": "Confirm the value date first", "note": "Bank should confirm the value date before anything else"}, {"label": "Impact on interest", "note": "Assess the impact on interest, liquidity and reconciliation"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "message mismatch"}, {"id": "JEB-A15", "seq": 441, "module": "Advanced", "source": "Public post", "title": "INDA or INGA: one code changes who settles the leg", "explain": "The settlement method code on a pacs.008 changes the accounting: INDA means the instructed agent settles this leg, while INGA means the instructing agent has already settled it. MT to MX migration is not a one-to-one field replacement, because information once implied is now explicit and carries business meaning, so an incoming INGA payment wrongly mapped as INDA makes the engine follow the wrong settlement logic and debit the sending bank account again, creating a double posting and a reconciliation break found at day-end. Migration must therefore ask who settles each leg, whether settlement has already happened, and what accounting entries should follow, because a field mapping shows where data goes while business analysis shows what it means.", "takeaway": "Migration must therefore ask who settles each leg, whether settlement has already happened, and what accounting entries should follow, because a field mapping shows where data goes while business analysis shows what it means.", "visual": {"type": "diagram", "diagram": {"centre": "INDA vs INGA settlement code", "parts": [{"label": "INDA: instructed agent settles", "note": "The instructed agent settles this leg of the payment"}, {"label": "INGA: already settled", "note": "The instructing agent has already settled this leg"}, {"label": "Wrong mapping, double posting", "note": "INGA mapped as INDA debits the sending bank again, a double posting"}, {"label": "Reconciliation break at day-end", "note": "The double posting is found as a reconciliation break at day-end"}, {"label": "Who settles each leg?", "note": "Ask who settles each leg and whether settlement has already happened"}, {"label": "Mapping vs meaning", "note": "A field mapping shows where data goes, business analysis shows what it means"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008"], "failure_category": "reconciliation break"}, {"id": "INS-006", "seq": 450, "module": "Advanced", "source": "Public post", "title": "Payment failed but the customer account was debited", "explain": "A customer sends EUR 850 through a mobile app, the app shows the payment as failed, yet the account statement shows the EUR 850 debit. The payment is in an uncertain state: the debit may mean the payment reached the clearing system and is still processing, or it may mean the ledger posted while the payment status update failed. Treat the payment as one transaction with one identity across every system, and use the original instruction ID, end-to-end ID and ledger posting reference to trace it through the channel, the payment engine, the clearing adapter and the core ledger. Do not retry until the true status is known, because a blind retry could create a duplicate payment of EUR 850.", "takeaway": "Do not retry until the true status is known, because a blind retry could create a duplicate payment of EUR 850.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the transaction identity", "note": "One instruction ID, end-to-end ID and ledger reference."}, {"kind": "step", "title": "Trace the channel", "note": "Follow the payment through the channel."}, {"kind": "step", "title": "Trace the payment engine", "note": "Follow it through the payment engine."}, {"kind": "step", "title": "Trace the clearing adapter", "note": "Follow it through the clearing adapter."}, {"kind": "step", "title": "Trace the core ledger", "note": "Follow it through the core ledger."}, {"kind": "decision", "title": "Decide before retrying", "note": "Do not retry until the true status is known."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "INS-032", "seq": 451, "module": "Advanced", "source": "Public post", "title": "Gateway success but core banking posting fails", "explain": "A payment gateway returns a success response for a EUR 40,000 supplier payment and the channel shows the payment as accepted, yet hours later the supplier has not been paid, the finance team finds no debit in the core banking ledger, and the payment engine still shows the payment as in progress. Separate the three facts and find the authoritative source for each: the gateway is authoritative for acceptance of the instruction, the ledger is authoritative for whether the debit posted, and the payment engine state must be reconciled against both. A success response from the gateway does not prove the ledger posted, so the investigation must check the posting rather than trusting the channel message.", "takeaway": "A success response from the gateway does not prove the ledger posted, so the investigation must check the posting rather than trusting the channel message.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Separate the three facts", "note": "Gateway acceptance, ledger debit and engine state."}, {"kind": "step", "title": "Check the gateway", "note": "Authoritative for acceptance of the instruction."}, {"kind": "step", "title": "Check the ledger", "note": "Authoritative for whether the debit posted."}, {"kind": "step", "title": "Reconcile the engine state", "note": "Reconcile the engine against gateway and ledger."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "INS-071", "seq": 452, "module": "Advanced", "source": "Public post", "title": "Payment timeout and uncertain final status", "explain": "A corporate customer submits a supplier payment through the online channel, the screen spins and then times out, and no confirmation appears and no reference is shown. The payment is in an unknown state: it may have been accepted, executed, or never received. Make the timeout path explicit in the product, so the channel shows a pending or unknown state, never a success and never a failure, until the outcome is confirmed. The status enquiry uses the original correlation ID and payment reference to ask the payment engine, then the ledger, then the downstream clearing status, in that order, and only then is a retry safe.", "takeaway": "The status enquiry uses the original correlation ID and payment reference to ask the payment engine, then the ledger, then the downstream clearing status, in that order, and only then is a retry safe.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Show pending or unknown", "note": "Never a success and never a failure until confirmed."}, {"kind": "step", "title": "Ask the payment engine", "note": "Use the original correlation ID and payment reference."}, {"kind": "step", "title": "Ask the ledger", "note": "Check the ledger next, in that order."}, {"kind": "step", "title": "Ask clearing status", "note": "Check downstream clearing status last."}, {"kind": "decision", "title": "Retry only when confirmed", "note": "A retry is safe only once the outcome is known."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "INS-033", "seq": 455, "module": "Advanced", "source": "Public post", "title": "Quantifying a 20,000-transaction reconciliation gap", "explain": "A bank processes 20,000 transactions in a day and the morning reconciliation shows 500 transactions unmatched between the ledger and the clearing reports. Quantify in layers and never present an illustrative figure as a confirmed loss: state the population clearly, 20,000 transactions processed, 500 unmatched, an unmatched rate of 2.5 percent, and an illustrative exposure of INR 40 lakh based on 500 multiplied by an average of INR 8,000. The illustrative figure frames the scale of the problem, but the real exposure is only known once the unmatched transactions are investigated one by one.", "takeaway": "The illustrative figure frames the scale of the problem, but the real exposure is only known once the unmatched transactions are investigated one by one.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Matched transactions", "note": "19,500 of 20,000 transactions matched, 97.5 percent.", "value": 97.5}, {"label": "Unmatched transactions", "note": "500 of 20,000 transactions unmatched, 2.5 percent.", "value": 2.5}], "unit": "%"}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "investigate"}, {"id": "INS-035", "seq": 456, "module": "Advanced", "source": "Public post", "title": "Two banking systems show different balances", "explain": "A customer checks the mobile app and sees a balance of EUR 4,120, then calls the contact centre where the agent's screen shows EUR 3,850. The difference is EUR 270, exactly the amount of a card payment the customer made that morning. Start by defining what each balance means: the ledger balance is the posted balance in the core banking system and it is authoritative for posted funds, while the app balance may include pending or unposted items. The EUR 270 difference is the pending card payment, so the two balances are both accurate for what they represent, and the fix is to explain the difference rather than to change either balance.", "takeaway": "The EUR 270 difference is the pending card payment, so the two balances are both accurate for what they represent, and the fix is to explain the difference rather than to change either balance.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define each balance", "note": "Ledger balance is posted; the app may include pending items."}, {"kind": "step", "title": "Identify the EUR 270 difference", "note": "It is the pending card payment from this morning."}, {"kind": "step", "title": "Explain the difference", "note": "Both balances are accurate for what they represent."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "INS-057", "seq": 457, "module": "Advanced", "source": "Public post", "title": "UI, API and database values differ", "explain": "A cross-border payment complaint shows one amount in the online banking screen, a different amount transmitted by the API, and a third value held in the database, and the beneficiary address appears complete in the user interface but arrives truncated in the payment message. Fix the record first: pick one affected payment and its stable identifier, such as the end-to-end identification, and use that single identifier at every layer so the comparison is about the same record. Then capture the value at each point, what the customer entered and what the screen displayed, the API request payload as received, the transformed canonical model, the validation and defaulting applied, and the persisted record, to find where the value changed.", "takeaway": "Then capture the value at each point, what the customer entered and what the screen displayed, the API request payload as received, the transformed canonical model, the validation and defaulting applied, and the persisted record, to find where the value changed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the record", "note": "Pick one payment and its end-to-end identification."}, {"kind": "step", "title": "Capture screen values", "note": "What the customer entered and what the screen displayed."}, {"kind": "step", "title": "Capture the API payload", "note": "The API request payload as received."}, {"kind": "step", "title": "Capture the canonical model", "note": "The transformed model, validation and defaulting."}, {"kind": "step", "title": "Capture the persisted record", "note": "The record as stored in the database."}, {"kind": "step", "title": "Find where the value changed", "note": "Compare the layers to find where it changed."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D04 Messaging and standards", "messages": [], "failure_category": "message mismatch", "resolution": "investigate"}, {"id": "INS-036", "seq": 458, "module": "Advanced", "source": "Public post", "title": "Legacy-to-new customer data mismatch", "explain": "During a migration from a legacy core system to a new platform, the first rehearsal shows thousands of mismatches: names that do not match, addresses that cannot be placed into the new structured format, dates in different formats, and payment records whose beneficiary details are incomplete. Define the migration as a controlled data movement with proof at every stage: start with a field-level mapping from the legacy system to the new platform, with every source field, its target field, its transformation rule, its validation rule and its owner, then prove the movement with control totals and exception handling at each stage. A migration without proof at each stage is a hope, not a plan.", "takeaway": "A migration without proof at each stage is a hope, not a plan.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the field mapping", "note": "Source field, target, transformation, validation, owner."}, {"kind": "step", "title": "Prove movement with control totals", "note": "Control totals and exception handling at each stage."}, {"kind": "step", "title": "Handle exceptions", "note": "Exception handling proves the movement at each stage."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "message mismatch"}, {"id": "INS-064", "seq": 463, "module": "Advanced", "source": "Public post", "title": "Rs 18,500 debit but the e-commerce order stays pending", "explain": "A customer pays Rs 18,500 for an order through a retailer's checkout, the bank account is debited, the payment gateway reports success, and the order remains pending with no confirmation, no dispatch and no delivery date. Start by fixing the reference: take the payment reference from the customer's bank statement and the gateway transaction ID, and confirm they belong to the same payment. Then trace the four boundaries in order, the gateway, the bank, the merchant callback and the order creation, to find where the payment outcome was lost, because the fulfilment path and the refund path depend on which boundary failed.", "takeaway": "Then trace the four boundaries in order, the gateway, the bank, the merchant callback and the order creation, to find where the payment outcome was lost, because the fulfilment path and the refund path depend on which boundary failed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the reference", "note": "Payment reference and gateway transaction ID, same payment."}, {"kind": "step", "title": "Trace the gateway boundary", "note": "Find where the outcome was lost at the gateway."}, {"kind": "step", "title": "Trace the bank boundary", "note": "Find where the outcome was lost at the bank."}, {"kind": "step", "title": "Trace the merchant callback", "note": "Find where the outcome was lost at the callback."}, {"kind": "step", "title": "Trace order creation", "note": "Find where the outcome was lost at order creation."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "INS-062", "seq": 464, "module": "Advanced", "source": "Public post", "title": "Gateway succeeds but the order system gets no callback", "explain": "A retailer runs a checkout where the payment gateway returns a success response, the customer sees a confirmation screen, and then nothing happens: the order system never receives the callback, so no order is created, no goods are picked, and the customer is charged for a purchase the retailer cannot see. Contain the impact by identifying every payment with no matching order, stop telling customers a payment succeeded until its outcome is known, and give support a holding message that is honest about the uncertainty. Then trace one affected payment end to end using its correlation ID, from the gateway request and response through the payment service state, the event published to the bus, and the callback delivery, to find where the outcome was lost.", "takeaway": "Then trace one affected payment end to end using its correlation ID, from the gateway request and response through the payment service state, the event published to the bus, and the callback delivery, to find where the outcome was lost.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Identify payments with no order", "note": "Find every payment with no matching order."}, {"kind": "step", "title": "Stop confirming success", "note": "Stop telling customers a payment succeeded until known."}, {"kind": "step", "title": "Give support a holding message", "note": "An honest message about the uncertainty."}, {"kind": "step", "title": "Trace one payment end to end", "note": "Gateway, payment service, event bus and callback."}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "name mismatch", "resolution": "investigate"}, {"id": "PAI-C047", "seq": 484, "module": "Advanced", "source": "Article and reader comments", "title": "Beneficiary short after intermediary charges", "explain": "When an ordering customer pays an employee with an MT103 and an intermediary bank deducts its charges, the beneficiary receives less than the amount sent, and the shortfall is the charge, not an error. The beneficiary bank credits the amount that arrives after the deductions, and the ordering customer must explain the difference to the employee. The situation is a normal consequence of the serial method, and it is why the charge-bearer field matters before the payment is sent.", "takeaway": "The situation is a normal consequence of the serial method, and it is why the charge-bearer field matters before the payment is sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Ordering customer pays employee by MT103", "note": "An ordering customer pays an employee with an MT103"}, {"kind": "step", "title": "Intermediary deducts its charge", "note": "An intermediary bank deducts its charges from the payment"}, {"kind": "step", "title": "Beneficiary bank credits the reduced amount", "note": "The beneficiary bank credits the amount that arrives after deductions"}, {"kind": "step", "title": "Ordering customer explains the shortfall", "note": "The ordering customer must explain the difference to the employee"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D14 Business analysis and professional practice", "messages": ["MT103"], "failure_category": "charge deduction"}, {"id": "PAI-C076", "seq": 494, "module": "Advanced", "source": "Article and reader comments", "title": "UETR: the thread through a pass-through payment", "explain": "When a payment passes through a correspondent bank, that bank sees two payments: the incoming payment from the sender and the outgoing payment to the next bank. The two legs are linked by the unique end-to-end transaction reference, the UETR, which travels unchanged from one message to the next and is carried in field 121 of block 3. No bank in the chain may modify field 121, because changing it would break the link that lets every bank reconcile the payment it received with the payment it sent.", "takeaway": "No bank in the chain may modify field 121, because changing it would break the link that lets every bank reconcile the payment it received with the payment it sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Correspondent sees two payments", "note": "The bank sees the incoming payment and the outgoing payment to the next bank"}, {"kind": "step", "title": "UETR travels unchanged in both legs", "note": "The unique end-to-end transaction reference travels unchanged between messages"}, {"kind": "step", "title": "UETR carried in field 121 of block 3", "note": "The UETR is carried in field 121 of block 3"}, {"kind": "step", "title": "No bank may modify field 121", "note": "Changing it would break the link between the payment received and the payment sent"}, {"kind": "step", "title": "Bank reconciles incoming and outgoing legs", "note": "The UETR lets every bank reconcile the payment received with the payment sent"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": []}, {"id": "PAI-C099", "seq": 496, "module": "Advanced", "source": "Article and reader comments", "title": "The accounting inside an MT101", "explain": "Accounting is done on the MT101 itself, in part: the debtor's account is debited and the funds are placed on an intermediary account inside the bank. When the MT103 is generated to move the money onward, the funds are debited from that intermediary account and forwarded to the destination. The MT101 therefore does the customer-side accounting, and the MT103 does the interbank settlement.", "takeaway": "The MT101 therefore does the customer-side accounting, and the MT103 does the interbank settlement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Debtor account debited to intermediary account", "note": "The debtor's account is debited and the funds go to an intermediary account in the bank"}, {"kind": "step", "title": "MT103 generated to move money onward", "note": "When the MT103 is generated, the funds are debited from that intermediary account"}, {"kind": "step", "title": "Funds forwarded to the destination", "note": "The funds are forwarded to the destination from the intermediary account"}, {"kind": "step", "title": "MT101 is customer-side accounting", "note": "The MT101 does the customer-side accounting"}, {"kind": "step", "title": "MT103 is interbank settlement", "note": "The MT103 does the interbank settlement"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": ["MT101", "MT103"]}, {"id": "INS-103", "seq": 501, "module": "Advanced", "source": "Public post", "title": "MT103 cannot supply what pacs.008 demands", "explain": "MT to MX coexistence creates a data gap: an MT103 may carry no structured address, yet pacs.008 requires town name and country code. The missing town cannot be invented, guessing writes false data onto the payment and a blank fails validation. Handle the gap with explicit translation rules, enrichment from a trusted source, and exception governance for every field the old message cannot supply.", "takeaway": "Handle the gap with explicit translation rules, enrichment from a trusted source, and exception governance for every field the old message cannot supply.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Take the old-format instruction exactly as sent.", "title": "Take in the MT103"}, {"kind": "step", "note": "Test it against every field pacs.008 requires.", "title": "Test against MX requirements"}, {"kind": "step", "note": "Flag each field the MT message cannot supply.", "title": "Flag the missing fields"}, {"kind": "step", "note": "Fill gaps only from an authoritative source, never by guessing.", "title": "Enrich from an authoritative source"}, {"kind": "step", "note": "Route unresolvable gaps through a defined exception path.", "title": "Route gaps to exception handling"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D04 Messaging and standards", "messages": ["MT103", "pacs.008"], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "SCN-07", "seq": 507, "module": "Advanced", "source": "Public post", "title": "Two legs settled, two returns needed", "explain": "A cover payment settles twice over, the pacs.008 instruction and the pacs.009 cover that moved funds between correspondents. Returning the customer payment unwinds only the first leg; the cover needs its own pacs.004, matched to the original cover by UETR and settlement references. Both legs post to the Nostro ledger, so reconciliation must pair all four messages, instruction, cover, return of instruction, and return of cover.", "takeaway": "Both legs post to the Nostro ledger, so reconciliation must pair all four messages, instruction, cover, return of instruction, and return of cover.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Customer payment returns through its own return.", "title": "Return the instruction leg"}, {"kind": "step", "note": "Cover is a separate settlement with its own return.", "title": "Return the cover leg"}, {"kind": "step", "note": "Match on UETR and settlement references.", "title": "Match on UETR"}, {"kind": "step", "note": "Pair instruction, cover, and both returns.", "title": "Reconcile all four messages"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D06 Cross-border payments", "messages": ["pacs.008", "pacs.009", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "SCN-10", "seq": 508, "module": "Advanced", "source": "Public post", "title": "Debited, failed, and the books disagree", "explain": "A 5,000 euro SEPA credit transfer debited the account yet failed between engine and clearing, so the books and reality disagree. Before touching anything, establish the true state across core banking, payment engine, ISO 20022 messages, clearing, settlement and accounting, and rule out duplicates. Then reverse the debit or re-release the payment, post correcting entries with a clear audit trail, and bring every system to the same outcome.", "takeaway": "Then reverse the debit or re-release the payment, post correcting entries with a clear audit trail, and bring every system to the same outcome.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Sent, rejected, duplicated, or never released.", "title": "Establish the true state"}, {"kind": "step", "note": "Confirm no automatic retry made a second payment.", "title": "Rule the duplicates out"}, {"kind": "step", "note": "Follow the customer instruction.", "title": "Reverse or re-release the payment"}, {"kind": "step", "note": "Tie the correction to the original debit.", "title": "Post the correcting entries"}, {"kind": "step", "note": "The customer statement is the final proof.", "title": "Confirm the customer outcome"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "reconciliation break", "resolution": "repair"}, {"id": "SCN-27", "seq": 510, "module": "Advanced", "source": "Public post", "title": "acks=1: acknowledged, then lost", "explain": "With acks=1 only the leader acknowledges, so a broker dying before replication loses the message, yet the payment had already been charged and the retry charged a second time. Nothing alerted because each component behaved as designed; the failure lived in the interaction. Fix the guarantees, acks=all with idempotent producers and dedup keys on every payment, add the transactional outbox pattern so the business record and the event cannot diverge, and keep reconciliation as the backstop.", "takeaway": "Fix the guarantees, acks=all with idempotent producers and dedup keys on every payment, add the transactional outbox pattern so the business record and the event cannot diverge, and keep reconciliation as the backstop.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Leader acknowledged before replication finished.", "title": "Broker dies before replication ends"}, {"kind": "step", "note": "Believed failed, so the retry charged again.", "title": "Retry charges a second time"}, {"kind": "step", "note": "acks=all, idempotent producers and dedup keys.", "title": "Strengthen the messaging guarantees"}, {"kind": "step", "note": "Record and event written atomically.", "title": "Add the transactional outbox"}, {"kind": "step", "note": "Double debits caught even when messaging fails.", "title": "Reconcile as the backstop"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "duplicate payment", "resolution": "repair"}, {"id": "SCN-34", "seq": 512, "module": "Advanced", "source": "Public post", "title": "Processed, timed out, then re-submitted", "explain": "A core banking API processed the transaction, then timed out before responding, so caller retry logic re-submitted a completed transaction. The missing controls were idempotency keys, a smart timeout strategy, and a reconciliation layer. The fix is idempotency keys on every mutating call, a pending-state transaction model that checks state before acting, and a standing rule that on any timeout the true state is queried first, asking what actually happened to the money.", "takeaway": "The fix is idempotency keys on every mutating call, a pending-state transaction model that checks state before acting, and a standing rule that on any timeout the true state is queried first, asking what actually happened to the money.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Work done, response never arrived.", "title": "API times out once processed"}, {"kind": "step", "note": "Completed transaction submitted again.", "title": "Retry submits it again"}, {"kind": "step", "note": "A repeat request is recognised, not re-executed.", "title": "Put idempotency keys on every call"}, {"kind": "step", "note": "Check state before acting, never blind re-submit.", "title": "Add a pending-state model"}, {"kind": "step", "note": "Ask first what happened to the money.", "title": "Query the true state first"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D10 APIs and integration", "messages": [], "failure_category": "timeout", "resolution": "repair"}, {"id": "SCN-36", "seq": 513, "module": "Advanced", "source": "Public post", "title": "UPI debit landed, credit never did", "explain": "A UPI debit committed locally while the credit acknowledgement timed out, a partial commit across two systems: the sender account debited, the receiver never credited. A retry hit duplicate-suppression logic and the message parked in a queue, leaving one system committed and the other uncertain. The mitigations are globally unique transaction references, idempotent processing at each bank, compensating transactions such as auto-reversal, and settlement-level balancing at the end of the cycle.", "takeaway": "The mitigations are globally unique transaction references, idempotent processing at each bank, compensating transactions such as auto-reversal, and settlement-level balancing at the end of the cycle.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Debit committed, that part certain.", "title": "The local debit commits"}, {"kind": "step", "note": "Second leg left unconfirmed.", "title": "Credit acknowledgement never arrives"}, {"kind": "step", "note": "Message parks in an internal queue.", "title": "Retry meets duplicate suppression"}, {"kind": "step", "note": "Auto-reversal returns the debited funds.", "title": "Auto-reversal compensates"}, {"kind": "step", "note": "Catch what the real-time flow missed.", "title": "Balance at settlement"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "timeout", "resolution": "repair"}, {"id": "JEB-E06", "seq": 520, "module": "Advanced", "source": "Public post", "title": "A return code gap usually sits between systems", "explain": "Mapping AC06 for a blocked account to MS03, reason not specified, looks like a one-line change until the BA asks how core banking communicates the condition, what the payment engine actually understands, and which conditions should produce AC06 at all. Core banking may know the account is blocked for a KYC restriction, a debit block, dormancy, or another restriction, while the engine only understands that the account is blocked, and national data-protection requirements may forbid passing the specific reason downstream. The real gap is found by comparing what the ecosystem understands today with what the requirement expects, then tracing the chain from core banking through business interpretation, country rule, and mapping to the return code, and deciding which system changes and who agrees the mapping.", "takeaway": "The real gap is found by comparing what the ecosystem understands today with what the requirement expects, then tracing the chain from core banking through business interpretation, country rule, and mapping to the return code, and deciding which system changes and who agrees the mapping.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "KYC restriction, debit block, dormancy, or another account restriction.", "title": "Core banking knows the condition"}, {"kind": "step", "note": "Decide which conditions should produce AC06 and when MS03 applies instead.", "title": "Business interpretation"}, {"kind": "step", "note": "Apply the country-specific rule and map the condition to a return code.", "title": "Country rule and mapping"}, {"kind": "step", "note": "The engine returns the agreed code to the receiving party.", "title": "Payment engine sends the code"}, {"kind": "step", "note": "Gap analysis decides which system changes and who owns the mapping.", "title": "Agree who changes what"}]}}, "level": "advanced", "stage": 4, "stage_name": "Cross-system consequences", "domain": "D04 Messaging and standards", "messages": [], "failure_category": "message mismatch", "resolution": "investigate"}, {"id": "INS-127", "seq": 17, "module": "Foundations", "source": "Public post", "title": "Three calendars govern one collection", "explain": "A direct debit collection depends on three calendars at once: the creditor PSP, the debtor PSP, and the clearing and settlement mechanism. If any one of them is closed on the due date, the collection cannot complete that day, even when the other two are open. Planning on a single calendar, such as only the creditor's own business calendar, is what produces late debits.", "takeaway": "Planning on a single calendar, such as only the creditor's own business calendar, is what produces late debits.", "visual": {"type": "diagram", "diagram": {"centre": "Three calendars for a collection", "parts": [{"label": "Creditor PSP calendar", "note": "Creditor PSP calendar must be open on the due date"}, {"label": "Debtor PSP calendar", "note": "Debtor PSP calendar must be open on the due date"}, {"label": "Clearing mechanism calendar", "note": "Clearing and settlement mechanism calendar must be open"}, {"label": "Any closure blocks it", "note": "If any one is closed, the collection cannot complete that day"}, {"label": "Single calendar risk", "note": "Planning on only the creditor calendar causes late debits"}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "cut-off missed"}, {"id": "INS-135", "seq": 18, "module": "Foundations", "source": "Public post", "title": "Why cross-border still lags domestic instant", "explain": "A domestic instant payment moves inside one system under one set of rules, while a cross-border payment passes through several payment service providers, currency conversions, compliance checks and settlement systems. Each hop adds time, and the hops depend on each other's operating hours. The chain of dependencies is the reason cross-border payments stay slower even when every individual leg is fast.", "takeaway": "The chain of dependencies is the reason cross-border payments stay slower even when every individual leg is fast.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Domestic instant payment", "note": "Moves inside one system with one set of rules"}, {"kind": "step", "title": "Several providers involved", "note": "Cross-border payment passes through several payment service providers"}, {"kind": "step", "title": "Currency conversion", "note": "Payment passes through currency conversions"}, {"kind": "step", "title": "Compliance checks", "note": "Payment passes through compliance checks"}, {"kind": "step", "title": "Settlement systems and hours", "note": "Each hop adds time and hops depend on each other's operating hours"}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D12 Risk, compliance and regulation", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "RUN4-002", "seq": 71, "module": "Foundations", "source": "Article and reader comments", "title": "Foreign currency account: the real funds sit abroad", "explain": "When a customer opens a USD account with a bank in France, the bank records the account in its own books while the actual USD rests with its correspondent in the USA. Funding comes from the customer buying USD or receiving it from someone, and the sending bank locates the French bank's US correspondent and routes the funds there. The correspondent then advises the French bank with an MT103, and only on that advice is the customer's account credited.", "takeaway": "The correspondent then advises the French bank with an MT103, and only on that advice is the customer's account credited.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer opens a USD account", "note": "The French bank records the account in its own books."}, {"kind": "step", "title": "Customer funds the account", "note": "The customer buys USD or receives it from someone."}, {"kind": "step", "title": "Sending bank finds the US correspondent", "note": "It locates the French bank's correspondent in the USA."}, {"kind": "step", "title": "Correspondent advises with MT103", "note": "The correspondent advises the French bank that funds are for the customer."}, {"kind": "step", "title": "Customer account credited", "note": "Only on that advice is the customer's account credited."}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "RUN4-003", "seq": 72, "module": "Foundations", "source": "Article and reader comments", "title": "A new nostro opens empty, then FX funds it", "explain": "Currency never leaves its home country, so a bank funds a new nostro by buying the foreign currency on the FX market and naming the nostro as the account to receive it. Where no banking relationship exists yet, the bank first asks a bank in that currency's country to open the account, which starts at zero, and only then does the FX deal. Where the bank already holds the currency in an account elsewhere, it simply instructs that bank to move the funds across, with no FX deal needed.", "takeaway": "Where the bank already holds the currency in an account elsewhere, it simply instructs that bank to move the funds across, with no FX deal needed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Buy currency on the FX market", "note": "The bank buys the foreign currency and names its nostro to receive it."}, {"kind": "decision", "title": "Relationship already in place?", "note": "Without one, the bank must first ask a local bank to open the account."}, {"kind": "step", "title": "New account starts at zero", "note": "The account opens empty; the FX deal follows only after that."}, {"kind": "step", "title": "Or move funds from elsewhere", "note": "Currency already held elsewhere moves across with no FX deal."}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "liquidity shortfall"}, {"id": "JEB-D07", "seq": 92, "module": "Foundations", "source": "Public post", "title": "Project Nexus: connect once, reach many countries", "explain": "Project Nexus, announced by the Bank for International Settlements, aims to link domestic instant payment systems across countries so a system joins Nexus a single time and through that link can pay any other country on the network, instead of every pair building a one-to-one connection. Each national system stays independent, keeping its own rules and running its own business, while Nexus serves as the central hub and global connector for instant payments. The distinction that matters is connection versus interaction, and a central platform connecting everyone replaces a web of bilateral links.", "takeaway": "The distinction that matters is connection versus interaction, and a central platform connecting everyone replaces a web of bilateral links.", "visual": {"type": "diagram", "diagram": {"centre": "Nexus as the global connector", "parts": [{"label": "One connection", "note": "Each system joins Nexus once instead of building one-to-one links."}, {"label": "Many countries", "note": "Through Nexus, a system can pay any other country on the network."}, {"label": "Systems stay independent", "note": "Each country keeps its own rules and runs its own business."}, {"label": "Central hub", "note": "Nexus links domestic instant payment systems across countries."}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D13", "seq": 94, "module": "Foundations", "source": "Public post", "title": "Cross-border payments: slow, costly, changing", "explain": "A payment that takes a second domestically can take three days across borders, and the outdated cross-border system, not the money itself, carries most of the blame. Instant payment systems have already changed this in more than 70 countries, including India with UPI, Europe with SEPA Instant, Singapore, Brazil, the United States, the United Kingdom and Thailand, yet a global money transfer is still said to cost 6 percent of the transaction value against a UN target of 3 percent. Reaching people in remote areas who do not use smartphones needs processing systems, not just mobile apps, and that gap is the real test of whether the world is ready for cross-border payments like UPI.", "takeaway": "Reaching people in remote areas who do not use smartphones needs processing systems, not just mobile apps, and that gap is the real test of whether the world is ready for cross-border payments like UPI.", "visual": {"type": "diagram", "diagram": {"centre": "Slow, expensive, and changing", "parts": [{"label": "3 days across borders", "note": "A payment that takes a second domestically can take days cross-border."}, {"label": "Outdated system", "note": "The old cross-border payment system is the main culprit."}, {"label": "Instant in 70+ countries", "note": "UPI, SEPA Instant and others already work in seconds domestically."}, {"label": "Cost: 6 percent vs 3 percent target", "note": "Global transfer costs about 6 percent, the UN target is 3 percent."}, {"label": "Remote areas need systems", "note": "Offline modes and processing systems, not just mobile apps."}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D15", "seq": 96, "module": "Foundations", "source": "Public post", "title": "Cross-border instant needs seven pieces together", "explain": "Instant payments already run in many countries, and linking domestic instant systems together makes them global, with SCT Inst and OCT Inst delivering instant payments across Europe. But switches and interoperability do not solve everything: liquidity, visible FX pricing and the correspondent bank role all still count, compliance has to keep up, UETR traceability helps resolve cases on time, and clearing and settlement still occur between systems. Cross-border payments become truly instant only when rules are clear, systems are aligned, and technology works with people, so the experience of the payment matters as much as the speed.", "takeaway": "Cross-border payments become truly instant only when rules are clear, systems are aligned, and technology works with people, so the experience of the payment matters as much as the speed.", "visual": {"type": "diagram", "diagram": {"centre": "What makes cross-border instant", "parts": [{"label": "Instant systems, interlinked", "note": "Domestic instant systems linked together make payments global."}, {"label": "SCT Inst and OCT Inst", "note": "Instant payments across Europe."}, {"label": "Liquidity and FX transparency", "note": "Liquidity, FX transparency and the correspondent bank still matter."}, {"label": "Compliance keeps up", "note": "Compliance must work at instant-payment speed."}, {"label": "UETR traceability", "note": "Traceability helps resolve cases on time."}, {"label": "Clearing and settlement", "note": "Settlement still occurs between systems."}]}}, "level": "foundation", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "INS-137", "seq": 143, "module": "Core", "source": "Public post", "title": "Instant end to end means every step is fast", "explain": "For an instant payment to feel instant end to end, every step must be fast: the customer channel, the payment engine, clearing and settlement. If any one step is slow, the customer promise breaks even when the other steps are instant. The work is to find which step is the bottleneck and optimise it, rather than assuming the rail alone makes the payment instant.", "takeaway": "The work is to find which step is the bottleneck and optimise it, rather than assuming the rail alone makes the payment instant.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer channel", "note": "Customer channel must be fast"}, {"kind": "step", "title": "Payment engine", "note": "Payment engine must be fast"}, {"kind": "step", "title": "Clearing", "note": "Clearing must be fast"}, {"kind": "step", "title": "Settlement", "note": "Settlement must be fast"}, {"kind": "decision", "title": "Which step is the bottleneck?", "note": "Find which step is the bottleneck and optimise it"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "INS-143", "seq": 146, "module": "Core", "source": "Public post", "title": "The FX provider inside the instant payment chain", "explain": "A bank that does not hold liquidity in every currency relies on an FX provider to source quotes, lock rates, execute the conversion and supply the settlement currency. The arrangement works on quiet days, but a quote can expire while screening runs, or the provider may not have the currency when it is needed. The FX provider is a dependency in the payment chain, and its failure modes must be designed for, because a chain is only as reliable as its weakest link.", "takeaway": "The FX provider is a dependency in the payment chain, and its failure modes must be designed for, because a chain is only as reliable as its weakest link.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank relies on FX provider", "note": "Bank does not hold liquidity in every currency"}, {"kind": "step", "title": "Source quotes, lock rates", "note": "FX provider sources quotes and locks rates"}, {"kind": "step", "title": "Execute the conversion", "note": "FX provider executes the conversion"}, {"kind": "step", "title": "Supply settlement currency", "note": "FX provider supplies the settlement currency"}, {"kind": "decision", "title": "Quote still valid?", "note": "Quote can expire while screening runs"}, {"kind": "decision", "title": "Currency available?", "note": "Provider may not have the currency when it is needed"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "liquidity shortfall", "resolution": "investigate"}, {"id": "INS-144", "seq": 147, "module": "Core", "source": "Public post", "title": "A good rate is not the same as having the currency", "explain": "Having a competitive exchange rate is not the same as having the settlement currency available at the moment it is needed. A bank can offer instant dollar payments and still fail on some mornings because it does not hold enough dollars to settle. The constraint is liquidity, not conversion, and it must be managed by treasury, not just by the payment engine.", "takeaway": "The constraint is liquidity, not conversion, and it must be managed by treasury, not just by the payment engine.", "visual": {"type": "diagram", "diagram": {"centre": "Currency liquidity constraint", "parts": [{"label": "Competitive rate", "note": "Bank can offer a competitive exchange rate"}, {"label": "Currency must be available", "note": "Settlement currency must be available at the moment it is needed"}, {"label": "Instant dollar payments", "note": "Bank can offer instant dollar payments and still fail on some mornings"}, {"label": "Not enough dollars", "note": "Bank may not hold enough dollars to settle"}, {"label": "Liquidity, not conversion", "note": "Constraint is liquidity, not conversion"}, {"label": "Managed by treasury", "note": "Must be managed by treasury, not just by the payment engine"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "liquidity shortfall", "resolution": "investigate"}, {"id": "INS-150", "seq": 149, "module": "Core", "source": "Public post", "title": "Timeout across corridor legs: never retry blind", "explain": "In a corridor where a payment crosses two fast payment systems joined by an orchestration layer, a timeout leaves the outcome uncertain: the money may have moved, or it may not have. If the customer taps send again, the bank can end up with two instructions and one debit. The safe handling is to establish the true state, never retry blindly, and use an inter-PSP investigation to resolve the uncertainty.", "takeaway": "The safe handling is to establish the true state, never retry blindly, and use an inter-PSP investigation to resolve the uncertainty.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Two fast systems joined", "note": "Payment crosses two fast payment systems joined by an orchestration layer"}, {"kind": "step", "title": "Timeout occurs", "note": "Timeout leaves the outcome uncertain"}, {"kind": "decision", "title": "Money moved or not?", "note": "Money may have moved, or it may not have"}, {"kind": "step", "title": "Customer taps send again", "note": "Customer taps send again"}, {"kind": "step", "title": "Two instructions, one debit", "note": "Bank can end up with two instructions and one debit"}, {"kind": "step", "title": "Establish the true state", "note": "Safe handling is to establish the true state, never retry blindly"}, {"kind": "step", "title": "Inter-PSP investigation", "note": "Use an inter-PSP investigation to resolve the uncertainty"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "SCN-03", "seq": 157, "module": "Core", "source": "Public post", "title": "One hour cut-off extension is not a small change", "explain": "Extending a branch cut-off for RTGS or NEFT by one hour sounds small, but a cut-off is a contract between the bank, the clearing system and every downstream batch. Settlement windows are fixed, and core banking hours, batch jobs, standing instructions and reconciliation all read the same clock. Moving the cut-off means re-validating everything that depends on it, and a payment accepted past the clearing window will be rejected downstream, so the change is a full regression exercise, not a parameter tweak.", "takeaway": "Moving the cut-off means re-validating everything that depends on it, and a payment accepted past the clearing window will be rejected downstream, so the change is a full regression exercise, not a parameter tweak.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cut-off extended one hour", "note": "Branch cut-off for RTGS or NEFT extended by one hour"}, {"kind": "step", "title": "Cut-off is a contract", "note": "Cut-off is a contract between the bank, the clearing system, downstream batches"}, {"kind": "step", "title": "Settlement windows are fixed", "note": "Settlement windows are fixed"}, {"kind": "step", "title": "Dependent systems read same clock", "note": "Core banking hours, batch jobs, standing instructions, reconciliation read same clock"}, {"kind": "step", "title": "Re-validate dependencies", "note": "Moving the cut-off means re-validating everything that depends on it"}, {"kind": "step", "title": "Payment past window rejected", "note": "Payment accepted past the clearing window will be rejected downstream"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "cut-off missed", "resolution": "reject"}, {"id": "JEB-B05", "seq": 166, "module": "Core", "source": "Public post", "title": "Direct Debit migration: reuse is not a business decision", "explain": "Reuse looks efficient when moving Direct Debits to a new platform after the existing process was defined for Germany and worked well there, yet efficiency is not the test. The Netherlands has its own local specification, the Overstapservice, a bank-switching service that lets Direct Debits continue after a customer moves to a new Dutch bank, so an incoming Direct Debit for a closed account may need redirecting rather than rejecting. Reuse is a delivery choice, not a business decision, so before agreeing to reuse, check whether the requirement is a common scheme rule or a local specification, and whether the new country adds requirements the existing logic never had to meet.", "takeaway": "Reuse is a delivery choice, not a business decision, so before agreeing to reuse, check whether the requirement is a common scheme rule or a local specification, and whether the new country adds requirements the existing logic never had to meet.", "visual": {"type": "diagram", "diagram": {"centre": "Reuse is not a business decision", "parts": [{"label": "German process worked well", "note": "The existing process was defined for Germany and worked well there"}, {"label": "Dutch Overstapservice", "note": "A bank-switching service that lets Direct Debits continue after a move"}, {"label": "Redirect, not reject", "note": "An incoming Direct Debit for a closed account may need redirecting, not rejecting"}, {"label": "Common rule or local spec?", "note": "Check whether the requirement is a common scheme rule or a local specification"}, {"label": "New country requirements", "note": "Check whether the new country adds requirements the existing logic never met"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "invalid beneficiary data", "resolution": "reject"}, {"id": "PAI-C038", "seq": 260, "module": "Core", "source": "Article and reader comments", "title": "Paying a bank that is not a SWIFT member", "explain": "When the beneficiary bank is not a SWIFT member, the MT103 cannot be sent to it directly, so the payment must reach it through a bank that is a member and can forward the instruction. The forwarding bank becomes an intermediary in the chain, and the payment follows the same serial or cover logic as any other payment with an intermediary. Non-membership does not stop the payment; it adds a step to the chain.", "takeaway": "Non-membership does not stop the payment; it adds a step to the chain.", "visual": {"type": "diagram", "diagram": {"centre": "A beneficiary bank outside SWIFT", "parts": [{"label": "MT103 cannot be sent to it directly", "note": "The MT103 cannot go directly to a non-member bank"}, {"label": "Forwarding bank becomes an intermediary", "note": "A member bank forwards the instruction onward"}, {"label": "Same serial or cover logic applies", "note": "The payment follows the usual serial or cover logic"}, {"label": "Non-membership adds a step", "note": "Non-membership adds a step, it does not stop the payment"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": ["MT103"]}, {"id": "RUN4-008", "seq": 308, "module": "Core", "source": "Article and reader comments", "title": "Small banks ride on large banks' correspondent networks", "explain": "Building and maintaining a correspondent network is costly and slow, so a small bank often opens a foreign currency account with a large bank in its own country that already holds a correspondent in the currency's country. That large bank then acts as intermediary for the small bank's cross-border payments, while the real funds still end up held in the currency's country. Strictly the large bank is the small bank's correspondent, but in a cross-border transfer it is usually called the intermediary bank.", "takeaway": "Strictly the large bank is the small bank's correspondent, but in a cross-border transfer it is usually called the intermediary bank.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Small bank opens a local account", "note": "It opens a foreign currency account with a large bank at home."}, {"kind": "step", "title": "Large bank brings its correspondent", "note": "That bank already holds a correspondent in the currency's country."}, {"kind": "step", "title": "Large bank acts as intermediary", "note": "It intermediates the small bank's cross-border payments."}, {"kind": "step", "title": "Funds stay in the currency country", "note": "The real funds still end up held where the currency belongs."}, {"kind": "step", "title": "Correspondent, called intermediary", "note": "Strictly its correspondent, usually called the intermediary bank."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN4-013", "seq": 313, "module": "Core", "source": "Article and reader comments", "title": "Treasury keeps the nostro funded, never moves money", "explain": "A treasury team moves no money itself; it watches balances on the correspondent accounts and buys or sells foreign exchange to hold enough funds for the day's payments. When it buys currency in the FX market, the funds land in the correspondent bank account in the foreign country, and the mirror account simply reflects that credit. The mirror does nothing on its own; it only records what happened on the real account.", "takeaway": "The mirror does nothing on its own; it only records what happened on the real account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Treasury watches the balances", "note": "The team monitors funds on the correspondent accounts."}, {"kind": "step", "title": "Treasury buys or sells FX", "note": "It trades FX to hold enough funds for the day's payments."}, {"kind": "step", "title": "Funds land abroad", "note": "Bought currency is credited to the correspondent account overseas."}, {"kind": "step", "title": "Mirror only reflects it", "note": "The mirror records the credit and does nothing on its own."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "message mismatch"}, {"id": "RUN4-014", "seq": 314, "module": "Core", "source": "Article and reader comments", "title": "Cover leg: same country means local clearing can settle it", "explain": "In a cross-border payment the cover leg moves funds between the sender's correspondent and the receiver's correspondent, and where both correspondents sit in the same country a local clearing system can settle that leg. The payment message still travels over SWIFT, but the money itself moves locally. The local route costs less than moving the funds over the SWIFT network.", "takeaway": "The local route costs less than moving the funds over the SWIFT network.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover moves between correspondents", "note": "The cover leg moves funds from sender's to receiver's correspondent."}, {"kind": "decision", "title": "Both correspondents in one country?", "note": "If both sit in one country, local clearing can settle the leg."}, {"kind": "step", "title": "Local clearing settles it", "note": "The money moves locally through the clearing system."}, {"kind": "step", "title": "Message still goes by SWIFT", "note": "The payment message still travels over SWIFT."}, {"kind": "step", "title": "Local route costs less", "note": "Local settlement is cheaper than moving funds over SWIFT."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "RUN4-015", "seq": 315, "module": "Core", "source": "Article and reader comments", "title": "Euro leg in Europe: SEPA beats MT202 COV", "explain": "When a bank outside Europe instructs its correspondent in France to pay a customer of a German bank in euros, it need not use an MT202 COV. The correspondent can pay through SEPA or another local system instead, and in practice that local route is the one used most often. It also costs less than sending the funds over the SWIFT network.", "takeaway": "It also costs less than sending the funds over the SWIFT network.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank outside Europe instructs", "note": "It asks its French correspondent to pay a German bank customer in euros."}, {"kind": "step", "title": "Correspondent uses SEPA", "note": "SEPA or another local system replaces the MT202 COV."}, {"kind": "step", "title": "Local route is the norm", "note": "That local route is the usual choice in practice."}, {"kind": "step", "title": "Local route costs less", "note": "It costs less than sending funds over the SWIFT network."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": ["MT202"], "failure_category": "system or connectivity failure"}, {"id": "RUN4-016", "seq": 316, "module": "Core", "source": "Article and reader comments", "title": "Withdrawing foreign cash the bank holds at home", "explain": "A customer holding a USD account with a bank in France can ask for the funds in physical USD cash, even though the real dollars sit with the bank's correspondent in the USA. The bank keeps an estimated stock of USD cash on hand, sized on customer demand, and sources it from customers selling USD for euros or from another bank. It hands over the cash and debits the same amount from the customer's USD account.", "takeaway": "It hands over the cash and debits the same amount from the customer's USD account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer asks for USD cash", "note": "A USD account holder in France requests physical USD cash."}, {"kind": "step", "title": "Real dollars sit in the USA", "note": "The actual dollars rest with the bank's US correspondent."}, {"kind": "step", "title": "Bank keeps cash on hand", "note": "It holds an estimated stock of USD cash, sized on demand."}, {"kind": "step", "title": "Bank sources the cash", "note": "Cash comes from customers selling USD or from another bank."}, {"kind": "step", "title": "Cash paid, account debited", "note": "The cash is handed over and the same amount is debited."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-F13", "seq": 364, "module": "Core", "source": "Public post", "title": "Instant cross-border: speed is only one piece", "explain": "Instant cross-border payments are not only about speed, because several pieces must work together for the whole journey to be efficient. Clearing, processing and settlement must become more efficient, FX conversion must be transparent to the customer, and payment status must be traceable, while richer remittance information supports AML and fraud checks, and common messaging standards and APIs make systems interoperable. When these pieces combine, transaction time and end-user costs fall, which is the real transformation.", "takeaway": "When these pieces combine, transaction time and end-user costs fall, which is the real transformation.", "visual": {"type": "diagram", "diagram": {"centre": "Instant is not just speed", "parts": [{"label": "Efficient processing", "note": "Faster clearing, processing and settlement"}, {"label": "FX transparency", "note": "The customer sees the conversion cost"}, {"label": "Status traceability", "note": "The payment journey can be tracked"}, {"label": "Richer remittance data", "note": "More information for AML and fraud checks"}, {"label": "Common standards and APIs", "note": "Interoperability across systems"}, {"label": "Lower end-user costs", "note": "Less time and less cost for the customer"}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-D09", "seq": 370, "module": "Core", "source": "Public post", "title": "Interoperability demands more than connectivity", "explain": "Interoperability goes beyond connecting two systems with an API, because messaging, processing rules, clearing, settlement, compliance and day-to-day operations must also line up. A payment bridge joins two payment ecosystems in business and technical terms, where each side may run its own instant rail, currency and rules, and the bridge works as shared standards, scheme rules and cooperation between systems dictate. ISO 20022 supplies the common language, UETR supplies traceability, OCT Inst supplies rules for the Euro leg, and together they move interoperable instant payments across borders closer.", "takeaway": "ISO 20022 supplies the common language, UETR supplies traceability, OCT Inst supplies rules for the Euro leg, and together they move interoperable instant payments across borders closer.", "visual": {"type": "diagram", "diagram": {"centre": "A bridge, not just a connection", "parts": [{"label": "Technology", "note": "Connecting systems is only the first piece."}, {"label": "Common rules", "note": "Messaging, processing rules, clearing, settlement and compliance must align."}, {"label": "Common messaging", "note": "ISO 20022 gives a common language across systems."}, {"label": "Traceability", "note": "UETR helps trace a payment end to end."}, {"label": "FX transparency", "note": "Currency conversion must be visible across the bridge."}, {"label": "Efficient processing", "note": "Each side may have its own rail, currency and rules."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-E05", "seq": 377, "module": "Core", "source": "Public post", "title": "A holiday calendar is an end-to-end operating decision", "explain": "A payment engine can be open while the rest of the payment journey is not, so asking whether the engine is open is the wrong question when the USA is open, France is closed, and a French bank holds the account receiving an international USD payment. Core banking and account booking, compliance controls, customer reporting, and the nostro funding feed must remain available, because a credit that never appears in intraday reporting leaves a cash management customer acting on an incomplete cash position. Internal reporting, regulatory reporting, and the nostro reconciliation feed may be able to wait under agreed controls, but the BA must not decide that alone: the Reporting Product Manager defines reporting criticality and Operations defines the reconciliation catch-up.", "takeaway": "Internal reporting, regulatory reporting, and the nostro reconciliation feed may be able to wait under agreed controls, but the BA must not decide that alone: the Reporting Product Manager defines reporting criticality and Operations defines the reconciliation catch-up.", "visual": {"type": "diagram", "diagram": {"centre": "Are we really ready to process?", "parts": [{"label": "Critical: core banking", "note": "Account booking must be available to post the payment."}, {"label": "Critical: compliance", "note": "Compliance controls must run before the payment is processed."}, {"label": "Critical: customer reporting", "note": "Intraday reporting drives the customer liquidity and cash position."}, {"label": "Critical: nostro funding", "note": "The nostro funding feed must be available to fund the payment."}, {"label": "Can wait with controls", "note": "Internal and regulatory reporting and nostro reconciliation can catch up later."}]}}, "level": "core", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "INS-141", "seq": 424, "module": "Advanced", "source": "Public post", "title": "Interoperability is more than an API", "explain": "Connecting two instant payment systems through an API proves that a message can be sent and a response received, but it does not prove the payment will work end to end. The systems must also align on message formats, scheme rules, clearing, settlement, compliance and operations. A payment accepted by the channel can still be rejected by clearing if those layers do not match, so connectivity is the easiest part of the integration.", "takeaway": "A payment accepted by the channel can still be rejected by clearing if those layers do not match, so connectivity is the easiest part of the integration.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Connect via API", "note": "API proves a message can be sent and a response received"}, {"kind": "step", "title": "Align message formats", "note": "Systems must align on message formats"}, {"kind": "step", "title": "Align scheme rules", "note": "Systems must align on scheme rules"}, {"kind": "step", "title": "Align clearing and settlement", "note": "Systems must align on clearing and settlement"}, {"kind": "step", "title": "Align compliance and operations", "note": "Systems must align on compliance and operations"}, {"kind": "step", "title": "Channel accepts, clearing rejects", "note": "Payment accepted by the channel can still be rejected by clearing"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "message mismatch", "resolution": "reject"}, {"id": "INS-166", "seq": 425, "module": "Advanced", "source": "Public post", "title": "UPI, SCT Inst, FedNow and RTP are not one system", "explain": "Connecting to instant payment systems in several markets, such as UPI in India, SCT Inst in Europe, and FedNow and RTP in the United States, is not just a technical connection. The systems differ in scheme rules, participants, operating hours and dispute processes, so a payment that works in one market can fail in another for a non-technical reason. Technical connectivity and scheme alignment must both be designed, because the same payment behaves differently under different scheme rules.", "takeaway": "Technical connectivity and scheme alignment must both be designed, because the same payment behaves differently under different scheme rules.", "visual": {"type": "diagram", "diagram": {"centre": "Instant system interoperability", "parts": [{"label": "UPI in India", "note": "UPI in India is one market system to connect"}, {"label": "SCT Inst in Europe", "note": "SCT Inst in Europe is one market system to connect"}, {"label": "FedNow and RTP in US", "note": "FedNow and RTP in the United States are market systems to connect"}, {"label": "Scheme rules differ", "note": "Systems differ in scheme rules"}, {"label": "Participants differ", "note": "Systems differ in participants"}, {"label": "Operating hours differ", "note": "Systems differ in operating hours"}, {"label": "Dispute processes differ", "note": "Systems differ in dispute processes"}, {"label": "Technical plus scheme alignment", "note": "Technical connectivity and scheme alignment must both be designed"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "INS-167", "seq": 426, "module": "Advanced", "source": "Public post", "title": "One generic field set loses payment data", "explain": "Different channels and corridors send similar but non-identical payment fields, and collapsing them into one generic set of fields loses information. A common data model must define how fields translate, how validation works, and what error semantics apply across different domestic rails. Without that model, small data differences become payment failures that are hard to trace, so the model is the integration, not a document about it.", "takeaway": "Without that model, small data differences become payment failures that are hard to trace, so the model is the integration, not a document about it.", "visual": {"type": "diagram", "diagram": {"centre": "Common data model across corridors", "parts": [{"label": "Similar but non-identical fields", "note": "Different channels and corridors send similar but non-identical fields"}, {"label": "Generic set loses information", "note": "Collapsing them into one generic set of fields loses information"}, {"label": "Field translation", "note": "Common data model must define how fields translate"}, {"label": "Validation", "note": "Common data model must define how validation works"}, {"label": "Error semantics", "note": "Common data model must define what error semantics apply"}, {"label": "Small differences become failures", "note": "Without that model, small differences become payment failures hard to trace"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D04 Messaging and standards", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-142", "seq": 427, "module": "Advanced", "source": "Public post", "title": "UPI and PayNow linkage", "explain": "The UPI and PayNow linkage lets a person in India send money to a family member in Singapore using only the recipient mobile number, and the reverse. It works through proxy identifiers and a participating institution model, where each side resolves the proxy to the right account. The scope of the linkage must be validated, because not every account type or transaction type is covered, so the first design question is always what the linkage actually covers.", "takeaway": "The scope of the linkage must be validated, because not every account type or transaction type is covered, so the first design question is always what the linkage actually covers.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Person in India sends", "note": "Person in India sends money to a family member in Singapore"}, {"kind": "step", "title": "Use only mobile number", "note": "Sender uses only the recipient mobile number"}, {"kind": "step", "title": "Proxy identifier resolved", "note": "Each side resolves the proxy to the right account"}, {"kind": "step", "title": "Participating institution model", "note": "Works through proxy identifiers and a participating institution model"}, {"kind": "step", "title": "Reverse direction works", "note": "Reverse direction works the same way"}, {"kind": "decision", "title": "Scope validated?", "note": "Scope must be validated, because not every account or transaction type is covered"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "INS-153", "seq": 429, "module": "Advanced", "source": "Public post", "title": "Designing an India-Europe payment bridge", "explain": "Building a payment corridor from India to Europe means mapping every dependency: currency, scheme, compliance, data, FX and settlement. Today a payment from a European buyer to an Indian exporter travels through a chain of correspondents, takes days, and gives neither side a reliable status. A bridge design must replace that chain with a defined path that both sides can track, because a corridor without a trackable path is just a longer chain of correspondents.", "takeaway": "A bridge design must replace that chain with a defined path that both sides can track, because a corridor without a trackable path is just a longer chain of correspondents.", "visual": {"type": "diagram", "diagram": {"centre": "India-Europe payment bridge", "parts": [{"label": "Currency", "note": "Bridge design must map the currency dependency"}, {"label": "Scheme", "note": "Bridge design must map the scheme dependency"}, {"label": "Compliance", "note": "Bridge design must map the compliance dependency"}, {"label": "Data", "note": "Bridge design must map the data dependency"}, {"label": "FX", "note": "Bridge design must map the FX dependency"}, {"label": "Settlement", "note": "Bridge design must map the settlement dependency"}, {"label": "Today via correspondents", "note": "Today the payment travels through a chain of correspondents and takes days"}, {"label": "Defined trackable path", "note": "Bridge must replace that chain with a defined path both sides can track"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "INS-066", "seq": 462, "module": "Advanced", "source": "Public post", "title": "Payment volume rises 300 percent in a zero-fee campaign", "explain": "A bank launches a zero-fee weekend campaign for retail payments and within the first hour payment volume rises to 300 percent of a normal peak, roughly four times the usual load. Latency climbs, channel sessions start timing out, and the clearing connector queue grows faster than it drains. Treat the surge as a capacity problem with three controls: intake, queue and recovery. At intake, apply back-pressure through the API gateway and channel, queue or gracefully defer non-critical traffic, show a clear pending state instead of a silent timeout, and throttle campaign traffic to a rate the downstream chain can sustain.", "takeaway": "At intake, apply back-pressure through the API gateway and channel, queue or gracefully defer non-critical traffic, show a clear pending state instead of a silent timeout, and throttle campaign traffic to a rate the downstream chain can sustain.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Normal peak volume", "note": "The usual peak load, the baseline for the campaign.", "value": 100}, {"label": "Additional campaign volume", "note": "Volume rises to 300 percent of a normal peak.", "value": 300}], "unit": "%"}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D10 APIs and integration", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "PAI-C044", "seq": 481, "module": "Advanced", "source": "Article and reader comments", "title": "Reaching a bank with no direct relationship", "explain": "A customer can transfer funds to a bank that has no account with the sending bank, because the payment travels through correspondent and intermediary banks that do hold accounts with each other. The sending bank passes the instruction to its correspondent, which passes it onward until it reaches a bank that holds an account for the beneficiary bank. The chain exists precisely to connect banks that have no direct relationship.", "takeaway": "The chain exists precisely to connect banks that have no direct relationship.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sending bank has no account with beneficiary", "note": "The beneficiary bank holds no account with the sending bank"}, {"kind": "step", "title": "Sending bank passes to its correspondent", "note": "The sending bank passes the instruction to its correspondent"}, {"kind": "step", "title": "Correspondent passes it onward", "note": "Each correspondent passes it on until an account holder is reached"}, {"kind": "step", "title": "Payment reaches the beneficiary bank", "note": "The chain connects banks with no direct relationship"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C049", "seq": 486, "module": "Advanced", "source": "Article and reader comments", "title": "CHAPS as the sterling leg of a cross-border payment", "explain": "CHAPS is the UK high-value payment system, and the question is whether it can be used for cross-border payments. CHAPS settles sterling payments between UK banks in central bank money, and a cross-border payment that needs sterling settlement in the UK can use it as the domestic leg. The cross-border leg itself still needs a correspondent or a scheme to carry the payment out of the UK, so CHAPS is one leg of the journey, not the whole journey.", "takeaway": "The cross-border leg itself still needs a correspondent or a scheme to carry the payment out of the UK, so CHAPS is one leg of the journey, not the whole journey.", "visual": {"type": "diagram", "diagram": {"centre": "CHAPS for cross-border payments", "parts": [{"label": "UK high-value payment system", "note": "CHAPS is the UK high-value payment system"}, {"label": "Settles sterling in central bank money", "note": "CHAPS settles sterling between UK banks in central bank money"}, {"label": "Usable as the domestic sterling leg", "note": "A cross-border payment can use CHAPS as its domestic leg"}, {"label": "Cross-border leg still needs a scheme", "note": "The cross-border leg still needs a correspondent or a scheme"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "system or connectivity failure"}, {"id": "PAI-C051", "seq": 488, "module": "Advanced", "source": "Article and reader comments", "title": "How Wise settles without SWIFT on each leg", "explain": "Wise moves money internationally without using SWIFT codes for every payment, because it holds local accounts in the countries it serves and settles each leg domestically. A customer paying from one country to another funds a local account in the sending country, and Wise pays the beneficiary from its local account in the receiving country, so no cross-border SWIFT message is needed for the legs. The model works because Wise nets the flows across its customers, and it is a different design from the correspondent banking chain.", "takeaway": "The model works because Wise nets the flows across its customers, and it is a different design from the correspondent banking chain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer funds a local Wise account", "note": "A customer funds a local account in the sending country"}, {"kind": "step", "title": "Wise pays from its local account abroad", "note": "Wise pays the beneficiary from its local account in the receiving country"}, {"kind": "step", "title": "Each leg settles domestically", "note": "No cross-border SWIFT message is needed for the legs"}, {"kind": "step", "title": "Wise nets the flows across customers", "note": "The model works because Wise nets flows across its customers"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "PAI-C067", "seq": 491, "module": "Advanced", "source": "Article and reader comments", "title": "Paying a bank with a non-connected BIC", "explain": "Some banks hold a BIC with the digit 1 in position 8, which marks it as non-connected: it is a SWIFT participant but cannot receive messages directly. The MT103 announcement and the MT202 COV are then sent to a live BIC, which forwards the funds to the non-connected bank over an internal network, usually with a normal serial MT103. The same pattern appears in bank groups where SWIFT communication is centralised at the head office and the head office forwards payments to subsidiaries and branches.", "takeaway": "The same pattern appears in bank groups where SWIFT communication is centralised at the head office and the head office forwards payments to subsidiaries and branches.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank holds a non-connected BIC", "note": "The BIC has the digit 1 in position 8, so the bank cannot receive messages directly"}, {"kind": "step", "title": "MT103 and MT202 COV sent to a live BIC", "note": "The announcement and the cover are sent to a live BIC"}, {"kind": "step", "title": "Live BIC forwards the funds onward", "note": "The live BIC forwards the funds over an internal network"}, {"kind": "step", "title": "Forwarding uses a normal serial MT103", "note": "The onward leg usually uses a normal serial MT103"}, {"kind": "step", "title": "Head office forwards to subsidiaries", "note": "The same pattern appears where SWIFT is centralised at the head office"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D04 Messaging and standards", "messages": ["MT103", "MT202"]}, {"id": "PAI-C071", "seq": 492, "module": "Advanced", "source": "Article and reader comments", "title": "Why a bank waits to buy the payment currency", "explain": "A bank does not buy the currency of every payment the moment it is instructed, because it does not know in advance how much foreign currency it will need. It collects orders until a cut-off time and then decides whether to buy, sell or do nothing, based on the balance of orders and the funds already sitting in its nostro accounts. A payment can therefore wait for the bank's currency position to be settled, even when the instruction itself is complete.", "takeaway": "A payment can therefore wait for the bank's currency position to be settled, even when the instruction itself is complete.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank receives payment instructions", "note": "The bank is instructed on payments but does not buy the currency at once"}, {"kind": "step", "title": "Orders collected until cut-off time", "note": "The bank collects orders until a cut-off time"}, {"kind": "step", "title": "Bank checks its nostro balances", "note": "It weighs the balance of orders against funds in its nostro accounts"}, {"kind": "decision", "title": "Buy, sell or do nothing", "note": "It decides whether to buy, sell or do nothing based on the balance of orders"}, {"kind": "step", "title": "Payment waits for the currency position", "note": "A payment can wait for the bank's currency position to be settled"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": [], "failure_category": "liquidity shortfall"}, {"id": "RUN4-017", "seq": 497, "module": "Advanced", "source": "Article and reader comments", "title": "Bank to bank dollars settle inside the USA", "explain": "When a French bank sends USD to a German bank, it tells its US correspondent to debit the nostro and credit the German bank's account with that bank's own US correspondent. Settlement completes in a single domestic step, since both accounts sit in the USA. The sender finds the German bank's US correspondent in its Standing Settlement Instructions and states it in the MT103.", "takeaway": "The sender finds the German bank's US correspondent in its Standing Settlement Instructions and states it in the MT103.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "French bank instructs its correspondent", "note": "It tells its US correspondent to debit the nostro."}, {"kind": "step", "title": "German bank credited in the USA", "note": "The German bank's account with its own US correspondent is credited."}, {"kind": "step", "title": "Settles in a single step", "note": "Both accounts sit in the USA, so settlement is one domestic step."}, {"kind": "step", "title": "Correspondent found in instructions", "note": "The sender locates the German bank's US correspondent in the SSI."}, {"kind": "step", "title": "MT103 names the correspondent", "note": "The sender states that correspondent in the MT103."}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": ["MT103"], "failure_category": "liquidity shortfall"}, {"id": "RUN4-019", "seq": 498, "module": "Advanced", "source": "Article and reader comments", "title": "Letter of credit settlement: MT103 or MT103 plus cover", "explain": "A letter of credit is issued with an MT700, but the standard does not fix how it must be settled, so the parties agree the payment instrument between themselves. In general the settlement runs through a serial MT103, or through an MT103 together with an MT202 COV. Either route moves the funds under the credit once the documents have been accepted.", "takeaway": "Either route moves the funds under the credit once the documents have been accepted.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Credit issued with MT700", "note": "The letter of credit itself is issued with an MT700."}, {"kind": "step", "title": "Parties agree the instrument", "note": "The standard leaves settlement to agreement between the parties."}, {"kind": "step", "title": "Settle by serial MT103", "note": "One route is settlement through a serial MT103."}, {"kind": "step", "title": "Or MT103 plus MT202 COV", "note": "The other route pairs an MT103 with an MT202 COV."}, {"kind": "step", "title": "Funds move after acceptance", "note": "Either route moves the funds once documents are accepted."}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": ["MT103", "MT202", "MT700"], "resolution": "repair"}, {"id": "INS-164", "seq": 505, "module": "Advanced", "source": "Public post", "title": "One corridor, one owner, end to end", "explain": "A European buyer paying an Indian exporter crosses four legs, a domestic euro rail, a cross-border bridge, an FX conversion and a domestic Indian rail, and each participant reports only its own leg. With no owner of the end-to-end state, a late payment turns into a chain of calls, exporter to buyer, buyer to bank, bank to bridge operator, and nobody can say where the money is. Give the corridor a named owner for the whole journey, with every leg mapped to its rail, FX step, settlement and compliance check.", "takeaway": "Give the corridor a named owner for the whole journey, with every leg mapped to its rail, FX step, settlement and compliance check.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Buyer pays on the domestic euro rail.", "title": "Euro leg, domestic"}, {"kind": "step", "note": "Payment crosses to the Indian side.", "title": "The cross-border bridge"}, {"kind": "step", "note": "Euros convert to rupees.", "title": "Convert the currency"}, {"kind": "step", "note": "Exporter is paid on the Indian rail.", "title": "Indian leg, domestic"}, {"kind": "step", "note": "One owner follows the whole journey.", "title": "Own the journey end to end"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "JEB-F04", "seq": 518, "module": "Advanced", "source": "Public post", "title": "Interlinking: instructions, status and complaints", "explain": "Interlinking connects payment systems across countries so a payment can be tracked end to end once it is debited, and the open question is whether the customer-side acceptance of payment instructions can travel the same way, and then complaints and investigations too. If instructions, status and complaints all travel on the interlinked rails, the hardest cross-border problem, not knowing where a payment is, starts to close. That is why interlinking is a way of thinking about payments, not only a connectivity project.", "takeaway": "That is why interlinking is a way of thinking about payments, not only a connectivity project.", "visual": {"type": "diagram", "diagram": {"centre": "Interlinked payment systems", "parts": [{"label": "Payment instructions", "note": "Customer instructions accepted across linked systems"}, {"label": "End-to-end tracking", "note": "Once debited, the whole journey is visible"}, {"label": "Status visibility", "note": "No more not knowing where a payment is"}, {"label": "Complaints and investigations", "note": "Can complaints travel on the same links"}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D06 Cross-border payments", "messages": []}, {"id": "RUN6-014", "seq": 523, "module": "Advanced", "source": "Article and reader comments", "title": "The central bank view of indirect participation", "explain": "From the central bank standpoint the risk is liquidity: whether the indirect participant can meet its financial obligations. Ensuring that funding is normally the direct participant business, since the direct participant must confirm the indirect participant holds enough before sending debit payments. The central bank sees only the direct participant, even when the payment belongs to the indirect participant, and oversees the direct participant as a whole rather than dealing with the indirect participant.", "takeaway": "The central bank sees only the direct participant, even when the payment belongs to the indirect participant, and oversees the direct participant as a whole rather than dealing with the indirect participant.", "visual": {"type": "diagram", "diagram": {"centre": "The central bank view of indirect participation", "parts": [{"label": "The risk is liquidity", "note": "The question is whether the indirect participant can meet its obligations."}, {"label": "The DP must ensure funds", "note": "The direct participant checks the IP has enough before sending debits."}, {"label": "The central bank sees the DP", "note": "It sees the direct participant even when the payment is for the IP."}, {"label": "Oversight covers the DP whole", "note": "The central bank oversees the DP as a whole, not the IP directly."}]}}, "level": "advanced", "stage": 5, "stage_name": "Complex banking scenarios", "domain": "D07 Clearing, settlement and liquidity", "messages": [], "failure_category": "liquidity shortfall"}, {"id": "INS-120", "seq": 22, "module": "Foundations", "source": "Public post", "title": "Turn scheme rules into buildable requirements", "explain": "Payment scheme rules are written in technical language, but developers and business users need them as a clear trigger, decision, rule, timeline and system behaviour. Translating a rule into what happens, when, and what the system must do is what makes it buildable. Jargon left in a requirement produces a system that does the wrong thing confidently, so plain, precise wording is a quality control, not a courtesy.", "takeaway": "Jargon left in a requirement produces a system that does the wrong thing confidently, so plain, precise wording is a quality control, not a courtesy.", "visual": {"type": "diagram", "diagram": {"centre": "Payment rules without jargon", "parts": [{"label": "Trigger", "note": "Clear trigger states what starts the rule"}, {"label": "Decision", "note": "Clear decision states what is decided"}, {"label": "Rule", "note": "Clear rule states what must happen"}, {"label": "Timeline", "note": "Clear timeline states when it happens"}, {"label": "System behaviour", "note": "Clear system behaviour states what the system must do"}, {"label": "Jargon risk", "note": "Jargon in a requirement leads to a system doing the wrong thing confidently"}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": []}, {"id": "JEB-C07", "seq": 29, "module": "Foundations", "source": "Public post", "title": "Ask the right questions: the BA as translator", "explain": "A payments BA works with many stakeholders at once, from compliance and business teams to developers and vendors, across several projects and dependent systems. The work starts by asking whether each stakeholder understands the payment concepts, the sequence of payments, the business and its rules, and the payment journey, and whether the BA understands the system, the processing and where they fit in the flow. When a stakeholder does not know an answer, the BA helps them understand the question and reach it, because that translation is what makes the requirements workable, and asking the right questions is the core of stakeholder management, not a soft skill on the side.", "takeaway": "When a stakeholder does not know an answer, the BA helps them understand the question and reach it, because that translation is what makes the requirements workable, and asking the right questions is the core of stakeholder management, not a soft skill on the side.", "visual": {"type": "diagram", "diagram": {"centre": "The BA as stakeholder translator", "parts": [{"label": "Many stakeholders at once", "note": "Compliance and business teams, developers and vendors, across several projects"}, {"label": "Do they understand the concepts?", "note": "Ask whether each stakeholder understands the payment concepts and sequence"}, {"label": "Do they understand the journey?", "note": "Ask whether they understand the business, its rules and the payment journey"}, {"label": "Does the BA understand the system?", "note": "The BA must understand the system, the processing and where they fit in the flow"}, {"label": "Help them reach the answer", "note": "When a stakeholder does not know, help them understand the question and reach it"}, {"label": "Asking the right questions", "note": "Asking the right questions is the core of stakeholder management"}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-082", "seq": 33, "module": "Foundations", "source": "Public post", "title": "BA duties across the delivery lifecycle", "explain": "The analyst owns the thread from discovery to live running: discovery establishes the business problem and the real users, analysis and design convert that understanding into testable requirements, and build and test keep the increment honest against what was agreed. After release the work is not over: the analyst validates the outcome in production and reports what remains open. A lifecycle without that closing loop leaves value unproven.", "takeaway": "A lifecycle without that closing loop leaves value unproven.", "visual": {"type": "diagram", "diagram": {"centre": "Analyst ownership end to end", "parts": [{"label": "Discovery", "note": "Establishes the business problem and the real users."}, {"label": "Analysis and design", "note": "Converts understanding into testable requirements."}, {"label": "Build and test", "note": "Keeps the increment honest against agreed scope."}, {"label": "Post-release validation", "note": "Validates the live outcome and reports what is open."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-013", "seq": 34, "module": "Foundations", "source": "Public post", "title": "The analyst inside an Agile Scrum sprint", "explain": "In Scrum the analyst works the sprint, not around it: refinement turns vague stories into clear acceptance criteria, planning grounds scope and priority in what the team can actually deliver, and delivery is a running conversation as detail emerges. Review and acceptance close the loop by testing the built increment against the criteria agreed. An analyst who only appears at review is too late to shape anything.", "takeaway": "An analyst who only appears at review is too late to shape anything.", "visual": {"type": "diagram", "diagram": {"centre": "Analyst contribution across the sprint", "parts": [{"label": "Refinement", "note": "Turns vague stories into clear acceptance criteria."}, {"label": "Planning", "note": "Grounds scope and priority in deliverable reality."}, {"label": "Delivery", "note": "Answers questions and sharpens detail as it emerges."}, {"label": "Review and acceptance", "note": "Tests the increment against the agreed criteria."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-080", "seq": 35, "module": "Foundations", "source": "Public post", "title": "Functional and non-functional requirements", "explain": "Functional requirements state what the system must do, such as validating a payment or posting a ledger entry, while non-functional requirements state how well it must do it: performance, security, availability, usability and supportability. Both belong in the specification as explicit, testable statements, because a payment that is correct yet too slow or unavailable still fails the customer. Function without fitness for use is not a working payment.", "takeaway": "Function without fitness for use is not a working payment.", "visual": {"type": "diagram", "diagram": {"centre": "What the system does, and how well", "parts": [{"label": "Functional requirements", "note": "State what the system must do, such as validating a payment."}, {"label": "Non-functional requirements", "note": "State how well: performance, security, availability, usability."}, {"label": "Why both matter", "note": "A correct but slow or unavailable payment still fails the customer."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "reconciliation break", "resolution": "repair"}, {"id": "INS-016", "seq": 36, "module": "Foundations", "source": "Public post", "title": "User story or use case: choosing the form", "explain": "A user story is outcome led: it states what a user wants to achieve and why, which makes it the right tool for prioritisation and conversation. A use case is interaction led: it pins down steps, actors and outcomes for one interaction, including decisions and exception paths. Choose by the need in front of you, not by team habit. The wrong form hides the detail that matters.", "takeaway": "The wrong form hides the detail that matters.", "visual": {"type": "diagram", "diagram": {"centre": "Story for outcomes, use case for interaction", "parts": [{"label": "User story", "note": "Outcome led: what a user wants to achieve and why."}, {"label": "Use case", "note": "Interaction led: steps, actors and outcomes of one interaction."}, {"label": "Choosing the form", "note": "Fit the need, not the form the team happens to prefer."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-014", "seq": 37, "module": "Foundations", "source": "Public post", "title": "BRD, FRD and use case: picking the artefact", "explain": "The business requirements document states what the business needs and why, the functional requirements document states in detail what the system must do, and a use case describes one specific interaction between actors and the system. Selection turns on audience, complexity, traceability and delivery context, so each reader gets the detail they need and nothing they do not. The right artefact is the one its reader can act on.", "takeaway": "The right artefact is the one its reader can act on.", "visual": {"type": "diagram", "diagram": {"centre": "Matching the artefact to its reader", "parts": [{"label": "Business requirements document", "note": "States what the business needs and why."}, {"label": "Functional requirements document", "note": "States in detail what the system must do."}, {"label": "Use case", "note": "Describes one interaction between actors and the system."}, {"label": "Selection factors", "note": "Audience, complexity, traceability and delivery context."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-026", "seq": 38, "module": "Foundations", "source": "Public post", "title": "Post-deployment reporting that stakeholders use", "explain": "After release, stakeholders need one factual, regular report covering adoption, incidents, defects, service levels, benefits realised and open risks. Adoption shows whether the change is used, incidents and defects show what is still broken, service levels show whether it performs, and benefits and open risks show whether the intended outcome is on track. A report built this way lets stakeholders decide what needs attention next. Reporting that hides the open items is worse than no report at all.", "takeaway": "Reporting that hides the open items is worse than no report at all.", "visual": {"type": "diagram", "diagram": {"centre": "Post-release reporting stakeholders can act on", "parts": [{"label": "Adoption", "note": "Shows whether people are using the change."}, {"label": "Incidents", "note": "Shows what is still broken."}, {"label": "Defects", "note": "Shows known faults still awaiting a fix."}, {"label": "Service levels", "note": "Shows whether the change is performing."}, {"label": "Benefits realised", "note": "Shows whether the intended outcome is on track."}, {"label": "Open risks", "note": "Shows what still needs attention next."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-076", "seq": 39, "module": "Foundations", "source": "Public post", "title": "Presenting change in business value terms", "explain": "Stakeholders decide on outcomes, not on technical detail, so present the change in their terms: the outcome it delivers, the customer impact, the revenue or cost effect, the compliance position, the timing and the decisions needed. Keep the language plain and tie every point to something the stakeholder is accountable for. A case argued on value gets decided; a case argued on features gets deferred.", "takeaway": "A case argued on value gets decided; a case argued on features gets deferred.", "visual": {"type": "diagram", "diagram": {"centre": "Selling change on value, not features", "parts": [{"label": "Outcome delivered", "note": "State the outcome the change delivers."}, {"label": "Customer impact", "note": "State how customers are affected."}, {"label": "Revenue or cost effect", "note": "State the money effect of the change."}, {"label": "Compliance position", "note": "State where the change leaves compliance."}, {"label": "Timing and decisions needed", "note": "State timing and the decisions stakeholders must make."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-079", "seq": 40, "module": "Foundations", "source": "Public post", "title": "Incident status support teams can repeat", "explain": "During an incident, support needs a status it can repeat to customers without guessing: the symptom in plain language, the users affected, a workaround if one exists, the owner, the severity and the time of the next update. Update at the promised time even if nothing has changed, because silence makes customers assume the worst. Reliable updates are part of the fix, not an extra.", "takeaway": "Reliable updates are part of the fix, not an extra.", "visual": {"type": "diagram", "diagram": {"centre": "A status support can repeat with confidence", "parts": [{"label": "Symptom in plain language", "note": "Plain wording support can repeat without guessing."}, {"label": "Users affected", "note": "Names who the incident touches."}, {"label": "Workaround", "note": "Given if one exists."}, {"label": "Owner and severity", "note": "Names the owner and how severe it is."}, {"label": "Time of the next update", "note": "Update at the promised time even if nothing changed."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "INS-095", "seq": 41, "module": "Foundations", "source": "Public post", "title": "Written records and sign-offs that protect delivery", "explain": "Written communication is the record that protects a delivery: meeting notes name the action, the owner and the due date, decisions are recorded with the assumptions behind them, and approval is obtained explicitly rather than inferred from silence. A sign-off only works if it states exactly what was approved and by whom, leaving no room for a later dispute about scope. If it is not written down, it was not agreed.", "takeaway": "If it is not written down, it was not agreed.", "visual": {"type": "diagram", "diagram": {"centre": "The written record that protects delivery", "parts": [{"label": "Meeting notes", "note": "Name the action, the owner and the due date."}, {"label": "Decisions and assumptions", "note": "Recorded with the assumptions behind them."}, {"label": "Explicit approval", "note": "Obtained, never inferred from silence."}, {"label": "Sign-off content", "note": "States exactly what was approved and by whom."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-083", "seq": 44, "module": "Foundations", "source": "Public post", "title": "Turning prior experience into BA value", "explain": "Moving into business analysis from another domain works when transferable skills are mapped to the work an analyst actually does: experience in operations, support or product maps to domain knowledge, elicitation, documentation, delivery support and outcome measurement. State the mapping explicitly, with concrete examples of work done, rather than listing a previous job title and hoping the reader makes the connection. A mapped skill is a hiring argument; an unmapped job title is just a label.", "takeaway": "A mapped skill is a hiring argument; an unmapped job title is just a label.", "visual": {"type": "diagram", "diagram": {"centre": "Mapping transferable skills to BA work", "parts": [{"label": "Domain knowledge", "note": "Operations, support or product experience maps to it."}, {"label": "Elicitation", "note": "Prior experience maps to drawing out needs."}, {"label": "Documentation", "note": "Prior experience maps to recording requirements."}, {"label": "Delivery support", "note": "Prior experience maps to supporting the build."}, {"label": "Outcome measurement", "note": "Prior experience maps to measuring results."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-096", "seq": 45, "module": "Foundations", "source": "Public post", "title": "Pick a BA domain before learning tools", "explain": "Before learning tools, choose the domain to work in, weighing transferable experience, demand for the domain, genuine interest and a realistic entry path. An analyst is hired for domain understanding first and tool skill second, so a focused domain choice makes learning faster and a profile credible to a recruiter in that domain. Tools are easy to learn; credibility in a domain is what gets the interview.", "takeaway": "Tools are easy to learn; credibility in a domain is what gets the interview.", "visual": {"type": "diagram", "diagram": {"centre": "Domain first, tools second", "parts": [{"label": "Transferable experience", "note": "What can be carried into the domain."}, {"label": "Demand for the domain", "note": "Whether the domain is hiring."}, {"label": "Genuine interest", "note": "Whether the domain truly interests the person."}, {"label": "Realistic entry path", "note": "Whether there is a credible way in."}, {"label": "Why domain first", "note": "Domain understanding is hired before tool skill."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-098", "seq": 46, "module": "Foundations", "source": "Public post", "title": "Making a profile visible to recruiter search", "explain": "Recruiters search by keywords that match the role they are filling, so align profile keywords with the target role, the domain, the skills and the verifiable experience, and a search for that role will surface the profile. Claim only what can be evidenced, because a keyword that cannot be backed up damages credibility in the first conversation. Visibility gets the call; evidence wins it.", "takeaway": "Visibility gets the call; evidence wins it.", "visual": {"type": "diagram", "diagram": {"centre": "Recruiter search visibility", "parts": [{"label": "Target role keywords", "note": "Aligned with the role being sought."}, {"label": "Domain keywords", "note": "Aligned with the target domain."}, {"label": "Skills keywords", "note": "Aligned with the skills held."}, {"label": "Verifiable experience", "note": "Claim only what can be evidenced."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-085", "seq": 47, "module": "Foundations", "source": "Public post", "title": "Answering honestly when you do not know", "explain": "In an interview, not knowing an answer is acceptable if it is handled honestly: state the assumptions being made, explain the reasoning that follows from them, and identify what would need to be validated before committing to an answer. Never bluff. Interviewers test judgement and honesty as much as knowledge, and a confident guess that turns out wrong is worse than a clear statement of what is known and what is not.", "takeaway": "Interviewers test judgement and honesty as much as knowledge, and a confident guess that turns out wrong is worse than a clear statement of what is known and what is not.", "visual": {"type": "diagram", "diagram": {"centre": "Handling an unknown answer honestly", "parts": [{"label": "State assumptions", "note": "Say what is being assumed."}, {"label": "Explain reasoning", "note": "Show the reasoning that follows from the assumptions."}, {"label": "Identify what needs validation", "note": "Name what must be checked before committing."}, {"label": "Avoid bluffing", "note": "A confident wrong guess is worse than a clear statement."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-099", "seq": 48, "module": "Foundations", "source": "Public post", "title": "Working through an unfamiliar scenario", "explain": "Face an unfamiliar scenario in a fixed order: clarify the assumptions, break the flow into its stages, identify the risks at each stage, and state what evidence would be obtained before deciding. This structure shows clear thinking even when the domain is new, and it prevents the answer from becoming a guess. Method is what carries you when knowledge runs out.", "takeaway": "Method is what carries you when knowledge runs out.", "visual": {"type": "diagram", "diagram": {"centre": "A fixed order for unfamiliar scenarios", "parts": [{"label": "Clarify assumptions", "note": "Start by stating the assumptions."}, {"label": "Break the flow into stages", "note": "Work through the flow stage by stage."}, {"label": "Identify risks at each stage", "note": "Name the risk at every stage."}, {"label": "State evidence needed", "note": "Say what evidence would be obtained before deciding."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "SCN-26", "seq": 87, "module": "Foundations", "source": "Public post", "title": "Restore fast, then find the cause", "explain": "Incident and problem management are two disciplines with different clocks: incident restores service fast, problem finds why it happened so it never recurs. A P1 struck mobile banking, fund transfers and ATMs, the war room restored service in about 40 minutes, and the real work began after, a batch process had consumed critical database resources during peak hours. Keep the war room on the clock and the problem manager on the cause, and report both timelines to stakeholders.", "takeaway": "Keep the war room on the clock and the problem manager on the cause, and report both timelines to stakeholders.", "visual": {"type": "diagram", "diagram": {"centre": "Two disciplines, two clocks", "parts": [{"label": "Incident: restore service", "note": "Service restored in about 40 minutes here."}, {"label": "Problem: find the cause", "note": "Cause found so it never recurs."}, {"label": "Evidence of the cause", "note": "Database metrics, batch schedules and the overlap window."}, {"label": "The permanent fix", "note": "Reschedule the batch and add guards and alerts."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "SCN-33", "seq": 88, "module": "Foundations", "source": "Public post", "title": "Peak-only failures mean capacity", "explain": "Failures that appear only at peak hours point at capacity, not code. The 5-Why chain runs from timeouts to slow processing to lagging database queries to high server load to servers not sized for peak traffic. Fix the root, database indexing, increased server capacity and load balancing, then monitor to confirm the failures actually stopped. Remember the pattern: peak-only failures mean capacity, all-day failures mean code or data.", "takeaway": "Remember the pattern: peak-only failures mean capacity, all-day failures mean code or data.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Failures only at peak hours.", "title": "Start from the symptom"}, {"kind": "step", "note": "Timeouts, slow processing, lagging queries, heavy load, undersized servers.", "title": "Walk the 5-Why chain"}, {"kind": "step", "note": "Indexing, more capacity, load balancing.", "title": "Fix the root cause"}, {"kind": "step", "note": "Prove the failures stopped, not just moved.", "title": "Monitor once fixed"}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "RUN7-010", "seq": 116, "module": "Foundations", "source": "Article and reader comments", "title": "No rule picks the first trade instrument", "explain": "No rule fixes which instrument a trade starts with, whether a letter of credit or a bank guarantee. The choice depends on many factors, above all how much security both parties want. Greater appetite for security on both sides calls for more sophisticated payment techniques.", "takeaway": "Greater appetite for security on both sides calls for more sophisticated payment techniques.", "visual": {"type": "diagram", "diagram": {"centre": "Which instrument starts a trade?", "parts": [{"label": "No rule fixes the starting instrument", "note": "There is no rule that fixes which instrument a trade starts with, whether a letter of credit or a bank guarantee."}, {"label": "It depends on many factors", "note": "It depends on many factors."}, {"label": "Security both parties want matters most", "note": "Above all it depends on how much security both parties want."}, {"label": "More security means more sophisticated techniques", "note": "The more security both parties want, the more sophisticated the payment techniques will be."}]}}, "level": "foundation", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D06 Cross-border payments", "messages": []}, {"id": "ABH-18", "seq": 125, "module": "Core", "source": "Public post", "title": "A payment does not move simply A to B", "explain": "The Finastra GPP end-to-end flow has real implementation challenges: ISO 20022 mapping, routing, duplicates, core banking integration, testing and reconciliation. Each of these is a place where a payment can fail or be delayed, and each needs its own design and test coverage.", "takeaway": "Each of these is a place where a payment can fail or be delayed, and each needs its own design and test coverage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "ISO 20022 mapping", "note": "Mapping can fail or delay the payment"}, {"kind": "step", "title": "Routing", "note": "Wrong route delays or fails the payment"}, {"kind": "step", "title": "Duplicate handling", "note": "Duplicates must be caught before posting"}, {"kind": "step", "title": "Core banking integration", "note": "Integration gaps stall the payment"}, {"kind": "step", "title": "Testing", "note": "Each stage needs its own test coverage"}, {"kind": "step", "title": "Reconciliation", "note": "Proves the payment completed correctly"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D09 Payment architecture and technology", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "ABH-25", "seq": 132, "module": "Core", "source": "Public post", "title": "API analysis: look beyond the endpoint", "explain": "Analysing an API means looking beyond the endpoint. A BA must understand the data, the consumers, the dependencies and the impact of a change, because an API that looks simple at the endpoint can have deep downstream effects.", "takeaway": "A BA must understand the data, the consumers, the dependencies and the impact of a change, because an API that looks simple at the endpoint can have deep downstream effects.", "visual": {"type": "diagram", "diagram": {"centre": "API analysis", "parts": [{"label": "Data", "note": "What the API carries and changes"}, {"label": "Consumers", "note": "Who calls the API"}, {"label": "Dependencies", "note": "What the API relies on downstream"}, {"label": "Impact of change", "note": "What a change breaks or moves"}, {"label": "The endpoint", "note": "Only the surface, not the whole API"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D10 APIs and integration", "messages": []}, {"id": "ABH-26", "seq": 133, "module": "Core", "source": "Public post", "title": "Why every BA should understand APIs", "explain": "A BA who understands APIs can work with endpoints, payloads, data gaps, impact analysis, security and backward compatibility. Without that knowledge, the BA cannot write a complete requirement or assess the impact of a change.", "takeaway": "Without that knowledge, the BA cannot write a complete requirement or assess the impact of a change.", "visual": {"type": "diagram", "diagram": {"centre": "A BA who understands APIs", "parts": [{"label": "Endpoints", "note": "Where the API is called"}, {"label": "Payloads", "note": "What the API carries"}, {"label": "Data gaps", "note": "What is missing in the data"}, {"label": "Impact analysis", "note": "What a change affects"}, {"label": "Security", "note": "How the API is protected"}, {"label": "Backward compatibility", "note": "Old callers keep working after a change"}, {"label": "Complete requirements", "note": "Possible only with API knowledge"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-119", "seq": 154, "module": "Core", "source": "Public post", "title": "Vendor capability: check the configuration level", "explain": "A vendor may say a capability exists, but the real question is whether it can be configured at the right level: by country, by entity, by product, or by payment type. A capability that only works globally, when the bank needs it per country, is not fit for purpose. The business analyst must verify the configuration granularity before accepting that a requirement is met, because a demoed feature and a usable feature are not the same thing.", "takeaway": "The business analyst must verify the configuration granularity before accepting that a requirement is met, because a demoed feature and a usable feature are not the same thing.", "visual": {"type": "diagram", "diagram": {"centre": "Vendor capability granularity", "parts": [{"label": "Vendor says it exists", "note": "Vendor may say a capability exists"}, {"label": "Configure by country", "note": "Check whether it can be configured by country"}, {"label": "Configure by entity", "note": "Check whether it can be configured by entity"}, {"label": "Configure by product", "note": "Check whether it can be configured by product"}, {"label": "Configure by payment type", "note": "Check whether it can be configured by payment type"}, {"label": "Global only is not fit", "note": "Capability only working globally is not fit when the bank needs per country"}, {"label": "Verify before accepting", "note": "Analyst must verify granularity before accepting that a requirement is met"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": []}, {"id": "JEB-C10", "seq": 177, "module": "Core", "source": "Public post", "title": "Design for failure: every solution can fail somewhere", "explain": "A payment solution can fail in three places: functionally, when requirements change or were captured wrongly; technically, when processing is delayed, a system is down or performance drops; and in business terms, when a payment is processed with wrong details or a check like verification of payee fails. The BA should plan for each kind of failure, know the alternative when a solution fails, and keep a communication plan with the business and stakeholders. Before implementing, the question to ask is whether all possible failure scenarios have been covered, because one payment change rarely touches only one application, and a solution owner should prioritise the fix and evaluate the options, not chase perfection.", "takeaway": "Before implementing, the question to ask is whether all possible failure scenarios have been covered, because one payment change rarely touches only one application, and a solution owner should prioritise the fix and evaluate the options, not chase perfection.", "visual": {"type": "diagram", "diagram": {"centre": "Design for failure: three places", "parts": [{"label": "Functional failure", "note": "Requirements change or were captured wrongly"}, {"label": "Technical failure", "note": "Processing is delayed, a system is down or performance drops"}, {"label": "Business failure", "note": "A payment is processed with wrong details or a check like verification of payee fails"}, {"label": "Plan for each kind of failure", "note": "The BA should plan for each kind of failure and know the alternative"}, {"label": "Keep a communication plan", "note": "Keep a communication plan with the business and stakeholders"}, {"label": "Cover all failure scenarios", "note": "Ask whether all possible failure scenarios have been covered before implementing"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "system or connectivity failure", "resolution": "repair"}, {"id": "JEB-C14", "seq": 178, "module": "Core", "source": "Public post", "title": "Do not document the requirement, decode it", "explain": "A high-level need such as letting a customer schedule a payment looks simple, but it has to be decoded into business rules: a payment can be set for a future date, next week or next year, recreated or rescheduled with a new effective date, never scheduled for a date in the past, scheduled for several payment types, and cancelled when it is not processed on the requested date. The same applies to messages: in a request to pay such as pain.013, the execution date should not be shown to the customer when the data element is empty. The BA job is to find the business rule behind the requirement rather than mapping one field to another, and a requirement that cannot be written as a simple rule is not a simple requirement.", "takeaway": "The BA job is to find the business rule behind the requirement rather than mapping one field to another, and a requirement that cannot be written as a simple rule is not a simple requirement.", "visual": {"type": "diagram", "diagram": {"centre": "Decode the requirement, do not document it", "parts": [{"label": "Schedule for a future date", "note": "A payment can be set for a future date"}, {"label": "Recreate or reschedule", "note": "A payment can be recreated or rescheduled with a new effective date"}, {"label": "Never schedule in the past", "note": "A payment is never scheduled for a date in the past"}, {"label": "Several payment types", "note": "A payment can be scheduled for several payment types"}, {"label": "Cancel if not processed on the date", "note": "Cancel the payment when it is not processed on the requested date"}, {"label": "pain.013 execution date", "note": "In a request to pay, do not show the execution date when the data is empty"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D04 Messaging and standards", "messages": ["pain.013"]}, {"id": "INS-023", "seq": 191, "module": "Core", "source": "Public post", "title": "Finding customers with repeated failed transactions", "explain": "To find customers with repeated failed transactions, translate the business rule into a time-windowed aggregation: define the window, the failure condition and the threshold, then aggregate the transaction data over that window and validate the data quality before acting on the result. A count that includes test transactions, duplicates or a wrong window will target the wrong customers, so the data quality check is part of the work, not an afterthought. A precise rule plus clean data is the whole method.", "takeaway": "A precise rule plus clean data is the whole method.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the window", "note": "Set the time window for the aggregation."}, {"kind": "step", "title": "Define the failure condition", "note": "Set what counts as a failed transaction."}, {"kind": "step", "title": "Set the threshold", "note": "Set how many failures count as repeated."}, {"kind": "step", "title": "Aggregate the data", "note": "Aggregate transactions over the window."}, {"kind": "step", "title": "Validate data quality", "note": "Exclude test transactions and duplicates."}, {"kind": "step", "title": "Act on the result", "note": "Target the right customers."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "duplicate payment", "resolution": "investigate"}, {"id": "INS-007", "seq": 193, "module": "Core", "source": "Public post", "title": "Handling ambiguous business requirements", "explain": "Ambiguity is normal at the start of a requirement, so work it with discovery questions to find what is actually meant, concrete examples to pin down the behaviour, process observation to see how the work is really done, and playback to confirm the understanding with stakeholders. The output is a requirement that is testable, meaning it states an observable outcome, a boundary condition and an acceptance criterion, rather than a vague wish that no one can verify. Ambiguity handled early is cheap; ambiguity found in testing is expensive.", "takeaway": "Ambiguity handled early is cheap; ambiguity found in testing is expensive.", "visual": {"type": "diagram", "diagram": {"centre": "Turning ambiguity into a testable requirement", "parts": [{"label": "Discovery questions", "note": "Find what is actually meant."}, {"label": "Concrete examples", "note": "Pin down the behaviour."}, {"label": "Process observation", "note": "See how the work is really done."}, {"label": "Playback", "note": "Confirm understanding with stakeholders."}, {"label": "Testable output", "note": "States an observable outcome, a boundary and a criterion."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-008", "seq": 194, "module": "Core", "source": "Public post", "title": "Making requirements testable", "explain": "A requirement is testable when it defines an observable outcome, the boundary conditions, the negative cases and the acceptance criteria. An observable outcome states what can be seen or measured, a boundary condition states where the rule starts and stops, a negative case states what must not happen, and an acceptance criterion states the condition that proves the requirement is met. Without these four, a requirement cannot be verified and a dispute about whether it was delivered cannot be resolved.", "takeaway": "Without these four, a requirement cannot be verified and a dispute about whether it was delivered cannot be resolved.", "visual": {"type": "diagram", "diagram": {"centre": "The four parts of a testable requirement", "parts": [{"label": "Observable outcome", "note": "States what can be seen or measured."}, {"label": "Boundary conditions", "note": "State where the rule starts and stops."}, {"label": "Negative cases", "note": "State what must not happen."}, {"label": "Acceptance criteria", "note": "State the condition that proves it is met."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-009", "seq": 195, "module": "Core", "source": "Public post", "title": "Resolving conflicting stakeholder requirements", "explain": "When stakeholders disagree, compare the competing requirements on value, risk, urgency, customer impact and dependencies, then facilitate a documented decision. The comparison must be evidence based, so each stakeholder can see why one requirement was chosen over another. Document the decision, who made it and why, because an undocumented compromise will be reopened the next time the same stakeholders meet.", "takeaway": "Document the decision, who made it and why, because an undocumented compromise will be reopened the next time the same stakeholders meet.", "visual": {"type": "diagram", "diagram": {"centre": "Deciding between conflicting requirements", "parts": [{"label": "Value", "note": "Compare the competing requirements on value."}, {"label": "Risk", "note": "Compare them on risk."}, {"label": "Urgency", "note": "Compare them on urgency."}, {"label": "Customer impact", "note": "Compare them on customer impact."}, {"label": "Dependencies", "note": "Compare them on dependencies."}, {"label": "Documented decision", "note": "Record the decision, who made it and why."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-015", "seq": 196, "module": "Core", "source": "Public post", "title": "Eliciting requirements from non-technical stakeholders", "explain": "Non-technical stakeholders describe what they need in business language, not in system language, so use interviews to hear the need, workshops to build shared understanding, observation to see how the work is actually done, examples to pin down the detail, and structured playback to confirm the understanding before it is written down. Playback matters most, because it catches misunderstandings while they are still cheap to fix. Confirm before you write, not after you build.", "takeaway": "Confirm before you write, not after you build.", "visual": {"type": "diagram", "diagram": {"centre": "Eliciting from non-technical stakeholders", "parts": [{"label": "Interviews", "note": "Hear the need in business language."}, {"label": "Workshops", "note": "Build shared understanding."}, {"label": "Observation", "note": "See how the work is actually done."}, {"label": "Examples", "note": "Pin down the detail."}, {"label": "Structured playback", "note": "Catches misunderstandings while they are cheap to fix."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "INS-017", "seq": 197, "module": "Core", "source": "Public post", "title": "Resolving a late requirement gap", "explain": "A late requirement gap is found when a piece of the need was missed, so trace the gap back to where it was lost, whether in discovery, analysis, design, implementation or testing, and agree corrective action with the owner of that stage. Tracing the gap to its origin matters because it decides whether the fix is a small correction or a rework of a whole stage, and it prevents the same gap from recurring. Fix the origin, not just the symptom.", "takeaway": "Fix the origin, not just the symptom.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Find the gap", "note": "A piece of the need was missed."}, {"kind": "step", "title": "Trace it to its origin", "note": "Discovery, analysis, design, implementation or testing."}, {"kind": "step", "title": "Agree corrective action", "note": "Agreed with the owner of the stage where it was lost."}, {"kind": "step", "title": "Prevent recurrence", "note": "Tracing the origin stops the same gap recurring."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-018", "seq": 198, "module": "Core", "source": "Public post", "title": "Creating process and data-flow diagrams", "explain": "Choose the diagram that fits the problem being solved, then validate it: a process diagram must show the actors, the triggers, the decisions, the hand-offs and the data stores, and each of these must be checked against reality rather than assumed. Validate the diagram with the people who do the work, because a diagram that does not match the real process will mislead everyone who relies on it. A diagram is only as good as its validation.", "takeaway": "A diagram is only as good as its validation.", "visual": {"type": "diagram", "diagram": {"centre": "Process and data-flow diagrams", "parts": [{"label": "Actors", "note": "Shown and checked against reality."}, {"label": "Triggers", "note": "Shown and checked against reality."}, {"label": "Decisions", "note": "Shown and checked against reality."}, {"label": "Hand-offs", "note": "Shown and checked against reality."}, {"label": "Data stores", "note": "Shown and checked against reality."}, {"label": "Validation", "note": "Validated with the people who do the work."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "INS-019", "seq": 199, "module": "Core", "source": "Public post", "title": "Validating requirements before development", "explain": "Before development starts, run walkthroughs with stakeholders, consistency checks across the requirement set, testability checks on each requirement and a formal sign-off. A walkthrough catches misunderstandings, a consistency check catches contradictions, a testability check catches requirements that cannot be verified, and sign-off records agreement. Skipping validation does not save time; it moves the cost into development and testing, where fixes are far more expensive.", "takeaway": "Skipping validation does not save time; it moves the cost into development and testing, where fixes are far more expensive.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Walkthroughs", "note": "Walkthroughs with stakeholders catch misunderstandings."}, {"kind": "step", "title": "Consistency checks", "note": "Checks across the set catch contradictions."}, {"kind": "step", "title": "Testability checks", "note": "Checks on each requirement catch what cannot be verified."}, {"kind": "step", "title": "Formal sign-off", "note": "Sign-off records agreement before development starts."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "INS-081", "seq": 200, "module": "Core", "source": "Public post", "title": "Requirements Traceability Matrix", "explain": "A traceability matrix connects business objectives to requirements, stories, design, tests, defects and release evidence, with each row showing the chain from the objective through the requirement to the test that proves it. Any change can then be traced forward to its impact and any defect traced back to its origin. Without traceability, a team cannot prove that what was built is what was asked for, and cannot assess the impact of a change safely.", "takeaway": "Without traceability, a team cannot prove that what was built is what was asked for, and cannot assess the impact of a change safely.", "visual": {"type": "diagram", "diagram": {"centre": "Tracing objectives through to release evidence", "parts": [{"label": "Business objectives", "note": "The start of each traceability chain."}, {"label": "Requirements", "note": "Linked from the objective."}, {"label": "Stories", "note": "Linked from the requirement."}, {"label": "Design", "note": "Linked from the story."}, {"label": "Tests", "note": "Prove the requirement is met."}, {"label": "Defects and release evidence", "note": "Traced back to their origin."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-038", "seq": 201, "module": "Core", "source": "Public post", "title": "Stakeholder changes requirements every week", "explain": "Frequent requirement changes are managed with a clear change intake, impact analysis, prioritisation and decision governance. Change intake records what is being asked and why, impact analysis states what the change costs in scope, effort and risk, prioritisation ranks the change against other work, and decision governance records who approved it and why. Without this discipline, weekly changes silently erode the scope and the delivery date.", "takeaway": "Without this discipline, weekly changes silently erode the scope and the delivery date.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Change intake", "note": "Records what is asked and why."}, {"kind": "step", "title": "Impact analysis", "note": "States the cost in scope, effort and risk."}, {"kind": "step", "title": "Prioritisation", "note": "Ranks the change against other work."}, {"kind": "step", "title": "Decision governance", "note": "Records who approved it and why."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-039", "seq": 202, "module": "Core", "source": "Public post", "title": "Business wants two weeks, development estimates six", "explain": "When the business wants two weeks and development estimates six, clarify the minimum outcome that would still be valuable, then work through the options. Slice the scope to the smallest useful increment, identify the dependencies that drive the estimate, and present evidence based trade-offs rather than arguing over the number. The decision is then about what to deliver and what to defer, not about whose estimate is right.", "takeaway": "The decision is then about what to deliver and what to defer, not about whose estimate is right.", "visual": {"type": "diagram", "diagram": {"centre": "Two weeks wanted, six estimated", "parts": [{"label": "Minimum valuable outcome", "note": "Clarify the smallest outcome still worth having."}, {"label": "Slice the scope", "note": "Cut scope to the smallest useful increment."}, {"label": "Dependencies", "note": "Identify what drives the estimate."}, {"label": "Evidence based trade-offs", "note": "Present trade-offs rather than arguing over the number."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-044", "seq": 203, "module": "Core", "source": "Public post", "title": "Senior management asks for a solution, not requirements", "explain": "When senior management asks for a solution without requirements, reframe the request around outcomes, constraints, options and decision criteria: ask what outcome is needed, what constraints apply, what options exist and what criteria will decide between them. This turns a request for a specific solution into a decision that can be made on evidence, and it avoids building something that does not solve the real problem. Reframe the ask before you build the answer.", "takeaway": "Reframe the ask before you build the answer.", "visual": {"type": "diagram", "diagram": {"centre": "Solution requested without requirements", "parts": [{"label": "Outcomes", "note": "Ask what outcome is needed."}, {"label": "Constraints", "note": "Ask what constraints apply."}, {"label": "Options", "note": "Ask what options exist."}, {"label": "Decision criteria", "note": "Ask what criteria will decide between options."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-045", "seq": 204, "module": "Core", "source": "Public post", "title": "Business says complete, developers disagree", "explain": "When the business believes requirements are complete but developers disagree, the gap is usually in interpretation rather than in content. Use concrete examples to show how each side reads the requirement, run walkthroughs to surface the differences, use traceability to show what is covered and what is not, and agree shared definitions for the terms that are being read differently. Close the interpretation gap before development, because it is far cheaper to agree on meaning now than to rebuild later.", "takeaway": "Close the interpretation gap before development, because it is far cheaper to agree on meaning now than to rebuild later.", "visual": {"type": "diagram", "diagram": {"centre": "Business says complete, developers disagree", "parts": [{"label": "Concrete examples", "note": "Show how each side reads the requirement."}, {"label": "Walkthroughs", "note": "Surface the differences in interpretation."}, {"label": "Traceability", "note": "Show what is covered and what is not."}, {"label": "Shared definitions", "note": "Agree definitions for terms read differently."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-046", "seq": 205, "module": "Core", "source": "Public post", "title": "Digital transformation faces user resistance", "explain": "User resistance to a digital change usually has a cause that can be identified, so map the impacts on each group of users, identify the stakeholder groups and their concerns, define the training needs, find champions who will support the change, collect feedback and measure adoption. Resistance that is understood can be addressed; resistance that is dismissed as stubbornness will grow and will damage the change. Diagnose resistance before you try to overcome it.", "takeaway": "Diagnose resistance before you try to overcome it.", "visual": {"type": "diagram", "diagram": {"centre": "User resistance to digital change", "parts": [{"label": "Impacts on each user group", "note": "Map how the change affects each group."}, {"label": "Stakeholder groups and concerns", "note": "Identify who is concerned and about what."}, {"label": "Training needs", "note": "Define what training each group needs."}, {"label": "Champions", "note": "Find people who will support the change."}, {"label": "Feedback and adoption", "note": "Collect feedback and measure adoption."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-047", "seq": 206, "module": "Core", "source": "Public post", "title": "Demonstrating measurable BA contribution", "explain": "An analyst demonstrates contribution by connecting process changes to measurable outcomes: link the change to cost, cycle time, error rates, customer experience and benefits realisation, and measure before and after so the improvement can be shown rather than claimed. Benefits realisation is the final step: it proves that the change delivered the value that justified it, which is what stakeholders remember. Measured value is the analyst's evidence, not a claim.", "takeaway": "Measured value is the analyst's evidence, not a claim.", "visual": {"type": "diagram", "diagram": {"centre": "Proving BA contribution with measures", "parts": [{"label": "Cost", "note": "Link the change to cost, measure before and after."}, {"label": "Cycle time", "note": "Link the change to cycle time, measure before and after."}, {"label": "Error rates", "note": "Link the change to error rates, measure before and after."}, {"label": "Customer experience", "note": "Link the change to customer experience."}, {"label": "Benefits realisation", "note": "The final step, proves the value delivered."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-010", "seq": 207, "module": "Core", "source": "Public post", "title": "Managing requirement change mid-sprint", "explain": "A change requested mid-sprint must be assessed before it is agreed: assess the scope of the change, the impact on the sprint goal, the effort required and the dependencies it introduces. Only then decide whether to accept it, defer it or swap it for something else. Accepting a change without this assessment silently breaks the sprint goal and leaves the team accountable for a target it never agreed to.", "takeaway": "Accepting a change without this assessment silently breaks the sprint goal and leaves the team accountable for a target it never agreed to.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess the scope", "note": "Assess the scope of the change."}, {"kind": "step", "title": "Assess the sprint goal impact", "note": "Assess the impact on the sprint goal."}, {"kind": "step", "title": "Assess the effort", "note": "Assess the effort the change requires."}, {"kind": "step", "title": "Assess dependencies", "note": "Assess the dependencies it introduces."}, {"kind": "decision", "title": "Decide accept, defer or swap", "note": "Decide only after the assessment."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-052", "seq": 208, "module": "Core", "source": "Public post", "title": "Change requested after 70 percent of the sprint", "explain": "A change requested when most of the sprint is done needs a careful assessment: establish the reason for the change, the effort it requires, the dependencies it affects and the options the product owner has, and do not silently compromise the sprint goal to absorb it. The product owner decides, with the evidence in front of them, whether the change is worth the disruption or whether it waits for the next sprint. A late change is a decision, not an instruction.", "takeaway": "A late change is a decision, not an instruction.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Establish the reason", "note": "Establish the reason for the change."}, {"kind": "step", "title": "Assess the effort", "note": "Assess the effort it requires."}, {"kind": "step", "title": "Assess dependencies", "note": "Assess the dependencies it affects."}, {"kind": "step", "title": "Present the options", "note": "Lay out the options the product owner has."}, {"kind": "decision", "title": "Product owner decides", "note": "Worth the disruption, or it waits for next sprint."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-053", "seq": 209, "module": "Core", "source": "Public post", "title": "Two senior stakeholders want opposite outcomes", "explain": "When two senior stakeholders want opposite outcomes, facilitate an evidence based prioritisation and document the accountable decision. Lay out the value, the risk, the cost and the customer impact of each requirement, let the evidence drive the ranking, and record who made the decision and why. A documented decision ends the debate; an undocumented one will be reopened every time the stakeholders meet.", "takeaway": "A documented decision ends the debate; an undocumented one will be reopened every time the stakeholders meet.", "visual": {"type": "diagram", "diagram": {"centre": "Two senior stakeholders, opposite outcomes", "parts": [{"label": "Value", "note": "Lay out the value of each requirement."}, {"label": "Risk", "note": "Lay out the risk of each requirement."}, {"label": "Cost", "note": "Lay out the cost of each requirement."}, {"label": "Customer impact", "note": "Lay out the customer impact of each requirement."}, {"label": "Accountable decision", "note": "Record who made the decision and why."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-037", "seq": 210, "module": "Core", "source": "Public post", "title": "Business process change just before UAT", "explain": "A process change just before user acceptance testing must be assessed for requirement impact, test scope, release risk and decision rights: determine which requirements change, which tests must be added or rerun, what risk the change introduces to the release, and who has the authority to approve it. A change approved without this assessment can invalidate the testing that has already been done and put the release date at risk. Never let a late change silently void completed testing.", "takeaway": "Never let a late change silently void completed testing.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess requirement impact", "note": "Determine which requirements change."}, {"kind": "step", "title": "Assess test scope", "note": "Determine which tests must be added or rerun."}, {"kind": "step", "title": "Assess release risk", "note": "Determine what risk the change adds to the release."}, {"kind": "step", "title": "Confirm decision rights", "note": "Confirm who has the authority to approve it."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-041", "seq": 211, "module": "Core", "source": "Public post", "title": "User rejects a feature built to signed-off requirements", "explain": "When a user rejects a feature that was built to signed-off requirements, determine whether the issue is a defect, an ambiguity, a missed need or a scope change. A defect means the build does not match the requirement, an ambiguity means the requirement was read differently, a missed need means the requirement was incomplete, and a scope change means the need has moved. Each cause has a different owner and a different fix, so classifying it correctly is the first step.", "takeaway": "Each cause has a different owner and a different fix, so classifying it correctly is the first step.", "visual": {"type": "diagram", "diagram": {"centre": "User rejects a signed-off feature", "parts": [{"label": "Defect", "note": "The build does not match the requirement."}, {"label": "Ambiguity", "note": "The requirement was read differently."}, {"label": "Missed need", "note": "The requirement was incomplete."}, {"label": "Scope change", "note": "The need has moved since sign-off."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "message mismatch", "resolution": "reject"}, {"id": "INS-020", "seq": 212, "module": "Core", "source": "Public post", "title": "Planning UAT and preparing test cases", "explain": "User acceptance testing coverage is derived from the business journeys, the acceptance criteria, the roles involved and the exception paths. For each business journey, define the acceptance criteria that prove it works, the roles that must be able to perform it, and the exception paths that must be handled. Test cases built from this coverage test the business outcome rather than the system mechanics, which is what acceptance testing is for.", "takeaway": "Test cases built from this coverage test the business outcome rather than the system mechanics, which is what acceptance testing is for.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Map business journeys", "note": "Coverage starts from the business journeys."}, {"kind": "step", "title": "Define acceptance criteria", "note": "Criteria that prove each journey works."}, {"kind": "step", "title": "Identify the roles", "note": "The roles that must be able to perform each journey."}, {"kind": "step", "title": "Cover exception paths", "note": "The exception paths that must be handled."}, {"kind": "step", "title": "Build the test cases", "note": "Cases test the business outcome, not system mechanics."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-060", "seq": 213, "module": "Core", "source": "Public post", "title": "BA role in SIT defect discussions", "explain": "In system integration testing defect discussions, the analyst assesses reproducibility, requirement traceability, business impact, fix validation and regression. Reproducibility decides whether the defect is real, traceability shows which requirement it breaks, business impact decides its priority, fix validation confirms the fix works, and regression confirms nothing else broke. This assessment keeps defect discussions focused on evidence rather than on opinion.", "takeaway": "This assessment keeps defect discussions focused on evidence rather than on opinion.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess reproducibility", "note": "Reproducibility decides whether the defect is real."}, {"kind": "step", "title": "Check traceability", "note": "Traceability shows which requirement it breaks."}, {"kind": "step", "title": "Assess business impact", "note": "Business impact decides the priority."}, {"kind": "step", "title": "Validate the fix", "note": "Fix validation confirms the fix works."}, {"kind": "step", "title": "Check regression", "note": "Regression confirms nothing else broke."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-061", "seq": 214, "module": "Core", "source": "Public post", "title": "BA support during deployment and hypercare", "explain": "During deployment and hypercare, the analyst monitors the critical journeys, the exception rates, the unresolved transactions and the stakeholder updates. Critical journeys show whether customers can complete their payments, exception rates show whether the system is handling failures, unresolved transactions show what still needs attention, and stakeholder updates keep everyone informed. Hypercare ends when these measures are stable, not when a fixed number of days has passed.", "takeaway": "Hypercare ends when these measures are stable, not when a fixed number of days has passed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Monitor critical journeys", "note": "Show whether customers can complete payments."}, {"kind": "step", "title": "Monitor exception rates", "note": "Show whether the system handles failures."}, {"kind": "step", "title": "Monitor unresolved transactions", "note": "Show what still needs attention."}, {"kind": "step", "title": "Send stakeholder updates", "note": "Keep everyone informed through hypercare."}, {"kind": "step", "title": "End hypercare when stable", "note": "Ends when measures are stable, not after fixed days."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "system or connectivity failure", "resolution": "repair"}, {"id": "INS-051", "seq": 215, "module": "Core", "source": "Public post", "title": "Requirement, development, testing or environment miss", "explain": "When intended behaviour diverges from production behaviour, use a layered failure model to locate where it went wrong: check the requirement first, then the development, then the testing, then the environment, and find the layer where the divergence was introduced. Locating the layer matters because it decides whether the fix is a requirement correction, a code change, a test improvement or an environment fix, and it prevents the same miss from recurring. Fix at the layer that introduced the fault.", "takeaway": "Fix at the layer that introduced the fault.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Check the requirement layer", "note": "Find whether the divergence started in requirements."}, {"kind": "step", "title": "Check the development layer", "note": "Find whether it started in development."}, {"kind": "step", "title": "Check the testing layer", "note": "Find whether it started in testing."}, {"kind": "step", "title": "Check the environment layer", "note": "Find whether it started in the environment."}, {"kind": "step", "title": "Fix at the layer found", "note": "The layer decides the fix and prevents recurrence."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-021", "seq": 216, "module": "Core", "source": "Public post", "title": "KPI design for a digital banking application", "explain": "Key performance indicators for a digital banking application should cover adoption, task completion, failure, service, risk and customer outcome measures. Adoption shows whether customers use the feature, task completion shows whether they can finish what they start, failure shows where they are blocked, service shows whether the system performs, risk shows whether controls are holding, and customer outcome shows whether the feature delivered value. A KPI set that covers only one of these gives a misleading picture of health.", "takeaway": "A KPI set that covers only one of these gives a misleading picture of health.", "visual": {"type": "diagram", "diagram": {"centre": "KPIs that show true digital banking health", "parts": [{"label": "Adoption", "note": "Whether customers use the feature."}, {"label": "Task completion", "note": "Whether customers finish what they start."}, {"label": "Failure", "note": "Where customers are blocked."}, {"label": "Service", "note": "Whether the system performs."}, {"label": "Risk", "note": "Whether controls are holding."}, {"label": "Customer outcome", "note": "Whether the feature delivered value."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "system or connectivity failure", "resolution": "reject"}, {"id": "INS-072", "seq": 217, "module": "Core", "source": "Public post", "title": "Why customers abandon the payment page", "explain": "Customers abandon a payment page for reasons that can be found in the evidence: analyse the funnel to see where they drop off, the validation errors they encounter, the latency they experience, the payment options available and the user experience they report. Each of these points to a different fix, so the analysis must separate them rather than treating abandonment as a single problem with a single cause. Abandonment is several problems wearing one label.", "takeaway": "Abandonment is several problems wearing one label.", "visual": {"type": "diagram", "diagram": {"centre": "Diagnosing payment page abandonment", "parts": [{"label": "Funnel drop-off", "note": "Where customers drop off."}, {"label": "Validation errors", "note": "The errors customers encounter."}, {"label": "Latency", "note": "The latency customers experience."}, {"label": "Payment options", "note": "The payment options available."}, {"label": "User experience", "note": "What customers report."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D06 Cross-border payments", "messages": [], "resolution": "repair"}, {"id": "INS-073", "seq": 218, "module": "Core", "source": "Public post", "title": "Why loan approval time rises from hours to days", "explain": "When loan approval time rises from hours to days, map the process to find the bottleneck: look for queues where applications wait, manual checks that add delay, dependencies on other teams or systems, and rework where applications are sent back for correction. The bottleneck is usually a queue or a manual step rather than the decision itself, so measuring where time is actually spent is more useful than asking people where they think the delay is. Measure the clock, not the opinion.", "takeaway": "Measure the clock, not the opinion.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Map the process", "note": "Map the approval process to find the bottleneck."}, {"kind": "step", "title": "Find the queues", "note": "Look for queues where applications wait."}, {"kind": "step", "title": "Find manual checks", "note": "Look for manual checks that add delay."}, {"kind": "step", "title": "Find dependencies", "note": "Look for dependencies on other teams or systems."}, {"kind": "step", "title": "Find the rework", "note": "Look for applications sent back for correction."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "INS-074", "seq": 219, "module": "Core", "source": "Public post", "title": "Why UAT fails despite all test cases passing", "explain": "User acceptance testing can fail even when all test cases pass, because passing test cases do not prove the business need is met. Check the test design for gaps, the representativeness of the test data, the expected outcomes for correctness, and whether the unmet business need was ever covered by a test at all. A test suite that passes but does not represent the real business journeys gives false confidence and a failed acceptance.", "takeaway": "A test suite that passes but does not represent the real business journeys gives false confidence and a failed acceptance.", "visual": {"type": "diagram", "diagram": {"centre": "Passing tests, failed acceptance", "parts": [{"label": "Test design gaps", "note": "Check the design for gaps."}, {"label": "Representativeness of test data", "note": "Check the data matches real business use."}, {"label": "Expected outcomes", "note": "Check the expected outcomes are correct."}, {"label": "Unmet business need", "note": "Check whether the need was ever covered by a test."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-075", "seq": 220, "module": "Core", "source": "Public post", "title": "Why the same change is requested every sprint", "explain": "When the same change is requested every sprint, the root cause is usually unresolved: look for an unresolved root need that the change does not actually satisfy, weak discovery that missed the real requirement, policy uncertainty that leaves the team guessing, or a lack of decision ownership so no one can say no. Fixing the root cause stops the repeated request; implementing the same change again will not. Repeat requests are a symptom, not a backlog.", "takeaway": "Repeat requests are a symptom, not a backlog.", "visual": {"type": "diagram", "diagram": {"centre": "Same change requested every sprint", "parts": [{"label": "Unresolved root need", "note": "The change does not actually satisfy the need."}, {"label": "Weak discovery", "note": "The real requirement was missed."}, {"label": "Policy uncertainty", "note": "Uncertainty leaves the team guessing."}, {"label": "Lack of decision ownership", "note": "No one can say no to the request."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-077", "seq": 221, "module": "Core", "source": "Public post", "title": "Translate rules and edge cases for developers", "explain": "Developers need rules and edge cases stated precisely: explain the triggers that start a rule, the conditions that apply, the data involved, the expected behaviour and the failure outcomes. A rule stated as a business sentence leaves the developer guessing about the boundary, while a rule stated with triggers, conditions and failure outcomes can be built and tested without further questions. Precision at the boundary is what makes a rule buildable.", "takeaway": "Precision at the boundary is what makes a rule buildable.", "visual": {"type": "diagram", "diagram": {"centre": "Rules and edge cases developers can build from", "parts": [{"label": "Triggers", "note": "State what starts a rule."}, {"label": "Conditions", "note": "State the conditions that apply."}, {"label": "Data involved", "note": "State the data the rule uses."}, {"label": "Expected behaviour", "note": "State what should happen."}, {"label": "Failure outcomes", "note": "State what happens when the rule fails."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-078", "seq": 222, "module": "Core", "source": "Public post", "title": "Translate scenarios into testable QA coverage", "explain": "Test coverage is built by translating business scenarios into positive, negative, boundary and regression scenarios with expected results. Positive scenarios prove the happy path works, negative scenarios prove invalid input is handled, boundary scenarios prove the limits behave correctly, and regression scenarios prove existing behaviour still works. Each scenario needs an expected result, because a test without an expected result cannot pass or fail.", "takeaway": "Each scenario needs an expected result, because a test without an expected result cannot pass or fail.", "visual": {"type": "diagram", "diagram": {"centre": "Business scenarios into QA coverage", "parts": [{"label": "Positive scenarios", "note": "Prove the happy path works."}, {"label": "Negative scenarios", "note": "Prove invalid input is handled."}, {"label": "Boundary scenarios", "note": "Prove the limits behave correctly."}, {"label": "Regression scenarios", "note": "Prove existing behaviour still works."}, {"label": "Expected results", "note": "Every scenario needs one, or it cannot pass or fail."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "payment rejected or returned", "resolution": "repair"}, {"id": "INS-091", "seq": 223, "module": "Core", "source": "Public post", "title": "Feature complete, but the business problem remains", "explain": "A feature can be technically complete while the business problem remains unsolved, so revisit the hypothesis behind the feature, the actual user behaviour, the process adoption, the operational constraints and the outcome measures. The gap is usually that the feature was built as specified but the hypothesis was wrong, or that users did not adopt it, or that an operational constraint was missed. Measuring the outcome rather than the delivery reveals the gap.", "takeaway": "Measuring the outcome rather than the delivery reveals the gap.", "visual": {"type": "diagram", "diagram": {"centre": "Feature complete, problem remains", "parts": [{"label": "Hypothesis behind the feature", "note": "Revisit whether the hypothesis was right."}, {"label": "Actual user behaviour", "note": "Check what users really do."}, {"label": "Process adoption", "note": "Check whether users adopted the change."}, {"label": "Operational constraints", "note": "Check for a constraint that was missed."}, {"label": "Outcome measures", "note": "Measure the outcome rather than the delivery."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-092", "seq": 224, "module": "Core", "source": "Public post", "title": "Loan approval time: two hours to two days", "explain": "When loan approval time increases from two hours to two days, analyse queue time, manual reviews, document quality, decision rules and hand-offs. Queue time shows where applications wait, manual reviews show where human effort adds delay, document quality shows where rework is created, decision rules show where the logic is slow, and hand-offs show where work is lost between teams. The fix depends on which of these is actually causing the delay, so measure before changing anything.", "takeaway": "The fix depends on which of these is actually causing the delay, so measure before changing anything.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Analyse queue time", "note": "Queue time shows where applications wait."}, {"kind": "step", "title": "Analyse manual reviews", "note": "Manual reviews show where human effort adds delay."}, {"kind": "step", "title": "Analyse document quality", "note": "Document quality shows where rework is created."}, {"kind": "step", "title": "Analyse decision rules", "note": "Decision rules show where the logic is slow."}, {"kind": "step", "title": "Analyse hand-offs", "note": "Hand-offs show where work is lost between teams."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "repair"}, {"id": "INS-093", "seq": 225, "module": "Core", "source": "Public post", "title": "Why stakeholders repeat the same change request", "explain": "When stakeholders repeat the same change request, investigate the root need, the decision latency, the incomplete discovery and the feedback loops. The root need may never have been satisfied, the decision may have taken so long that the requester assumed it was ignored, the discovery may have missed the real requirement, or the feedback loop may never have closed the loop with the requester. Each cause has a different fix, and implementing the change again without fixing the cause will only repeat the cycle.", "takeaway": "Each cause has a different fix, and implementing the change again without fixing the cause will only repeat the cycle.", "visual": {"type": "diagram", "diagram": {"centre": "Stakeholders repeat the same request", "parts": [{"label": "Root need", "note": "It may never have been satisfied."}, {"label": "Decision latency", "note": "A slow decision can look like being ignored."}, {"label": "Incomplete discovery", "note": "The real requirement may have been missed."}, {"label": "Feedback loops", "note": "The loop with the requester may never have closed."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-094", "seq": 226, "module": "Core", "source": "Public post", "title": "BA ownership without direct authority", "explain": "An analyst often owns delivery outcomes without having direct authority over the teams involved, so drive clarity by stating what is needed and by when, keep decision records so accountability is visible, follow up on actions rather than assuming they will happen, and escalate transparently when a decision or a delivery is blocked. Ownership without authority works through clarity and follow-through, not through control. Authority is borrowed; clarity is owned.", "takeaway": "Authority is borrowed; clarity is owned.", "visual": {"type": "diagram", "diagram": {"centre": "Owning outcomes without authority", "parts": [{"label": "State what is needed and by when", "note": "Drive clarity on the ask and the date."}, {"label": "Decision records", "note": "Keep accountability visible."}, {"label": "Follow up on actions", "note": "Do not assume actions will happen."}, {"label": "Escalate transparently", "note": "Escalate when a decision or delivery is blocked."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "escalate"}, {"id": "INS-056", "seq": 227, "module": "Core", "source": "Public post", "title": "Client says the new process damaged operations", "explain": "When a client says a new process has damaged their operations, acknowledge the impact first, then establish the facts: provide a safe workaround so the client can keep operating, agree the recovery communications, and investigate what actually changed. Acknowledging the impact does not admit fault, it shows the client is being taken seriously, and it creates the space to find the real cause without the conversation becoming adversarial. Empathy first, evidence second, blame never.", "takeaway": "Empathy first, evidence second, blame never.", "visual": {"type": "diagram", "diagram": {"centre": "Client says the process damaged operations", "parts": [{"label": "Acknowledge the impact first", "note": "Shows the client is taken seriously."}, {"label": "Safe workaround", "note": "Lets the client keep operating."}, {"label": "Recovery communications", "note": "Agreed with the client."}, {"label": "Investigate what changed", "note": "Find the real cause without becoming adversarial."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-068", "seq": 228, "module": "Core", "source": "Public post", "title": "Evidence required during a payment surge", "explain": "During a payment surge, the evidence needed is specific: collect transaction IDs, gateway responses, API logs, timeout rates, timestamps and reconciliation status. Transaction IDs link the evidence to individual payments, gateway responses and API logs show what each system did, timeout rates show where the system is struggling, timestamps show when it happened, and reconciliation status shows whether money is accounted for. Without this evidence, the incident response is guesswork.", "takeaway": "Without this evidence, the incident response is guesswork.", "visual": {"type": "diagram", "diagram": {"centre": "Evidence to collect during a payment surge", "parts": [{"label": "Transaction IDs", "note": "Link evidence to individual payments."}, {"label": "Gateway responses", "note": "Show what the gateway did."}, {"label": "API logs", "note": "Show what each system did."}, {"label": "Timeout rates", "note": "Show where the system is struggling."}, {"label": "Timestamps", "note": "Show when it happened."}, {"label": "Reconciliation status", "note": "Shows whether money is accounted for."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "INS-063", "seq": 229, "module": "Core", "source": "Public post", "title": "Coordinating business, dev, QA, gateway and support", "explain": "Coordinating business, development, QA, gateway and support teams during an incident needs one incident view, clear owners, evidence requests and an update cadence. One incident view prevents each team from working from a different picture, clear owners prevent work from falling between teams, evidence requests ensure the right data is collected, and a regular update cadence keeps everyone aligned. Without this coordination, teams duplicate effort and the incident lasts longer than it should.", "takeaway": "Without this coordination, teams duplicate effort and the incident lasts longer than it should.", "visual": {"type": "diagram", "diagram": {"centre": "Coordinating teams during an incident", "parts": [{"label": "One incident view", "note": "Prevents teams working from different pictures."}, {"label": "Clear owners", "note": "Prevents work falling between teams."}, {"label": "Evidence requests", "note": "Ensure the right data is collected."}, {"label": "Update cadence", "note": "Keeps everyone aligned through the incident."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "duplicate payment", "resolution": "repair"}, {"id": "INS-097", "seq": 230, "module": "Core", "source": "Public post", "title": "Build practical BA projects, not only theory", "explain": "A practical BA portfolio is built from real work rather than from theory alone: create a portfolio with a problem statement, process maps, user stories, an API contract and UAT evidence, so that a reviewer can see the full chain from problem to delivered outcome. Theory shows what was studied; a portfolio shows what was actually done, which is what an employer needs to see. Show the chain, not the certificate.", "takeaway": "Show the chain, not the certificate.", "visual": {"type": "diagram", "diagram": {"centre": "Practical BA portfolio, not only theory", "parts": [{"label": "Problem statement", "note": "States the problem the work solved."}, {"label": "Process maps", "note": "Show the process as it was mapped."}, {"label": "User stories", "note": "Show the needs as stories."}, {"label": "API contract", "note": "Shows the integration as defined."}, {"label": "UAT evidence", "note": "Shows the outcome was tested and accepted."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-084", "seq": 231, "module": "Core", "source": "Public post", "title": "Present project experience with evidence", "explain": "Present project experience by structuring the walkthrough around the problem, the role played, the decisions made, the systems involved, the risks managed and the measurable result. This structure shows the scope of the work and the contribution made, rather than a list of tasks. Measurable results matter most, because they prove the work delivered value rather than simply occupying time.", "takeaway": "Measurable results matter most, because they prove the work delivered value rather than simply occupying time.", "visual": {"type": "diagram", "diagram": {"centre": "Presenting project experience", "parts": [{"label": "Problem", "note": "Structure the walkthrough around the problem."}, {"label": "Role played", "note": "Show the part played in the work."}, {"label": "Decisions made", "note": "Show the judgement exercised."}, {"label": "Systems involved", "note": "Show the technical landscape."}, {"label": "Risks managed", "note": "Show the risks handled."}, {"label": "Measurable result", "note": "Proves the work delivered value."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-100", "seq": 232, "module": "Core", "source": "Public post", "title": "Walk through a current project and your BA role", "explain": "When walking through a current project, structure the walkthrough around context, scope, stakeholders, systems, deliverables, decisions and outcomes. Context sets the scene, scope shows the size of the work, stakeholders show who was involved, systems show the technical landscape, deliverables show what was produced, decisions show judgement, and outcomes show the result. This structure keeps the walkthrough focused and complete, and it prevents it from becoming a list of tasks.", "takeaway": "This structure keeps the walkthrough focused and complete, and it prevents it from becoming a list of tasks.", "visual": {"type": "diagram", "diagram": {"centre": "Walking through a current project", "parts": [{"label": "Context", "note": "Sets the scene."}, {"label": "Scope", "note": "Shows the size of the work."}, {"label": "Stakeholders", "note": "Shows who was involved."}, {"label": "Systems", "note": "Shows the technical landscape."}, {"label": "Deliverables", "note": "Shows what was produced."}, {"label": "Decisions", "note": "Show judgement."}, {"label": "Outcomes", "note": "Show the result."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "SCN-28", "seq": 353, "module": "Core", "source": "Public post", "title": "Chase the cause upstream, not the symptom", "explain": "Start from the symptom and walk upstream, because the most visible error is rarely the root cause and a payment timeout is often a downstream effect of something earlier. Trace the full end-to-end lifecycle from where the message was created, hop by hop with timestamps and message copies. Here the culprit was a small deviation from payment message standards, which compounds downstream, so validate messages against the standard at every boundary, not just at entry.", "takeaway": "Here the culprit was a small deviation from payment message standards, which compounds downstream, so validate messages against the standard at every boundary, not just at entry.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Begin where the message was created.", "title": "Trace back to message creation"}, {"kind": "step", "note": "Timestamps and message copies, hop by hop.", "title": "Trace hop by hop"}, {"kind": "step", "note": "Small deviation from message standards.", "title": "Find the standards deviation"}, {"kind": "step", "note": "Every boundary, not just entry.", "title": "Check every boundary"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D04 Messaging and standards", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "JEB-F08", "seq": 361, "module": "Core", "source": "Public post", "title": "SDD resubmission: define the timing rule first", "explain": "When a collection is rejected, the originator can resubmit it only once the resubmission timing rule is clear, so before asking for the rule, the BA should ask what the rule must answer: how it aligns the original timing so the resubmission improves on the original outcome. The method compares the clean-state timeline of a complete collection with the rejection reason and the proposed resubmission timeline, and tests if the earliest resubmission point is tied to the original collection date. Once the rule is clear it goes into the backlog so the feature can be built quickly, and the BA should first see how the business operation works in practice, face to face.", "takeaway": "Once the rule is clear it goes into the backlog so the feature can be built quickly, and the BA should first see how the business operation works in practice, face to face.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The originator wants to resubmit to the debtor", "title": "Collection rejected"}, {"kind": "decision", "note": "Ask first what the rule needs to tell the business", "title": "What must the timing rule answer?"}, {"kind": "step", "note": "Clean-state timeline against the proposed resubmission timeline", "title": "Compare timelines and the rejection reason"}, {"kind": "decision", "note": "Test whether resubmission timing is tied to the original date", "title": "Does the earliest point depend on the original date?"}, {"kind": "step", "note": "A clear timing rule lets the feature be built quickly", "title": "Put the clear rule in the backlog"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "JEB-F06", "seq": 362, "module": "Core", "source": "Public post", "title": "Read the reason code, then investigate the failure", "explain": "A pacs.004 return tells a bank that a payment was returned, but on its own it does not say why it failed, while the pacs.002 carries the return reason code, and only when the two are reconciled does the bank know whether to flag, retry, investigate, replace or reject the payment. Gap analysis compares the instruction against its structure, the investigation against its evidence, the business rules against their procedure, and the return reason against its expected outcome. It measures the delta between the process the bank has and the process it needs, because a faulty gap analysis steers the technical team toward the wrong process.", "takeaway": "It measures the delta between the process the bank has and the process it needs, because a faulty gap analysis steers the technical team toward the wrong process.", "visual": {"type": "diagram", "diagram": {"centre": "Reason code plus investigation", "parts": [{"label": "Instruction vs structure", "note": "Compare the payment instruction with its structure"}, {"label": "Investigation vs evidence", "note": "Compare the investigation process with its evidence"}, {"label": "Rules vs procedure", "note": "Compare business rules with their procedure"}, {"label": "Reason vs outcome", "note": "Compare the return reason with the expected outcome"}, {"label": "pacs.002 plus pacs.004", "note": "Reconcile both messages to learn why the payment failed"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": ["pacs.004", "pacs.002"], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "JEB-F01", "seq": 363, "module": "Core", "source": "Public post", "title": "Reject or repair: decide from the business context", "explain": "A payment rejected for a format fault is not always a rejection, because the right response depends on where the fault sits, whether the original instruction is intact, who owns the defect, and whether the agreement permits a correction. When the bank's own pacs.008 is wrong, fix the mapping and repair and resubmit after status and duplicate checks, and when the customer pain.001 is wrong and the agreement allows correction, repair within the agreement and keep the audit trail, while a customer pain.001 fault with no agreement gets a rejection with a clear reason. A format fault is a diagnosis to make first, not a verdict, and the business context decides whether the payment is repaired or rejected.", "takeaway": "A format fault is a diagnosis to make first, not a verdict, and the business context decides whether the payment is repaired or rejected.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "A format fault does not decide reject or repair on its own", "title": "Payment rejected for format fault"}, {"kind": "decision", "note": "Locate the fault and check the instruction is intact", "title": "Fault in customer pain.001 or own pacs.008?"}, {"kind": "decision", "note": "Repair only where the agreement allows it", "title": "Does the agreement permit correction?"}, {"kind": "step", "note": "Fix own mapping defects, repair within the agreement, reject with a reason when correction is not allowed", "title": "Repair and resubmit, or reject clearly"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pain.001", "pacs.008"], "failure_category": "message mismatch", "resolution": "repair"}, {"id": "JEB-E01", "seq": 374, "module": "Core", "source": "Public post", "title": "Two rules collide after the SCT Inst limit is removed", "explain": "When the EU Instant Payments Regulation removed the EUR 100K scheme-level maximum for SCT Inst, the old routing rule that sent payments above EUR 100K to TARGET2 lost the scheme limit it was built on. A bank can now set its own customer limits, so Customer A with a EUR 300K limit can send EUR 200K instantly while the unchanged routing rule still sends anything above EUR 100K to TARGET2, which means two live rules produce different outcomes for the same payment. The BA must surface the conflict, trace why each rule exists, and take the choice to the Product Owner or Business Owner, because only the business can decide which outcome it wants once the scheme constraint is gone.", "takeaway": "The BA must surface the conflict, trace why each rule exists, and take the choice to the Product Owner or Business Owner, because only the business can decide which outcome it wants once the scheme constraint is gone.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "EU Instant Payments Regulation removes the EUR 100K SCT Inst maximum.", "title": "Scheme limit removed"}, {"kind": "step", "note": "Customer A is given a EUR 300K instant payment limit by the bank.", "title": "Customer limit set"}, {"kind": "decision", "note": "Customer limit allows SCT Instant, routing rule sends it to TARGET2.", "title": "Which rule wins for EUR 200K?"}, {"kind": "step", "note": "Trace why each rule exists and what changed since it was written.", "title": "BA surfaces the conflict"}, {"kind": "step", "note": "Product Owner or Business Owner chooses the intended business behaviour.", "title": "Decision-maker decides"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D05 Domestic payment systems", "messages": []}, {"id": "JEB-E03", "seq": 375, "module": "Core", "source": "Public post", "title": "Performance requirements start from business demand", "explain": "Monthly volume describes scale, but peak behaviour describes performance demand, so a BA who only records today's volumes has not defined what the platform must support. With payment traffic peaking between 7 AM and 10 AM and five clients in the pipeline who could add 10 million transactions a month, the BA must establish when they onboard, how certain the forecast is, what their peaks look like, whether they create new bursts, and whether the workload itself changes with more validations, API calls, real-time processing, and concurrency. The answer is a six-part view of current demand, peak behaviour, future demand, planning horizon, workload characteristics, and measurable requirements that cover response time, processing conditions, volume, and peak TPS, because a platform that performs today can still fail tomorrow if growth was never considered.", "takeaway": "The answer is a six-part view of current demand, peak behaviour, future demand, planning horizon, workload characteristics, and measurable requirements that cover response time, processing conditions, volume, and peak TPS, because a platform that performs today can still fail tomorrow if growth was never considered.", "visual": {"type": "diagram", "diagram": {"centre": "Performance is a business discussion", "parts": [{"label": "Current demand", "note": "How many transactions today, and when does traffic peak."}, {"label": "Peak behaviour", "note": "Peak concentration defines the performance demand, not monthly volume."}, {"label": "Future demand", "note": "Five clients in the pipeline could add 10 million transactions a month."}, {"label": "Workload change", "note": "More validations, API calls, real-time processing, and concurrency."}, {"label": "Measurable requirements", "note": "Volume, peak TPS, response time, and processing conditions, tested."}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "JEB-E07", "seq": 378, "module": "Core", "source": "Public post", "title": "Trace the chain before blaming the payment engine", "explain": "A payment routed to the wrong intermediary bank looks like a payment engine fault until the BA traces the full routing chain from instruction through routing decision, settlement directory, Swift reference data, intermediary selection, and routing. The fault may sit in an incorrectly updated settlement directory or in Swift reference data for a correspondent bank that was never updated, which means a correct routing rule can still produce the wrong intermediary from bad data. The investigation must establish what was expected, what actually happened, where the two diverged, which component decided, and what data it used, then move from symptom to investigation to root cause to corrective action instead of asking each team in turn whether it is their problem.", "takeaway": "The investigation must establish what was expected, what actually happened, where the two diverged, which component decided, and what data it used, then move from symptom to investigation to root cause to corrective action instead of asking each team in turn whether it is their problem.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "A payment reaches the wrong intermediary bank.", "title": "Symptom: wrong intermediary"}, {"kind": "step", "note": "Instruction, routing decision, settlement directory, reference data, selection, routing.", "title": "Trace the routing chain"}, {"kind": "decision", "note": "Check whether the rule, the directory, or the reference data is at fault.", "title": "Logic wrong or data wrong?"}, {"kind": "step", "note": "Correct the data or the logic, then apply the corrective action.", "title": "Fix the root cause"}]}}, "level": "core", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "wrong routing", "resolution": "investigate"}, {"id": "ABH-31", "seq": 404, "module": "Advanced", "source": "Public post", "title": "You can replace a person, not their context", "explain": "AI scales execution, but human expertise gives it context. Replacing a person removes the context they carry about the business, the customer and the history, and that context is not easily rebuilt.", "takeaway": "Replacing a person removes the context they carry about the business, the customer and the history, and that context is not easily rebuilt.", "visual": {"type": "diagram", "diagram": {"centre": "AI and human expertise", "parts": [{"label": "AI execution", "note": "Scales how fast work gets done"}, {"label": "Human context", "note": "Business, customer and history knowledge"}, {"label": "Replacing a person", "note": "Removes the context they carry"}, {"label": "Rebuilding context", "note": "Not easily rebuilt once removed"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": []}, {"id": "ABH-32", "seq": 405, "module": "Advanced", "source": "Public post", "title": "Think twice before layoffs, reskill for AI", "explain": "The post asks CEOs, CTOs and founders to think twice before layoffs, and offers free AI and GenAI reskilling help to anyone struggling. The point is that the AI shift is a skills problem as much as a headcount problem.", "takeaway": "The point is that the AI shift is a skills problem as much as a headcount problem.", "visual": {"type": "diagram", "diagram": {"centre": "Reskill for the AI shift", "parts": [{"label": "CEOs, CTOs and founders", "note": "Asked to think twice before layoffs"}, {"label": "Free AI and GenAI reskilling", "note": "Help offered to anyone struggling"}, {"label": "Skills problem", "note": "The AI shift is as much skills as headcount"}, {"label": "Headcount problem", "note": "The headcount side of the shift"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D15 Advanced and emerging payments", "messages": []}, {"id": "ABH-33", "seq": 406, "module": "Advanced", "source": "Public post", "title": "US green-card crackdown, PERM suspended", "explain": "Major tech and IT companies were suspended from the PERM program, and the post lists five actions Indian IT professionals should take. The situation shows how an immigration policy change can reshape career plans overnight.", "takeaway": "The situation shows how an immigration policy change can reshape career plans overnight.", "visual": {"type": "diagram", "diagram": {"centre": "PERM suspension", "parts": [{"label": "Major tech and IT companies", "note": "Suspended from the PERM program"}, {"label": "Five actions", "note": "Listed for Indian IT professionals to take"}, {"label": "Immigration policy change", "note": "Can reshape career plans overnight"}, {"label": "Indian IT professionals", "note": "The group the advice is aimed at"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-34", "seq": 407, "module": "Advanced", "source": "Public post", "title": "PERM suspension does not cancel H-1B", "explain": "A PERM suspension does not automatically cancel H-1B visas. The advice is not to panic but to plan proactively, because the two programs are separate and a suspension in one does not end the other.", "takeaway": "The advice is not to panic but to plan proactively, because the two programs are separate and a suspension in one does not end the other.", "visual": {"type": "diagram", "diagram": {"centre": "PERM suspension and H-1B", "parts": [{"label": "PERM suspension", "note": "Does not automatically cancel H-1B visas"}, {"label": "H-1B visas", "note": "A separate program from PERM"}, {"label": "No panic", "note": "Plan proactively instead"}, {"label": "Two separate programs", "note": "A suspension in one does not end the other"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-35", "seq": 408, "module": "Advanced", "source": "Public post", "title": "Corporate Banking BA role in Hanoi", "explain": "The hiring post is for a Corporate Banking Business Analyst with six or more years of experience, onsite in Hanoi, covering onboarding, entitlements, fees, limits and payments. It shows what a corporate banking BA is expected to own end to end.", "takeaway": "It shows what a corporate banking BA is expected to own end to end.", "visual": {"type": "diagram", "diagram": {"centre": "Corporate Banking BA role", "parts": [{"label": "Six or more years experience", "note": "The experience the role asks for"}, {"label": "Onsite in Hanoi", "note": "Where the role is based"}, {"label": "Onboarding", "note": "In the BA scope end to end"}, {"label": "Entitlements", "note": "In the BA scope end to end"}, {"label": "Fees", "note": "In the BA scope end to end"}, {"label": "Limits", "note": "In the BA scope end to end"}, {"label": "Payments", "note": "In the BA scope end to end"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": []}, {"id": "ABH-36", "seq": 409, "module": "Advanced", "source": "Public post", "title": "Open to Work: PM and Senior BA roles", "explain": "The post seeks Product Manager, Senior Project Manager, Product Owner or Senior BA roles in the UK, Australia and New Zealand, Asia, Europe and APAC. The background is Cognizant, Virtusa and Coforge, with payments and product experience.", "takeaway": "The background is Cognizant, Virtusa and Coforge, with payments and product experience.", "visual": {"type": "diagram", "diagram": {"centre": "Open to Work, PM and Senior BA", "parts": [{"label": "Product Manager", "note": "Role sought"}, {"label": "Senior Project Manager", "note": "Role sought"}, {"label": "Product Owner", "note": "Role sought"}, {"label": "Senior BA", "note": "Role sought"}, {"label": "UK, Australia, New Zealand, Asia, Europe, APAC", "note": "Regions sought"}, {"label": "Cognizant, Virtusa and Coforge", "note": "Background employers"}, {"label": "Payments and product experience", "note": "The experience on offer"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": []}, {"id": "ABH-37", "seq": 410, "module": "Advanced", "source": "Public post", "title": "Open to Work: PO and Senior BA, banking", "explain": "The post seeks Product Owner or Senior Business Analyst roles in banking and payments, with SEPA, cross-border, ISO 20022, SWIFT MT and MX, and APIs. It is a clear statement of the skills a payments BA brings to a hiring manager.", "takeaway": "It is a clear statement of the skills a payments BA brings to a hiring manager.", "visual": {"type": "diagram", "diagram": {"centre": "Payments BA open to work", "parts": [{"label": "Product Owner", "note": "Role sought in banking and payments"}, {"label": "Senior Business Analyst", "note": "Role sought in banking and payments"}, {"label": "SEPA", "note": "Skill the BA brings"}, {"label": "Cross-border", "note": "Skill the BA brings"}, {"label": "ISO 20022", "note": "Skill the BA brings"}, {"label": "SWIFT MT and MX", "note": "Skill the BA brings"}, {"label": "APIs", "note": "Skill the BA brings"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D06 Cross-border payments", "messages": []}, {"id": "ABH-38", "seq": 411, "module": "Advanced", "source": "Public post", "title": "Payments and BFS consulting, now open", "explain": "The post opens paid Payments and BFS consulting covering functional consulting, all payment types, BRD and FRD, AI use cases and product thinking, with curiosity free. It shows how a payments SME packages deep domain knowledge as a service.", "takeaway": "It shows how a payments SME packages deep domain knowledge as a service.", "visual": {"type": "diagram", "diagram": {"centre": "Payments and BFS consulting", "parts": [{"label": "Functional consulting", "note": "Consulting on how payments work"}, {"label": "All payment types", "note": "Covered by the consulting"}, {"label": "BRD and FRD", "note": "Documents the consulting produces"}, {"label": "AI use cases", "note": "Covered by the consulting"}, {"label": "Product thinking", "note": "Covered by the consulting"}, {"label": "Curiosity free", "note": "Questions welcome before engaging"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "ABH-39", "seq": 412, "module": "Advanced", "source": "Public post", "title": "Booking link blocked? Reach out on LinkedIn", "explain": "The Topmate link is blocked because of the current living location, so the ask is not to book sessions through Topmate for now and to reach out on LinkedIn instead. It is a practical note about staying reachable when a platform blocks you.", "takeaway": "It is a practical note about staying reachable when a platform blocks you.", "visual": {"type": "diagram", "diagram": {"centre": "Staying reachable when blocked", "parts": [{"label": "Topmate link blocked", "note": "Blocked by current living location"}, {"label": "No Topmate bookings", "note": "Asked not to book sessions there for now"}, {"label": "LinkedIn instead", "note": "The channel to use instead"}, {"label": "Practical note", "note": "Staying reachable when a platform blocks you"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": [], "resolution": "reject"}, {"id": "ABH-40", "seq": 413, "module": "Advanced", "source": "Public post", "title": "Building a network across Asia", "explain": "The post looks to expand a professional network across Asia, including Singapore, Malaysia, China, Vietnam, the Philippines and more. A payments career in Asia is built on relationships across many markets, not one.", "takeaway": "A payments career in Asia is built on relationships across many markets, not one.", "visual": {"type": "diagram", "diagram": {"centre": "Professional network across Asia", "parts": [{"label": "Singapore", "note": "A market in the network"}, {"label": "Malaysia", "note": "A market in the network"}, {"label": "China", "note": "A market in the network"}, {"label": "Vietnam", "note": "A market in the network"}, {"label": "Philippines", "note": "A market in the network"}, {"label": "More markets", "note": "The network spans many markets, not one"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-41", "seq": 414, "module": "Advanced", "source": "Public post", "title": "AI Alchemist award, Virtusa Vietnam team", "explain": "The post thanks a colleague for the opportunity and the AI Alchemist award, and shares a repost about the Virtusa Vietnam team. It is a recognition post that shows the value of a team that explores AI and turns ideas into impact.", "takeaway": "It is a recognition post that shows the value of a team that explores AI and turns ideas into impact.", "visual": {"type": "diagram", "diagram": {"centre": "The AI Alchemist award", "parts": [{"label": "The award", "note": "Recognises exploring AI and turning ideas into impact"}, {"label": "The team", "note": "Explores AI and turns ideas into impact"}, {"label": "The recognition post", "note": "Thanks a colleague for the opportunity"}, {"label": "The repost", "note": "Shares the team story"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-42", "seq": 415, "module": "Advanced", "source": "Public post", "title": "Awarded the AI Alchemist at Virtusa", "explain": "The post announces the AI Alchemist award at Virtusa. The award recognises exploring AI and turning ideas into impact, which is the work the author had been sharing.", "takeaway": "The award recognises exploring AI and turning ideas into impact, which is the work the author had been sharing.", "visual": {"type": "diagram", "diagram": {"centre": "The AI Alchemist award", "parts": [{"label": "Exploring AI", "note": "The work the award recognises"}, {"label": "Turning ideas into impact", "note": "The work the award recognises"}, {"label": "The announcement", "note": "Marks receiving the award"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-43", "seq": 416, "module": "Advanced", "source": "Public post", "title": "AI Alchemist: a milestone, not a finish", "explain": "The post marks receiving the AI Alchemist award at Virtusa for exploring AI and turning ideas into impact. It frames the award as a milestone in a longer journey of sharing practical knowledge.", "takeaway": "It frames the award as a milestone in a longer journey of sharing practical knowledge.", "visual": {"type": "diagram", "diagram": {"centre": "A milestone in sharing knowledge", "parts": [{"label": "The award", "note": "Marks receiving the AI Alchemist award"}, {"label": "Exploring AI", "note": "The journey the award marks"}, {"label": "Turning ideas into impact", "note": "The journey the award marks"}, {"label": "Sharing practical knowledge", "note": "The longer journey the award sits in"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-44", "seq": 417, "module": "Advanced", "source": "Public post", "title": "Why do postings say Only Females Can Apply", "explain": "The post asks HR and recruiters a genuine question: why do some job postings say only females can apply. It raises a fairness question about hiring language that a professional should be able to ask openly.", "takeaway": "It raises a fairness question about hiring language that a professional should be able to ask openly.", "visual": {"type": "diagram", "diagram": {"centre": "Fairness in hiring language", "parts": [{"label": "The question", "note": "Why do some postings say only females can apply"}, {"label": "HR and recruiters", "note": "Asked the genuine question"}, {"label": "Fairness", "note": "A question a professional should ask openly"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "ABH-45", "seq": 418, "module": "Advanced", "source": "Public post", "title": "Why demand joining in thirty days?", "explain": "The post asks why companies require immediate joining or joining within thirty days, when an employee cannot leave that fast either. Notice periods run both ways, and a hiring process that ignores that creates a mismatch.", "takeaway": "Notice periods run both ways, and a hiring process that ignores that creates a mismatch.", "visual": {"type": "diagram", "diagram": {"centre": "Joining in thirty days", "parts": [{"label": "Immediate joining", "note": "What companies demand"}, {"label": "Joining within thirty days", "note": "What companies demand"}, {"label": "Notice periods", "note": "Run both ways, for employee and employer"}, {"label": "The mismatch", "note": "A process that ignores notice creates it"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D01 Foundations of money and payments", "messages": [], "failure_category": "message mismatch"}, {"id": "ABH-46", "seq": 419, "module": "Advanced", "source": "Public post", "title": "Do banks need Sunday branches?", "explain": "The post questions Indian banks opening branches on Sundays, arguing that customers want better digital banking and bank employees deserve a Sunday with family. The point is that digital capability, not branch hours, is what customers actually need.", "takeaway": "The point is that digital capability, not branch hours, is what customers actually need.", "visual": {"type": "diagram", "diagram": {"centre": "Do banks need Sunday branches", "parts": [{"label": "Sunday branches", "note": "What banks are opening"}, {"label": "Better digital banking", "note": "What customers actually want"}, {"label": "Employees deserve Sunday", "note": "A Sunday with family"}, {"label": "Digital capability", "note": "What customers need, not branch hours"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D01 Foundations of money and payments", "messages": []}, {"id": "ABH-47", "seq": 420, "module": "Advanced", "source": "Public post", "title": "Earning far from home", "explain": "The Diwali post is about working away from family: the salary reaches home, but the heart wishes it could too. It is a reminder that a payments career often means working far from home, and that the human side of the job matters.", "takeaway": "It is a reminder that a payments career often means working far from home, and that the human side of the job matters.", "visual": {"type": "diagram", "diagram": {"centre": "Earning far from home", "parts": [{"label": "Working away from family", "note": "The reality of the payments career"}, {"label": "Salary reaches home", "note": "The money gets home"}, {"label": "Heart wishes it could too", "note": "The human side of the job"}, {"label": "The human side", "note": "It matters as much as the work"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-48", "seq": 421, "module": "Advanced", "source": "Public post", "title": "The human side behind the professional", "explain": "This is a light, image-only personal post. It carries no payments teaching, but it shows the human side, which is part of how a professional builds a following.", "takeaway": "It carries no payments teaching, but it shows the human side, which is part of how a professional builds a following.", "visual": {"type": "diagram", "diagram": {"centre": "The human side of a professional", "parts": [{"label": "Light personal post", "note": "Image only, no payments teaching"}, {"label": "Human side", "note": "Shows the person behind the professional"}, {"label": "Building a following", "note": "Part of how a professional grows it"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-49", "seq": 422, "module": "Advanced", "source": "Public post", "title": "Good engineering protects real people", "explain": "The post is about a house that stood strong while everything around it was destroyed, with prayers for the people of Nepal. It is a reminder that good engineering is not abstract: it protects real people in real disasters.", "takeaway": "It is a reminder that good engineering is not abstract: it protects real people in real disasters.", "visual": {"type": "diagram", "diagram": {"centre": "When good engineering saves lives", "parts": [{"label": "The house that stood strong", "note": "Stood while everything around it was destroyed"}, {"label": "Prayers for the people of Nepal", "note": "The human cost behind the story"}, {"label": "Good engineering", "note": "Not abstract, it protects real people"}, {"label": "Real disasters", "note": "Where engineering is tested"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "ABH-50", "seq": 423, "module": "Advanced", "source": "Public post", "title": "Fifteen thousand followers, fifteen years", "explain": "The milestone post marks fifteen thousand followers and fifteen years in payments, product management, APIs and ISO 20022, with a commitment to keep sharing practical payments and fintech insights. It closes the set by showing the breadth of the field this product covers.", "takeaway": "It closes the set by showing the breadth of the field this product covers.", "visual": {"type": "diagram", "diagram": {"centre": "Fifteen years in payments", "parts": [{"label": "Fifteen thousand followers", "note": "The milestone the post marks"}, {"label": "Fifteen years", "note": "In payments, product management, APIs and ISO 20022"}, {"label": "Practical insights", "note": "Shared on payments and fintech"}, {"label": "Commitment to keep sharing", "note": "The close of the set"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "messages": []}, {"id": "INS-148", "seq": 430, "module": "Advanced", "source": "Public post", "title": "Interoperability is an operating agreement", "explain": "When two banks connect their instant payment systems, the technical link is only the start. They must agree who investigates a failed payment, who returns the funds, how long the customer waits, and how disputes are resolved. Without that governance, a payment that fails after the sender is debited leaves both banks pointing at different contracts, so interoperability is a business and operating agreement, not just a connection.", "takeaway": "Without that governance, a payment that fails after the sender is debited leaves both banks pointing at different contracts, so interoperability is a business and operating agreement, not just a connection.", "visual": {"type": "diagram", "diagram": {"centre": "Interoperability operating model", "parts": [{"label": "Technical link only the start", "note": "Technical link is only the start"}, {"label": "Who investigates a failure", "note": "Banks must agree who investigates a failed payment"}, {"label": "Who returns the funds", "note": "Banks must agree who returns the funds"}, {"label": "How long the customer waits", "note": "Banks must agree how long the customer waits"}, {"label": "How disputes are resolved", "note": "Banks must agree how disputes are resolved"}, {"label": "No governance risk", "note": "Without governance, a failed payment leaves both banks pointing at contracts"}, {"label": "Business and operating agreement", "note": "Interoperability is a business and operating agreement, not just a connection"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "JEB-A01", "seq": 435, "module": "Advanced", "source": "Public post", "title": "Cancel or return: choose the refund route by agreement", "explain": "Settlement status decides the instrument for a EUR 250 payment executed in error: cancellation suits a payment still unsettled, while a settled payment needs a return. A camt.055 therefore works only before Bank B settles, and once settlement has cleared, the bank seeks the funds back through a camt.056 or a pacs.004. The refund route follows the standing agreement, with FOCR returning the full amount under its own procedure and the cover route sending the money back to the original account, and an unanswered camt.055 leaves pacs.004 as the fallback request.", "takeaway": "The refund route follows the standing agreement, with FOCR returning the full amount under its own procedure and the cover route sending the money back to the original account, and an unanswered camt.055 leaves pacs.004 as the fallback request.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "A legitimate EUR 250 payment went through with the wrong execution", "title": "EUR 250 executed in error"}, {"kind": "decision", "note": "Settlement status decides whether cancellation or return applies", "title": "Has settlement cleared?"}, {"kind": "step", "note": "Request cancellation before settlement; Bank B refuses it after settling", "title": "Cancel early with camt.055"}, {"kind": "step", "note": "Use camt.056 or pacs.004 to recover funds once the payment has settled", "title": "Seek return after settlement"}, {"kind": "decision", "note": "FOCR returns funds in full; cover returns them to the original account", "title": "FOCR or cover route?"}, {"kind": "step", "note": "An unanswered camt.055 leaves pacs.004 as the return request", "title": "pacs.004 when camt.055 is silent"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.055", "camt.056", "pacs.004"], "failure_category": "payment rejected or returned", "resolution": "return"}, {"id": "JEB-B03", "seq": 442, "module": "Advanced", "source": "Public post", "title": "One leg failed: check the cover before recalling it", "explain": "A USD 250,000 cover-method payment from India to Europe shows why a failed leg must not trigger an instant recall: the bank system rejected the pacs.008 before sending, while the pacs.009 COV had already been processed. Three questions decide the path, whether the cover has been released, whether it has settled, and whether the beneficiary bank USD cut-off is still open. If the cover has not been released, halt it, resolve the fault and rebuild both legs; if it has settled and the cut-off is still open, fixing the issue and sending the pacs.008 may complete the payment without a recall. Recalling straight away can make things worse, because unwinding a sound cover and processing it again can push the credit later and shift the value date.", "takeaway": "Recalling straight away can make things worse, because unwinding a sound cover and processing it again can push the credit later and shift the value date.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Bank system rejects the pacs.008 while the pacs.009 COV is already processed", "title": "pacs.008 rejected before sending"}, {"kind": "decision", "note": "First ask whether the cover has been released", "title": "Has the cover been released?"}, {"kind": "decision", "note": "Released but unsettled calls for investigation before any cancellation decision", "title": "Settled, and cut-off still open?"}, {"kind": "step", "note": "Halt the cover, resolve the fault and rebuild both legs", "title": "Not released: stop and regenerate"}, {"kind": "step", "note": "Fix the issue and send the pacs.008, which may complete the payment without a recall", "title": "Settled and cut-off open: fix and send"}, {"kind": "step", "note": "Unwinding a sound cover can push the credit later and shift the value date", "title": "Do not recall straight away"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.008", "pacs.009"], "failure_category": "cut-off missed", "resolution": "investigate"}, {"id": "JEB-B06", "seq": 443, "module": "Advanced", "source": "Public post", "title": "pacs.002 RJCT: check the cover before crediting", "explain": "Under the cover method the pacs.008 goes directly to the beneficiary bank while the pacs.009 COV moves the funds through the correspondent, so a pacs.002 RJCT on the pacs.008 does not by itself justify crediting the remitter. The first question is the status of the cover: not yet processed, on hold, or already processed and settled. Crediting too early can refund the customer while the cover is still at the correspondent, a loss the bank has to absorb, so the bank must establish where the funds are before acting. Mastering pacs.002, pacs.004 and camt.056 one by one is not enough; senior practice means understanding how the two legs interact and what to check before taking action.", "takeaway": "Mastering pacs.002, pacs.004 and camt.056 one by one is not enough; senior practice means understanding how the two legs interact and what to check before taking action.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "pacs.008 goes to the beneficiary bank while the COV moves funds through the correspondent", "title": "pacs.008 and pacs.009 COV sent"}, {"kind": "step", "note": "A rejection arrives for the pacs.008, and the instinct is to credit the remitter", "title": "pacs.002 RJCT arrives"}, {"kind": "decision", "note": "Not yet processed, on hold, or already processed and settled", "title": "What is the status of the cover?"}, {"kind": "step", "note": "Find where the funds are before acting", "title": "Establish where the funds are"}, {"kind": "step", "note": "Crediting too early can refund the customer while the cover is still at the correspondent", "title": "Do not credit too early"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["pacs.002", "pacs.008", "pacs.009", "pacs.004", "camt.056"], "resolution": "investigate"}, {"id": "JEB-B10", "seq": 444, "module": "Advanced", "source": "Public post", "title": "Regulatory vs client priority: phase both, not either-or", "explain": "Prioritising CBPR+ structured-address work over a strategic client Cash Pooling work because the regulatory date was November 2026 looked reasonable, yet the clash was worth challenging on the assumptions, not the authority. The questions are what is truly mandatory, what can be phased, and what the capacity impact is: the Cash Pooling side might need only domestic pooling first, and the regulatory side might sequence incoming support before outgoing. Breaking both pieces down turned an either-or choice into a plan with incoming structured-address support first, domestic Cash Pooling on track, and outgoing support plus international and cross-currency pooling in the next phase. The regulatory date later moved, yet the sequencing approach still held, so challenge the thinking, not the person, and check whether either piece can be phased before locking the priority in.", "takeaway": "The regulatory date later moved, yet the sequencing approach still held, so challenge the thinking, not the person, and check whether either piece can be phased before locking the priority in.", "visual": {"type": "diagram", "diagram": {"centre": "Phase both, not either-or", "parts": [{"label": "Regulatory date November 2026", "note": "CBPR+ structured-address work was prioritised for the regulatory date"}, {"label": "Strategic client Cash Pooling", "note": "The client work was deprioritised against the regulatory work"}, {"label": "Challenge the assumptions", "note": "Challenge the thinking, not the person, and question what is truly mandatory"}, {"label": "What can be phased?", "note": "Check what can be phased and what the capacity impact is"}, {"label": "Incoming first, domestic on track", "note": "Incoming structured-address support first, with domestic Cash Pooling on track"}, {"label": "Next phase: outgoing and more", "note": "Outgoing support plus international and cross-currency pooling in the next phase"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D12 Risk, compliance and regulation", "messages": [], "resolution": "escalate"}, {"id": "JEB-C09", "seq": 446, "module": "Advanced", "source": "Public post", "title": "Explain a recall as a journey, not a list of messages", "explain": "Many candidates can describe camt.055, camt.056, pacs.004 and camt.029 one by one but cannot connect them into the business journey. The journey runs from the customer asking the debtor bank to recall a payment, through the bank starting an investigation and sending a camt.056 to the creditor agent, to the creditor bank checking whether the payment was credited and whether the beneficiary agrees, and finally to the outcome and the investigation response. The interview answer should follow that chain of customer intention, investigation, interbank request, creditor decision, financial outcome and response, because that shows payments knowledge, not just message knowledge, and when learning any ISO 20022 message, ask who sends it, why, what triggered it, and what happens before and after it.", "takeaway": "The interview answer should follow that chain of customer intention, investigation, interbank request, creditor decision, financial outcome and response, because that shows payments knowledge, not just message knowledge, and when learning any ISO 20022 message, ask who sends it, why, what triggered it, and what happens before and after it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The journey starts with the customer asking the debtor bank to recall a payment", "title": "Customer asks to recall the payment"}, {"kind": "step", "note": "The bank starts an investigation and sends a camt.056 to the creditor agent", "title": "Bank starts an investigation"}, {"kind": "step", "note": "The creditor bank checks whether the payment was credited and the beneficiary agrees", "title": "Creditor bank checks the payment"}, {"kind": "step", "note": "The outcome follows the creditor decision on the return of funds", "title": "Financial outcome decided"}, {"kind": "step", "note": "Finally the outcome and the investigation response close the journey", "title": "Investigation response sent"}, {"kind": "step", "note": "Follow customer intention, investigation, request, decision, outcome and response", "title": "Answer as a chain, not a list"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": ["camt.055", "camt.056", "pacs.004", "camt.029"], "resolution": "investigate"}, {"id": "INS-011", "seq": 459, "module": "Advanced", "source": "Public post", "title": "First response to a production issue", "explain": "When the monitoring dashboard shows a sharp rise in failed instant payments just after 09:00, customers report payments stuck in pending, and the contact centre queue is growing, the first responder must act in a fixed order and not improvise. First, confirm the incident is real using monitoring, error rates and customer reports, and declare it through the agreed channel with a severity based on customer impact, not on the suspected cause. Then establish the impact, the affected population, the containment, the ownership, the evidence and the update cadence, so that the response is organised from the first minutes rather than assembled under pressure.", "takeaway": "Then establish the impact, the affected population, the containment, the ownership, the evidence and the update cadence, so that the response is organised from the first minutes rather than assembled under pressure.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Confirm the incident is real", "note": "Use monitoring, error rates and customer reports."}, {"kind": "step", "title": "Declare the incident", "note": "Agreed channel, severity by customer impact."}, {"kind": "step", "title": "Establish impact and population", "note": "Establish the affected population."}, {"kind": "step", "title": "Establish containment", "note": "Establish the containment for the incident."}, {"kind": "step", "title": "Establish ownership and cadence", "note": "Ownership, evidence and update cadence."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D13 Payments product and business", "messages": [], "failure_category": "payment rejected or returned", "resolution": "repair"}, {"id": "INS-065", "seq": 460, "module": "Advanced", "source": "Public post", "title": "Hundreds of similar complaints within 20 minutes", "explain": "On a weekday morning between 09:12 and 09:32, a contact centre receives more than 300 complaints with the same shape: customers report a debit that does not match the payment status shown in the app, or a credit they expected that has not appeared. Start with an incident bridge that separates three workstreams: customer and financial containment, technical root cause analysis, and communications. Containment owns the affected-transaction register, the decision on the next batch and any remediation, while the other workstreams proceed in parallel, so that customers are protected even before the root cause is known.", "takeaway": "Containment owns the affected-transaction register, the decision on the next batch and any remediation, while the other workstreams proceed in parallel, so that customers are protected even before the root cause is known.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Open an incident bridge", "note": "Start with an incident bridge for the complaints."}, {"kind": "step", "title": "Separate three workstreams", "note": "Containment, root cause analysis and communications."}, {"kind": "step", "title": "Containment owns the register", "note": "Affected-transaction register and remediation decisions."}, {"kind": "step", "title": "Other workstreams run in parallel", "note": "Customers are protected before the root cause is known."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D06 Cross-border payments", "messages": [], "resolution": "investigate"}, {"id": "INS-067", "seq": 461, "module": "Advanced", "source": "Public post", "title": "Failures across UPI, cards, net banking and wallets", "explain": "On the same day, UPI payments fail with timeouts, card payments fail at the gateway, net banking sessions drop before confirmation, and wallet payments fail after the wallet is debited. Build one incident table segmented by rail and channel, gateway, bank, response code, time window and transaction state, and join each row to its ledger and clearing evidence by correlation ID. For each segment, establish whether the payment left the customer account, whether it reached clearing or the scheme, and what its authoritative state is now. Segmenting the incident this way shows whether there is one cause or several, which decides whether one fix or several are needed.", "takeaway": "Segmenting the incident this way shows whether there is one cause or several, which decides whether one fix or several are needed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Segment the incident", "note": "One table by rail, channel, gateway, bank and code."}, {"kind": "step", "title": "Join each row to ledger evidence", "note": "Join by correlation ID to ledger and clearing evidence."}, {"kind": "step", "title": "Establish each segment state", "note": "Did it leave the account, reach clearing, what is its state."}, {"kind": "decision", "title": "One cause or several?", "note": "One cause means one fix, several means several fixes."}, {"kind": "step", "title": "Apply the fix", "note": "One fix or several, as the evidence decides."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D08 Cards and alternative payments", "messages": [], "failure_category": "timeout", "resolution": "investigate"}, {"id": "INS-030", "seq": 465, "module": "Advanced", "source": "Public post", "title": "Banking API integration walkthrough", "explain": "A retailer wants to connect its checkout directly to a bank's payment API so orders can be paid without leaving the retailer's site. The analyst must explain how the integration actually works end to end: how the client authenticates, what the request and response mean, how the retailer learns the final payment outcome, how failures are handled and how the integration is monitored. Walk through the integration in layers and make each layer testable, starting with the contract, the endpoints, the request and response schemas, mandatory and optional fields, validation rules and error codes, then the authentication, the asynchronous status path and the recovery procedures.", "takeaway": "Walk through the integration in layers and make each layer testable, starting with the contract, the endpoints, the request and response schemas, mandatory and optional fields, validation rules and error codes, then the authentication, the asynchronous status path and the recovery procedures.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the contract", "note": "Endpoints, schemas, fields, validation and error codes."}, {"kind": "step", "title": "Explain authentication", "note": "How the client authenticates."}, {"kind": "step", "title": "Explain request and response", "note": "What the request and response mean."}, {"kind": "step", "title": "Explain the status path", "note": "How the retailer learns the final outcome."}, {"kind": "step", "title": "Explain failure handling", "note": "How failures are handled and recovered."}, {"kind": "step", "title": "Explain monitoring", "note": "How the integration is monitored."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D10 APIs and integration", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-025", "seq": 466, "module": "Advanced", "source": "Public post", "title": "Gathering requirements for a third-party payment gateway", "explain": "A retailer sells online and in store and wants to add a third-party payment gateway so customers can pay by card and by instant payment at checkout, but the requirements are still a set of general wishes: fast, secure and easy to integrate. Start from the customer and finance outcomes, not from the provider brochure: list the payment methods, currencies, channels and customer journeys in scope, and for each one define the expected flow, authorisation, capture, refund, partial refund, void, chargeback handling and settlement timing. Then define the API capabilities, the request and response contracts, the error handling, the security, the retries and the reconciliation, so the provider can be compared on evidence rather than on marketing.", "takeaway": "Then define the API capabilities, the request and response contracts, the error handling, the security, the retries and the reconciliation, so the provider can be compared on evidence rather than on marketing.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "List what is in scope", "note": "Methods, currencies, channels and customer journeys."}, {"kind": "step", "title": "Define the flow per journey", "note": "Authorisation, capture, refund, void, chargeback, settlement."}, {"kind": "step", "title": "Define API capabilities", "note": "Contracts, error handling, security, retries, reconciliation."}, {"kind": "step", "title": "Compare providers on evidence", "note": "Compare on evidence, not on marketing."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "investigate"}, {"id": "INS-048", "seq": 467, "module": "Advanced", "source": "Public post", "title": "SIT passes but the production API fails", "explain": "A merchant payment API integration passes system integration testing cleanly, with every test case returning the expected response, yet it fails in production. Contain the impact first by stopping new submissions if the failure rate is rising, telling the partner what is known and what is not, and confirming which payments have a financial effect and which do not. Then compare the environments side by side in a fixed order: endpoint and configuration, credentials and scopes, certificates and expiry dates, network routes and firewall rules, feature flags, downstream dependency versions and production data. The difference between test and production is usually in one of these, and comparing them in a fixed order finds it faster than guessing.", "takeaway": "The difference between test and production is usually in one of these, and comparing them in a fixed order finds it faster than guessing.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Contain the impact", "note": "Stop new submissions, tell the partner, confirm effect."}, {"kind": "step", "title": "Compare endpoint and configuration", "note": "Check endpoint and configuration first."}, {"kind": "step", "title": "Compare credentials and certificates", "note": "Credentials, scopes, certificates and expiry dates."}, {"kind": "step", "title": "Compare network and firewall", "note": "Network routes and firewall rules."}, {"kind": "step", "title": "Compare flags and dependencies", "note": "Feature flags and downstream dependency versions."}, {"kind": "step", "title": "Compare production data", "note": "Production data is the last comparison."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D10 APIs and integration", "messages": [], "failure_category": "system or connectivity failure", "resolution": "investigate"}, {"id": "INS-089", "seq": 468, "module": "Advanced", "source": "Public post", "title": "Validating a payment API", "explain": "A fintech partner is integrating with a bank's payment API to submit customer credit transfers on behalf of its merchants. In testing, the API returns a successful HTTP response, but the merchant's downstream order record is not created, and in one case the payment is debited while the merchant dashboard still shows the order as unpaid. Start from the contract, not from the code: the API definition must state, for each endpoint, what a success response promises, receipt, validation, acceptance or completion, and what the caller must do next in each case. Then review authentication, schema, mandatory fields, business validation, response codes, idempotency and observability, because a success response that promises completion when it only means receipt will mislead every caller.", "takeaway": "Then review authentication, schema, mandatory fields, business validation, response codes, idempotency and observability, because a success response that promises completion when it only means receipt will mislead every caller.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "State what success promises", "note": "Receipt, validation, acceptance or completion per endpoint."}, {"kind": "step", "title": "State what the caller does next", "note": "What the caller must do next in each case."}, {"kind": "step", "title": "Review authentication", "note": "Review authentication for the API."}, {"kind": "step", "title": "Review schema and fields", "note": "Review schema, mandatory fields and business validation."}, {"kind": "step", "title": "Review response codes", "note": "Review response codes and what each means."}, {"kind": "step", "title": "Review idempotency", "note": "Review idempotency and observability."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D10 APIs and integration", "messages": [], "failure_category": "system or connectivity failure", "resolution": "return"}, {"id": "INS-059", "seq": 469, "module": "Advanced", "source": "Public post", "title": "Defining request and response expectations", "explain": "A bank is publishing a Payment API for corporate customers and retail partners, and the first draft of the contract is a list of fields with no rules. It does not say which fields are required and which are optional, what happens when a field is missing, which error code means what, whether a success response means the payment completed, or how a caller should safely retry. Define every field with its name, type, cardinality, validation rule and error code, and state explicitly which fields are required, which are optional, and which are conditionally mandatory by rail, destination or product. Where a field is optional under the message schema but the bank's reporting or product needs it, say so in the contract and state the source the bank will use and the derivation rule.", "takeaway": "Where a field is optional under the message schema but the bank's reporting or product needs it, say so in the contract and state the source the bank will use and the derivation rule.", "visual": {"type": "diagram", "diagram": {"centre": "Request and response expectations", "parts": [{"label": "Field definition", "note": "Name, type, cardinality, validation rule and error code."}, {"label": "Required fields", "note": "Stated explicitly in the contract."}, {"label": "Optional fields", "note": "Stated explicitly in the contract."}, {"label": "Conditionally mandatory fields", "note": "Mandatory by rail, destination or product."}, {"label": "Bank-needed optional fields", "note": "State the source and the derivation rule."}, {"label": "Success response meaning", "note": "Say whether success means receipt or completion."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D10 APIs and integration", "messages": []}, {"id": "INS-058", "seq": 470, "module": "Advanced", "source": "Public post", "title": "Two-week BA sprint for a Payment API integration", "explain": "A retailer needs a Payment API integration delivered in a two-week sprint. The checkout must submit payment instructions to the bank, receive a clear acceptance or rejection, and create the order only when the payment outcome is known. Start the sprint with discovery compressed into the first two days: confirm the business outcome, the checkout journey, the payment types in scope, the expected volumes and the response contract. The contract definition matters most, so agree in writing what each response means, so that an acceptance response is never mistaken for completion, and define the status enquiry path the retailer uses when a payment outcome is unclear.", "takeaway": "The contract definition matters most, so agree in writing what each response means, so that an acceptance response is never mistaken for completion, and define the status enquiry path the retailer uses when a payment outcome is unclear.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Discovery in two days", "note": "Outcome, journey, payment types, volumes, contract."}, {"kind": "step", "title": "Agree the contract in writing", "note": "Acceptance is never mistaken for completion."}, {"kind": "step", "title": "Define the status enquiry path", "note": "The path used when an outcome is unclear."}, {"kind": "step", "title": "Submit and get a clear outcome", "note": "Clear acceptance or rejection from the bank."}, {"kind": "step", "title": "Create the order only when known", "note": "Order is created only when the outcome is known."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "payment rejected or returned", "resolution": "investigate"}, {"id": "INS-022", "seq": 471, "module": "Advanced", "source": "Public post", "title": "Redesigning a KYC onboarding journey", "explain": "A bank wants more new retail customers to complete digital onboarding, but only a small share of started applications reach an active account. Customers abandon the journey at document upload and at identity verification, and many who do finish are later held for manual review because documents are unclear or data does not match. Start with evidence, not opinions, and measure the funnel stage by stage: started, identity details entered, document uploaded, identity verified, screening complete, account opened and first transaction. Then map the friction, the document collection, the validation, the screening, the exception handling and the conversion measures, so the redesign targets the stages where customers actually drop off.", "takeaway": "Then map the friction, the document collection, the validation, the screening, the exception handling and the conversion measures, so the redesign targets the stages where customers actually drop off.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Started to identity details", "note": "Measure the funnel stage by stage."}, {"kind": "step", "title": "Identity details to document upload", "note": "Customers abandon at document upload."}, {"kind": "step", "title": "Document upload to verified", "note": "Many are held for manual review after finishing."}, {"kind": "step", "title": "Verified to screening complete", "note": "Screening must complete before the account opens."}, {"kind": "step", "title": "Screening to account opened", "note": "The account opens after screening."}, {"kind": "step", "title": "Account opened to first transaction", "note": "The first transaction completes onboarding."}, {"kind": "step", "title": "Redesign at the drop-off stages", "note": "Target the stages where customers actually drop off."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "INS-040", "seq": 472, "module": "Advanced", "source": "Public post", "title": "Change affects multiple applications and teams", "explain": "A bank must change its instant euro payments to match the current scheme rules: there is no longer a scheme-level maximum amount for SCT Inst, execution must complete within 10 seconds, and verification of payee is mandatory for instant euro payments. The change touches the mobile app, the payment engine, the sanctions and fraud services, the clearing adapter, the ledger and the customer notifications. Build the impact analysis as a map, not as a list of opinions: start from the change and walk upstream to find which channels, products and customer journeys can submit an instant euro payment, which limits and validations apply today, and which of those must change, then walk downstream to find the systems, data, interfaces, controls, tests, operations and release dependencies that are affected.", "takeaway": "Build the impact analysis as a map, not as a list of opinions: start from the change and walk upstream to find which channels, products and customer journeys can submit an instant euro payment, which limits and validations apply today, and which of those must change, then walk downstream to find the systems, data, interfaces, controls, tests, operations and release dependencies that are affected.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Start from the change", "note": "No maximum, 10-second execution, payee verification."}, {"kind": "step", "title": "Walk upstream", "note": "Find channels, products and journeys that submit instant payments."}, {"kind": "step", "title": "Find limits to change", "note": "Find which limits and validations must change."}, {"kind": "step", "title": "Walk downstream", "note": "Find systems, data, interfaces, controls, tests and releases."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D12 Risk, compliance and regulation", "messages": []}, {"id": "INS-049", "seq": 473, "module": "Advanced", "source": "Public post", "title": "Critical requirement appears one day before deployment", "explain": "A bank is one day from deploying an upgrade to its instant euro payment service. UAT is signed off, regression evidence is filed, the deployment window is booked and the communications to customers are ready, and late in the afternoon the compliance team raises a requirement nobody recorded. First classify the item precisely as a defect against an agreed requirement, a safety or compliance obligation, or genuinely new scope, and confirm the obligation at its source, for example verification of payee is mandatory for instant euro payments from 9 October 2025 under Regulation (EU) 2024/886, and SCT Inst execution has a 10-second maximum with no scheme-level maximum since the 2025 rulebook change. Then triage defect versus new scope, quantify the risk and obtain a formal go or no-go decision, because a mandatory compliance obligation cannot be deferred the way new scope can.", "takeaway": "Then triage defect versus new scope, quantify the risk and obtain a formal go or no-go decision, because a mandatory compliance obligation cannot be deferred the way new scope can.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Classify the item", "note": "Defect, safety or compliance obligation, or new scope."}, {"kind": "step", "title": "Confirm the obligation", "note": "Payee verification is mandatory from 9 October 2025."}, {"kind": "step", "title": "Triage defect versus scope", "note": "Triage defect versus genuinely new scope."}, {"kind": "step", "title": "Quantify the risk", "note": "Quantify the risk of the late requirement."}, {"kind": "step", "title": "Obtain a go or no-go decision", "note": "A mandatory obligation cannot be deferred like scope."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "resolution": "escalate"}, {"id": "INS-054", "seq": 474, "module": "Advanced", "source": "Public post", "title": "Critical UAT failure rate at test start", "explain": "A bank is starting user acceptance testing for a new SEPA direct debit collection service. On the first morning the failure rate is critical: most test collections are rejected, mandate references cannot be found, and the test schedule shows collections submitted on the wrong day. Begin with a triage that separates the failure causes into four buckets, environment, test data, build and requirements, and check the environment first: whether the UAT build is the intended version, whether the endpoints, credentials and scheme adapters point at the right test systems, and whether the feature flags are set as the release notes state. Only then decide whether to continue, fix and restart, or stop, because continuing a test on a broken environment wastes the testers' time and produces evidence that cannot be trusted.", "takeaway": "Only then decide whether to continue, fix and restart, or stop, because continuing a test on a broken environment wastes the testers' time and produces evidence that cannot be trusted.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Triage into four buckets", "note": "Environment, test data, build and requirements."}, {"kind": "step", "title": "Check the environment first", "note": "Build version, endpoints, credentials, adapters, flags."}, {"kind": "decision", "title": "Decide continue, fix or stop", "note": "Continuing on a broken environment wastes tester time."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": [], "failure_category": "mandate issue", "resolution": "investigate"}, {"id": "INS-055", "seq": 475, "module": "Advanced", "source": "Public post", "title": "Incorrect EMI for a small customer subset", "explain": "A bank receives complaints from a small group of loan customers that their monthly EMI is wrong. Most customers are unaffected, which makes the problem harder, not easier, so start by defining the affected population precisely: list every complaining account and search for others with the same characteristics, so the fix covers silent cases as well as complaints. For each affected loan, capture the full calculation inputs: principal, sanctioned rate, rate change history with effective dates, tenure, schedule generation rules, rounding policy, part-payment history and customer data. The pattern only emerges when the cases are compared, because the affected loans share a characteristic, such as a particular rate change date, that the unaffected loans do not.", "takeaway": "The pattern only emerges when the cases are compared, because the affected loans share a characteristic, such as a particular rate change date, that the unaffected loans do not.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the affected population", "note": "List complaining accounts and search for silent cases."}, {"kind": "step", "title": "Capture the calculation inputs", "note": "Principal, rate, history, tenure, rules, rounding, payments."}, {"kind": "step", "title": "Compare the cases", "note": "The affected loans share a characteristic the others lack."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D12 Risk, compliance and regulation", "messages": [], "resolution": "investigate"}, {"id": "INS-042", "seq": 476, "module": "Advanced", "source": "Public post", "title": "Designing discovery for a new product", "explain": "A bank wants to launch an instant payment product for small business customers, and the product sponsor has asked the team to make payments faster. The request has no named user group, no baseline, no target speed and no statement of the problem customers actually face today. Start by naming the target users precisely, for example small businesses that pay domestic suppliers on fixed weekly cycles, and exclude segments the product will not serve in the first release, then write a problem statement in the form of who suffers, what it costs them and how often, and gather evidence such as payment volumes, current settlement times, supplier discount losses and support contacts. Then define the hypotheses, the constraints, the minimum viable product and the success metrics, so discovery ends with a decision rather than with a longer list of ideas.", "takeaway": "Then define the hypotheses, the constraints, the minimum viable product and the success metrics, so discovery ends with a decision rather than with a longer list of ideas.", "visual": {"type": "diagram", "diagram": {"centre": "Discovery for a new instant payment product", "parts": [{"label": "Target users", "note": "Small businesses paying domestic suppliers weekly."}, {"label": "Excluded segments", "note": "Segments not served in the first release."}, {"label": "Problem statement", "note": "Who suffers, what it costs them and how often."}, {"label": "Evidence", "note": "Volumes, settlement times, discount losses, support contacts."}, {"label": "Hypotheses and constraints", "note": "Defined so discovery ends with a decision."}, {"label": "MVP and success metrics", "note": "Define the minimum product and how success is judged."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D02 Accounts, ledger and accounting", "messages": [], "resolution": "repair"}, {"id": "INS-043", "seq": 477, "module": "Advanced", "source": "Public post", "title": "Optimising an inefficient legacy process", "explain": "A bank runs a legacy supplier payment process that has grown by accretion over a decade. A corporate customer sends a payment file, operations staff print exception lists, re-key corrected details into three different screens, phone the customer for missing information, and then release the file late in the day. Begin by observing the work as performed, not as documented: follow real files from intake to release, time each step, and record every workaround, hand-off and re-key, then quantify the pain with measures the business can compare, such as straight-through processing rate, repair rate by defect type, average and worst-case cycle time per step, rework hours, error rate after release and customer contacts per file. Then design the target process, validate the controls and the operational impacts, and only then change the process.", "takeaway": "Then design the target process, validate the controls and the operational impacts, and only then change the process.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Observe the work as performed", "note": "Follow real files, time each step, record workarounds."}, {"kind": "step", "title": "Quantify the pain", "note": "Straight-through rate, repair rate, cycle time, rework, errors."}, {"kind": "step", "title": "Design the target process", "note": "Design the target process from the evidence."}, {"kind": "step", "title": "Validate controls and impacts", "note": "Validate the controls and operational impacts."}, {"kind": "step", "title": "Change the process", "note": "Only then change the process."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": [], "resolution": "investigate"}, {"id": "INS-114", "seq": 503, "module": "Advanced", "source": "Public post", "title": "Ten million a month: test the peak, not the average", "explain": "Five new clients at ten million transactions a month add roughly 330,000 transactions a day on average, but averages hide the risk: payroll and supplier files arrive in concentrated morning windows, so the peak dwarfs the average. With the busiest hour already at about 70 percent of measured capacity, the only question that matters is whether the peak fits. Convert the growth into throughput, concurrency, queue depth, storage, monitoring and resilience requirements before the clients go live.", "takeaway": "Convert the growth into throughput, concurrency, queue depth, storage, monitoring and resilience requirements before the clients go live.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "Find the busiest hour, not the daily average.", "title": "Measure today's peak"}, {"kind": "step", "note": "Layer the ten million a month onto its morning peaks.", "title": "Model the added volume"}, {"kind": "step", "note": "Test the peak against measured capacity.", "title": "Size for peak throughput"}, {"kind": "step", "note": "Allow for concentrated file windows.", "title": "Size queues and storage for bursts"}, {"kind": "step", "note": "Watch the peak and absorb a surge.", "title": "Monitor the peak and build resilience"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D09 Payment architecture and technology", "messages": []}, {"id": "INS-115", "seq": 504, "module": "Advanced", "source": "Public post", "title": "An extra hour moves every deadline", "explain": "A cut-off is not a single time but the end of a deadline chain, channel cut-offs, scheme windows, liquidity checks and operational staffing. Adding an hour moves the whole chain, and the customer promise has to survive at the new time. Judge the extension on four things, downstream scheme windows, liquidity for the extra hour, staffing to run it, and exception handling for payments that still miss the new cut-off.", "takeaway": "Judge the extension on four things, downstream scheme windows, liquidity for the extra hour, staffing to run it, and exception handling for payments that still miss the new cut-off.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "List every deadline the cut-off closes.", "title": "Map every deadline in the chain"}, {"kind": "step", "note": "Test whether the schemes accept the later time.", "title": "Test the scheme windows"}, {"kind": "step", "note": "Test whether funding covers the extra hour.", "title": "Test liquidity for the extra hour"}, {"kind": "step", "note": "Test whether operations can run the later window.", "title": "Test staffing for the later window"}, {"kind": "step", "note": "Define the path when the new cut-off is missed.", "title": "Define the exception path"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D07 Clearing, settlement and liquidity", "messages": []}, {"id": "JEB-F09", "seq": 514, "module": "Advanced", "source": "Public post", "title": "Direct debit rejects routed to a third-party account", "explain": "A debtor bank normally returns a rejected collection to the creditor bank, authorising it to debit the originator's account, but a collection can instead be booked to a designated third-party account. The third-party account is funded to meet regulatory obligations and to follow rejected payments through the general ledger, and it can be used only if the originator's instructions allow it, the account was opened and funded first, and it is opened and maintained by the creditor bank. Building it as a system requirement is a sensitive decision that needs product owner and business owner agreement, with checks for the returning customer, fraud signs and valid repayment flows. A BA cannot necessarily refuse a requirement, yet challenging it remains the BA responsibility.", "takeaway": "A BA cannot necessarily refuse a requirement, yet challenging it remains the BA responsibility.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "AC01 wrong account number or AC06 blocked account are typical returns", "title": "Collection rejected by the debtor bank"}, {"kind": "decision", "note": "The normal path returns the collection to the creditor bank", "title": "Book to a third-party account?"}, {"kind": "decision", "note": "Originator instruction, account opened and funded first, creditor bank maintains it", "title": "Are the preconditions met?"}, {"kind": "step", "note": "The funded account tracks the rejected payment in the ledger", "title": "Book the reject to the designated account"}, {"kind": "step", "note": "Identify the customer, check fraud signs and repayment flows", "title": "Run fraud, clearing and accounting checks"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D05 Domestic payment systems", "messages": [], "failure_category": "payment rejected or returned", "resolution": "escalate"}, {"id": "JEB-F05", "seq": 515, "module": "Advanced", "source": "Public post", "title": "Late consent after a camt.056 cancellation", "explain": "A negative camt.029 can arrive while a payment engine is still processing a set of 500 payments, and a beneficiary consent can then arrive after the expected timeframe, while the pacs.004 return that follows can be made per payment or grouped by customer, reason, value or compliance cause. The remaining payments have no universal answer: return them, complete them, or reject the late consent by accepting or overriding the rule, so each bank must define when a late consent can be accepted and when it cannot, and record the message, the consent and the retention rules that apply. Treating a late consent as merely late misses the point, since it can still reflect sound business behaviour.", "takeaway": "Treating a late consent as merely late misses the point, since it can still reflect sound business behaviour.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "note": "The cancellation request reaches the payment engine", "title": "camt.056 cancels the payment set"}, {"kind": "step", "note": "Some of the 500 payments are still unprocessed", "title": "Negative camt.029 arrives mid-processing"}, {"kind": "step", "note": "Consent from the same beneficiary, after the timeframe", "title": "Late beneficiary consent arrives"}, {"kind": "decision", "note": "Apply the bank rule for accepting or rejecting late consent", "title": "Can late consent be accepted?"}, {"kind": "step", "note": "pacs.004 returns the funds, record the message, consent and retention", "title": "Return funds and record everything"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D11 Operations, exceptions and reconciliation", "messages": ["camt.056", "camt.029", "pacs.004"]}, {"id": "JEB-F03", "seq": 517, "module": "Advanced", "source": "Public post", "title": "ISO 20022 readiness: close the eight gaps first", "explain": "ISO 20022 migration is a transformation of the payments business model, not a message format change, and readiness fails where processes are not aligned to customer payment journeys, hand-offs are unplanned, business teams are untrained, systems cannot hold high data quality, and compliance, fraud and AML teams are not aligned. Limited resources, missing governance and weak coordination across stakeholders leave the gap between business and technology in place even after execution starts. A migration plan must close these eight gaps before it can claim the business is ready.", "takeaway": "A migration plan must close these eight gaps before it can claim the business is ready.", "visual": {"type": "diagram", "diagram": {"centre": "ISO 20022 migration readiness", "parts": [{"label": "Journey alignment", "note": "Processes must follow the customer payment journey"}, {"label": "Planned hand-offs", "note": "Every hand-off between teams is defined in advance"}, {"label": "Trained business teams", "note": "Business teams understand ISO 20022 principles"}, {"label": "High data quality", "note": "Systems must hold rich, accurate payment data"}, {"label": "Aligned control teams", "note": "Compliance, fraud and AML work to the same plan"}, {"label": "Governance and resources", "note": "Oversight, skills and coordination across stakeholders"}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D14 Business analysis and professional practice", "messages": []}, {"id": "RUN6-005", "seq": 521, "module": "Advanced", "source": "Article and reader comments", "title": "Blockchain for payments: four open questions", "explain": "Transparency means every node sees transaction detail, and control over confidential fields is still being built. A business relationship links each node with every other node, which simplifies maintenance of the shared ledger. Formats will vary with the algorithm each network uses, so one universal message and ledger format is ambitious yet not impossible. A single network spanning domestic and cross-border payments is achievable if the industry aligns on common standards.", "takeaway": "A single network spanning domestic and cross-border payments is achievable if the industry aligns on common standards.", "visual": {"type": "diagram", "diagram": {"centre": "Four open questions on blockchain payments", "parts": [{"label": "Confidentiality", "note": "Every node sees transaction detail; control of confidential fields is in progress."}, {"label": "Business relationships", "note": "Each node relates to every other node in the network."}, {"label": "Formats", "note": "Message and ledger formats vary by algorithm; one format is ambitious."}, {"label": "Reach", "note": "One network for domestic and cross-border payments needs common standards."}]}}, "level": "advanced", "stage": 6, "stage_name": "Senior SME judgement", "domain": "D15 Advanced and emerging payments", "messages": []}];
